package main

// This file is the CANDIDATE SLOT for evolved routing algorithms. During
// optimization, the entire file is replaced (via go build -overlay) with a
// generated implementation. The contract is a single constructor:
//
//	newCandidateRouter(view, source, localBalances, spec)
//
// returning a routing.SimRouter. The router sees only the public gossip
// graph, its own channel balances and per-attempt feedback — the same
// information a real Lightning sender has. The in-tree implementation below
// is the seed algorithm: a deliberately simple fee-optimizing Dijkstra with
// failure blacklisting and halving-based MPP splitting.

import (
	"container/heap"
	"context"
	"errors"
	"fmt"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

// candidateEdge is one directed edge of the public graph: a channel from
// one node to another, with the policy the sending node announced.
type candidateEdge struct {
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

// fee returns the fee the sending node charges to forward amt over this
// edge.
func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

// usable reports whether the edge can carry the given amount per its
// announced policy.
func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	// The public capacity is a hard upper bound on what can flow.
	return amt <= e.capacity
}

// candidateRouter is the seed algorithm: cheapest-path routing with a
// failure blacklist and amount halving when no route is found.
type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	// incomingEdges maps a node to the directed edges arriving at it,
	// the natural shape for backward Dijkstra.
	incomingEdges map[route.Vertex][]*candidateEdge

	// localBalances is the exact outbound liquidity of our own channels.
	localBalances map[uint64]lnwire.MilliSatoshi

	// failedAmt records, per directed channel, the lowest amount that
	// failed with a liquidity error; routes are built to stay below it.
	failedAmt map[uint64]lnwire.MilliSatoshi

	// shardAmt is the current shard size for MPP splitting.
	shardAmt lnwire.MilliSatoshi

	// partsUsed counts the successful shards so far.
	partsUsed uint32

	// pending maps in-flight attempt ids to their routes.
	pending map[uint64]*route.Route
}

// newCandidateRouter builds the router for one payment. This signature is
// the stable contract between the harness and generated candidates.
func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	router := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		localBalances: localBalances,
		failedAmt:     make(map[uint64]lnwire.MilliSatoshi),
		shardAmt:      spec.Amount,
		pending:       make(map[uint64]*route.Route),
	}

	// Build the adjacency list from gossip. Iterating a node's channels
	// yields, per channel, the policy the OTHER node announced toward us
	// (InPolicy). That is exactly the policy governing the directed edge
	// other -> node, so we record the reversed edge at each visit.
	ctx := context.Background()
	seen := make(map[route.Vertex]bool)
	queue := []route.Vertex{source}
	seen[source] = true

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: pol.FeeBaseMSat,
					feeRatePPM: pol.
						FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				router.incomingEdges[edge.to] = append(
					router.incomingEdges[edge.to], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return router, nil
}

// dijkstraItem is a priority queue entry.
type dijkstraItem struct {
	node route.Vertex
	cost lnwire.MilliSatoshi
	idx  int
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int           { return len(q) }
func (q dijkstraQueue) Less(i, j int) bool { return q[i].cost < q[j].cost }
func (q dijkstraQueue) Swap(i, j int)      { q[i], q[j] = q[j], q[i]; q[i].idx = i; q[j].idx = j }
func (q *dijkstraQueue) Push(x any) {
	item := x.(*dijkstraItem)
	item.idx = len(*q)
	*q = append(*q, item)
}
func (q *dijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

// findRoute computes the cheapest usable path delivering amt to the target,
// walking backward from the target so fees accumulate correctly.
func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi) (*route.Route,
	error) {

	// dist[node] = amount that must arrive at node to deliver amt.
	dist := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)

	dist[r.spec.Target] = amt
	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{node: r.spec.Target, cost: amt})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		node, arriving := item.node, item.cost

		if arriving > dist[node] {
			continue
		}
		if node == r.source {
			break
		}

		// Consider all edges INTO node: for edge u->node, u must
		// send arriving plus u's fee.
		for _, edge := range r.incomingEdges[node] {
			amtOver := arriving

			if !edge.usable(amtOver) {
				continue
			}

			// Skip channels whose liquidity failure bound says
			// this amount cannot pass.
			if bound, ok := r.failedAmt[edge.chanID]; ok &&
				amtOver >= bound {

				continue
			}

			// Our own channels: check exact local balance.
			if edge.from == r.source {
				if r.localBalances[edge.chanID] < amtOver {
					continue
				}
			}

			var sending lnwire.MilliSatoshi
			if edge.from == r.source {
				// We pay no fee to ourselves.
				sending = amtOver
			} else {
				sending = amtOver + edge.fee(amtOver)
			}

			best, ok := dist[edge.from]
			if !ok || sending < best {
				dist[edge.from] = sending
				next[edge.from] = edge
				heap.Push(pq, &dijkstraItem{
					node: edge.from,
					cost: sending,
				})
			}
		}
	}

	if _, ok := dist[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	return r.buildRoute(amt, next)
}

// buildRoute walks the next-pointers from source to target and constructs a
// route with correctly accumulated fees and cltv deltas.
func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	const finalCltvDelta = 40

	// Collect the path edges source -> target.
	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.to
	}

	// Amounts and expiries per channel, computed backward.
	numHops := len(path)
	amtOver := make([]lnwire.MilliSatoshi, numHops)
	expiryOver := make([]uint32, numHops)

	amtOver[numHops-1] = amt
	expiryOver[numHops-1] = finalCltvDelta

	for i := numHops - 2; i >= 0; i-- {
		fwd := path[i+1]
		amtOver[i] = amtOver[i+1] + fwd.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(fwd.timeLockDelta)
	}

	hops := make([]*route.Hop, numHops)
	for i, edge := range path {
		amtToFwd := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < numHops-1 {
			amtToFwd = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     amtToFwd,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

// RequestRoute returns the next route to try: the cheapest path for the
// current shard size, halving the shard when no route exists.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if r.shardAmt > amt {
		r.shardAmt = amt
	}

	for {
		rt, err := r.findRoute(r.shardAmt)
		if err == nil {
			return rt, nil
		}

		// No route at this shard size: split if we're allowed more
		// parts and the shard is still meaningfully large.
		partsLeft := r.spec.MaxParts - inFlightHtlcs
		if partsLeft <= 1 || r.shardAmt < 10_000_000 {
			return nil, err
		}
		r.shardAmt /= 2
	}
}

// ReportAttempt learns from an attempt: liquidity failures set an upper
// bound on the failing channel.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if result.Failure == nil {
		return nil
	}

	// Locate the failing hop and record the amount bound on its
	// outgoing channel.
	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	}
	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == result.FailureSource {
			failIdx = i + 1
		}
	}

	// The failing node could not forward over its outgoing channel,
	// which is rt.Hops[failIdx].
	if failIdx >= 0 && failIdx < len(rt.Hops) {
		hop := rt.Hops[failIdx]
		amtOver := rt.TotalAmount
		if failIdx > 0 {
			amtOver = rt.Hops[failIdx-1].AmtToForward
		}

		bound, ok := r.failedAmt[hop.ChannelID]
		if !ok || amtOver < bound {
			r.failedAmt[hop.ChannelID] = amtOver
		}
	}

	return nil
}

best_candidate.source:
package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40
	riskWeight     = 2_500_000.0
)

type edgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
	cap    lnwire.MilliSatoshi
}

type liquidityBelief struct {
	lowerOK lnwire.MilliSatoshi
	upper   lnwire.MilliSatoshi

	estimate  lnwire.MilliSatoshi
	confidence float64

	suspectAmt   lnwire.MilliSatoshi
	failVotes    uint8
	lastFailPath uint64
}

var sharedBeliefs = struct {
	sync.Mutex
	m map[edgeKey]liquidityBelief
}{
	m: make(map[edgeKey]liquidityBelief),
}

type candidateEdge struct {
	key      edgeKey
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usableHTLC(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return amt <= e.capacity
}

type edgeUse struct {
	edge   *candidateEdge
	amount lnwire.MilliSatoshi
}

type searchResult struct {
	rt      *route.Route
	path    []*candidateEdge
	uses    []edgeUse
	logProb float64
	fee     lnwire.MilliSatoshi
}

type plannedRoute struct {
	result *searchResult
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeByKey     map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[edgeKey]liquidityBelief

	// reserved includes successful shards and routes returned but not yet
	// reported. This prevents atomic MPP siblings from double-spending a
	// corridor.
	reserved map[edgeKey]lnwire.MilliSatoshi
	issued   map[*route.Route][]edgeUse

	// penalty is payment-local. Unlike shared beliefs, it can react
	// aggressively without permanently poisoning later payments.
	penalty map[edgeKey]float64

	// tried records the smallest failed delivery amount for an exact path.
	// The same path remains eligible at a lower amount.
	tried map[uint64]lnwire.MilliSatoshi

	plan         []plannedRoute
	retryCeiling lnwire.MilliSatoshi
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edgeByKey:     make(map[edgeKey]*candidateEdge),
		localBalances: make(map[uint64]lnwire.MilliSatoshi),
		beliefs:       make(map[edgeKey]liquidityBelief),
		reserved:      make(map[edgeKey]lnwire.MilliSatoshi),
		issued:        make(map[*route.Route][]edgeUse),
		penalty:       make(map[edgeKey]float64),
		tried:         make(map[uint64]lnwire.MilliSatoshi),
	}

	for id, balance := range localBalances {
		r.localBalances[id] = balance
	}

	ctx := context.Background()
	seen := make(map[route.Vertex]bool)
	queue := []route.Vertex{source}
	seen[source] = true

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				capacity := lnwire.NewMSatFromSatoshis(ch.Capacity)
				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					cap:    capacity,
				}
				edge := &candidateEdge{
					key:           key,
					chanID:        ch.ChannelID,
					from:          ch.OtherNode,
					to:            node,
					capacity:      capacity,
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[edge.to] = append(
					r.incomingEdges[edge.to], edge,
				)
				r.edgeByKey[key] = edge

				sharedBeliefs.Lock()
				b := sharedBeliefs.m[key]
				sharedBeliefs.Unlock()
				r.beliefs[key] = b

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func clampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005
	case p > 0.995:
		return 0.995
	default:
		return p
	}
}

// bimodalPrior models a channel as roughly equally likely to be in a
// depleted mode or a well-funded mode. Tiny HTLCs can pass either mode,
// while amounts near capacity fall off a logistic cliff.
func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.025)

	z := (x - 0.90) / 0.045
	var highMode float64
	switch {
	case z > 40:
		highMode = 0
	case z < -40:
		highMode = 1
	default:
		highMode = 1 / (1 + math.Exp(z))
	}

	return clampProbability(0.5*lowMode + 0.5*highMode)
}

func (r *candidateRouter) totalReserved(key edgeKey,
	extra map[edgeKey]lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	total := r.reserved[key]
	if extra != nil {
		total += extra[key]
	}
	return total
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi,
	extra map[edgeKey]lnwire.MilliSatoshi) float64 {

	reserved := r.totalReserved(edge.key, extra)
	needed := reserved + amt

	if edge.from == r.source {
		if needed <= r.localBalances[edge.chanID] {
			return 0.995
		}
		return 0.005
	}

	prior := bimodalPrior(needed, edge.capacity)
	b := r.beliefs[edge.key]

	if b.lowerOK > edge.capacity {
		b.lowerOK = edge.capacity
	}
	if b.upper > edge.capacity {
		b.upper = edge.capacity
	}
	if b.estimate > edge.capacity {
		b.estimate = edge.capacity
	}

	// Truthful successes dominate uncertain failures.
	if b.lowerOK > 0 && needed <= b.lowerOK {
		return 0.995
	}
	if b.upper > 0 && needed >= b.upper {
		return 0.008
	}

	p := prior
	if b.confidence > 0 && b.estimate > 0 {
		scale := math.Max(float64(edge.capacity)*0.10, 1)
		z := (float64(needed) - float64(b.estimate)) / scale

		var estimated float64
		switch {
		case z > 40:
			estimated = 0
		case z < -40:
			estimated = 1
		default:
			estimated = 1 / (1 + math.Exp(z))
		}

		weight := math.Min(0.70, b.confidence*0.70)
		p = (1-weight)*p + weight*estimated
	}

	// A single uncorroborated blame is only soft evidence.
	if b.failVotes == 1 && b.suspectAmt > 0 &&
		needed >= b.suspectAmt*3/4 {

		p *= 0.62
	}

	return clampProbability(p)
}

func (r *candidateRouter) edgeAvailable(edge *candidateEdge,
	amt lnwire.MilliSatoshi,
	extra map[edgeKey]lnwire.MilliSatoshi) bool {

	if !edge.usableHTLC(amt) {
		return false
	}

	reserved := r.totalReserved(edge.key, extra)
	if reserved+amt > edge.capacity {
		return false
	}

	if edge.from == r.source &&
		reserved+amt > r.localBalances[edge.chanID] {

		return false
	}

	return true
}

type dijkstraItem struct {
	node   route.Vertex
	score  float64
	amount lnwire.MilliSatoshi
	index  int
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int { return len(q) }
func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}
func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index = i
	q[j].index = j
}
func (q *dijkstraQueue) Push(x any) {
	item := x.(*dijkstraItem)
	item.index = len(*q)
	*q = append(*q, item)
}
func (q *dijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	extra map[edgeKey]lnwire.MilliSatoshi,
	reuse map[edgeKey]int, bias map[edgeKey]float64) (*searchResult, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is payment target")
	}

	bestScore := make(map[route.Vertex]float64)
	required := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)
	logProbability := make(map[route.Vertex]float64)

	bestScore[r.spec.Target] = 0
	required[r.spec.Target] = amt
	logProbability[r.spec.Target] = 0

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node:   r.spec.Target,
		score:  0,
		amount: amt,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		node := item.node

		current, ok := bestScore[node]
		if !ok || item.score > current+0.0001 {
			continue
		}
		if node == r.source {
			break
		}

		arriving := required[node]
		for _, edge := range r.incomingEdges[node] {
			if !r.edgeAvailable(edge, arriving, extra) {
				continue
			}

			p := r.edgeProbability(edge, arriving, extra)
			edgeFee := lnwire.MilliSatoshi(0)
			sending := arriving
			if edge.from != r.source {
				edgeFee = edge.fee(arriving)
				sending += edgeFee
			}

			edgeCost := float64(edgeFee) -
				riskWeight*math.Log(p) + 2_000

			edgeCost += r.penalty[edge.key]
			if bias != nil {
				edgeCost += bias[edge.key]
			}
			if reuse != nil && reuse[edge.key] > 0 {
				edgeCost += float64(reuse[edge.key]) * 4_000_000
			}

			score := item.score + edgeCost
			old, exists := bestScore[edge.from]
			if exists && score >= old {
				continue
			}

			bestScore[edge.from] = score
			required[edge.from] = sending
			next[edge.from] = edge
			logProbability[edge.from] =
				logProbability[node] + math.Log(p)

			heap.Push(pq, &dijkstraItem{
				node:   edge.from,
				score:  score,
				amount: sending,
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	rt, path, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, err
	}

	uses := routeUses(rt, path)
	return &searchResult{
		rt:      rt,
		path:    path,
		uses:    uses,
		logProb: logProbability[r.source],
		fee:     rt.TotalAmount - amt,
	}, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route,
	[]*candidateEdge, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.to
	}

	if len(path) == 0 {
		return nil, nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		nextEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			nextEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(nextEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forward := amt
		expiry := uint32(finalCltvDelta)
		if i < last {
			forward = amtOver[i+1]
			expiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, path, nil
}

func routeUses(rt *route.Route, path []*candidateEdge) []edgeUse {
	uses := make([]edgeUse, len(path))
	for i, edge := range path {
		amount := rt.TotalAmount
		if i > 0 {
			amount = rt.Hops[i-1].AmtToForward
		}
		uses[i] = edgeUse{edge: edge, amount: amount}
	}
	return uses
}

func deliveredAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func routeHash(rt *route.Route) uint64 {
	h := uint64(1469598103934665603)
	for _, hop := range rt.Hops {
		h ^= hop.ChannelID
		h *= 1099511628211
		for _, b := range hop.PubKeyBytes {
			h ^= uint64(b)
			h *= 1099511628211
		}
	}
	return h
}

func (r *candidateRouter) findFreshRoute(amt lnwire.MilliSatoshi,
	extra map[edgeKey]lnwire.MilliSatoshi,
	reuse map[edgeKey]int) (*searchResult, error) {

	bias := make(map[edgeKey]float64)
	var lastErr error

	for n := 0; n < 10; n++ {
		result, err := r.findRoute(amt, extra, reuse, bias)
		if err != nil {
			return nil, err
		}

		hash := routeHash(result.rt)
		failedAt, failed := r.tried[hash]
		if !failed || amt < failedAt {
			return result, nil
		}

		lastErr = errors.New("all candidate routes already failed")
		if len(result.path) == 0 {
			break
		}

		// Exclude a different edge on successive duplicate paths. This
		// uses only payment-local information and does not turn an
		// unreadable onion error into a permanent channel accusation.
		index := int((hash + uint64(n)) % uint64(len(result.path)))
		bias[result.path[index].key] += 7_000_000
	}

	if lastErr == nil {
		lastErr = errors.New("no fresh route found")
	}
	return nil, lastErr
}

func (r *candidateRouter) reliableDeliveryLimit(result *searchResult,
	extra map[edgeKey]lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	delivery := deliveredAmount(result.rt)
	limit := delivery * 8
	if limit < delivery {
		limit = delivery
	}

	for _, use := range result.uses {
		edge := use.edge
		reserved := r.totalReserved(edge.key, extra)

		var safeTotal lnwire.MilliSatoshi
		if edge.from == r.source {
			safeTotal = r.localBalances[edge.chanID]
		} else {
			b := r.beliefs[edge.key]
			safeTotal = edge.capacity * 78 / 100

			if b.estimate > 0 && b.confidence > 0 {
				w := math.Min(0.85, b.confidence)
				safeTotal = lnwire.MilliSatoshi(
					(1-w)*float64(safeTotal) +
						w*float64(b.estimate),
				)
			}
			if b.lowerOK > safeTotal {
				safeTotal = b.lowerOK
			}
			if b.upper > 0 && safeTotal >= b.upper {
				safeTotal = b.upper * 9 / 10
			}
		}

		if safeTotal > edge.capacity {
			safeTotal = edge.capacity
		}
		if safeTotal <= reserved {
			return 0
		}

		available := safeTotal - reserved
		edgeLimit := delivery * available / use.amount

		if edge.maxHTLC != 0 && use.amount > 0 {
			policyLimit := delivery * edge.maxHTLC / use.amount
			if policyLimit < edgeLimit {
				edgeLimit = policyLimit
			}
		}
		if edgeLimit < limit {
			limit = edgeLimit
		}
	}

	return limit
}

func addReservations(dst map[edgeKey]lnwire.MilliSatoshi,
	uses []edgeUse) {

	for _, use := range uses {
		dst[use.edge.key] += use.amount
	}
}

func planMetric(results []*searchResult) float64 {
	metric := -0.04 * float64(len(results))
	for _, result := range results {
		metric += result.logProb
		metric -= float64(result.fee) / 5_000_000
	}
	return metric
}

func (r *candidateRouter) buildPlanForParts(amt lnwire.MilliSatoshi,
	parts int) ([]*searchResult, bool) {

	remaining := amt
	virtual := make(map[edgeKey]lnwire.MilliSatoshi)
	reuse := make(map[edgeKey]int)
	results := make([]*searchResult, 0, parts)

	for i := 0; i < parts; i++ {
		slots := parts - i
		if remaining <= 0 {
			return nil, false
		}

		share := (remaining + lnwire.MilliSatoshi(slots) - 1) /
			lnwire.MilliSatoshi(slots)

		result, err := r.findFreshRoute(share, virtual, reuse)
		if err != nil {
			return nil, false
		}

		safe := r.reliableDeliveryLimit(result, virtual)
		if safe < share {
			if slots == 1 || safe <= 0 {
				return nil, false
			}

			share = safe
			result, err = r.findFreshRoute(share, virtual, reuse)
			if err != nil {
				return nil, false
			}
		}

		if share <= 0 || share >= remaining && slots > 1 {
			return nil, false
		}

		results = append(results, result)
		addReservations(virtual, result.uses)
		for _, use := range result.uses {
			reuse[use.edge.key]++
		}
		remaining -= share
	}

	if remaining != 0 {
		return nil, false
	}
	return results, true
}

// preparePlan compares a direct attempt with jointly constructed route sets.
// The set planner accounts for all earlier shards as virtual reservations,
// so atomic siblings cannot unknowingly depend on the same liquidity twice.
func (r *candidateRouter) preparePlan(amt lnwire.MilliSatoshi,
	partsLeft uint32) error {

	r.plan = nil
	if partsLeft == 0 {
		return errors.New("maximum in-flight parts reached")
	}

	var best []*searchResult
	bestMetric := math.Inf(-1)

	direct, directErr := r.findFreshRoute(amt, nil, nil)
	if directErr == nil {
		best = []*searchResult{direct}
		bestMetric = planMetric(best)
	}

	maxParts := int(partsLeft)
	if maxParts > 16 {
		maxParts = 16
	}

	for parts := 2; parts <= maxParts; parts++ {
		results, ok := r.buildPlanForParts(amt, parts)
		if !ok {
			continue
		}

		metric := planMetric(results)
		if metric > bestMetric+0.08 {
			best = results
			bestMetric = metric
		}
	}

	if len(best) == 0 {
		if directErr != nil {
			return directErr
		}
		return errors.New("no route set found")
	}

	r.plan = make([]plannedRoute, len(best))
	for i, result := range best {
		r.plan[i] = plannedRoute{result: result}
	}
	return nil
}

func (r *candidateRouter) issue(result *searchResult) *route.Route {
	addReservations(r.reserved, result.uses)
	r.issued[result.rt] = result.uses
	return result.rt
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum in-flight parts reached")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.plan) > 0 {
		result := r.plan[0].result
		if deliveredAmount(result.rt) <= amt {
			r.plan = r.plan[1:]
			return r.issue(result), nil
		}
		r.plan = nil
	}

	if err := r.preparePlan(amt, partsLeft); err == nil &&
		len(r.plan) > 0 {

		result := r.plan[0].result
		r.plan = r.plan[1:]
		return r.issue(result), nil
	}

	// If joint planning cannot complete the amount, retain a conservative
	// lower-amount escape hatch. It never proposes a shard so small that
	// the currently available atomic slots could not finish the payment.
	if partsLeft <= 1 {
		return nil, errors.New("no route found")
	}

	minShard := (amt + lnwire.MilliSatoshi(partsLeft) - 1) /
		lnwire.MilliSatoshi(partsLeft)
	tryAmt := amt
	if r.retryCeiling > 0 && r.retryCeiling < tryAmt {
		tryAmt = r.retryCeiling
	}
	if tryAmt < minShard {
		tryAmt = minShard
	}

	for tryAmt >= minShard {
		result, err := r.findFreshRoute(tryAmt, nil, nil)
		if err == nil {
			return r.issue(result), nil
		}
		if tryAmt == minShard {
			break
		}

		next := tryAmt * 3 / 5
		if next < minShard {
			next = minShard
		}
		if next == tryAmt {
			break
		}
		tryAmt = next
	}

	return nil, errors.New("no route found")
}

func (r *candidateRouter) saveBelief(key edgeKey,
	b liquidityBelief) {

	r.beliefs[key] = b
	sharedBeliefs.Lock()
	sharedBeliefs.m[key] = b
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) learnSuccess(use edgeUse,
	totalObserved lnwire.MilliSatoshi) {

	key := use.edge.key
	b := r.beliefs[key]

	if totalObserved > b.lowerOK {
		b.lowerOK = totalObserved
	}
	if totalObserved > b.estimate {
		b.estimate = totalObserved
	}
	b.confidence = math.Min(1, b.confidence+0.35)

	// A success is truthful and therefore disproves any ceiling at or
	// below the amount that just passed.
	if b.upper > 0 && totalObserved >= b.upper {
		b.upper = 0
	}
	if b.suspectAmt > 0 && totalObserved >= b.suspectAmt {
		b.suspectAmt = 0
		b.failVotes = 0
		b.lastFailPath = 0
	}

	r.saveBelief(key, b)
}

func (r *candidateRouter) learnFailure(edge *candidateEdge,
	totalObserved lnwire.MilliSatoshi, pathHash uint64) {

	key := edge.key
	b := r.beliefs[key]

	if b.suspectAmt == 0 ||
		totalObserved < b.suspectAmt/2 ||
		totalObserved > b.suspectAmt*2 {

		b.suspectAmt = totalObserved
		b.failVotes = 1
		b.lastFailPath = pathHash
	} else {
		if totalObserved < b.suspectAmt {
			b.suspectAmt = totalObserved
		}
		// Repeated blame on the identical route does not corroborate the
		// reported hop. A second, distinct route does.
		if pathHash != b.lastFailPath && b.failVotes < 255 {
			b.failVotes++
			b.lastFailPath = pathHash
		}
	}

	failedEstimate := totalObserved * 3 / 4
	if b.estimate == 0 {
		b.estimate = failedEstimate
	} else {
		b.estimate = (b.estimate*3 + failedEstimate) / 4
	}
	b.confidence = math.Min(1, b.confidence+0.15)

	if b.failVotes >= 2 {
		if b.upper == 0 || b.suspectAmt < b.upper {
			b.upper = b.suspectAmt
		}
		if b.lowerOK >= b.upper {
			b.lowerOK = 0
		}
	}

	r.saveBelief(key, b)
}

func releaseReservations(reserved map[edgeKey]lnwire.MilliSatoshi,
	uses []edgeUse) {

	for _, use := range uses {
		current := reserved[use.edge.key]
		if current <= use.amount {
			delete(reserved, use.edge.key)
		} else {
			reserved[use.edge.key] = current - use.amount
		}
	}
}

func findFailureNode(rt *route.Route, source route.Vertex) int {
	if source == rt.SourcePubKey {
		return 0
	}
	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}
	return -1
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	uses, ok := r.issued[rt]
	if !ok {
		// The simulator normally returns the same route pointer. Rebuild
		// the edge uses defensively if it returns an equivalent route.
		path := make([]*candidateEdge, 0, len(rt.Hops))
		from := rt.SourcePubKey
		for _, hop := range rt.Hops {
			var found *candidateEdge
			for _, edge := range r.incomingEdges[hop.PubKeyBytes] {
				if edge.from == from && edge.chanID == hop.ChannelID {
					found = edge
					break
				}
			}
			if found == nil {
				break
			}
			path = append(path, found)
			from = hop.PubKeyBytes
		}
		if len(path) == len(rt.Hops) {
			uses = routeUses(rt, path)
		}
	}
	delete(r.issued, rt)

	if result.Failure == nil {
		for _, use := range uses {
			// reserved includes this shard and any prior successful
			// siblings, which is the total liquidity proven to have
			// existed before those reservations.
			r.learnSuccess(use, r.reserved[use.edge.key])
		}
		return nil
	}

	hash := routeHash(rt)
	delivered := deliveredAmount(rt)
	if old, exists := r.tried[hash]; !exists || delivered < old {
		r.tried[hash] = delivered
	}

	// Capture total demand before releasing this failed attempt.
	totalDemand := make(map[edgeKey]lnwire.MilliSatoshi, len(uses))
	for _, use := range uses {
		totalDemand[use.edge.key] = r.reserved[use.edge.key]
	}
	releaseReservations(r.reserved, uses)
	r.plan = nil

	nextCeiling := delivered * 3 / 5
	if nextCeiling > 0 &&
		(r.retryCeiling == 0 || nextCeiling < r.retryCeiling) {

		r.retryCeiling = nextCeiling
	}

	failNode := findFailureNode(rt, result.FailureSource)
	if failNode < 0 {
		// Unreadable attribution is not written to the persistent
		// channel store. The exact failed route is still avoided at this
		// amount through r.tried.
		return nil
	}

	code := result.Failure.Code()
	isLiquidity := code == lnwire.CodeTemporaryChannelFailure

	// A node failure refers to its outgoing channel, whose hop index is
	// the node index. The target has no outgoing channel.
	if failNode >= len(uses) {
		return nil
	}

	primary := failNode
	if isLiquidity {
		use := uses[primary]
		r.penalty[use.edge.key] += 5_000_000
		r.learnFailure(
			use.edge, totalDemand[use.edge.key], hash,
		)

		// Shifted attribution is plausible. Adjacent edges receive only
		// payment-local soft penalties; they never receive persistent
		// hard bounds without being reported directly and corroborated.
		if primary > 0 {
			r.penalty[uses[primary-1].edge.key] += 900_000
		}
		if primary+1 < len(uses) {
			r.penalty[uses[primary+1].edge.key] += 900_000
		}
		return nil
	}

	// Policy failures cannot safely establish a liquidity ceiling,
	// especially when the reported source may have shifted.
	r.penalty[uses[primary].edge.key] += 8_000_000
	if primary > 0 {
		r.penalty[uses[primary-1].edge.key] += 1_000_000
	}
	if primary+1 < len(uses) {
		r.penalty[uses[primary+1].edge.key] += 1_000_000
	}

	return nil
}

