package main

// This file is the CANDIDATE SLOT for evolved routing algorithms. During
// optimization, the entire file is replaced (via go build -overlay) with a
// generated implementation. The contract is a single constructor:
//
//	newCandidateRouter(view, source, localBalances, spec)
//
// returning a routing.SimRouter. The router sees only the public gossip
// graph, its own channel balances and per-attempt feedback — the same
// information a real Lightning sender has. The in-tree implementation below
// is the seed algorithm: a deliberately simple fee-optimizing Dijkstra with
// failure blacklisting and halving-based MPP splitting.

import (
	"container/heap"
	"context"
	"errors"
	"fmt"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

// candidateEdge is one directed edge of the public graph: a channel from
// one node to another, with the policy the sending node announced.
type candidateEdge struct {
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

// fee returns the fee the sending node charges to forward amt over this
// edge.
func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

// usable reports whether the edge can carry the given amount per its
// announced policy.
func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	// The public capacity is a hard upper bound on what can flow.
	return amt <= e.capacity
}

// candidateRouter is the seed algorithm: cheapest-path routing with a
// failure blacklist and amount halving when no route is found.
type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	// incomingEdges maps a node to the directed edges arriving at it,
	// the natural shape for backward Dijkstra.
	incomingEdges map[route.Vertex][]*candidateEdge

	// localBalances is the exact outbound liquidity of our own channels.
	localBalances map[uint64]lnwire.MilliSatoshi

	// failedAmt records, per directed channel, the lowest amount that
	// failed with a liquidity error; routes are built to stay below it.
	failedAmt map[uint64]lnwire.MilliSatoshi

	// shardAmt is the current shard size for MPP splitting.
	shardAmt lnwire.MilliSatoshi

	// partsUsed counts the successful shards so far.
	partsUsed uint32

	// pending maps in-flight attempt ids to their routes.
	pending map[uint64]*route.Route
}

// newCandidateRouter builds the router for one payment. This signature is
// the stable contract between the harness and generated candidates.
func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	router := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		localBalances: localBalances,
		failedAmt:     make(map[uint64]lnwire.MilliSatoshi),
		shardAmt:      spec.Amount,
		pending:       make(map[uint64]*route.Route),
	}

	// Build the adjacency list from gossip. Iterating a node's channels
	// yields, per channel, the policy the OTHER node announced toward us
	// (InPolicy). That is exactly the policy governing the directed edge
	// other -> node, so we record the reversed edge at each visit.
	ctx := context.Background()
	seen := make(map[route.Vertex]bool)
	queue := []route.Vertex{source}
	seen[source] = true

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: pol.FeeBaseMSat,
					feeRatePPM: pol.
						FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				router.incomingEdges[edge.to] = append(
					router.incomingEdges[edge.to], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return router, nil
}

// dijkstraItem is a priority queue entry.
type dijkstraItem struct {
	node route.Vertex
	cost lnwire.MilliSatoshi
	idx  int
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int           { return len(q) }
func (q dijkstraQueue) Less(i, j int) bool { return q[i].cost < q[j].cost }
func (q dijkstraQueue) Swap(i, j int)      { q[i], q[j] = q[j], q[i]; q[i].idx = i; q[j].idx = j }
func (q *dijkstraQueue) Push(x any) {
	item := x.(*dijkstraItem)
	item.idx = len(*q)
	*q = append(*q, item)
}
func (q *dijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

// findRoute computes the cheapest usable path delivering amt to the target,
// walking backward from the target so fees accumulate correctly.
func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi) (*route.Route,
	error) {

	// dist[node] = amount that must arrive at node to deliver amt.
	dist := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)

	dist[r.spec.Target] = amt
	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{node: r.spec.Target, cost: amt})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		node, arriving := item.node, item.cost

		if arriving > dist[node] {
			continue
		}
		if node == r.source {
			break
		}

		// Consider all edges INTO node: for edge u->node, u must
		// send arriving plus u's fee.
		for _, edge := range r.incomingEdges[node] {
			amtOver := arriving

			if !edge.usable(amtOver) {
				continue
			}

			// Skip channels whose liquidity failure bound says
			// this amount cannot pass.
			if bound, ok := r.failedAmt[edge.chanID]; ok &&
				amtOver >= bound {

				continue
			}

			// Our own channels: check exact local balance.
			if edge.from == r.source {
				if r.localBalances[edge.chanID] < amtOver {
					continue
				}
			}

			var sending lnwire.MilliSatoshi
			if edge.from == r.source {
				// We pay no fee to ourselves.
				sending = amtOver
			} else {
				sending = amtOver + edge.fee(amtOver)
			}

			best, ok := dist[edge.from]
			if !ok || sending < best {
				dist[edge.from] = sending
				next[edge.from] = edge
				heap.Push(pq, &dijkstraItem{
					node: edge.from,
					cost: sending,
				})
			}
		}
	}

	if _, ok := dist[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	return r.buildRoute(amt, next)
}

// buildRoute walks the next-pointers from source to target and constructs a
// route with correctly accumulated fees and cltv deltas.
func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	const finalCltvDelta = 40

	// Collect the path edges source -> target.
	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.to
	}

	// Amounts and expiries per channel, computed backward.
	numHops := len(path)
	amtOver := make([]lnwire.MilliSatoshi, numHops)
	expiryOver := make([]uint32, numHops)

	amtOver[numHops-1] = amt
	expiryOver[numHops-1] = finalCltvDelta

	for i := numHops - 2; i >= 0; i-- {
		fwd := path[i+1]
		amtOver[i] = amtOver[i+1] + fwd.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(fwd.timeLockDelta)
	}

	hops := make([]*route.Hop, numHops)
	for i, edge := range path {
		amtToFwd := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < numHops-1 {
			amtToFwd = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     amtToFwd,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

// RequestRoute returns the next route to try: the cheapest path for the
// current shard size, halving the shard when no route exists.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if r.shardAmt > amt {
		r.shardAmt = amt
	}

	for {
		rt, err := r.findRoute(r.shardAmt)
		if err == nil {
			return rt, nil
		}

		// No route at this shard size: split if we're allowed more
		// parts and the shard is still meaningfully large.
		partsLeft := r.spec.MaxParts - inFlightHtlcs
		if partsLeft <= 1 || r.shardAmt < 10_000_000 {
			return nil, err
		}
		r.shardAmt /= 2
	}
}

// ReportAttempt learns from an attempt: liquidity failures set an upper
// bound on the failing channel.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if result.Failure == nil {
		return nil
	}

	// Locate the failing hop and record the amount bound on its
	// outgoing channel.
	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	}
	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == result.FailureSource {
			failIdx = i + 1
		}
	}

	// The failing node could not forward over its outgoing channel,
	// which is rt.Hops[failIdx].
	if failIdx >= 0 && failIdx < len(rt.Hops) {
		hop := rt.Hops[failIdx]
		amtOver := rt.TotalAmount
		if failIdx > 0 {
			amtOver = rt.Hops[failIdx-1].AmtToForward
		}

		bound, ok := r.failedAmt[hop.ChannelID]
		if !ok || amtOver < bound {
			r.failedAmt[hop.ChannelID] = amtOver
		}
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"reflect"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40
	riskWeight     = 0.012
)

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return amt <= e.capacity
}

type liquidityBelief struct {
	lowerOK lnwire.MilliSatoshi

	upperFail lnwire.MilliSatoshi

	suspectUpper lnwire.MilliSatoshi
	failVotes    uint8
}

type sharedKnowledge struct {
	mu      sync.RWMutex
	beliefs map[candidateEdgeKey]*liquidityBelief
}

type knowledgeSlot struct {
	view      routing.SimNetworkView
	knowledge *sharedKnowledge
}

var candidateKnowledgeRegistry = struct {
	sync.Mutex
	slots map[uintptr]*knowledgeSlot
}{
	slots: make(map[uintptr]*knowledgeSlot),
}

func knowledgeForView(view routing.SimNetworkView) *sharedKnowledge {
	value := reflect.ValueOf(view)
	for value.IsValid() && value.Kind() == reflect.Interface {
		value = value.Elem()
	}

	var identity uintptr
	if value.IsValid() {
		switch value.Kind() {
		case reflect.Chan, reflect.Func, reflect.Map, reflect.Ptr,
			reflect.Slice, reflect.UnsafePointer:

			identity = value.Pointer()
		}
	}

	if identity == 0 {
		return &sharedKnowledge{
			beliefs: make(map[candidateEdgeKey]*liquidityBelief),
		}
	}

	candidateKnowledgeRegistry.Lock()
	defer candidateKnowledgeRegistry.Unlock()

	if slot, ok := candidateKnowledgeRegistry.slots[identity]; ok {
		return slot.knowledge
	}

	knowledge := &sharedKnowledge{
		beliefs: make(map[candidateEdgeKey]*liquidityBelief),
	}
	candidateKnowledgeRegistry.slots[identity] = &knowledgeSlot{
		view:      view,
		knowledge: knowledge,
	}

	return knowledge
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.003
	}

	x := float64(amt) / float64(capacity)

	lowMode := 0.48 * math.Exp(-x/0.05)
	highMode := 0.50 / (1 + math.Exp((x-0.92)/0.035))
	p := lowMode + highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func (k *sharedKnowledge) probability(key candidateEdgeKey,
	amt, capacity lnwire.MilliSatoshi) float64 {

	prior := bimodalPrior(amt, capacity)

	k.mu.RLock()
	belief := k.beliefs[key]
	if belief == nil {
		k.mu.RUnlock()
		return prior
	}
	snapshot := *belief
	k.mu.RUnlock()

	if snapshot.lowerOK > 0 && amt <= snapshot.lowerOK {
		return 0.995
	}
	if snapshot.upperFail > 0 && amt >= snapshot.upperFail {
		return 0.003
	}

	p := prior

	if snapshot.lowerOK > 0 && snapshot.upperFail > snapshot.lowerOK &&
		amt > snapshot.lowerOK && amt < snapshot.upperFail {

		position := float64(amt-snapshot.lowerOK) /
			float64(snapshot.upperFail-snapshot.lowerOK)
		bounded := 0.97*(1-position) + 0.03*position
		p = 0.35*prior + 0.65*bounded
	}

	if snapshot.suspectUpper > 0 && amt >= snapshot.suspectUpper {
		p *= 0.18
	}

	if p < 0.003 {
		return 0.003
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

func (k *sharedKnowledge) noteSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	k.mu.Lock()
	defer k.mu.Unlock()

	belief := k.beliefs[key]
	if belief == nil {
		belief = &liquidityBelief{}
		k.beliefs[key] = belief
	}

	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}

	// Successes are trustworthy. They override any contradictory failure
	// attribution, including a previously corroborated but shifted blame.
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}
	if belief.suspectUpper > 0 && amt >= belief.suspectUpper {
		belief.suspectUpper = 0
		belief.failVotes = 0
	}
}

func similarAmounts(a, b lnwire.MilliSatoshi) bool {
	if a <= 0 || b <= 0 {
		return false
	}

	larger, smaller := a, b
	if smaller > larger {
		larger, smaller = smaller, larger
	}

	return float64(smaller)/float64(larger) >= 0.70
}

func (k *sharedKnowledge) noteFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	k.mu.Lock()
	defer k.mu.Unlock()

	belief := k.beliefs[key]
	if belief == nil {
		belief = &liquidityBelief{}
		k.beliefs[key] = belief
	}

	// A new failure below an old success is evidence that liquidity moved.
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	switch {
	case belief.suspectUpper == 0:
		belief.suspectUpper = amt
		belief.failVotes = 1

	case similarAmounts(belief.suspectUpper, amt):
		if amt < belief.suspectUpper {
			belief.suspectUpper = amt
		}
		if belief.failVotes < 255 {
			belief.failVotes++
		}

	case amt < belief.suspectUpper:
		belief.suspectUpper = amt
		belief.failVotes = 1
	}

	// One report is only a suspect observation because failure attribution
	// may be shifted. A second consistent report establishes the bound.
	if belief.failVotes >= 2 {
		if belief.upperFail == 0 ||
			belief.suspectUpper < belief.upperFail {

			belief.upperFail = belief.suspectUpper
		}
	}
}

type edgeUse struct {
	key candidateEdgeKey
	amt lnwire.MilliSatoshi
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi
	knowledge     *sharedKnowledge

	// reserved includes routes already returned during this payment. Failed
	// routes are released; successful routes remain reserved so atomic MPP
	// siblings account for liquidity held by earlier shards.
	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	pending  map[*route.Route][]edgeUse

	// attemptPenalty promotes route diversity without turning unreadable
	// failures into false liquidity bounds.
	attemptPenalty map[candidateEdgeKey]float64

	policyVotes map[candidateEdgeKey]uint8
	policyBlock map[candidateEdgeKey]bool

	lastFailedShard lnwire.MilliSatoshi
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	router := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		knowledge:      knowledgeForView(view),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		pending:        make(map[*route.Route][]edgeUse),
		attemptPenalty: make(map[candidateEdgeKey]float64),
		policyVotes:    make(map[candidateEdgeKey]uint8),
		policyBlock:    make(map[candidateEdgeKey]bool),
	}

	ctx := context.Background()
	seen := make(map[route.Vertex]bool)
	queue := []route.Vertex{source}
	seen[source] = true

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: policy.FeeBaseMSat,
					feeRatePPM: policy.
						FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				router.incomingEdges[node] = append(
					router.incomingEdges[node], edge,
				)
				router.edges[key] = edge
				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return router, nil
}

type candidateLabel struct {
	score  float64
	amount lnwire.MilliSatoshi
}

type candidateQueueItem struct {
	node   route.Vertex
	score  float64
	amount lnwire.MilliSatoshi
}

type candidateQueue []*candidateQueueItem

func (q candidateQueue) Len() int {
	return len(q)
}

func (q candidateQueue) Less(i, j int) bool {
	if q[i].score == q[j].score {
		return q[i].amount < q[j].amount
	}
	return q[i].score < q[j].score
}

func (q candidateQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *candidateQueue) Push(value any) {
	*q = append(*q, value.(*candidateQueueItem))
}

func (q *candidateQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]
	return last
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	reserved := r.reserved[edge.key]
	required := amt + reserved
	if required < amt {
		return 0.003
	}

	if required > edge.capacity {
		return 0.003
	}

	if edge.key.from == r.source {
		if r.localBalances[edge.key.chanID] < required {
			return 0.003
		}
		return 0.999
	}

	return r.knowledge.probability(
		edge.key, required, edge.capacity,
	)
}

func (r *candidateRouter) edgeUsable(edge *candidateEdge,
	amt lnwire.MilliSatoshi) bool {

	if r.policyBlock[edge.key] || !edge.policyAllows(amt) {
		return false
	}

	required := amt + r.reserved[edge.key]
	if required < amt || required > edge.capacity {
		return false
	}

	if edge.key.from == r.source &&
		r.localBalances[edge.key.chanID] < required {

		return false
	}

	return true
}

type candidateRouteChoice struct {
	route   *route.Route
	path    []*candidateEdge
	logProb float64
}

func (r *candidateRouter) findRoute(
	deliver lnwire.MilliSatoshi) (*candidateRouteChoice, error) {

	if deliver <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is payment target")
	}

	labels := make(map[route.Vertex]candidateLabel)
	next := make(map[route.Vertex]*candidateEdge)

	labels[r.spec.Target] = candidateLabel{
		score:  0,
		amount: deliver,
	}

	pq := &candidateQueue{}
	heap.Push(pq, &candidateQueueItem{
		node:   r.spec.Target,
		score:  0,
		amount: deliver,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateQueueItem)
		label, ok := labels[item.node]
		if !ok || item.score > label.score+0.000001 {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOver := item.amount
			if !r.edgeUsable(edge, amtOver) {
				continue
			}

			sending := amtOver
			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
				if fee < 0 || sending > math.MaxInt64-fee {
					continue
				}
				sending += fee
			}

			probability := r.edgeProbability(edge, amtOver)
			if probability < 0.003 {
				probability = 0.003
			}

			riskCost := riskWeight * float64(deliver) *
				(-math.Log(probability))

			// This is deliberately a soft, payment-local diversity cost.
			// It prevents an unreadable failure from retrying the identical
			// path forever without poisoning persistent liquidity beliefs.
			diversityCost := riskWeight * float64(deliver) *
				r.attemptPenalty[edge.key]

			score := item.score + float64(fee) +
				riskCost + diversityCost + 250

			old, exists := labels[edge.key.from]
			if !exists || score < old.score {
				labels[edge.key.from] = candidateLabel{
					score:  score,
					amount: sending,
				}
				next[edge.key.from] = edge
				heap.Push(pq, &candidateQueueItem{
					node:   edge.key.from,
					score:  score,
					amount: sending,
				})
			}
		}
	}

	if _, ok := labels[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.key.to
	}

	rt, err := r.buildRoute(deliver, path)
	if err != nil {
		return nil, err
	}

	logProb := 0.0
	for index, edge := range path {
		amtOver := rt.TotalAmount
		if index > 0 {
			amtOver = rt.Hops[index-1].AmtToForward
		}
		logProb += math.Log(r.edgeProbability(edge, amtOver))
	}

	return &candidateRouteChoice{
		route:   rt,
		path:    path,
		logProb: logProb,
	}, nil
}

func (r *candidateRouter) buildRoute(deliver lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, error) {

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	numHops := len(path)
	amounts := make([]lnwire.MilliSatoshi, numHops)
	expiries := make([]uint32, numHops)

	amounts[numHops-1] = deliver
	expiries[numHops-1] = finalCltvDelta

	for i := numHops - 2; i >= 0; i-- {
		fee := path[i+1].fee(amounts[i+1])
		if fee < 0 || amounts[i+1] > math.MaxInt64-fee {
			return nil, errors.New("route amount overflow")
		}
		amounts[i] = amounts[i+1] + fee
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, numHops)
	for i, edge := range path {
		amountToForward := deliver
		outgoingExpiry := uint32(finalCltvDelta)
		if i < numHops-1 {
			amountToForward = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amountToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func routeDeliveredAmount(rt *route.Route) lnwire.MilliSatoshi {
	if len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func usesForRoute(rt *route.Route) []edgeUse {
	uses := make([]edgeUse, 0, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		amt := rt.TotalAmount
		if i > 0 {
			amt = rt.Hops[i-1].AmtToForward
		}

		uses = append(uses, edgeUse{
			key: candidateEdgeKey{
				chanID: hop.ChannelID,
				from:   from,
				to:     hop.PubKeyBytes,
			},
			amt: amt,
		})
		from = hop.PubKeyBytes
	}

	return uses
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	uses := usesForRoute(rt)
	for _, use := range uses {
		r.reserved[use.key] += use.amt
	}
	r.pending[rt] = uses
}

func (r *candidateRouter) releaseFailedRoute(rt *route.Route) []edgeUse {
	uses, ok := r.pending[rt]
	if !ok {
		return usesForRoute(rt)
	}
	delete(r.pending, rt)

	for _, use := range uses {
		current := r.reserved[use.key]
		if current <= use.amt {
			delete(r.reserved, use.key)
		} else {
			r.reserved[use.key] = current - use.amt
		}
	}

	return uses
}

func appendCandidateAmount(amounts []lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, amount, minimum,
	maximum lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if amount < minimum {
		amount = minimum
	}
	if amount > maximum {
		amount = maximum
	}
	if amount <= 0 || seen[amount] {
		return amounts
	}

	seen[amount] = true
	return append(amounts, amount)
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid payment amount")
	}

	partsLeft := uint32(1)
	if r.spec.MaxParts > inFlightHtlcs {
		partsLeft = r.spec.MaxParts - inFlightHtlcs
	}

	minimum := amt
	if partsLeft > 1 {
		divisor := lnwire.MilliSatoshi(partsLeft)
		minimum = (amt + divisor - 1) / divisor
	}

	seen := make(map[lnwire.MilliSatoshi]bool)
	var amounts []lnwire.MilliSatoshi

	amounts = appendCandidateAmount(amounts, seen, amt, minimum, amt)
	amounts = appendCandidateAmount(
		amounts, seen, amt*7/8, minimum, amt,
	)
	amounts = appendCandidateAmount(
		amounts, seen, amt*3/4, minimum, amt,
	)
	amounts = appendCandidateAmount(
		amounts, seen, amt*2/3, minimum, amt,
	)
	amounts = appendCandidateAmount(
		amounts, seen, amt/2, minimum, amt,
	)
	amounts = appendCandidateAmount(
		amounts, seen, amt/3, minimum, amt,
	)
	amounts = appendCandidateAmount(
		amounts, seen, amt/4, minimum, amt,
	)

	if r.lastFailedShard > 0 {
		amounts = appendCandidateAmount(
			amounts, seen, r.lastFailedShard*7/10,
			minimum, amt,
		)
		amounts = appendCandidateAmount(
			amounts, seen, r.lastFailedShard/2,
			minimum, amt,
		)
	}

	amounts = appendCandidateAmount(
		amounts, seen, minimum, minimum, amt,
	)

	var best *candidateRouteChoice
	bestUtility := math.Inf(-1)

	for _, shard := range amounts {
		choice, err := r.findRoute(shard)
		if err != nil {
			continue
		}

		fee := choice.route.TotalAmount - shard
		feeFraction := float64(fee) /
			math.Max(1, float64(shard))

		// Maximize expected useful progress. The minimum shard constraint
		// guarantees that the remainder can still fit into the available
		// MPP slots, while the probability term naturally selects unequal
		// shards when corridors have different capacities.
		utility := math.Log(float64(shard)) +
			choice.logProb - 2*feeFraction

		if best == nil || utility > bestUtility {
			best = choice
			bestUtility = utility
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	r.reserveRoute(best.route)
	return best.route, nil
}

func failureEdgeIndex(rt *route.Route, source route.Vertex) int {
	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if result.Failure == nil {
		uses, ok := r.pending[rt]
		if !ok {
			uses = usesForRoute(rt)
		} else {
			delete(r.pending, rt)
		}

		for _, use := range uses {
			proven := r.reserved[use.key]
			if proven < use.amt {
				proven = use.amt
			}
			r.knowledge.noteSuccess(use.key, proven)

			r.attemptPenalty[use.key] *= 0.25
			r.policyVotes[use.key] = 0
			delete(r.policyBlock, use.key)
		}

		return nil
	}

	uses := r.releaseFailedRoute(rt)
	r.lastFailedShard = routeDeliveredAmount(rt)

	// Every failed route gets only a soft, local diversity cost. This is
	// safe even when the onion failure is unreadable because it does not
	// become a persistent liquidity claim.
	for _, use := range uses {
		r.attemptPenalty[use.key] += 0.22
	}

	failIndex := failureEdgeIndex(rt, result.FailureSource)
	if failIndex < 0 || failIndex >= len(uses) {
		// The reported source is not an eligible forwarding node on the
		// route. This is explicitly no-information attribution.
		return nil
	}

	failedUse := uses[failIndex]
	required := failedUse.amt + r.reserved[failedUse.key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		// A single plausible attribution is only a suspect observation.
		// Repeated consistent blame promotes it to a strong upper bound.
		r.knowledge.noteFailure(failedUse.key, required)
		r.attemptPenalty[failedUse.key] += 1.15

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		// Shifted blame can also affect policy errors, so require a second
		// observation before excluding the edge for this payment.
		if r.policyVotes[failedUse.key] < 255 {
			r.policyVotes[failedUse.key]++
		}
		r.attemptPenalty[failedUse.key] += 1.5
		if r.policyVotes[failedUse.key] >= 2 {
			r.policyBlock[failedUse.key] = true
		}
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate lnwire.MilliSatoshi
	conf     uint8

	suspectAmt   lnwire.MilliSatoshi
	suspectVotes uint8
}

var candidateBeliefStore = struct {
	sync.Mutex
	beliefs map[candidateEdgeKey]*candidateBelief
}{
	beliefs: make(map[candidateEdgeKey]*candidateBelief),
}

type candidateLocalFailure struct {
	upper lnwire.MilliSatoshi
	count uint8
}

type candidateTraversal struct {
	key  candidateEdgeKey
	edge *candidateEdge
	amt  lnwire.MilliSatoshi
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	reserved    map[candidateEdgeKey]lnwire.MilliSatoshi
	usedTotals  map[candidateEdgeKey]lnwire.MilliSatoshi
	localFails  map[candidateEdgeKey]candidateLocalFailure
	edgePenalty map[candidateEdgeKey]float64

	plannedParts uint32
	failures     uint32
	unknownFails uint32
	retryCap     lnwire.MilliSatoshi
	delivered    lnwire.MilliSatoshi
	settled      bool
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[candidateEdgeKey]*candidateEdge),
		localBalances: localBalances,
		reserved:      make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		usedTotals:    make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		localFails:    make(map[candidateEdgeKey]candidateLocalFailure),
		edgePenalty:   make(map[candidateEdgeKey]float64),
	}

	r.plannedParts = r.initialPartCount(spec.Amount)
	if spec.MaxParts != 0 && r.plannedParts > spec.MaxParts {
		r.plannedParts = spec.MaxParts
	}
	if r.plannedParts == 0 {
		r.plannedParts = 1
	}

	ctx := context.Background()
	seen := make(map[route.Vertex]bool)
	queue := []route.Vertex{source}
	seen[source] = true

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[key] = edge
				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func (r *candidateRouter) initialPartCount(
	amt lnwire.MilliSatoshi) uint32 {

	switch {
	case amt <= 25_000_000:
		return 1
	case amt <= 250_000_000:
		return 4
	case amt <= 1_000_000_000:
		return 6
	case amt <= 2_000_000_000:
		return 8
	default:
		return 12
	}
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.003
	}

	x := float64(amt) / float64(capacity)

	// A compact bimodal prior: a small low-balance mode that decays
	// quickly, and a high-balance mode with a cliff near capacity.
	lowMode := 0.48 * math.Exp(-x/0.025)
	highMode := 0.50 / (1 + math.Exp((x-0.90)/0.025))
	p := 0.005 + lowMode + highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func candidateLogisticProbability(amt, estimate,
	capacity lnwire.MilliSatoshi) float64 {

	if capacity <= 0 {
		return 0.005
	}

	scale := 0.07 * float64(capacity)
	if scale < 1 {
		scale = 1
	}
	z := (float64(amt) - float64(estimate)) / scale
	if z > 30 {
		return 0.005
	}
	if z < -30 {
		return 0.995
	}
	return 1 / (1 + math.Exp(z))
}

func (r *candidateRouter) edgeProbability(e *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	required := amt + r.reserved[e.key]
	if required > e.capacity {
		return 0.001
	}

	// Our own outgoing balance is exact and should not be overridden by
	// noisy remote failure attribution.
	if e.key.from == r.source {
		if r.localBalances[e.key.chanID] < required {
			return 0.001
		}
		return 0.999
	}

	p := candidatePrior(required, e.capacity)

	candidateBeliefStore.Lock()
	b, ok := candidateBeliefStore.beliefs[e.key]
	var belief candidateBelief
	if ok {
		belief = *b
	}
	candidateBeliefStore.Unlock()

	if ok {
		if belief.estimate > 0 && belief.conf > 0 {
			q := candidateLogisticProbability(
				required, belief.estimate, e.capacity,
			)
			weight := 0.14 * float64(belief.conf)
			if weight > 0.70 {
				weight = 0.70
			}
			p = (1-weight)*p + weight*q
		}

		if belief.lowerOK > 0 && required <= belief.lowerOK {
			p = math.Max(p, 0.995)
		}

		if belief.upperFail > 0 {
			switch {
			case required >= belief.upperFail:
				p = math.Min(p, 0.008)

			case belief.lowerOK > 0 &&
				belief.upperFail > belief.lowerOK:

				span := float64(
					belief.upperFail - belief.lowerOK,
				)
				pos := float64(
					required - belief.lowerOK,
				) / span
				if pos > 0 {
					bounded := 0.995*(1-pos) + 0.008*pos
					p = 0.35*p + 0.65*bounded
				}
			}
		}
	}

	if local, ok := r.localFails[e.key]; ok &&
		required >= local.upper {

		if local.count >= 2 {
			p = math.Min(p, 0.004)
		} else {
			// A single attribution is only a suspect observation.
			// It strongly encourages a different route without turning
			// a shifted blame report into a permanent blacklist.
			p *= 0.08
		}
	}

	if p < 0.003 {
		return 0.003
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

func (r *candidateRouter) edgeCost(e *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	p := r.edgeProbability(e, amt)
	cost := -math.Log(p) + 0.01 + r.edgePenalty[e.key]

	if reserved := r.reserved[e.key]; reserved > 0 &&
		e.capacity > 0 {

		cost += 0.04 +
			0.35*float64(reserved)/float64(e.capacity)
	}

	return cost
}

type candidateDijkstraItem struct {
	node  route.Vertex
	score float64
	amt   lnwire.MilliSatoshi
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *candidateDijkstraQueue) Push(x any) {
	*q = append(*q, x.(*candidateDijkstraItem))
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}

	score := make(map[route.Vertex]float64)
	arriving := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)

	score[r.spec.Target] = 0
	arriving[r.spec.Target] = amt

	pq := &candidateDijkstraQueue{}
	heap.Push(pq, &candidateDijkstraItem{
		node: r.spec.Target,
		amt:  amt,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)
		bestScore, ok := score[item.node]
		if !ok || item.score > bestScore+1e-12 {
			continue
		}
		if item.amt != arriving[item.node] {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOver := item.amt
			if !edge.policyAllows(amtOver) {
				continue
			}

			required := amtOver + r.reserved[edge.key]
			if required > edge.capacity {
				continue
			}
			if edge.key.from == r.source &&
				r.localBalances[edge.key.chanID] < required {

				continue
			}

			sending := amtOver
			feeCost := 0.0
			if edge.key.from != r.source {
				fee := edge.fee(amtOver)
				sending += fee

				denom := float64(amt)
				if denom < 1 {
					denom = 1
				}
				feeCost = 18 * float64(fee) / denom
			}

			newScore := item.score +
				r.edgeCost(edge, amtOver) + feeCost

			oldScore, exists := score[edge.key.from]
			if exists && newScore >= oldScore {
				continue
			}

			score[edge.key.from] = newScore
			arriving[edge.key.from] = sending
			next[edge.key.from] = edge
			heap.Push(pq, &candidateDijkstraItem{
				node:  edge.key.from,
				score: newScore,
				amt:   sending,
			})
		}
	}

	if _, ok := score[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}

	pathProbability := 1.0
	for _, traversal := range r.routeTraversals(rt) {
		pathProbability *= r.edgeProbability(
			traversal.edge, traversal.amt,
		)
	}

	return rt, pathProbability, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateCeilDiv(amt lnwire.MilliSatoshi,
	parts uint32) lnwire.MilliSatoshi {

	if parts <= 1 {
		return amt
	}
	divisor := lnwire.MilliSatoshi(parts)
	return (amt + divisor - 1) / divisor
}

func (r *candidateRouter) targetPartCount() uint32 {
	target := r.plannedParts

	// Failure feedback opens spare part slots gradually. This keeps the
	// initial route set compact while allowing smaller lower-bound
	// retries when a corridor proves depleted.
	target += r.failures / 2
	if r.unknownFails >= 2 {
		target++
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if target > maxParts {
		target = maxParts
	}
	if target == 0 {
		target = 1
	}
	return target
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum parts already in flight")
	}
	partsLeft := maxParts - inFlightHtlcs
	minimumShard := candidateCeilDiv(amt, partsLeft)

	var wholeRoute *route.Route
	if rt, probability, err := r.findRoute(amt); err == nil {
		wholeRoute = rt

		// Whole-payment routing is retained when the path is already
		// well-supported by tiny-amount priors or truthful successes.
		if r.failures == 0 &&
			(r.plannedParts == 1 || probability >= 0.75) {

			return rt, nil
		}
	}

	targetParts := r.targetPartCount()
	var desiredSlots uint32
	if targetParts > inFlightHtlcs {
		desiredSlots = targetParts - inFlightHtlcs
	} else {
		desiredSlots = 1
	}
	if desiredSlots > partsLeft {
		desiredSlots = partsLeft
	}
	if desiredSlots == 0 {
		desiredSlots = 1
	}

	shard := candidateCeilDiv(amt, desiredSlots)
	if r.retryCap > 0 && r.retryCap < shard {
		shard = r.retryCap
	}
	if shard < minimumShard {
		shard = minimumShard
	}
	if shard > amt {
		shard = amt
	}

	for {
		rt, _, err := r.findRoute(shard)
		if err == nil {
			return rt, nil
		}

		if shard <= minimumShard {
			if wholeRoute != nil && shard != amt {
				return wholeRoute, nil
			}
			return nil, err
		}

		nextShard := shard * 2 / 3
		if nextShard < minimumShard {
			nextShard = minimumShard
		}
		if nextShard == shard {
			nextShard--
		}
		shard = nextShard
	}
}

func (r *candidateRouter) routeTraversals(
	rt *route.Route) []candidateTraversal {

	traversals := make([]candidateTraversal, 0, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		key := candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		edge := r.edges[key]
		if edge == nil {
			from = hop.PubKeyBytes
			continue
		}

		amt := rt.TotalAmount
		if i > 0 {
			amt = rt.Hops[i-1].AmtToForward
		}
		traversals = append(traversals, candidateTraversal{
			key:  key,
			edge: edge,
			amt:  amt,
		})
		from = hop.PubKeyBytes
	}

	return traversals
}

func candidateDeliveredAmount(rt *route.Route) lnwire.MilliSatoshi {
	if len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func (r *candidateRouter) recordSuccess(rt *route.Route) {
	traversals := r.routeTraversals(rt)

	candidateBeliefStore.Lock()
	for _, traversal := range traversals {
		required := traversal.amt + r.reserved[traversal.key]
		b := candidateBeliefStore.beliefs[traversal.key]
		if b == nil {
			b = &candidateBelief{}
			candidateBeliefStore.beliefs[traversal.key] = b
		}

		if required > b.lowerOK {
			b.lowerOK = required
		}

		highEstimate := traversal.edge.capacity * 88 / 100
		if required > highEstimate {
			highEstimate = required
		}
		if highEstimate > b.estimate {
			b.estimate = highEstimate
		}
		if b.conf < 8 {
			b.conf++
		}

		// Truthful success invalidates any conflicting attribution.
		if b.upperFail > 0 && required >= b.upperFail {
			b.upperFail = 0
		}
		if b.suspectAmt > 0 && required >= b.suspectAmt {
			b.suspectAmt = 0
			b.suspectVotes = 0
		}
	}
	candidateBeliefStore.Unlock()

	for _, traversal := range traversals {
		required := traversal.amt + r.reserved[traversal.key]
		if local, ok := r.localFails[traversal.key]; ok &&
			required >= local.upper {

			delete(r.localFails, traversal.key)
		}

		r.reserved[traversal.key] += traversal.amt
		r.usedTotals[traversal.key] += traversal.amt
	}

	r.delivered += candidateDeliveredAmount(rt)
	if r.delivered >= r.spec.Amount && !r.settled {
		r.recordSettlement()
		r.settled = true
	}
}

func (r *candidateRouter) recordSettlement() {
	candidateBeliefStore.Lock()
	defer candidateBeliefStore.Unlock()

	for key, used := range r.usedTotals {
		if used <= 0 {
			continue
		}

		if b := candidateBeliefStore.beliefs[key]; b != nil {
			if b.lowerOK > used {
				b.lowerOK -= used
			} else {
				b.lowerOK = 0
			}
			if b.estimate > used {
				b.estimate -= used
			} else {
				b.estimate = 0
			}
			if b.upperFail > used {
				b.upperFail -= used
			} else {
				b.upperFail = 0
			}
			if b.suspectAmt > used {
				b.suspectAmt -= used
			} else {
				b.suspectAmt = 0
				b.suspectVotes = 0
			}
		}

		reverse := candidateEdgeKey{
			chanID: key.chanID,
			from:   key.to,
			to:     key.from,
		}
		reverseBelief := candidateBeliefStore.beliefs[reverse]
		if reverseBelief == nil {
			reverseBelief = &candidateBelief{}
			candidateBeliefStore.beliefs[reverse] = reverseBelief
		}

		reverseCapacity := lnwire.MilliSatoshi(0)
		if edge := r.edges[reverse]; edge != nil {
			reverseCapacity = edge.capacity
		} else if edge := r.edges[key]; edge != nil {
			reverseCapacity = edge.capacity
		}

		reverseBelief.lowerOK += used
		reverseBelief.estimate += used
		if reverseCapacity > 0 {
			if reverseBelief.lowerOK > reverseCapacity {
				reverseBelief.lowerOK = reverseCapacity
			}
			if reverseBelief.estimate > reverseCapacity {
				reverseBelief.estimate = reverseCapacity
			}
		}
		if reverseBelief.upperFail > 0 {
			reverseBelief.upperFail += used
			if reverseCapacity > 0 &&
				reverseBelief.upperFail > reverseCapacity {

				reverseBelief.upperFail = reverseCapacity
			}
		}
	}
}

func (r *candidateRouter) failureEdge(rt *route.Route,
	source route.Vertex) (candidateTraversal, bool) {

	traversals := r.routeTraversals(rt)
	if len(traversals) != len(rt.Hops) {
		return candidateTraversal{}, false
	}

	index := -1
	if source == rt.SourcePubKey {
		index = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == source {
				index = i + 1
				break
			}
		}
	}

	if index < 0 || index >= len(traversals) {
		return candidateTraversal{}, false
	}
	return traversals[index], true
}

func (r *candidateRouter) recordAttributedLiquidityFailure(
	traversal candidateTraversal) {

	required := traversal.amt + r.reserved[traversal.key]

	local := r.localFails[traversal.key]
	if local.upper == 0 || required < local.upper {
		local.upper = required
	}
	if local.count < 255 {
		local.count++
	}
	r.localFails[traversal.key] = local
	r.edgePenalty[traversal.key] += 1.25

	// Exact local balances outrank a shifted remote attribution.
	if traversal.key.from == r.source {
		return
	}

	candidateBeliefStore.Lock()
	defer candidateBeliefStore.Unlock()

	b := candidateBeliefStore.beliefs[traversal.key]
	if b == nil {
		b = &candidateBelief{}
		candidateBeliefStore.beliefs[traversal.key] = b
	}

	if b.suspectVotes == 0 {
		b.suspectAmt = required
		b.suspectVotes = 1
		return
	}

	if required < b.suspectAmt || b.suspectAmt == 0 {
		b.suspectAmt = required
	}
	if b.suspectVotes < 255 {
		b.suspectVotes++
	}

	// Two independent reports promote a suspect to a soft upper bound.
	// It remains routable at a very low probability so drift or a pair
	// of shifted reports cannot permanently poison the channel.
	if b.suspectVotes >= 2 {
		if b.upperFail == 0 || b.suspectAmt < b.upperFail {
			b.upperFail = b.suspectAmt
		}

		failedEstimate := required * 70 / 100
		if b.estimate == 0 || failedEstimate < b.estimate {
			b.estimate = failedEstimate
		}
		if b.conf < 8 {
			b.conf++
		}
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64,
	rt *route.Route, result routing.SimHtlcResult) error {

	if result.Failure == nil {
		r.retryCap = 0
		r.recordSuccess(rt)
		return nil
	}

	r.failures++
	traversals := r.routeTraversals(rt)
	for _, traversal := range traversals {
		r.edgePenalty[traversal.key] += 0.03
	}

	code := result.Failure.Code()
	if code == lnwire.CodeTemporaryChannelFailure {
		if traversal, ok := r.failureEdge(
			rt, result.FailureSource,
		); ok {
			r.recordAttributedLiquidityFailure(traversal)

			delivered := candidateDeliveredAmount(rt)
			if delivered > 1 {
				r.retryCap = delivered * 62 / 100
			}
			return nil
		}
	}

	// An off-route source carries no channel information. Route-wide
	// penalties only diversify the next attempt and never enter the
	// persistent liquidity store.
	r.unknownFails++
	for _, traversal := range traversals {
		r.edgePenalty[traversal.key] += 0.15
	}

	if code == lnwire.CodeFeeInsufficient ||
		code == lnwire.CodeIncorrectCltvExpiry {

		if traversal, ok := r.failureEdge(
			rt, result.FailureSource,
		); ok {
			r.edgePenalty[traversal.key] += 2.0
		}
	}

	if r.unknownFails%2 == 0 {
		delivered := candidateDeliveredAmount(rt)
		if delivered > 1 {
			r.retryCap = delivered * 72 / 100
		}
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	conf      uint8

	suspectAmt   lnwire.MilliSatoshi
	suspectVotes uint8
}

var candidateBeliefStore = struct {
	sync.Mutex
	beliefs map[candidateEdgeKey]*candidateBelief
}{
	beliefs: make(map[candidateEdgeKey]*candidateBelief),
}

type candidateLocalFailure struct {
	upper lnwire.MilliSatoshi
	count uint8
}

type candidateTraversal struct {
	key  candidateEdgeKey
	edge *candidateEdge
	amt  lnwire.MilliSatoshi
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	reserved    map[candidateEdgeKey]lnwire.MilliSatoshi
	usedTotals  map[candidateEdgeKey]lnwire.MilliSatoshi
	localFails  map[candidateEdgeKey]candidateLocalFailure
	edgePenalty map[candidateEdgeKey]float64
	policyFails map[candidateEdgeKey]uint8

	plannedParts uint32
	failures     uint32
	unknownFails uint32
	requestNo    uint64
	searchSalt   uint64
	retryCap     lnwire.MilliSatoshi
	delivered    lnwire.MilliSatoshi
	settled      bool
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[candidateEdgeKey]*candidateEdge),
		localBalances: localBalances,
		reserved:      make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		usedTotals:    make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		localFails:    make(map[candidateEdgeKey]candidateLocalFailure),
		edgePenalty:   make(map[candidateEdgeKey]float64),
		policyFails:   make(map[candidateEdgeKey]uint8),
	}

	r.plannedParts = r.initialPartCount(spec.Amount)
	if spec.MaxParts != 0 && r.plannedParts > spec.MaxParts {
		r.plannedParts = spec.MaxParts
	}
	if r.plannedParts == 0 {
		r.plannedParts = 1
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[key] = edge

				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func (r *candidateRouter) initialPartCount(
	amt lnwire.MilliSatoshi) uint32 {

	switch {
	case amt <= 20_000_000:
		return 1
	case amt <= 100_000_000:
		return 2
	case amt <= 400_000_000:
		return 4
	case amt <= 1_000_000_000:
		return 6
	case amt <= 3_000_000_000:
		return 10
	default:
		if r.spec.MaxParts != 0 {
			return r.spec.MaxParts
		}
		return 12
	}
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.003
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.48 * math.Exp(-x/0.025)
	highMode := 0.50 / (1 + math.Exp((x-0.90)/0.025))
	p := 0.005 + lowMode + highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func candidateLogisticProbability(amt, estimate,
	capacity lnwire.MilliSatoshi) float64 {

	if capacity <= 0 {
		return 0.005
	}

	scale := 0.065 * float64(capacity)
	if scale < 1 {
		scale = 1
	}

	z := (float64(amt) - float64(estimate)) / scale
	switch {
	case z > 30:
		return 0.005
	case z < -30:
		return 0.995
	default:
		return 1 / (1 + math.Exp(z))
	}
}

func (r *candidateRouter) edgeProbability(e *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	required := amt + r.reserved[e.key]
	if required > e.capacity {
		return 0.001
	}

	if e.key.from == r.source {
		if r.localBalances[e.key.chanID] < required {
			return 0.001
		}
		return 0.999
	}

	p := candidatePrior(required, e.capacity)

	candidateBeliefStore.Lock()
	stored, ok := candidateBeliefStore.beliefs[e.key]
	var belief candidateBelief
	if ok {
		belief = *stored
	}
	candidateBeliefStore.Unlock()

	if ok {
		if belief.estimate > 0 && belief.conf > 0 {
			q := candidateLogisticProbability(
				required, belief.estimate, e.capacity,
			)
			weight := 0.11 * float64(belief.conf)
			if weight > 0.62 {
				weight = 0.62
			}
			p = (1-weight)*p + weight*q
		}

		if belief.lowerOK > 0 && required <= belief.lowerOK {
			p = math.Max(p, 0.997)
		}

		if belief.upperFail > 0 {
			switch {
			case required >= belief.upperFail:
				p = math.Min(p, 0.025)

			case belief.lowerOK > 0 &&
				belief.upperFail > belief.lowerOK &&
				required > belief.lowerOK:

				span := float64(
					belief.upperFail - belief.lowerOK,
				)
				pos := float64(
					required - belief.lowerOK,
				) / span
				bounded := 0.997*(1-pos) + 0.025*pos
				p = 0.45*p + 0.55*bounded
			}
		}
	}

	if local, exists := r.localFails[e.key]; exists &&
		required >= local.upper {

		if local.count >= 3 {
			p *= 0.06
		} else if local.count == 2 {
			p *= 0.15
		} else {
			p *= 0.38
		}
	}

	if p < 0.003 {
		return 0.003
	}
	if p > 0.997 {
		return 0.997
	}
	return p
}

func candidateEdgeHash(key candidateEdgeKey, salt uint64) float64 {
	h := key.chanID ^ salt ^ 0x9e3779b97f4a7c15
	for _, b := range key.from {
		h ^= uint64(b)
		h *= 0x100000001b3
	}
	for _, b := range key.to {
		h ^= uint64(b) + 0x9d
		h *= 0x100000001b3
	}

	h ^= h >> 30
	h *= 0xbf58476d1ce4e5b9
	h ^= h >> 27
	h *= 0x94d049bb133111eb
	h ^= h >> 31

	return float64(h>>11) / float64(uint64(1)<<53)
}

func (r *candidateRouter) edgeCost(e *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	p := r.edgeProbability(e, amt)
	cost := -math.Log(p) + 0.01 + r.edgePenalty[e.key]

	if reserved := r.reserved[e.key]; reserved > 0 &&
		e.capacity > 0 {

		cost += 0.85 +
			1.20*float64(reserved)/float64(e.capacity)
	}

	if r.failures > 0 {
		exploration := 0.10 + 0.025*float64(r.failures)
		if exploration > 0.70 {
			exploration = 0.70
		}
		cost += exploration * candidateEdgeHash(
			e.key, r.searchSalt,
		)
	}

	return cost
}

type candidateLabel struct {
	node     route.Vertex
	score    float64
	amt      lnwire.MilliSatoshi
	nextEdge *candidateEdge
	next     *candidateLabel
	active   bool
}

type candidateLabelQueue []*candidateLabel

func (q candidateLabelQueue) Len() int {
	return len(q)
}

func (q candidateLabelQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateLabelQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *candidateLabelQueue) Push(x any) {
	*q = append(*q, x.(*candidateLabel))
}

func (q *candidateLabelQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func candidateLabelContains(label *candidateLabel,
	node route.Vertex) bool {

	for current := label; current != nil; current = current.next {
		if current.node == node {
			return true
		}
	}
	return false
}

func candidateAddLabel(labels map[route.Vertex][]*candidateLabel,
	label *candidateLabel) bool {

	existing := labels[label.node]
	activeCount := 0

	for _, old := range existing {
		if !old.active {
			continue
		}
		activeCount++

		if old.score <= label.score && old.amt <= label.amt {
			return false
		}
	}

	for _, old := range existing {
		if !old.active {
			continue
		}
		if label.score <= old.score && label.amt <= old.amt {
			old.active = false
			activeCount--
		}
	}

	if activeCount >= 10 {
		var worst *candidateLabel
		for _, old := range existing {
			if !old.active {
				continue
			}
			if worst == nil || old.score > worst.score {
				worst = old
			}
		}
		if worst != nil && worst.score <= label.score {
			return false
		}
		if worst != nil {
			worst.active = false
		}
	}

	label.active = true
	labels[label.node] = append(existing, label)
	return true
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}

	target := &candidateLabel{
		node:   r.spec.Target,
		score:  0,
		amt:    amt,
		active: true,
	}
	labels := map[route.Vertex][]*candidateLabel{
		r.spec.Target: {target},
	}
	pq := &candidateLabelQueue{}
	heap.Push(pq, target)

	var sourceLabel *candidateLabel

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateLabel)
		if !item.active {
			continue
		}
		if item.node == r.source {
			sourceLabel = item
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if candidateLabelContains(item, edge.key.from) {
				continue
			}

			amtOver := item.amt
			if !edge.policyAllows(amtOver) {
				continue
			}

			required := amtOver + r.reserved[edge.key]
			if required > edge.capacity {
				continue
			}
			if edge.key.from == r.source &&
				r.localBalances[edge.key.chanID] < required {

				continue
			}

			sending := amtOver
			feeCost := 0.0
			if edge.key.from != r.source {
				fee := edge.fee(amtOver)
				sending += fee

				denom := float64(amt)
				if denom < 1 {
					denom = 1
				}
				feeCost = 16 * float64(fee) / denom
			}

			label := &candidateLabel{
				node:     edge.key.from,
				score:    item.score + r.edgeCost(edge, amtOver) + feeCost,
				amt:      sending,
				nextEdge: edge,
				next:     item,
			}
			if candidateAddLabel(labels, label) {
				heap.Push(pq, label)
			}
		}
	}

	if sourceLabel == nil {
		return nil, 0, errors.New("no route found")
	}

	path := make([]*candidateEdge, 0, 8)
	for label := sourceLabel; label.nextEdge != nil; label = label.next {
		path = append(path, label.nextEdge)
	}

	rt, err := r.buildRoute(amt, path)
	if err != nil {
		return nil, 0, err
	}

	probability := 1.0
	for _, traversal := range r.routeTraversals(rt) {
		probability *= r.edgeProbability(
			traversal.edge, traversal.amt,
		)
	}

	return rt, probability, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, error) {

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateCeilDiv(amt lnwire.MilliSatoshi,
	parts uint32) lnwire.MilliSatoshi {

	if parts <= 1 {
		return amt
	}
	divisor := lnwire.MilliSatoshi(parts)
	return (amt + divisor - 1) / divisor
}

func (r *candidateRouter) targetPartCount() uint32 {
	target := r.plannedParts + (r.failures+1)/2
	if r.unknownFails >= 2 {
		target++
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if target > maxParts {
		target = maxParts
	}
	if target == 0 {
		target = 1
	}
	return target
}

func candidateAppendAmount(amounts []lnwire.MilliSatoshi,
	amt, minimum, maximum lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if amt < minimum {
		amt = minimum
	}
	if amt > maximum {
		amt = maximum
	}
	if amt <= 0 {
		return amounts
	}

	for _, existing := range amounts {
		if existing == amt {
			return amounts
		}
	}
	return append(amounts, amt)
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum parts already in flight")
	}

	r.requestNo++
	r.searchSalt = r.requestNo*0x9e3779b97f4a7c15 +
		uint64(r.failures)*0xbf58476d1ce4e5b9

	partsLeft := maxParts - inFlightHtlcs
	minimumShard := candidateCeilDiv(amt, partsLeft)

	wholeRoute, wholeProbability, wholeErr := r.findRoute(amt)
	if wholeErr == nil && r.failures == 0 {
		if maxParts == 1 || r.plannedParts == 1 ||
			wholeProbability >= 0.90 {

			return wholeRoute, nil
		}
	}

	targetParts := r.targetPartCount()
	desiredSlots := uint32(1)
	if targetParts > inFlightHtlcs {
		desiredSlots = targetParts - inFlightHtlcs
	}
	if desiredSlots > partsLeft {
		desiredSlots = partsLeft
	}

	base := candidateCeilDiv(amt, desiredSlots)
	maximum := amt
	if r.retryCap > 0 && r.retryCap < maximum {
		maximum = r.retryCap
	}
	if maximum < minimumShard {
		maximum = minimumShard
	}
	if base > maximum {
		base = maximum
	}
	if base < minimumShard {
		base = minimumShard
	}

	amounts := make([]lnwire.MilliSatoshi, 0, 7)
	amounts = candidateAppendAmount(
		amounts, base, minimumShard, maximum,
	)
	amounts = candidateAppendAmount(
		amounts, minimumShard, minimumShard, maximum,
	)
	amounts = candidateAppendAmount(
		amounts, (minimumShard+base)/2,
		minimumShard, maximum,
	)
	amounts = candidateAppendAmount(
		amounts, base*5/4, minimumShard, maximum,
	)
	amounts = candidateAppendAmount(
		amounts, base*3/2, minimumShard, maximum,
	)
	amounts = candidateAppendAmount(
		amounts, base*2, minimumShard, maximum,
	)
	amounts = candidateAppendAmount(
		amounts, maximum, minimumShard, maximum,
	)

	var bestRoute *route.Route
	bestScore := math.Inf(-1)
	var lastErr error

	for _, shard := range amounts {
		rt, probability, err := r.findRoute(shard)
		if err != nil {
			lastErr = err
			continue
		}

		if probability < 0.0000001 {
			probability = 0.0000001
		}

		progress := float64(shard) / float64(base)
		if progress < 0.0000001 {
			progress = 0.0000001
		}

		delivered := candidateDeliveredAmount(rt)
		feeRatio := 0.0
		if delivered > 0 && rt.TotalAmount > delivered {
			feeRatio = float64(rt.TotalAmount-delivered) /
				float64(delivered)
		}

		score := math.Log(probability) +
			0.18*math.Log(progress) - 4*feeRatio

		if score > bestScore {
			bestScore = score
			bestRoute = rt
		}
	}

	if bestRoute != nil {
		return bestRoute, nil
	}
	if wholeRoute != nil {
		return wholeRoute, nil
	}
	if lastErr != nil {
		return nil, lastErr
	}
	return nil, wholeErr
}

func (r *candidateRouter) routeTraversals(
	rt *route.Route) []candidateTraversal {

	traversals := make([]candidateTraversal, 0, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		key := candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		edge := r.edges[key]
		if edge == nil {
			from = hop.PubKeyBytes
			continue
		}

		amt := rt.TotalAmount
		if i > 0 {
			amt = rt.Hops[i-1].AmtToForward
		}

		traversals = append(traversals, candidateTraversal{
			key:  key,
			edge: edge,
			amt:  amt,
		})
		from = hop.PubKeyBytes
	}

	return traversals
}

func candidateDeliveredAmount(rt *route.Route) lnwire.MilliSatoshi {
	if len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func (r *candidateRouter) recordSuccess(rt *route.Route) {
	traversals := r.routeTraversals(rt)

	candidateBeliefStore.Lock()
	for _, traversal := range traversals {
		required := traversal.amt + r.reserved[traversal.key]
		belief := candidateBeliefStore.beliefs[traversal.key]
		if belief == nil {
			belief = &candidateBelief{}
			candidateBeliefStore.beliefs[traversal.key] = belief
		}

		if required > belief.lowerOK {
			belief.lowerOK = required
		}

		estimate := traversal.edge.capacity * 90 / 100
		if required > estimate {
			estimate = required
		}
		if estimate > belief.estimate {
			belief.estimate = estimate
		}
		if belief.conf < 8 {
			belief.conf++
		}

		if belief.upperFail > 0 &&
			required >= belief.upperFail {

			belief.upperFail = 0
		}
		if belief.suspectAmt > 0 &&
			required >= belief.suspectAmt {

			belief.suspectAmt = 0
			belief.suspectVotes = 0
		}
	}
	candidateBeliefStore.Unlock()

	for _, traversal := range traversals {
		required := traversal.amt + r.reserved[traversal.key]
		if local, ok := r.localFails[traversal.key]; ok &&
			required >= local.upper {

			delete(r.localFails, traversal.key)
		}

		r.edgePenalty[traversal.key] *= 0.25
		r.policyFails[traversal.key] = 0
		r.reserved[traversal.key] += traversal.amt
		r.usedTotals[traversal.key] += traversal.amt
	}

	r.delivered += candidateDeliveredAmount(rt)
	if r.delivered >= r.spec.Amount && !r.settled {
		r.recordSettlement()
		r.settled = true
	}
}

func (r *candidateRouter) recordSettlement() {
	candidateBeliefStore.Lock()
	defer candidateBeliefStore.Unlock()

	for key, used := range r.usedTotals {
		if used <= 0 {
			continue
		}

		if belief := candidateBeliefStore.beliefs[key]; belief != nil {
			if belief.lowerOK > used {
				belief.lowerOK -= used
			} else {
				belief.lowerOK = 0
			}
			if belief.estimate > used {
				belief.estimate -= used
			} else {
				belief.estimate = 0
			}
			if belief.upperFail > used {
				belief.upperFail -= used
			} else {
				belief.upperFail = 0
			}
			if belief.suspectAmt > used {
				belief.suspectAmt -= used
			} else {
				belief.suspectAmt = 0
				belief.suspectVotes = 0
			}
		}

		reverse := candidateEdgeKey{
			chanID: key.chanID,
			from:   key.to,
			to:     key.from,
		}
		reverseBelief := candidateBeliefStore.beliefs[reverse]
		if reverseBelief == nil {
			reverseBelief = &candidateBelief{}
			candidateBeliefStore.beliefs[reverse] = reverseBelief
		}

		capacity := lnwire.MilliSatoshi(0)
		if edge := r.edges[reverse]; edge != nil {
			capacity = edge.capacity
		} else if edge := r.edges[key]; edge != nil {
			capacity = edge.capacity
		}

		reverseBelief.lowerOK += used
		reverseBelief.estimate += used
		if capacity > 0 {
			if reverseBelief.lowerOK > capacity {
				reverseBelief.lowerOK = capacity
			}
			if reverseBelief.estimate > capacity {
				reverseBelief.estimate = capacity
			}
		}

		if reverseBelief.upperFail > 0 {
			reverseBelief.upperFail += used
			if capacity > 0 &&
				reverseBelief.upperFail > capacity {

				reverseBelief.upperFail = capacity
			}
		}
	}
}

func (r *candidateRouter) failureEdge(rt *route.Route,
	source route.Vertex) (candidateTraversal, bool) {

	traversals := r.routeTraversals(rt)
	if len(traversals) != len(rt.Hops) {
		return candidateTraversal{}, false
	}

	index := -1
	if source == rt.SourcePubKey {
		index = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == source {
				index = i + 1
				break
			}
		}
	}

	if index < 0 || index >= len(traversals) {
		return candidateTraversal{}, false
	}
	return traversals[index], true
}

func (r *candidateRouter) recordAttributedLiquidityFailure(
	traversal candidateTraversal) {

	required := traversal.amt + r.reserved[traversal.key]

	if traversal.key.from != r.source {
		local := r.localFails[traversal.key]
		if local.upper == 0 || required < local.upper {
			local.upper = required
		}
		if local.count < 255 {
			local.count++
		}
		r.localFails[traversal.key] = local
		r.edgePenalty[traversal.key] += 0.75
	} else {
		r.edgePenalty[traversal.key] += 0.20
		return
	}

	candidateBeliefStore.Lock()
	defer candidateBeliefStore.Unlock()

	belief := candidateBeliefStore.beliefs[traversal.key]
	if belief == nil {
		belief = &candidateBelief{}
		candidateBeliefStore.beliefs[traversal.key] = belief
	}

	if belief.suspectVotes == 0 {
		belief.suspectAmt = required
		belief.suspectVotes = 1
		return
	}

	if belief.suspectAmt == 0 || required < belief.suspectAmt {
		belief.suspectAmt = required
	}
	if belief.suspectVotes < 255 {
		belief.suspectVotes++
	}

	votesNeeded := uint8(2)
	if belief.lowerOK > 0 &&
		belief.suspectAmt <= belief.lowerOK {

		votesNeeded = 3
	}

	if belief.suspectVotes < votesNeeded {
		return
	}

	if belief.lowerOK > 0 &&
		belief.suspectAmt <= belief.lowerOK {

		if belief.suspectAmt > 1 {
			belief.lowerOK = belief.suspectAmt - 1
		} else {
			belief.lowerOK = 0
		}
	}

	if belief.upperFail == 0 ||
		belief.suspectAmt < belief.upperFail {

		belief.upperFail = belief.suspectAmt
	}

	failedEstimate := belief.suspectAmt * 65 / 100
	if belief.estimate == 0 || failedEstimate < belief.estimate {
		belief.estimate = failedEstimate
	}
	if belief.conf < 8 {
		belief.conf++
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64,
	rt *route.Route, result routing.SimHtlcResult) error {

	if result.Failure == nil {
		r.retryCap = 0
		r.recordSuccess(rt)
		return nil
	}

	r.failures++
	traversals := r.routeTraversals(rt)
	for _, traversal := range traversals {
		r.edgePenalty[traversal.key] += 0.10
	}

	code := result.Failure.Code()
	if code == lnwire.CodeTemporaryChannelFailure {
		if traversal, ok := r.failureEdge(
			rt, result.FailureSource,
		); ok {
			r.recordAttributedLiquidityFailure(traversal)

			delivered := candidateDeliveredAmount(rt)
			if delivered > 1 {
				factor := lnwire.MilliSatoshi(70)
				if local := r.localFails[traversal.key]; local.count >= 2 {
					factor = 58
				}
				r.retryCap = delivered * factor / 100
			}
			return nil
		}
	}

	r.unknownFails++
	for _, traversal := range traversals {
		r.edgePenalty[traversal.key] += 0.24
	}

	if code == lnwire.CodeFeeInsufficient ||
		code == lnwire.CodeIncorrectCltvExpiry {

		if traversal, ok := r.failureEdge(
			rt, result.FailureSource,
		); ok {
			count := r.policyFails[traversal.key]
			if count < 255 {
				count++
			}
			r.policyFails[traversal.key] = count

			if count >= 2 {
				r.edgePenalty[traversal.key] += 8.0
			} else {
				r.edgePenalty[traversal.key] += 2.5
			}
		}
	}

	if r.unknownFails%2 == 0 {
		delivered := candidateDeliveredAmount(rt)
		if delivered > 1 {
			r.retryCap = delivered * 72 / 100
		}
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	chanID  uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

// Beliefs are directed. A success is trustworthy, while a reported failure
// must be corroborated before it becomes a hard upper bound.
type candidateBelief struct {
	lowerOK lnwire.MilliSatoshi

	upperFail lnwire.MilliSatoshi

	suspectAmt   lnwire.MilliSatoshi
	suspectVotes uint8

	stamp uint64
}

var candidateMemory = struct {
	sync.Mutex
	epoch   uint64
	beliefs map[candidateEdgeKey]candidateBelief
}{
	beliefs: make(map[candidateEdgeKey]candidateBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec
	epoch  uint64

	incomingEdges map[route.Vertex][]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[candidateEdgeKey]candidateBelief

	// reserved is liquidity consumed or held by successful shards of the
	// current payment. It prevents atomic-MPP siblings from assuming that
	// the same corridor's liquidity is still entirely available.
	reserved map[candidateEdgeKey]lnwire.MilliSatoshi

	// Per-payment soft penalties encourage route diversity without turning
	// an unreadable failure into false channel-level knowledge.
	edgePenalty map[candidateEdgeKey]float64

	retryLimit lnwire.MilliSatoshi
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	candidateMemory.Lock()
	candidateMemory.epoch++
	epoch := candidateMemory.epoch

	snapshot := make(map[candidateEdgeKey]candidateBelief,
		len(candidateMemory.beliefs))
	for key, belief := range candidateMemory.beliefs {
		snapshot[key] = belief
	}
	candidateMemory.Unlock()

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		epoch:         epoch,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		localBalances: localBalances,
		beliefs:       snapshot,
		reserved:      make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		edgePenalty:   make(map[candidateEdgeKey]float64),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
					},
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: policy.FeeBaseMSat,
					feeRatePPM: policy.
						FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func candidateClampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005
	case p > 0.995:
		return 0.995
	default:
		return p
	}
}

// candidatePrior models a channel as roughly half nearly empty and half
// nearly full. Tiny transfers can fit in either mode, medium transfers
// mostly require the full mode, and transfers near capacity encounter a
// steep cliff.
func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.025)
	highMode := 1 / (1 + math.Exp(18*(x-0.82)))

	return candidateClampProbability(0.5*lowMode + 0.5*highMode)
}

func (r *candidateRouter) evidenceConfidence(b candidateBelief) float64 {
	if b.stamp == 0 || r.epoch <= b.stamp+3 {
		return 1
	}

	age := float64(r.epoch - b.stamp - 3)
	return math.Max(0.12, math.Exp(-age/12))
}

func (r *candidateRouter) probability(edge *candidateEdge,
	totalAmt lnwire.MilliSatoshi) float64 {

	if edge.from == r.source {
		available := r.localBalances[edge.chanID]
		if totalAmt <= available {
			return 0.999
		}
		return 0.001
	}

	prior := candidatePrior(totalAmt, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok || belief.stamp == 0 {
		return prior
	}

	learned := prior

	switch {
	case belief.lowerOK > 0 && totalAmt <= belief.lowerOK:
		learned = 0.995

	case belief.upperFail > 0 &&
		totalAmt >= belief.upperFail:

		learned = 0.008

	case belief.lowerOK > 0 && belief.upperFail > belief.lowerOK:
		span := float64(belief.upperFail - belief.lowerOK)
		pos := float64(totalAmt-belief.lowerOK) / span
		pos = math.Max(0, math.Min(1, pos))
		learned = 0.995*(1-pos) + 0.008*pos

	case belief.lowerOK > 0 && totalAmt > belief.lowerOK:
		ratio := float64(belief.lowerOK) / float64(totalAmt)
		learned = prior + (0.995-prior)*ratio*ratio

	case belief.upperFail > 0 && totalAmt < belief.upperFail:
		ratio := float64(totalAmt) / float64(belief.upperFail)
		learned = prior * (1 - 0.75*ratio*ratio)
	}

	// One uncorroborated blame is only a soft hint. This is deliberately
	// insufficient to exclude a channel because attribution can be shifted.
	if belief.upperFail == 0 && belief.suspectAmt > 0 &&
		totalAmt >= belief.suspectAmt {

		learned *= 0.55
	}

	confidence := r.evidenceConfidence(belief)
	p := confidence*learned + (1-confidence)*prior

	return candidateClampProbability(p)
}

func (r *candidateRouter) hardFailed(edge *candidateEdge,
	totalAmt lnwire.MilliSatoshi) bool {

	belief, ok := r.beliefs[edge.key]
	if !ok || belief.upperFail == 0 {
		return false
	}

	// Recent corroborated evidence is a bound. Old evidence merely affects
	// probability because background traffic may have moved liquidity.
	return r.evidenceConfidence(belief) >= 0.72 &&
		totalAmt >= belief.upperFail
}

type candidateItem struct {
	node  route.Vertex
	score float64
}

type candidateQueue []*candidateItem

func (q candidateQueue) Len() int {
	return len(q)
}

func (q candidateQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *candidateQueue) Push(value any) {
	*q = append(*q, value.(*candidateItem))
}

func (q *candidateQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]
	return last
}

type candidatePath struct {
	route       *route.Route
	edges       []*candidateEdge
	probability float64
	pressure    float64
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*candidatePath, error) {

	if amt <= 0 {
		return nil, errors.New("invalid payment amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is target")
	}

	scores := make(map[route.Vertex]float64)
	amounts := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)

	scores[r.spec.Target] = 0
	amounts[r.spec.Target] = amt

	pq := &candidateQueue{}
	heap.Push(pq, &candidateItem{
		node:  r.spec.Target,
		score: 0,
	})

	for pq.Len() != 0 {
		item := heap.Pop(pq).(*candidateItem)
		bestScore, ok := scores[item.node]
		if !ok || item.score > bestScore+1e-12 {
			continue
		}
		if item.node == r.source {
			break
		}

		arriving := amounts[item.node]

		for _, edge := range r.incomingEdges[item.node] {
			if !edge.usable(arriving) {
				continue
			}

			totalLiquidity := arriving + r.reserved[edge.key]
			if totalLiquidity < arriving ||
				totalLiquidity > edge.capacity {

				continue
			}

			if edge.from == r.source {
				if totalLiquidity >
					r.localBalances[edge.chanID] {

					continue
				}
			} else if r.hardFailed(edge, totalLiquidity) {
				continue
			}

			sending := arriving
			fee := lnwire.MilliSatoshi(0)
			if edge.from != r.source {
				fee = edge.fee(arriving)
				sending += fee
				if sending < arriving {
					continue
				}
			}

			probability := r.probability(edge, totalLiquidity)
			edgeCost := -math.Log(probability) + 0.025
			if arriving > 0 {
				edgeCost += 5 * float64(fee) /
					float64(arriving)
			}
			edgeCost += r.edgePenalty[edge.key]

			newScore := item.score + edgeCost
			oldScore, visited := scores[edge.from]
			if visited && newScore >= oldScore {
				continue
			}

			scores[edge.from] = newScore
			amounts[edge.from] = sending
			next[edge.from] = edge
			heap.Push(pq, &candidateItem{
				node:  edge.from,
				score: newScore,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	rt, path, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, err
	}

	probability := 1.0
	pressure := 0.0

	for i, edge := range path {
		amtOver := candidateRouteAmount(rt, i)
		totalLiquidity := amtOver + r.reserved[edge.key]

		probability *= r.probability(edge, totalLiquidity)

		denominator := edge.capacity
		if edge.from == r.source {
			denominator = r.localBalances[edge.chanID]
		} else if belief, ok := r.beliefs[edge.key]; ok &&
			belief.upperFail > 0 &&
			r.evidenceConfidence(belief) >= 0.72 &&
			belief.upperFail < denominator {

			denominator = belief.upperFail
		}

		if denominator > 0 {
			ratio := float64(totalLiquidity) /
				float64(denominator)
			if ratio > pressure {
				pressure = ratio
			}
		}
	}

	return &candidatePath{
		route:       rt,
		edges:       path,
		probability: probability,
		pressure:    pressure,
	}, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route,
	[]*candidateEdge, error) {

	const finalCltvDelta = uint32(40)

	var path []*candidateEdge
	seen := make(map[route.Vertex]bool)
	for node := r.source; node != r.spec.Target; {
		if seen[node] {
			return nil, nil, errors.New("cycle in route")
		}
		seen[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.to
	}

	if len(path) == 0 {
		return nil, nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := finalCltvDelta

		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, path, nil
}

func candidateCeilDiv(a lnwire.MilliSatoshi,
	b uint32) lnwire.MilliSatoshi {

	if b <= 1 {
		return a
	}
	divisor := lnwire.MilliSatoshi(b)
	return (a + divisor - 1) / divisor
}

// RequestRoute commits large payments in a small route set when a single
// route is near its capacity cliff. Failed channels remain eligible at a
// lower amount rather than being permanently blacklisted.
func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid remaining amount")
	}

	partsLeft := uint32(1)
	if r.spec.MaxParts > inFlightHtlcs {
		partsLeft = r.spec.MaxParts - inFlightHtlcs
	}

	// The last available part must cover the entire remainder.
	if partsLeft <= 1 {
		path, err := r.findRoute(amt)
		if err != nil {
			return nil, err
		}
		return path.route, nil
	}

	if r.retryLimit == 0 {
		full, fullErr := r.findRoute(amt)

		// Small or low-pressure payments are best sent without needless
		// splitting. Learned high-confidence paths are also tried whole.
		if fullErr == nil &&
			(amt < 50_000_000 ||
				full.pressure < 0.30 ||
				full.probability >= 0.70) {

			return full.route, nil
		}

		numParts := uint32(2)
		if fullErr != nil {
			numParts = 4
		} else {
			numParts = uint32(math.Ceil(
				full.pressure / 0.28,
			))
			if numParts < 2 {
				numParts = 2
			}
			if numParts > 4 {
				numParts = 4
			}
		}
		if numParts > partsLeft {
			numParts = partsLeft
		}

		r.retryLimit = candidateCeilDiv(amt, numParts)
	}

	desired := r.retryLimit
	if desired <= 0 || desired > amt {
		desired = amt
	}

	const minimumShard = lnwire.MilliSatoshi(1_000_000)
	var lastErr error

	for {
		path, err := r.findRoute(desired)
		if err == nil {
			return path.route, nil
		}
		lastErr = err

		if desired <= minimumShard {
			return nil, lastErr
		}

		smaller := desired * 72 / 100
		if smaller < minimumShard {
			smaller = minimumShard
		}
		if smaller >= desired {
			return nil, lastErr
		}

		desired = smaller
		r.retryLimit = smaller
	}
}

func candidateRouteAmount(rt *route.Route,
	edgeIndex int) lnwire.MilliSatoshi {

	if edgeIndex == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[edgeIndex-1].AmtToForward
}

func candidateRouteEdgeKey(rt *route.Route,
	edgeIndex int) candidateEdgeKey {

	from := rt.SourcePubKey
	if edgeIndex > 0 {
		from = rt.Hops[edgeIndex-1].PubKeyBytes
	}

	return candidateEdgeKey{
		chanID: rt.Hops[edgeIndex].ChannelID,
		from:   from,
	}
}

func candidateFailureEdge(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func candidateIsLiquidityFailure(failure any) bool {
	switch failure.(type) {
	case *lnwire.FailTemporaryChannelFailure:
		return true
	default:
		return false
	}
}

func candidateIsPolicyFailure(failure any) bool {
	switch failure.(type) {
	case *lnwire.FailFeeInsufficient,
		*lnwire.FailIncorrectCltvExpiry:

		return true
	default:
		return false
	}
}

func (r *candidateRouter) saveBelief(
	key candidateEdgeKey, belief candidateBelief) {

	belief.stamp = r.epoch
	r.beliefs[key] = belief

	candidateMemory.Lock()
	candidateMemory.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) recordSuccess(key candidateEdgeKey,
	totalAmt lnwire.MilliSatoshi) {

	belief := r.beliefs[key]

	if totalAmt > belief.lowerOK {
		belief.lowerOK = totalAmt
	}

	// A truthful success disproves any ceiling at or below this amount.
	if belief.upperFail > 0 && totalAmt >= belief.upperFail {
		belief.upperFail = 0
	}
	if belief.suspectAmt > 0 && totalAmt >= belief.suspectAmt {
		belief.suspectAmt = 0
		belief.suspectVotes = 0
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) recordFailure(key candidateEdgeKey,
	totalAmt lnwire.MilliSatoshi) {

	belief := r.beliefs[key]

	corroborates := false
	if belief.suspectAmt > 0 {
		low := belief.suspectAmt * 60 / 100
		high := belief.suspectAmt * 150 / 100
		corroborates = totalAmt >= low && totalAmt <= high
	}

	if corroborates {
		if belief.suspectVotes < 255 {
			belief.suspectVotes++
		}
		if totalAmt < belief.suspectAmt {
			belief.suspectAmt = totalAmt
		}
	} else {
		belief.suspectAmt = totalAmt
		belief.suspectVotes = 1
	}

	requiredVotes := uint8(2)
	if belief.lowerOK > 0 && totalAmt <= belief.lowerOK {
		// Contradicting a truthful success requires extra evidence. This
		// may still happen after genuine liquidity drift.
		requiredVotes = 3
	}

	if belief.suspectVotes >= requiredVotes {
		if totalAmt <= belief.lowerOK {
			belief.lowerOK = 0
		}

		if belief.upperFail == 0 ||
			belief.suspectAmt < belief.upperFail {

			belief.upperFail = belief.suspectAmt
		}
	}

	r.saveBelief(key, belief)
}

// ReportAttempt uses successes as hard evidence. Liquidity blame is first
// quarantined as a soft observation and becomes a bound only after another
// compatible failure. Unreadable failures never modify liquidity beliefs.
func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if rt == nil || len(rt.Hops) == 0 {
		return nil
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key := candidateRouteEdgeKey(rt, i)
			amtOver := candidateRouteAmount(rt, i)
			totalAmt := amtOver + r.reserved[key]

			r.recordSuccess(key, totalAmt)
			r.reserved[key] += amtOver
			r.edgePenalty[key] *= 0.35
		}

		r.retryLimit = 0
		return nil
	}

	// Every failed route receives only a small, capped diversity penalty.
	// This is useful even when the onion error cannot be read, but is much
	// weaker than channel-level liquidity evidence.
	for i := range rt.Hops {
		key := candidateRouteEdgeKey(rt, i)
		r.edgePenalty[key] = math.Min(
			3, r.edgePenalty[key]+0.08,
		)
	}

	failIndex := candidateFailureEdge(
		rt, result.FailureSource,
	)
	attributed := failIndex >= 0 && failIndex < len(rt.Hops)

	if candidateIsLiquidityFailure(result.Failure) && attributed {
		key := candidateRouteEdgeKey(rt, failIndex)
		amtOver := candidateRouteAmount(rt, failIndex)
		totalAmt := amtOver + r.reserved[key]

		r.recordFailure(key, totalAmt)
		r.edgePenalty[key] = math.Min(
			6, r.edgePenalty[key]+0.9,
		)

		delivered := rt.Hops[len(rt.Hops)-1].AmtToForward
		lowerRetry := delivered * 72 / 100
		if lowerRetry < 1_000_000 {
			lowerRetry = 1_000_000
		}
		r.retryLimit = lowerRetry

		return nil
	}

	if candidateIsPolicyFailure(result.Failure) && attributed {
		key := candidateRouteEdgeKey(rt, failIndex)
		r.edgePenalty[key] = math.Min(
			6, r.edgePenalty[key]+1.5,
		)
	}

	// Unknown and policy failures should try another route at the same
	// delivered amount rather than being mistaken for liquidity ceilings.
	r.retryLimit = 0
	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type directedKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      directedKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return amt <= e.capacity
}

type liquidityBelief struct {
	capacity lnwire.MilliSatoshi

	// Truthful successes establish a lower bound. Corroborated failures
	// establish an upper bound.
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi

	// Estimate expresses the bimodal interpretation of observations:
	// success suggests the high-liquidity mode, while repeated failure
	// suggests the depleted mode.
	estimate lnwire.MilliSatoshi
	evidence uint32

	// A first attributed failure is only a suspect observation. This
	// avoids turning one shifted attribution into a hard bound.
	suspectAmt lnwire.MilliSatoshi
	failVotes  uint32
}

var sharedBeliefs = struct {
	sync.Mutex
	m map[directedKey]liquidityBelief
}{
	m: make(map[directedKey]liquidityBelief),
}

type amountPenalty struct {
	amount lnwire.MilliSatoshi
	weight float64
}

type edgeUse struct {
	key    directedKey
	amount lnwire.MilliSatoshi
	from   route.Vertex
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[directedKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[directedKey]*liquidityBelief

	// Reservations include attempts already handed to the runner. Failed
	// attempts release them; successful shards retain them so atomic MPP
	// siblings cannot assume the same liquidity is still free.
	reserved map[directedKey]lnwire.MilliSatoshi
	pending  map[*route.Route][]edgeUse

	// Per-payment penalties promptly diversify after a failure without
	// permanently poisoning knowledge from a single shifted attribution.
	penalties map[directedKey]amountPenalty

	retryCap lnwire.MilliSatoshi
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	if spec == nil {
		return nil, errors.New("nil payment specification")
	}

	balances := make(map[uint64]lnwire.MilliSatoshi, len(localBalances))
	for chanID, balance := range localBalances {
		balances[chanID] = balance
	}

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[directedKey]*candidateEdge),
		localBalances: balances,
		beliefs:       make(map[directedKey]*liquidityBelief),
		reserved:      make(map[directedKey]lnwire.MilliSatoshi),
		pending:       make(map[*route.Route][]edgeUse),
		penalties:     make(map[directedKey]amountPenalty),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				key := directedKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, exists := r.edges[key]; exists {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: pol.FeeBaseMSat,
					feeRatePPM: pol.
						FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.edges[key] = edge
				r.incomingEdges[key.to] = append(
					r.incomingEdges[key.to], edge,
				)

				sharedBeliefs.Lock()
				b, ok := sharedBeliefs.m[key]
				sharedBeliefs.Unlock()

				if !ok {
					b.capacity = edge.capacity
				} else if b.capacity != edge.capacity {
					b.capacity = edge.capacity
					if b.lowerOK > edge.capacity {
						b.lowerOK = edge.capacity
					}
					if b.upperFail > edge.capacity {
						b.upperFail = edge.capacity
					}
					if b.estimate > edge.capacity {
						b.estimate = edge.capacity
					}
				}
				copy := b
				r.beliefs[key] = &copy

				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func clampProbability(p float64) float64 {
	switch {
	case p < 0.002:
		return 0.002
	case p > 0.995:
		return 0.995
	default:
		return p
	}
}

// bimodalPrior models a channel as a mixture of a narrow depleted mode and
// a broad high-liquidity mode. Tiny HTLCs can fit in either mode, ordinary
// HTLCs mostly require the favorable side, and amounts near capacity face
// a steep cliff.
func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.002
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.44 * math.Exp(-x/0.025)
	highMode := 0.54 / (1 + math.Exp((x-0.90)/0.055))

	return clampProbability(lowMode + highMode)
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	reserved := r.reserved[edge.key]
	demand := amt + reserved
	if demand < amt {
		return 0.002
	}

	if edge.key.from == r.source {
		if demand > r.localBalances[edge.key.chanID] {
			return 0.002
		}
		return 0.995
	}

	if demand > edge.capacity {
		return 0.002
	}

	b := r.beliefs[edge.key]
	if b == nil {
		return bimodalPrior(demand, edge.capacity)
	}

	if b.lowerOK > 0 && demand <= b.lowerOK {
		return 0.995
	}
	if b.upperFail > 0 && demand >= b.upperFail {
		return 0.002
	}

	prior := bimodalPrior(demand, edge.capacity)
	p := prior

	if b.lowerOK > 0 && b.upperFail > b.lowerOK {
		span := float64(b.upperFail - b.lowerOK)
		pos := float64(demand-b.lowerOK) / span
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}
		bounded := 0.995*(1-pos) + 0.002*pos
		p = 0.25*prior + 0.75*bounded
	} else if b.evidence > 0 && b.estimate > 0 {
		width := math.Max(float64(edge.capacity)*0.10, 1)
		estimated := 1 / (1 + math.Exp(
			(float64(demand)-float64(b.estimate))/width,
		))
		p = 0.35*prior + 0.65*estimated
	}

	// One uncorroborated attribution is deliberately soft. It affects
	// route ordering but cannot make a channel impossible.
	if b.failVotes == 1 && b.suspectAmt > 0 {
		ratio := float64(demand) / float64(b.suspectAmt)
		switch {
		case ratio >= 0.85:
			p *= 0.55
		case ratio > 0:
			p *= 1 - 0.45*ratio*ratio
		}
	}

	return clampProbability(p)
}

func (r *candidateRouter) penaltyFor(key directedKey,
	amt lnwire.MilliSatoshi) float64 {

	p, ok := r.penalties[key]
	if !ok || p.amount <= 0 {
		return 0
	}

	ratio := float64(amt) / float64(p.amount)
	if ratio >= 0.80 {
		return p.weight
	}
	if ratio <= 0 {
		return 0
	}

	// A failed large HTLC is much weaker evidence against a materially
	// smaller retry.
	return p.weight * ratio * ratio
}

type dijkstraItem struct {
	node    route.Vertex
	amount  lnwire.MilliSatoshi
	score   float64
	logRisk float64
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(x any) {
	*q = append(*q, x.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

type routeChoice struct {
	route       *route.Route
	probability float64
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*routeChoice, error) {

	if amt <= 0 {
		return nil, errors.New("non-positive route amount")
	}

	dist := make(map[route.Vertex]float64)
	arrival := make(map[route.Vertex]lnwire.MilliSatoshi)
	risk := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)

	dist[r.spec.Target] = 0
	arrival[r.spec.Target] = amt
	risk[r.spec.Target] = 0

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node:   r.spec.Target,
		amount: amt,
	})

	riskScale := math.Max(25_000, float64(amt)*0.012)

	for pq.Len() != 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		best, ok := dist[item.node]
		if !ok || item.score > best+0.0001 {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOver := item.amount
			if !edge.policyAllows(amtOver) {
				continue
			}

			demand := amtOver + r.reserved[edge.key]
			if demand < amtOver || demand > edge.capacity {
				continue
			}
			if edge.key.from == r.source &&
				demand > r.localBalances[edge.key.chanID] {

				continue
			}

			prob := r.edgeProbability(edge, amtOver)
			edgeRisk := -math.Log(prob)
			localPenalty := r.penaltyFor(edge.key, demand)

			sending := amtOver
			if edge.key.from != r.source {
				sending += edge.fee(amtOver)
			}
			if sending < amtOver {
				continue
			}

			feeCost := float64(sending - amtOver)
			score := item.score + feeCost + 1_000 +
				riskScale*(edgeRisk+localPenalty)
			logRisk := item.logRisk + edgeRisk

			old, exists := dist[edge.key.from]
			if exists && score >= old {
				continue
			}

			dist[edge.key.from] = score
			arrival[edge.key.from] = sending
			risk[edge.key.from] = logRisk
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:    edge.key.from,
				amount:  sending,
				score:   score,
				logRisk: logRisk,
			})
		}
	}

	if _, ok := arrival[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, err
	}

	logRisk := risk[r.source]
	if logRisk > 700 {
		logRisk = 700
	}

	return &routeChoice{
		route:       rt,
		probability: math.Exp(-logRisk),
	}, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("cycle in selected route")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		outgoing := path[i+1]
		amtOver[i] = amtOver[i+1] +
			outgoing.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func routeUses(rt *route.Route) []edgeUse {
	if rt == nil {
		return nil
	}

	uses := make([]edgeUse, 0, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		amt := rt.TotalAmount
		if i > 0 {
			amt = rt.Hops[i-1].AmtToForward
		}

		uses = append(uses, edgeUse{
			key: directedKey{
				chanID: hop.ChannelID,
				from:   from,
				to:     hop.PubKeyBytes,
			},
			amount: amt,
			from:   from,
		})
		from = hop.PubKeyBytes
	}

	return uses
}

func (r *candidateRouter) reserve(rt *route.Route) {
	uses := routeUses(rt)
	for _, use := range uses {
		r.reserved[use.key] += use.amount
	}
	r.pending[rt] = uses
}

func (r *candidateRouter) release(rt *route.Route) {
	uses, ok := r.pending[rt]
	if !ok {
		return
	}

	for _, use := range uses {
		current := r.reserved[use.key]
		if use.amount >= current {
			delete(r.reserved, use.key)
		} else {
			r.reserved[use.key] = current - use.amount
		}
	}
	delete(r.pending, rt)
}

func (r *candidateRouter) handOut(choice *routeChoice) (*route.Route, error) {
	if choice == nil || choice.route == nil {
		return nil, errors.New("no route found")
	}
	r.reserve(choice.route)
	return choice.route, nil
}

func ceilDivide(amt lnwire.MilliSatoshi,
	parts uint32) lnwire.MilliSatoshi {

	if parts <= 1 {
		return amt
	}
	divisor := lnwire.MilliSatoshi(parts)
	return amt/divisor + lnwire.MilliSatoshi(
		amt%divisor != 0,
	)
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}

	partsLeft := uint32(1)
	if r.spec.MaxParts > inFlightHtlcs {
		partsLeft = r.spec.MaxParts - inFlightHtlcs
	}

	// With one slot left, the route must carry the full remainder.
	if partsLeft <= 1 {
		choice, err := r.findRoute(amt)
		if err != nil {
			return nil, err
		}
		r.retryCap = 0
		return r.handOut(choice)
	}

	var desired lnwire.MilliSatoshi

	if r.retryCap > 0 {
		desired = r.retryCap
		if desired > amt {
			desired = amt
		}
		r.retryCap = 0
	} else if inFlightHtlcs > 0 {
		// Once an atomic set is being assembled, deliberately fill the
		// remaining slots instead of probing a long halving ladder.
		desired = ceilDivide(amt, partsLeft)
	} else {
		full, err := r.findRoute(amt)
		if err == nil && full.probability >= 0.35 {
			return r.handOut(full)
		}

		// Pick an up-front shard count from the full-route confidence.
		// Highly uncertain long paths use more parallel corridors.
		shards := partsLeft
		if err == nil {
			switch {
			case full.probability >= 0.08:
				shards = 2
			case full.probability >= 0.015:
				shards = 4
			}
			if shards > partsLeft {
				shards = partsLeft
			}
		}
		desired = ceilDivide(amt, shards)
	}

	if desired <= 0 {
		desired = 1
	}

	tried := make(map[lnwire.MilliSatoshi]bool)
	try := func(candidate lnwire.MilliSatoshi) (*routeChoice, error) {
		if candidate <= 0 || candidate > amt || tried[candidate] {
			return nil, errors.New("amount already tried")
		}
		tried[candidate] = true
		return r.findRoute(candidate)
	}

	if choice, err := try(desired); err == nil {
		return r.handOut(choice)
	}

	// A small HTLC may violate min-HTLC policies even where a larger one
	// is routable. Check larger deliberate allocations before descending.
	if desired < amt {
		mid := desired + (amt-desired)/2
		if choice, err := try(mid); err == nil {
			return r.handOut(choice)
		}
		if choice, err := try(amt); err == nil {
			return r.handOut(choice)
		}
	}

	// Retry failed corridors at materially smaller amounts. Unlike a hard
	// blacklist, this can discover the depleted side's remaining low-mode
	// liquidity.
	candidate := desired
	for i := 0; i < 14 && candidate > 1; i++ {
		candidate = candidate * 62 / 100
		if candidate < 1 {
			candidate = 1
		}
		if choice, err := try(candidate); err == nil {
			return r.handOut(choice)
		}
	}

	return nil, errors.New("no route found")
}

func (r *candidateRouter) persist(key directedKey) {
	b := r.beliefs[key]
	if b == nil {
		return
	}

	sharedBeliefs.Lock()
	sharedBeliefs.m[key] = *b
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) recordSuccess(use edgeUse) {
	if use.from == r.source {
		return
	}

	b := r.beliefs[use.key]
	edge := r.edges[use.key]
	if b == nil || edge == nil {
		return
	}

	proven := use.amount
	if total := r.reserved[use.key]; total > proven {
		proven = total
	}
	if proven > edge.capacity {
		proven = edge.capacity
	}

	if proven > b.lowerOK {
		b.lowerOK = proven
	}

	highEstimate := proven +
		lnwire.MilliSatoshi(
			0.65*float64(edge.capacity-proven),
		)
	if highEstimate > b.estimate {
		b.estimate = highEstimate
	}
	if b.estimate > edge.capacity {
		b.estimate = edge.capacity
	}
	b.evidence++

	// A truthful success at or above a suspected/failed amount refutes
	// that observation completely.
	if b.upperFail > 0 && proven >= b.upperFail {
		b.upperFail = 0
	}
	if b.suspectAmt > 0 && proven >= b.suspectAmt {
		b.suspectAmt = 0
		b.failVotes = 0
	}

	if p, ok := r.penalties[use.key]; ok && proven >= p.amount {
		delete(r.penalties, use.key)
	}

	r.persist(use.key)
}

func (r *candidateRouter) addFailurePenalty(key directedKey,
	amount lnwire.MilliSatoshi, weight float64) {

	old := r.penalties[key]
	if old.amount == 0 || amount < old.amount {
		old.amount = amount
	}
	old.weight += weight
	if old.weight > 12 {
		old.weight = 12
	}
	r.penalties[key] = old
}

func (r *candidateRouter) recordAttributedFailure(use edgeUse,
	effectiveAmount lnwire.MilliSatoshi) {

	if use.from == r.source {
		return
	}

	b := r.beliefs[use.key]
	edge := r.edges[use.key]
	if b == nil || edge == nil {
		return
	}

	r.addFailurePenalty(use.key, effectiveAmount, 2.8)

	if b.failVotes == 0 {
		b.failVotes = 1
		b.suspectAmt = effectiveAmount
		r.persist(use.key)
		return
	}

	b.failVotes++
	if b.suspectAmt == 0 || effectiveAmount < b.suspectAmt {
		b.suspectAmt = effectiveAmount
	}

	// Only corroborated attribution becomes a hard upper bound.
	bound := b.suspectAmt
	if b.upperFail == 0 || bound < b.upperFail {
		b.upperFail = bound
	}
	if b.lowerOK >= b.upperFail {
		// Success is truthful, so contradictory failure attribution must
		// not erase the proven lower bound.
		b.upperFail = 0
		b.failVotes = 1
		b.suspectAmt = effectiveAmount
		r.persist(use.key)
		return
	}

	depletedEstimate := effectiveAmount / 4
	if b.estimate == 0 || depletedEstimate < b.estimate {
		b.estimate = depletedEstimate
	}
	b.evidence++
	r.persist(use.key)
}

func (r *candidateRouter) failureUse(rt *route.Route,
	source route.Vertex) (edgeUse, bool) {

	uses := routeUses(rt)
	if len(uses) == 0 {
		return edgeUse{}, false
	}

	failIdx := -1
	if source == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == source {
				failIdx = i + 1
				break
			}
		}
	}

	if failIdx < 0 || failIdx >= len(uses) {
		return edgeUse{}, false
	}
	return uses[failIdx], true
}

// An unreadable failure only proves that something on the route failed.
// Apply a small, payment-local penalty to the route's least convincing
// non-local edge. Nothing is written to the persistent belief store.
func (r *candidateRouter) recordUnattributedFailure(rt *route.Route) {
	uses := routeUses(rt)

	var weakest edgeUse
	weakestProb := 2.0
	found := false

	for _, use := range uses {
		if use.from == r.source {
			continue
		}
		edge := r.edges[use.key]
		if edge == nil {
			continue
		}

		p := r.edgeProbability(edge, use.amount)
		if !found || p < weakestProb {
			weakest = use
			weakestProb = p
			found = true
		}
	}

	if found {
		effective := weakest.amount + r.reserved[weakest.key]
		r.addFailurePenalty(weakest.key, effective, 0.9)
	}
}

func routeDeliveryAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if rt == nil {
		return errors.New("nil attempted route")
	}

	if result.Failure == nil {
		for _, use := range routeUses(rt) {
			r.recordSuccess(use)
		}
		// The reservation remains: in atomic MPP it is held, and in
		// ordinary MPP the successful transfer consumed that direction's
		// liquidity.
		delete(r.pending, rt)
		return nil
	}

	use, attributed := r.failureUse(rt, result.FailureSource)
	if attributed {
		effective := use.amount
		if total := r.reserved[use.key]; total > effective {
			effective = total
		}
		r.recordAttributedFailure(use, effective)
	} else {
		r.recordUnattributedFailure(rt)
	}

	r.release(rt)

	delivered := routeDeliveryAmount(rt)
	if delivered > 1 {
		next := delivered * 62 / 100
		if next < 1 {
			next = 1
		}
		if r.retryCap == 0 || next < r.retryCap {
			r.retryCap = next
		}
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	capacity  lnwire.MilliSatoshi
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	conf      uint8

	suspectAmt   lnwire.MilliSatoshi
	suspectVotes uint8
}

var candidateBeliefStore = struct {
	sync.Mutex
	beliefs map[candidateEdgeKey]*candidateBelief
}{
	beliefs: make(map[candidateEdgeKey]*candidateBelief),
}

type candidateLocalFailure struct {
	upper lnwire.MilliSatoshi
	votes uint8
}

type candidateTraversal struct {
	key  candidateEdgeKey
	edge *candidateEdge
	amt  lnwire.MilliSatoshi
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	reserved    map[candidateEdgeKey]lnwire.MilliSatoshi
	usedTotals  map[candidateEdgeKey]lnwire.MilliSatoshi
	localFails  map[candidateEdgeKey]candidateLocalFailure
	edgePenalty map[candidateEdgeKey]float64
	policyFails map[candidateEdgeKey]uint8

	plannedParts uint32
	failures     uint32
	unknownFails uint32
	requestNo    uint64
	searchSalt   uint64
	retryHint    lnwire.MilliSatoshi
	delivered    lnwire.MilliSatoshi
	settled      bool
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[candidateEdgeKey]*candidateEdge),
		localBalances: localBalances,
		reserved:      make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		usedTotals:    make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		localFails:    make(map[candidateEdgeKey]candidateLocalFailure),
		edgePenalty:   make(map[candidateEdgeKey]float64),
		policyFails:   make(map[candidateEdgeKey]uint8),
	}

	r.plannedParts = r.initialPartCount(spec.Amount)

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[key] = edge

				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func (r *candidateRouter) initialPartCount(
	amt lnwire.MilliSatoshi) uint32 {

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		return 1
	}

	var parts uint32
	switch {
	case amt <= 5_000_000:
		parts = 1
	case amt <= 20_000_000:
		parts = 3
	case amt <= 50_000_000:
		parts = 6
	default:
		parts = maxParts
	}

	if parts > maxParts {
		parts = maxParts
	}
	if parts == 0 {
		parts = 1
	}
	return parts
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.003
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.48 * math.Exp(-x/0.025)
	highMode := 0.50 / (1 + math.Exp((x-0.90)/0.025))
	p := 0.005 + lowMode + highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func candidateLogisticProbability(amt, estimate,
	capacity lnwire.MilliSatoshi) float64 {

	if capacity <= 0 {
		return 0.005
	}

	scale := 0.055 * float64(capacity)
	if scale < 1 {
		scale = 1
	}

	z := (float64(amt) - float64(estimate)) / scale
	switch {
	case z > 30:
		return 0.005
	case z < -30:
		return 0.995
	default:
		return 1 / (1 + math.Exp(z))
	}
}

func (r *candidateRouter) beliefSnapshot(
	e *candidateEdge) (candidateBelief, bool) {

	candidateBeliefStore.Lock()
	defer candidateBeliefStore.Unlock()

	stored := candidateBeliefStore.beliefs[e.key]
	if stored == nil || (stored.capacity != 0 &&
		stored.capacity != e.capacity) {

		return candidateBelief{}, false
	}

	return *stored, true
}

func (r *candidateRouter) edgeProbability(e *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	required := amt + r.reserved[e.key]
	if required > e.capacity {
		return 0.001
	}

	if e.key.from == r.source {
		if r.localBalances[e.key.chanID] < required {
			return 0.001
		}
		return 0.999
	}

	p := candidatePrior(required, e.capacity)
	belief, ok := r.beliefSnapshot(e)

	if ok {
		if belief.estimate > 0 && belief.conf > 0 {
			q := candidateLogisticProbability(
				required, belief.estimate, e.capacity,
			)
			weight := 0.12 * float64(belief.conf)
			if weight > 0.68 {
				weight = 0.68
			}
			p = (1-weight)*p + weight*q
		}

		if belief.lowerOK > 0 && required <= belief.lowerOK {
			p = math.Max(p, 0.997)
		}

		if belief.upperFail > 0 {
			switch {
			case required >= belief.upperFail:
				p = math.Min(p, 0.018)

			case belief.lowerOK > 0 &&
				belief.upperFail > belief.lowerOK &&
				required > belief.lowerOK:

				span := float64(
					belief.upperFail - belief.lowerOK,
				)
				pos := float64(
					required - belief.lowerOK,
				) / span
				bounded := 0.997*(1-pos) + 0.018*pos
				p = 0.35*p + 0.65*bounded
			}
		}
	}

	if local, exists := r.localFails[e.key]; exists &&
		required >= local.upper {

		switch {
		case local.votes >= 3:
			p *= 0.04
		case local.votes == 2:
			p *= 0.12
		default:
			p *= 0.62
		}
	}

	if p < 0.003 {
		return 0.003
	}
	if p > 0.997 {
		return 0.997
	}
	return p
}

func candidateEdgeHash(key candidateEdgeKey, salt uint64) float64 {
	h := key.chanID ^ salt ^ 0x9e3779b97f4a7c15
	for _, b := range key.from {
		h ^= uint64(b)
		h *= 0x100000001b3
	}
	for _, b := range key.to {
		h ^= uint64(b) + 0x9d
		h *= 0x100000001b3
	}

	h ^= h >> 30
	h *= 0xbf58476d1ce4e5b9
	h ^= h >> 27
	h *= 0x94d049bb133111eb
	h ^= h >> 31

	return float64(h>>11) / float64(uint64(1)<<53)
}

func (r *candidateRouter) edgeCost(e *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	p := r.edgeProbability(e, amt)
	cost := -math.Log(p) + 0.012 + r.edgePenalty[e.key]

	if reserved := r.reserved[e.key]; reserved > 0 &&
		e.capacity > 0 {

		cost += 0.70 +
			1.35*float64(reserved)/float64(e.capacity)
	}

	if r.failures > 0 {
		exploration := 0.12 + 0.035*float64(r.failures)
		if exploration > 0.85 {
			exploration = 0.85
		}
		cost += exploration * candidateEdgeHash(
			e.key, r.searchSalt,
		)
	}

	return cost
}

func (r *candidateRouter) addPenalty(
	key candidateEdgeKey, amount float64) {

	next := r.edgePenalty[key] + amount
	if next > 12 {
		next = 12
	}
	r.edgePenalty[key] = next
}

type candidateLabel struct {
	node     route.Vertex
	score    float64
	amt      lnwire.MilliSatoshi
	nextEdge *candidateEdge
	next     *candidateLabel
	active   bool
}

type candidateLabelQueue []*candidateLabel

func (q candidateLabelQueue) Len() int {
	return len(q)
}

func (q candidateLabelQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateLabelQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *candidateLabelQueue) Push(x any) {
	*q = append(*q, x.(*candidateLabel))
}

func (q *candidateLabelQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func candidateLabelContains(label *candidateLabel,
	node route.Vertex) bool {

	for current := label; current != nil; current = current.next {
		if current.node == node {
			return true
		}
	}
	return false
}

func candidateAddLabel(labels map[route.Vertex][]*candidateLabel,
	label *candidateLabel) bool {

	existing := labels[label.node]
	activeCount := 0

	for _, old := range existing {
		if !old.active {
			continue
		}
		activeCount++

		if old.score <= label.score && old.amt <= label.amt {
			return false
		}
	}

	for _, old := range existing {
		if !old.active {
			continue
		}
		if label.score <= old.score && label.amt <= old.amt {
			old.active = false
			activeCount--
		}
	}

	if activeCount >= 16 {
		var worst *candidateLabel
		for _, old := range existing {
			if !old.active {
				continue
			}
			if worst == nil || old.score > worst.score {
				worst = old
			}
		}
		if worst != nil && worst.score <= label.score {
			return false
		}
		if worst != nil {
			worst.active = false
		}
	}

	label.active = true
	labels[label.node] = append(existing, label)
	return true
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}

	target := &candidateLabel{
		node:   r.spec.Target,
		score:  0,
		amt:    amt,
		active: true,
	}
	labels := map[route.Vertex][]*candidateLabel{
		r.spec.Target: []*candidateLabel{target},
	}
	pq := &candidateLabelQueue{}
	heap.Push(pq, target)

	var sourceLabel *candidateLabel

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateLabel)
		if !item.active {
			continue
		}
		if item.node == r.source {
			sourceLabel = item
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if candidateLabelContains(item, edge.key.from) {
				continue
			}

			amtOver := item.amt
			if !edge.policyAllows(amtOver) {
				continue
			}

			required := amtOver + r.reserved[edge.key]
			if required > edge.capacity {
				continue
			}
			if edge.key.from == r.source &&
				r.localBalances[edge.key.chanID] < required {

				continue
			}

			sending := amtOver
			feeCost := 0.0
			if edge.key.from != r.source {
				fee := edge.fee(amtOver)
				sending += fee

				denom := float64(amt)
				if denom < 1 {
					denom = 1
				}
				feeCost = 14 * float64(fee) / denom
			}

			label := &candidateLabel{
				node:     edge.key.from,
				score: item.score +
					r.edgeCost(edge, amtOver) + feeCost,
				amt:      sending,
				nextEdge: edge,
				next:     item,
			}
			if candidateAddLabel(labels, label) {
				heap.Push(pq, label)
			}
		}
	}

	if sourceLabel == nil {
		return nil, 0, errors.New("no route found")
	}

	path := make([]*candidateEdge, 0, 8)
	for label := sourceLabel; label.nextEdge != nil; label = label.next {
		path = append(path, label.nextEdge)
	}

	rt, err := r.buildRoute(amt, path)
	if err != nil {
		return nil, 0, err
	}

	probability := 1.0
	for _, traversal := range r.routeTraversals(rt) {
		probability *= r.edgeProbability(
			traversal.edge, traversal.amt,
		)
	}

	return rt, probability, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, error) {

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateCeilDiv(amt lnwire.MilliSatoshi,
	parts uint32) lnwire.MilliSatoshi {

	if parts <= 1 {
		return amt
	}
	divisor := lnwire.MilliSatoshi(parts)
	return (amt + divisor - 1) / divisor
}

func (r *candidateRouter) targetPartCount() uint32 {
	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		return 1
	}

	target := r.plannedParts + r.failures/2
	if r.unknownFails >= 2 {
		target++
	}
	if target > maxParts {
		target = maxParts
	}
	if target == 0 {
		target = 1
	}
	return target
}

func candidateAppendAmount(amounts []lnwire.MilliSatoshi,
	amt, maximum lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if amt < 1 {
		amt = 1
	}
	if amt > maximum {
		amt = maximum
	}

	for _, existing := range amounts {
		if existing == amt {
			return amounts
		}
	}
	return append(amounts, amt)
}

func (r *candidateRouter) reserveTemporarily(rt *route.Route,
	add bool) {

	for _, traversal := range r.routeTraversals(rt) {
		if add {
			r.reserved[traversal.key] += traversal.amt
			continue
		}

		current := r.reserved[traversal.key]
		if current <= traversal.amt {
			delete(r.reserved, traversal.key)
		} else {
			r.reserved[traversal.key] =
				current - traversal.amt
		}
	}
}

func (r *candidateRouter) futureProbability(rt *route.Route,
	remaining lnwire.MilliSatoshi,
	futureSlots uint32) (float64, bool) {

	if remaining <= 0 {
		return 1, true
	}
	if futureSlots == 0 {
		return 0, false
	}

	r.reserveTemporarily(rt, true)
	nextAmount := candidateCeilDiv(remaining, futureSlots)
	_, probability, err := r.findRoute(nextAmount)
	r.reserveTemporarily(rt, false)

	if err != nil {
		return 0, false
	}
	return probability, true
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum parts already in flight")
	}

	r.requestNo++
	r.searchSalt = r.requestNo*0x9e3779b97f4a7c15 +
		uint64(r.failures)*0xbf58476d1ce4e5b9

	partsLeft := maxParts - inFlightHtlcs
	wholeRoute, wholeProbability, wholeErr := r.findRoute(amt)

	if wholeErr == nil {
		if partsLeft == 1 ||
			(inFlightHtlcs == 0 && r.plannedParts == 1) ||
			wholeProbability >= 0.92 {

			return wholeRoute, nil
		}
	}

	targetParts := r.targetPartCount()
	desiredSlots := uint32(1)
	if targetParts > inFlightHtlcs {
		desiredSlots = targetParts - inFlightHtlcs
	}
	if desiredSlots > partsLeft {
		desiredSlots = partsLeft
	}

	base := candidateCeilDiv(amt, desiredSlots)
	if partsLeft == 1 {
		base = amt
	}

	retryHint := r.retryHint
	r.retryHint = 0

	amounts := make([]lnwire.MilliSatoshi, 0, 10)
	amounts = candidateAppendAmount(amounts, base, amt)

	if partsLeft > 1 {
		amounts = candidateAppendAmount(
			amounts, base*3/4, amt,
		)
		amounts = candidateAppendAmount(
			amounts, base/2, amt,
		)
		amounts = candidateAppendAmount(
			amounts, base/3, amt,
		)
		amounts = candidateAppendAmount(
			amounts, base*5/4, amt,
		)
		amounts = candidateAppendAmount(
			amounts, base*3/2, amt,
		)
		amounts = candidateAppendAmount(
			amounts, base*2, amt,
		)
	}
	if retryHint > 0 {
		amounts = candidateAppendAmount(
			amounts, retryHint, amt,
		)
	}
	amounts = candidateAppendAmount(amounts, amt, amt)

	var bestRoute *route.Route
	bestScore := math.Inf(-1)
	var fallbackRoute *route.Route
	fallbackScore := math.Inf(-1)
	var lastErr error

	for _, shard := range amounts {
		rt, probability, err := r.findRoute(shard)
		if err != nil {
			lastErr = err
			continue
		}

		if probability < 1e-12 {
			probability = 1e-12
		}

		progress := float64(shard) / float64(base)
		if progress < 1e-12 {
			progress = 1e-12
		}

		delivered := candidateDeliveredAmount(rt)
		feeRatio := 0.0
		if delivered > 0 && rt.TotalAmount > delivered {
			feeRatio = float64(rt.TotalAmount-delivered) /
				float64(delivered)
		}

		score := math.Log(probability) +
			0.34*math.Log(progress) - 5*feeRatio

		if score > fallbackScore {
			fallbackScore = score
			fallbackRoute = rt
		}

		remaining := amt - shard
		if remaining > 0 {
			future, feasible := r.futureProbability(
				rt, remaining, partsLeft-1,
			)
			if !feasible {
				continue
			}
			if future < 1e-12 {
				future = 1e-12
			}
			score += 0.16 * math.Log(future)
		}

		if score > bestScore {
			bestScore = score
			bestRoute = rt
		}
	}

	if bestRoute != nil {
		return bestRoute, nil
	}
	if fallbackRoute != nil {
		return fallbackRoute, nil
	}
	if wholeRoute != nil {
		return wholeRoute, nil
	}
	if lastErr != nil {
		return nil, lastErr
	}
	if wholeErr != nil {
		return nil, wholeErr
	}
	return nil, errors.New("no route found")
}

func (r *candidateRouter) routeTraversals(
	rt *route.Route) []candidateTraversal {

	traversals := make([]candidateTraversal, 0, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		key := candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		edge := r.edges[key]
		if edge == nil {
			from = hop.PubKeyBytes
			continue
		}

		amt := rt.TotalAmount
		if i > 0 {
			amt = rt.Hops[i-1].AmtToForward
		}

		traversals = append(traversals, candidateTraversal{
			key:  key,
			edge: edge,
			amt:  amt,
		})
		from = hop.PubKeyBytes
	}

	return traversals
}

func candidateDeliveredAmount(rt *route.Route) lnwire.MilliSatoshi {
	if len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateStoredBelief(
	traversal candidateTraversal) *candidateBelief {

	belief := candidateBeliefStore.beliefs[traversal.key]
	if belief == nil || (belief.capacity != 0 &&
		belief.capacity != traversal.edge.capacity) {

		belief = &candidateBelief{
			capacity: traversal.edge.capacity,
		}
		candidateBeliefStore.beliefs[traversal.key] = belief
	}
	if belief.capacity == 0 {
		belief.capacity = traversal.edge.capacity
	}
	return belief
}

func (r *candidateRouter) recordSuccess(rt *route.Route) {
	traversals := r.routeTraversals(rt)

	candidateBeliefStore.Lock()
	for _, traversal := range traversals {
		required := traversal.amt + r.reserved[traversal.key]
		belief := candidateStoredBelief(traversal)

		if required > belief.lowerOK {
			belief.lowerOK = required
		}

		estimate := traversal.edge.capacity * 92 / 100
		if required > estimate {
			estimate = required
		}
		if estimate > belief.estimate {
			belief.estimate = estimate
		}
		if belief.conf < 8 {
			belief.conf++
		}

		if belief.upperFail > 0 &&
			required >= belief.upperFail {

			belief.upperFail = 0
		}
		if belief.suspectAmt > 0 &&
			required >= belief.suspectAmt {

			belief.suspectAmt = 0
			belief.suspectVotes = 0
		}
	}
	candidateBeliefStore.Unlock()

	for _, traversal := range traversals {
		required := traversal.amt + r.reserved[traversal.key]
		if local, ok := r.localFails[traversal.key]; ok &&
			required >= local.upper {

			delete(r.localFails, traversal.key)
		}

		r.edgePenalty[traversal.key] *= 0.35
		r.policyFails[traversal.key] = 0
		r.reserved[traversal.key] += traversal.amt
		r.usedTotals[traversal.key] += traversal.amt
	}

	r.delivered += candidateDeliveredAmount(rt)
	if r.delivered >= r.spec.Amount && !r.settled {
		r.recordSettlement()
		r.settled = true
	}
}

func (r *candidateRouter) recordSettlement() {
	candidateBeliefStore.Lock()
	defer candidateBeliefStore.Unlock()

	for key, used := range r.usedTotals {
		if used <= 0 {
			continue
		}

		if belief := candidateBeliefStore.beliefs[key]; belief != nil {
			if belief.lowerOK > used {
				belief.lowerOK -= used
			} else {
				belief.lowerOK = 0
			}
			if belief.estimate > used {
				belief.estimate -= used
			} else {
				belief.estimate = 0
			}
			if belief.upperFail > used {
				belief.upperFail -= used
			} else {
				belief.upperFail = 0
			}
			if belief.suspectAmt > used {
				belief.suspectAmt -= used
			} else {
				belief.suspectAmt = 0
				belief.suspectVotes = 0
			}
		}

		reverse := candidateEdgeKey{
			chanID: key.chanID,
			from:   key.to,
			to:     key.from,
		}
		reverseBelief := candidateBeliefStore.beliefs[reverse]
		if reverseBelief == nil {
			reverseBelief = &candidateBelief{}
			candidateBeliefStore.beliefs[reverse] = reverseBelief
		}

		capacity := lnwire.MilliSatoshi(0)
		if edge := r.edges[reverse]; edge != nil {
			capacity = edge.capacity
		} else if edge := r.edges[key]; edge != nil {
			capacity = edge.capacity
		}

		if reverseBelief.capacity != 0 &&
			reverseBelief.capacity != capacity {

			*reverseBelief = candidateBelief{
				capacity: capacity,
			}
		} else {
			reverseBelief.capacity = capacity
		}

		reverseBelief.lowerOK += used
		reverseBelief.estimate += used

		if capacity > 0 {
			if reverseBelief.lowerOK > capacity {
				reverseBelief.lowerOK = capacity
			}
			if reverseBelief.estimate > capacity {
				reverseBelief.estimate = capacity
			}
		}

		if reverseBelief.upperFail > 0 {
			reverseBelief.upperFail += used
			if capacity > 0 &&
				reverseBelief.upperFail > capacity {

				reverseBelief.upperFail = capacity
			}
		}
	}
}

func (r *candidateRouter) failureEdge(rt *route.Route,
	source route.Vertex) (candidateTraversal, bool) {

	traversals := r.routeTraversals(rt)
	if len(traversals) != len(rt.Hops) {
		return candidateTraversal{}, false
	}

	index := -1
	if source == rt.SourcePubKey {
		index = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == source {
				index = i + 1
				break
			}
		}
	}

	if index < 0 || index >= len(traversals) {
		return candidateTraversal{}, false
	}
	return traversals[index], true
}

func (r *candidateRouter) recordAttributedLiquidityFailure(
	traversal candidateTraversal) {

	required := traversal.amt + r.reserved[traversal.key]

	if traversal.key.from == r.source {
		r.addPenalty(traversal.key, 0.12)
		return
	}

	local := r.localFails[traversal.key]
	if local.upper == 0 || required < local.upper {
		local.upper = required
	}
	if local.votes < 255 {
		local.votes++
	}
	r.localFails[traversal.key] = local

	if local.votes >= 2 {
		r.addPenalty(traversal.key, 0.90)
	} else {
		r.addPenalty(traversal.key, 0.38)
	}

	candidateBeliefStore.Lock()
	defer candidateBeliefStore.Unlock()

	belief := candidateStoredBelief(traversal)

	if belief.suspectVotes == 0 {
		belief.suspectAmt = required
		belief.suspectVotes = 1
		return
	}

	if belief.suspectAmt == 0 || required < belief.suspectAmt {
		belief.suspectAmt = required
	}
	if belief.suspectVotes < 255 {
		belief.suspectVotes++
	}

	votesNeeded := uint8(2)
	if belief.lowerOK > 0 &&
		belief.suspectAmt <= belief.lowerOK {

		votesNeeded = 3
	}

	if belief.suspectVotes < votesNeeded {
		return
	}

	if belief.lowerOK > 0 &&
		belief.suspectAmt <= belief.lowerOK {

		if belief.suspectAmt > 1 {
			belief.lowerOK = belief.suspectAmt - 1
		} else {
			belief.lowerOK = 0
		}
	}

	if belief.upperFail == 0 ||
		belief.suspectAmt < belief.upperFail {

		belief.upperFail = belief.suspectAmt
	}

	failedEstimate := belief.suspectAmt / 4
	if belief.estimate == 0 || failedEstimate < belief.estimate {
		belief.estimate = failedEstimate
	}
	if belief.conf < 8 {
		belief.conf++
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64,
	rt *route.Route, result routing.SimHtlcResult) error {

	if result.Failure == nil {
		r.retryHint = 0
		r.recordSuccess(rt)
		return nil
	}

	r.failures++
	traversals := r.routeTraversals(rt)
	routeShare := 0.04
	if len(traversals) > 0 {
		routeShare += 0.18 / float64(len(traversals))
	}
	for _, traversal := range traversals {
		r.addPenalty(traversal.key, routeShare)
	}

	code := result.Failure.Code()
	if code == lnwire.CodeTemporaryChannelFailure {
		if traversal, ok := r.failureEdge(
			rt, result.FailureSource,
		); ok {
			r.recordAttributedLiquidityFailure(traversal)

			delivered := candidateDeliveredAmount(rt)
			if delivered > 1 {
				factor := lnwire.MilliSatoshi(68)
				if local := r.localFails[traversal.key];
					local.votes >= 2 {

					factor = 54
				}
				r.retryHint = delivered * factor / 100
			}
			return nil
		}
	}

	if code == lnwire.CodeFeeInsufficient ||
		code == lnwire.CodeIncorrectCltvExpiry {

		if traversal, ok := r.failureEdge(
			rt, result.FailureSource,
		); ok {
			count := r.policyFails[traversal.key]
			if count < 255 {
				count++
			}
			r.policyFails[traversal.key] = count

			if count >= 2 {
				r.addPenalty(traversal.key, 7.5)
			} else {
				r.addPenalty(traversal.key, 0.9)
			}
			return nil
		}
	}

	r.unknownFails++
	unknownShare := 0.02
	if len(traversals) > 0 {
		unknownShare += 0.40 / float64(len(traversals))
	}
	for _, traversal := range traversals {
		r.addPenalty(traversal.key, unknownShare)
	}

	if r.unknownFails%2 == 0 {
		delivered := candidateDeliveredAmount(rt)
		if delivered > 1 {
			r.retryHint = delivered * 70 / 100
		}
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type edgeKey struct {
	chanID uint64
	from   route.Vertex
}

type globalEdgeKey struct {
	source route.Vertex
	edge   edgeKey
}

type candidateEdge struct {
	key      edgeKey
	chanID  uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type persistentBelief struct {
	lowerOK    lnwire.MilliSatoshi
	upperFail  lnwire.MilliSatoshi
	successes  float64
	failures   float64
	lastEpoch  uint64
}

var beliefStore = struct {
	sync.Mutex
	beliefs map[globalEdgeKey]persistentBelief
	epochs  map[route.Vertex]uint64
}{
	beliefs: make(map[globalEdgeKey]persistentBelief),
	epochs:  make(map[route.Vertex]uint64),
}

type localBelief struct {
	lowerOK     lnwire.MilliSatoshi
	softFail    lnwire.MilliSatoshi
	hardFail    lnwire.MilliSatoshi
	failVotes   int
	policyVotes int
	penalty     float64
}

type routeResult struct {
	route *route.Route
	path  []*candidateEdge
	score float64
}

type plannedShard struct {
	amount lnwire.MilliSatoshi
	result *routeResult
}

type pathCandidate struct {
	path     []*candidateEdge
	capacity lnwire.MilliSatoshi
	score    float64
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec
	epoch  uint64

	incomingEdges map[route.Vertex][]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	localEvidence map[edgeKey]*localBelief
	edgePenalty   map[edgeKey]float64
	routeFailures map[string]int
	routeFailAmt  map[string]lnwire.MilliSatoshi

	heldReservations map[edgeKey]lnwire.MilliSatoshi
	planReservations map[edgeKey]lnwire.MilliSatoshi
	plan             []plannedShard
	planDirty        bool
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	beliefStore.Lock()
	beliefStore.epochs[source]++
	epoch := beliefStore.epochs[source]
	beliefStore.Unlock()

	r := &candidateRouter{
		source:           source,
		spec:             spec,
		epoch:            epoch,
		incomingEdges:    make(map[route.Vertex][]*candidateEdge),
		localBalances:    localBalances,
		localEvidence:    make(map[edgeKey]*localBelief),
		edgePenalty:      make(map[edgeKey]float64),
		routeFailures:    make(map[string]int),
		routeFailAmt:     make(map[string]lnwire.MilliSatoshi),
		heldReservations: make(map[edgeKey]lnwire.MilliSatoshi),
		planReservations: make(map[edgeKey]lnwire.MilliSatoshi),
		planDirty:        true,
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: edgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
					},
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func clampProbability(p float64) float64 {
	if p < 0.005 {
		return 0.005
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.46 * math.Exp(-x/0.05)
	highMode := 0.54 / (1 + math.Exp((x-0.90)/0.055))

	return clampProbability(lowMode + highMode)
}

func (r *candidateRouter) persistentProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	prior := bimodalPrior(amt, edge.capacity)
	key := globalEdgeKey{source: r.source, edge: edge.key}

	beliefStore.Lock()
	belief, ok := beliefStore.beliefs[key]
	beliefStore.Unlock()

	if !ok {
		return prior
	}

	age := uint64(0)
	if r.epoch > belief.lastEpoch {
		age = r.epoch - belief.lastEpoch
	}
	freshness := math.Exp(-float64(age) / 8.0)

	p := prior

	if belief.lowerOK > 0 && belief.successes > 0 {
		successP := prior
		if amt <= belief.lowerOK {
			successP = 0.995
		} else {
			ratio := float64(belief.lowerOK) / float64(amt)
			successP = prior + (0.97-prior)*ratio*ratio
		}

		confidence := (1 - math.Exp(-1.4*belief.successes)) *
			freshness
		p = p*(1-confidence) + successP*confidence
	}

	if belief.upperFail > belief.lowerOK && belief.failures > 0 {
		ratio := float64(amt) / float64(belief.upperFail)
		failP := 0.02
		if ratio < 1 {
			failP = 0.02 + 0.80*(1-ratio)
		}

		confidence := (1 - math.Exp(-belief.failures)) *
			freshness
		p = p*(1-confidence) + failP*confidence
	}

	return clampProbability(p)
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	totalDemand lnwire.MilliSatoshi) float64 {

	if edge.from == r.source {
		if r.localBalances[edge.chanID] < totalDemand {
			return 0.005
		}
		return 0.995
	}

	p := r.persistentProbability(edge, totalDemand)
	local := r.localEvidence[edge.key]
	if local == nil {
		return p
	}

	if local.lowerOK > 0 && totalDemand <= local.lowerOK {
		p = 0.997
	}

	if local.softFail > 0 && totalDemand >= local.softFail {
		factor := 0.30
		if local.failVotes >= 2 {
			factor = 0.04
		}
		p *= factor
	} else if local.softFail > 0 {
		ratio := float64(totalDemand) / float64(local.softFail)
		p *= 1 - 0.65*ratio
	}

	p *= math.Exp(-0.20 * local.penalty)
	return clampProbability(p)
}

func combinedReservations(a, b map[edgeKey]lnwire.MilliSatoshi,
	key edgeKey) lnwire.MilliSatoshi {

	return a[key] + b[key]
}

func (r *candidateRouter) edgeAllowed(edge *candidateEdge,
	amt lnwire.MilliSatoshi,
	extra map[edgeKey]lnwire.MilliSatoshi) bool {

	if !edge.usable(amt) {
		return false
	}

	reserved := combinedReservations(
		r.heldReservations, extra, edge.key,
	)
	totalDemand := amt + reserved
	if totalDemand > edge.capacity {
		return false
	}

	if edge.from == r.source &&
		totalDemand > r.localBalances[edge.chanID] {

		return false
	}

	local := r.localEvidence[edge.key]
	if local != nil {
		if local.hardFail > 0 && totalDemand >= local.hardFail {
			return false
		}
		if local.policyVotes >= 2 {
			return false
		}
	}

	return true
}

type dijkstraItem struct {
	node   route.Vertex
	amount lnwire.MilliSatoshi
	score  float64
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(x any) {
	*q = append(*q, x.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) rawRoute(amt lnwire.MilliSatoshi,
	reservations map[edgeKey]lnwire.MilliSatoshi,
	banned map[edgeKey]bool) (*routeResult, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}

	bestScore := map[route.Vertex]float64{
		r.spec.Target: 0,
	}
	bestAmount := map[route.Vertex]lnwire.MilliSatoshi{
		r.spec.Target: amt,
	}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node:   r.spec.Target,
		amount: amt,
		score:  0,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		if item.score > bestScore[item.node]+1e-12 {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if banned != nil && banned[edge.key] {
				continue
			}

			amtOver := item.amount
			if !r.edgeAllowed(edge, amtOver, reservations) {
				continue
			}

			reserved := combinedReservations(
				r.heldReservations, reservations, edge.key,
			)
			probability := r.edgeProbability(
				edge, amtOver+reserved,
			)

			fee := lnwire.MilliSatoshi(0)
			sending := amtOver
			if edge.from != r.source {
				fee = edge.fee(amtOver)
				sending += fee
			}

			feeRatio := float64(fee) /
				float64(maxMSat(amt, 1))
			edgeScore := -math.Log(probability) +
				20*feeRatio + 0.006 +
				r.edgePenalty[edge.key]

			newScore := item.score + edgeScore
			oldScore, ok := bestScore[edge.from]
			if ok && newScore >= oldScore {
				continue
			}

			bestScore[edge.from] = newScore
			bestAmount[edge.from] = sending
			next[edge.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:   edge.from,
				amount: sending,
				score:  newScore,
			})
		}
	}

	score, ok := bestScore[r.source]
	if !ok {
		return nil, errors.New("no route found")
	}

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.to
	}

	rt, err := r.buildRoute(amt, path)
	if err != nil {
		return nil, err
	}

	_ = bestAmount
	return &routeResult{
		route: rt,
		path:  path,
		score: score,
	}, nil
}

func routeSignature(path []*candidateEdge) string {
	sig := ""
	for _, edge := range path {
		sig += fmt.Sprintf("%d:%x/", edge.chanID, edge.from[:4])
	}
	return sig
}

func (r *candidateRouter) adjustedRouteScore(result *routeResult,
	amt lnwire.MilliSatoshi) float64 {

	sig := routeSignature(result.path)
	count := r.routeFailures[sig]
	if count == 0 {
		return result.score
	}

	failedAmt := r.routeFailAmt[sig]
	factor := 1.5
	if failedAmt > 0 && amt*10 < failedAmt*7 {
		factor = 0.20
	}

	return result.score + float64(count)*factor
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	reservations map[edgeKey]lnwire.MilliSatoshi) (*routeResult, error) {

	base, err := r.rawRoute(amt, reservations, nil)
	if err != nil {
		return nil, err
	}

	best := base
	bestScore := r.adjustedRouteScore(base, amt)
	if r.routeFailures[routeSignature(base.path)] == 0 {
		return best, nil
	}

	for _, edge := range base.path {
		banned := map[edgeKey]bool{edge.key: true}
		alternative, altErr := r.rawRoute(
			amt, reservations, banned,
		)
		if altErr != nil {
			continue
		}

		score := r.adjustedRouteScore(alternative, amt)
		if score < bestScore {
			best = alternative
			bestScore = score
		}
	}

	return best, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, error) {

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	n := len(path)
	amtOver := make([]lnwire.MilliSatoshi, n)
	expiryOver := make([]uint32, n)

	amtOver[n-1] = amt
	expiryOver[n-1] = finalCltvDelta

	for i := n - 2; i >= 0; i-- {
		forwardEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, n)
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < n-1 {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func maxMSat(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if a > b {
		return a
	}
	return b
}

func minMSat(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if a < b {
		return a
	}
	return b
}

func routeChannelAmount(rt *route.Route,
	index int) lnwire.MilliSatoshi {

	if index == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[index-1].AmtToForward
}

func (r *candidateRouter) pathFeasible(path []*candidateEdge,
	delivery lnwire.MilliSatoshi,
	reservations map[edgeKey]lnwire.MilliSatoshi,
	minProbability float64) bool {

	rt, err := r.buildRoute(delivery, path)
	if err != nil {
		return false
	}

	for i, edge := range path {
		amt := routeChannelAmount(rt, i)
		if !r.edgeAllowed(edge, amt, reservations) {
			return false
		}

		reserved := combinedReservations(
			r.heldReservations, reservations, edge.key,
		)
		if r.edgeProbability(edge, amt+reserved) < minProbability {
			return false
		}
	}

	return true
}

func (r *candidateRouter) pathCapacity(path []*candidateEdge,
	low, high lnwire.MilliSatoshi,
	reservations map[edgeKey]lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if low <= 0 {
		low = 1
	}
	if high < low ||
		!r.pathFeasible(path, low, reservations, 0.12) {

		return 0
	}

	best := low
	left, right := low, high
	for left <= right {
		mid := left + (right-left)/2
		if r.pathFeasible(path, mid, reservations, 0.12) {
			best = mid
			left = mid + 1
		} else {
			right = mid - 1
		}
	}

	return best
}

func addPathReservation(reservations map[edgeKey]lnwire.MilliSatoshi,
	result *routeResult, sign int) {

	for i, edge := range result.path {
		amt := routeChannelAmount(result.route, i)
		if sign > 0 {
			reservations[edge.key] += amt
			continue
		}

		if reservations[edge.key] <= amt {
			delete(reservations, edge.key)
		} else {
			reservations[edge.key] -= amt
		}
	}
}

func (r *candidateRouter) clearPlan() {
	r.plan = nil
	r.planReservations = make(map[edgeKey]lnwire.MilliSatoshi)
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32) {

	r.clearPlan()
	r.planDirty = false

	if total <= 0 || parts == 0 {
		return
	}

	if parts == 1 || total <= 20_000_000 {
		result, err := r.findRoute(
			total, r.planReservations,
		)
		if err == nil {
			r.plan = append(r.plan, plannedShard{
				amount: total,
				result: result,
			})
			addPathReservation(
				r.planReservations, result, 1,
			)
		}
		return
	}

	maxParts := int(parts)
	base := total / lnwire.MilliSatoshi(maxParts*3)
	if base < 1_000 {
		base = 1_000
	}
	if base > total {
		base = total
	}

	discoveryReservations := make(map[edgeKey]lnwire.MilliSatoshi)
	var candidates []pathCandidate
	var aggregateCapacity lnwire.MilliSatoshi

	for i := 0; i < maxParts && aggregateCapacity < total; i++ {
		result, err := r.findRoute(base, discoveryReservations)
		if err != nil {
			break
		}

		capacity := r.pathCapacity(
			result.path, base, total, discoveryReservations,
		)
		if capacity < base {
			break
		}

		candidates = append(candidates, pathCandidate{
			path:     result.path,
			capacity: capacity,
			score:    result.score,
		})
		aggregateCapacity += capacity

		capRoute, err := r.buildRoute(capacity, result.path)
		if err != nil {
			break
		}
		addPathReservation(discoveryReservations, &routeResult{
			route: capRoute,
			path:  result.path,
		}, 1)
	}

	if len(candidates) == 0 {
		return
	}

	sort.SliceStable(candidates, func(i, j int) bool {
		if candidates[i].capacity == candidates[j].capacity {
			return candidates[i].score < candidates[j].score
		}
		return candidates[i].capacity > candidates[j].capacity
	})

	remaining := total
	for _, candidate := range candidates {
		if remaining <= 0 {
			break
		}

		shard := minMSat(candidate.capacity, remaining)
		resultRoute, err := r.buildRoute(shard, candidate.path)
		if err != nil {
			continue
		}

		result := &routeResult{
			route: resultRoute,
			path:  candidate.path,
			score: candidate.score,
		}
		if !r.pathFeasible(
			candidate.path, shard,
			r.planReservations, 0.08,
		) {
			continue
		}

		r.plan = append(r.plan, plannedShard{
			amount: shard,
			result: result,
		})
		addPathReservation(r.planReservations, result, 1)
		remaining -= shard
	}

	if len(r.plan) == 0 {
		return
	}

	if remaining > 0 && len(r.plan) < maxParts {
		shard := remaining
		for shard > 0 {
			result, err := r.findRoute(
				shard, r.planReservations,
			)
			if err == nil {
				r.plan = append(r.plan, plannedShard{
					amount: shard,
					result: result,
				})
				addPathReservation(
					r.planReservations, result, 1,
				)
				break
			}
			if shard <= 1_000 {
				break
			}
			shard /= 2
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum parts reached")
	}

	partsLeft := r.spec.MaxParts - inFlightHtlcs

	if r.planDirty || len(r.plan) == 0 {
		r.makePlan(amt, partsLeft)
	}

	if len(r.plan) > 0 {
		shard := r.plan[0]
		if shard.amount > amt {
			r.makePlan(amt, partsLeft)
			if len(r.plan) == 0 {
				return nil, errors.New("no route found")
			}
			shard = r.plan[0]
		}

		r.plan = r.plan[1:]
		addPathReservation(
			r.planReservations, shard.result, -1,
		)
		return shard.result.route, nil
	}

	shard := amt
	for {
		result, err := r.findRoute(
			shard, make(map[edgeKey]lnwire.MilliSatoshi),
		)
		if err == nil {
			return result.route, nil
		}

		if partsLeft <= 1 || shard <= 1_000 {
			return nil, err
		}
		shard /= 2
	}
}

func routeEdges(rt *route.Route) []edgeKey {
	edges := make([]edgeKey, len(rt.Hops))
	from := rt.SourcePubKey
	for i, hop := range rt.Hops {
		edges[i] = edgeKey{
			chanID: hop.ChannelID,
			from:   from,
		}
		from = hop.PubKeyBytes
	}
	return edges
}

func (r *candidateRouter) routePathSignature(rt *route.Route) string {
	edges := routeEdges(rt)
	sig := ""
	for _, edge := range edges {
		sig += fmt.Sprintf("%d:%x/", edge.chanID, edge.from[:4])
	}
	return sig
}

func (r *candidateRouter) updatePersistentSuccess(key edgeKey,
	amt lnwire.MilliSatoshi) {

	globalKey := globalEdgeKey{source: r.source, edge: key}

	beliefStore.Lock()
	belief := beliefStore.beliefs[globalKey]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
		belief.failures = 0
	}
	belief.successes = math.Min(4, belief.successes+1)
	belief.lastEpoch = r.epoch
	beliefStore.beliefs[globalKey] = belief
	beliefStore.Unlock()
}

func (r *candidateRouter) updatePersistentFailure(key edgeKey,
	amt lnwire.MilliSatoshi, weight float64) {

	globalKey := globalEdgeKey{source: r.source, edge: key}

	beliefStore.Lock()
	belief := beliefStore.beliefs[globalKey]
	if amt > belief.lowerOK &&
		(belief.upperFail == 0 || amt < belief.upperFail) {

		belief.upperFail = amt
	}
	belief.failures = math.Min(2, belief.failures+weight)
	belief.lastEpoch = r.epoch
	beliefStore.beliefs[globalKey] = belief
	beliefStore.Unlock()
}

func (r *candidateRouter) locateFailure(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}
	return -1
}

func (r *candidateRouter) ReportAttempt(attemptID uint64,
	rt *route.Route, result routing.SimHtlcResult) error {

	_ = attemptID
	edges := routeEdges(rt)
	sig := r.routePathSignature(rt)

	if result.Failure == nil {
		for i, key := range edges {
			amt := routeChannelAmount(rt, i)
			local := r.localEvidence[key]
			if local == nil {
				local = &localBelief{}
				r.localEvidence[key] = local
			}

			if amt > local.lowerOK {
				local.lowerOK = amt
			}
			if local.softFail > 0 && amt >= local.softFail {
				local.softFail = 0
				local.hardFail = 0
				local.failVotes = 0
			}
			local.penalty *= 0.25
			r.edgePenalty[key] *= 0.25
			r.updatePersistentSuccess(key, amt)
		}

		delete(r.routeFailures, sig)
		delete(r.routeFailAmt, sig)
		addPathReservation(r.heldReservations, &routeResult{
			route: rt,
			path: func() []*candidateEdge {
				path := make([]*candidateEdge, len(edges))
				for i, key := range edges {
					path[i] = &candidateEdge{key: key}
				}
				return path
			}(),
		}, 1)

		return nil
	}

	r.planDirty = true
	r.clearPlan()

	r.routeFailures[sig]++
	deliveryAmt := rt.Hops[len(rt.Hops)-1].AmtToForward
	oldFailAmt, ok := r.routeFailAmt[sig]
	if !ok || deliveryAmt < oldFailAmt {
		r.routeFailAmt[sig] = deliveryAmt
	}

	failIdx := r.locateFailure(rt, result.FailureSource)
	if failIdx < 0 || failIdx >= len(edges) {
		for _, key := range edges {
			r.edgePenalty[key] = math.Min(
				2.0, r.edgePenalty[key]+0.08,
			)
		}
		return nil
	}

	for i, key := range edges {
		increment := 0.03
		if i == failIdx {
			increment = 0.55
		}
		r.edgePenalty[key] = math.Min(
			3.0, r.edgePenalty[key]+increment,
		)
	}

	key := edges[failIdx]
	amt := routeChannelAmount(rt, failIdx)
	totalDemand := amt + r.heldReservations[key]

	local := r.localEvidence[key]
	if local == nil {
		local = &localBelief{}
		r.localEvidence[key] = local
	}
	local.penalty = math.Min(5, local.penalty+1)

	switch result.Failure.(type) {
	case *lnwire.FailTemporaryChannelFailure:
		if local.softFail == 0 || totalDemand < local.softFail {
			local.softFail = totalDemand
		}
		local.failVotes++

		if local.failVotes >= 2 {
			if local.hardFail == 0 ||
				totalDemand < local.hardFail {

				local.hardFail = totalDemand
			}

			weight := 0.35
			if local.failVotes == 2 {
				weight = 0.70
			}
			r.updatePersistentFailure(key, amt, weight)
		}

	case *lnwire.FailFeeInsufficient,
		*lnwire.FailIncorrectCltvExpiry:

		local.policyVotes++
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi

	suspectAmt   lnwire.MilliSatoshi
	suspectVotes uint8
	stamp        uint64
}

type candidateNetworkMemory struct {
	epoch   uint64
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[uint64]*candidateNetworkMemory
}{
	networks: make(map[uint64]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	memoryID uint64
	epoch    uint64

	incomingEdges map[route.Vertex][]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[candidateEdgeKey]candidateBelief

	// Successful shards consume or hold directional liquidity for the rest
	// of the payment. This is required for both ordinary and atomic MPP.
	reserved map[candidateEdgeKey]lnwire.MilliSatoshi

	// These penalties are deliberately local to one payment. They provide
	// useful route-level learning even when an onion error is unreadable.
	edgePenalty map[candidateEdgeKey]float64

	// planLimit is the preferred size of the next shard. It survives shard
	// successes, producing an up-front partition rather than a new probe
	// ladder after every result.
	planLimit lnwire.MilliSatoshi

	failureStreak uint32
	lastFailedAmt lnwire.MilliSatoshi
}

func candidateHashUint(h, value uint64) uint64 {
	h ^= value
	h *= 1099511628211
	h ^= h >> 32
	return h
}

func candidateHashVertex(h uint64, vertex route.Vertex) uint64 {
	for i := 0; i < len(vertex); i++ {
		h ^= uint64(vertex[i])
		h *= 1099511628211
	}

	return h
}

func candidateEdgeFingerprint(edge *candidateEdge) uint64 {
	h := uint64(1469598103934665603)
	h = candidateHashUint(h, edge.chanID)
	h = candidateHashVertex(h, edge.from)
	h = candidateHashVertex(h, edge.to)
	h = candidateHashUint(h, uint64(edge.capacity))
	h = candidateHashUint(h, uint64(edge.baseFeeMsat))
	h = candidateHashUint(h, uint64(edge.feeRatePPM))
	h = candidateHashUint(h, uint64(edge.timeLockDelta))
	h = candidateHashUint(h, uint64(edge.minHTLC))
	h = candidateHashUint(h, uint64(edge.maxHTLC))
	return h
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		localBalances: localBalances,
		beliefs:       make(map[candidateEdgeKey]candidateBelief),
		reserved:      make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		edgePenalty:   make(map[candidateEdgeKey]float64),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	var topologySum uint64
	var topologyXor uint64
	var edgeCount uint64

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
					},
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: policy.FeeBaseMSat,
					feeRatePPM: policy.
						FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				token := candidateEdgeFingerprint(edge)
				topologySum += token * 0x9e3779b97f4a7c15
				topologyXor ^= token +
					0x517cc1b727220a95 +
					(token << 7) + (token >> 3)
				edgeCount++

				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	memoryID := uint64(1469598103934665603)
	memoryID = candidateHashVertex(memoryID, source)
	memoryID = candidateHashUint(memoryID, topologySum)
	memoryID = candidateHashUint(memoryID, topologyXor)
	memoryID = candidateHashUint(memoryID, edgeCount)
	r.memoryID = memoryID

	candidateMemory.Lock()
	network := candidateMemory.networks[memoryID]
	if network == nil {
		network = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[memoryID] = network
	}

	network.epoch++
	r.epoch = network.epoch
	for key, belief := range network.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidateClampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005
	case p > 0.995:
		return 0.995
	default:
		return p
	}
}

// Liquidity is predominantly bimodal. The low mode supports only a small
// fraction of capacity, while the high mode remains useful until a steep
// cliff near the channel's capacity.
func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.024)
	highMode := 1 / (1 + math.Exp(19*(x-0.82)))

	return candidateClampProbability(
		0.5*lowMode + 0.5*highMode,
	)
}

func (r *candidateRouter) evidenceConfidence(
	belief candidateBelief) float64 {

	if belief.stamp == 0 {
		return 0
	}

	if belief.stamp >= r.epoch {
		return 1
	}

	// Evidence is strongest within its payment. Across payments it is
	// softened immediately because settlement and background traffic can
	// both move liquidity.
	age := float64(r.epoch - belief.stamp - 1)
	return math.Max(0.15, 0.82*math.Exp(-age/9))
}

func (r *candidateRouter) probability(edge *candidateEdge,
	totalAmt lnwire.MilliSatoshi) float64 {

	if edge.from == r.source {
		available := r.localBalances[edge.chanID]
		if totalAmt <= available {
			return 0.999
		}

		return 0.001
	}

	prior := candidatePrior(totalAmt, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok || belief.stamp == 0 {
		return prior
	}

	learned := prior

	switch {
	case belief.lowerOK > 0 && totalAmt <= belief.lowerOK:
		learned = 0.995

	case belief.upperFail > 0 && totalAmt >= belief.upperFail:
		// Corroborated blame remains probabilistic. It is never a route
		// exclusion because apparently valid attribution may be shifted.
		learned = 0.025

	case belief.lowerOK > 0 &&
		belief.upperFail > belief.lowerOK:

		span := float64(belief.upperFail - belief.lowerOK)
		position := float64(totalAmt-belief.lowerOK) / span
		position = math.Max(0, math.Min(1, position))
		learned = 0.995*(1-position) + 0.025*position

	case belief.lowerOK > 0 && totalAmt > belief.lowerOK:
		ratio := float64(belief.lowerOK) / float64(totalAmt)
		learned = prior + (0.995-prior)*ratio*ratio

	case belief.upperFail > 0 && totalAmt < belief.upperFail:
		ratio := float64(totalAmt) /
			float64(belief.upperFail)
		learned = prior * (1 - 0.65*ratio*ratio)
	}

	// A single blame is useful as a hint, but not as a liquidity bound.
	if belief.upperFail == 0 && belief.suspectAmt > 0 &&
		totalAmt >= belief.suspectAmt {

		learned *= 0.70
	}

	confidence := r.evidenceConfidence(belief)
	return candidateClampProbability(
		confidence*learned + (1-confidence)*prior,
	)
}

type candidateItem struct {
	node  route.Vertex
	score float64
}

type candidateQueue []*candidateItem

func (q candidateQueue) Len() int {
	return len(q)
}

func (q candidateQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *candidateQueue) Push(value any) {
	*q = append(*q, value.(*candidateItem))
}

func (q *candidateQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]
	return last
}

type candidatePath struct {
	route       *route.Route
	edges       []*candidateEdge
	probability float64
	pressure    float64
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*candidatePath, error) {

	if amt <= 0 {
		return nil, errors.New("invalid payment amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is target")
	}

	scores := make(map[route.Vertex]float64)
	amounts := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)

	scores[r.spec.Target] = 0
	amounts[r.spec.Target] = amt

	pq := &candidateQueue{}
	heap.Push(pq, &candidateItem{
		node:  r.spec.Target,
		score: 0,
	})

	for pq.Len() != 0 {
		item := heap.Pop(pq).(*candidateItem)
		bestScore, ok := scores[item.node]
		if !ok || item.score > bestScore+1e-12 {
			continue
		}
		if item.node == r.source {
			break
		}

		arriving := amounts[item.node]

		for _, edge := range r.incomingEdges[item.node] {
			if !edge.usable(arriving) {
				continue
			}

			held := r.reserved[edge.key]
			totalLiquidity := arriving + held
			if totalLiquidity < arriving ||
				totalLiquidity > edge.capacity {

				continue
			}

			if edge.from == r.source &&
				totalLiquidity >
					r.localBalances[edge.chanID] {

				continue
			}

			sending := arriving
			fee := lnwire.MilliSatoshi(0)
			if edge.from != r.source {
				fee = edge.fee(arriving)
				sending += fee
				if sending < arriving {
					continue
				}
			}

			probability := r.probability(
				edge, totalLiquidity,
			)

			edgeCost := -math.Log(probability) + 0.065
			if arriving > 0 {
				edgeCost += 4 * float64(fee) /
					float64(arriving)
			}
			edgeCost += r.edgePenalty[edge.key]

			// Successful atomic-MPP siblings should normally use another
			// corridor. This remains a soft cost so unavoidable shared
			// source or destination bottlenecks are still usable.
			if held > 0 {
				denominator := edge.capacity
				if edge.from == r.source {
					denominator =
						r.localBalances[edge.chanID]
				}

				reservationCost := 1.25
				if denominator > 0 {
					reservationCost += 2.5 *
						float64(held) /
						float64(denominator)
				}
				edgeCost += reservationCost
			}

			newScore := item.score + edgeCost
			oldScore, visited := scores[edge.from]
			if visited && newScore >= oldScore {
				continue
			}

			scores[edge.from] = newScore
			amounts[edge.from] = sending
			next[edge.from] = edge

			heap.Push(pq, &candidateItem{
				node:  edge.from,
				score: newScore,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	rt, edges, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, err
	}

	pathProbability := 1.0
	pressure := 0.0

	for i, edge := range edges {
		amtOver := candidateRouteAmount(rt, i)
		totalLiquidity := amtOver + r.reserved[edge.key]

		pathProbability *= r.probability(
			edge, totalLiquidity,
		)

		denominator := edge.capacity
		if edge.from == r.source {
			denominator = r.localBalances[edge.chanID]
		}

		if denominator > 0 {
			ratio := float64(totalLiquidity) /
				float64(denominator)
			if ratio > pressure {
				pressure = ratio
			}
		}
	}

	return &candidatePath{
		route:       rt,
		edges:       edges,
		probability: pathProbability,
		pressure:    pressure,
	}, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route,
	[]*candidateEdge, error) {

	const finalCltvDelta = uint32(40)

	var path []*candidateEdge
	seen := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if seen[node] {
			return nil, nil, errors.New("cycle in route")
		}
		seen[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, nil, fmt.Errorf(
				"broken path at %v", node,
			)
		}

		path = append(path, edge)
		node = edge.to
	}

	if len(path) == 0 {
		return nil, nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := finalCltvDelta

		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, path, nil
}

func candidateCeilDiv(amt lnwire.MilliSatoshi,
	divisor uint32) lnwire.MilliSatoshi {

	if divisor <= 1 {
		return amt
	}

	d := lnwire.MilliSatoshi(divisor)
	return amt/d + func() lnwire.MilliSatoshi {
		if amt%d != 0 {
			return 1
		}
		return 0
	}()
}

func candidateMaxUint32(a, b uint32) uint32 {
	if a > b {
		return a
	}

	return b
}

func candidateMinUint32(a, b uint32) uint32 {
	if a < b {
		return a
	}

	return b
}

func (r *candidateRouter) initialPlan(
	amt lnwire.MilliSatoshi,
	partsLeft uint32) (*candidatePath, error) {

	full, fullErr := r.findRoute(amt)

	if fullErr == nil &&
		(amt <= 5_000_000 ||
			full.probability >= 0.62 ||
			full.pressure <= 0.012) {

		r.planLimit = amt
		return full, nil
	}

	if partsLeft <= 1 {
		if fullErr != nil {
			return nil, fullErr
		}

		r.planLimit = amt
		return full, nil
	}

	parts := uint32(2)

	if fullErr != nil {
		parts = partsLeft
	} else {
		capacityParts := uint32(math.Ceil(
			full.pressure / 0.045,
		))
		if capacityParts < 2 {
			capacityParts = 2
		}
		parts = capacityParts

		var riskParts uint32
		switch {
		case full.probability < 0.01:
			riskParts = 12
		case full.probability < 0.05:
			riskParts = 8
		case full.probability < 0.15:
			riskParts = 5
		case full.probability < 0.35:
			riskParts = 3
		default:
			riskParts = 2
		}
		parts = candidateMaxUint32(parts, riskParts)
	}

	parts = candidateMinUint32(parts, partsLeft)
	if parts == 0 {
		parts = 1
	}

	r.planLimit = candidateCeilDiv(amt, parts)
	return nil, fullErr
}

func (r *candidateRouter) findNearbyRoute(desired, minimum,
	remaining lnwire.MilliSatoshi) (*candidatePath, error) {

	path, err := r.findRoute(desired)
	if err == nil {
		return path, nil
	}
	lastErr := err

	// A shard can be too small for advertised min-HTLC policies. Search
	// upward before assuming that no route exists.
	up := desired
	for i := 0; i < 4 && up < remaining; i++ {
		next := up + up/2
		if next <= up || next > remaining {
			next = remaining
		}
		if next == up {
			break
		}

		up = next
		path, routeErr := r.findRoute(up)
		if routeErr == nil {
			r.planLimit = up
			return path, nil
		}
		lastErr = routeErr
	}

	// Conversely, nominal capacity or local balance may require a smaller
	// shard. Never go below the amount needed to finish within MaxParts.
	down := desired
	for i := 0; i < 6 && down > minimum; i++ {
		next := down * 3 / 4
		if next < minimum {
			next = minimum
		}
		if next >= down {
			break
		}

		down = next
		path, routeErr := r.findRoute(down)
		if routeErr == nil {
			r.planLimit = down
			return path, nil
		}
		lastErr = routeErr
	}

	return nil, lastErr
}

// RequestRoute plans around the part budget from the first request. It uses
// small enough shards for a bimodal network, favors wider learned corridors
// for unequal shards, and uses held-liquidity costs to obtain diverse MPP
// paths without permanently excluding any channel.
func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid remaining amount")
	}

	partsLeft := uint32(1)
	if r.spec.MaxParts > inFlightHtlcs {
		partsLeft = r.spec.MaxParts - inFlightHtlcs
	}

	if partsLeft <= 1 {
		path, err := r.findRoute(amt)
		if err != nil {
			return nil, err
		}

		return path.route, nil
	}

	if r.planLimit == 0 {
		full, err := r.initialPlan(amt, partsLeft)
		if full != nil {
			return full.route, nil
		}
		if err != nil && r.planLimit == 0 {
			return nil, err
		}
	}

	minimum := candidateCeilDiv(amt, partsLeft)
	desired := r.planLimit

	if desired < minimum {
		desired = minimum
	}
	if desired <= 0 || desired > amt {
		desired = amt
	}

	path, err := r.findNearbyRoute(desired, minimum, amt)
	if err != nil {
		return nil, err
	}

	delivered := path.route.Hops[
		len(path.route.Hops)-1].AmtToForward

	// A corridor with a substantially stronger belief can deliberately
	// carry a larger unequal shard. The remaining corridors then carry
	// smaller shards under the persistent plan limit.
	if r.failureStreak == 0 &&
		delivered < amt &&
		path.probability >= 0.58 {

		larger := delivered + delivered/2
		if larger > amt {
			larger = amt
		}

		if larger > delivered {
			biggerPath, biggerErr := r.findRoute(larger)
			if biggerErr == nil &&
				biggerPath.probability >= 0.48 &&
				biggerPath.probability >=
					path.probability*0.72 &&
				biggerPath.pressure <= 0.10 {

				return biggerPath.route, nil
			}
		}
	}

	return path.route, nil
}

func candidateRouteAmount(rt *route.Route,
	edgeIndex int) lnwire.MilliSatoshi {

	if edgeIndex == 0 {
		return rt.TotalAmount
	}

	return rt.Hops[edgeIndex-1].AmtToForward
}

func candidateRouteEdgeKey(rt *route.Route,
	edgeIndex int) candidateEdgeKey {

	from := rt.SourcePubKey
	if edgeIndex > 0 {
		from = rt.Hops[edgeIndex-1].PubKeyBytes
	}

	return candidateEdgeKey{
		chanID: rt.Hops[edgeIndex].ChannelID,
		from:   from,
	}
}

func candidateFailureEdge(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func candidateIsLiquidityFailure(failure any) bool {
	_, ok := failure.(*lnwire.FailTemporaryChannelFailure)
	return ok
}

func candidateIsPolicyFailure(failure any) bool {
	switch failure.(type) {
	case *lnwire.FailFeeInsufficient,
		*lnwire.FailIncorrectCltvExpiry:

		return true
	default:
		return false
	}
}

func (r *candidateRouter) saveBelief(
	key candidateEdgeKey, belief candidateBelief) {

	belief.stamp = r.epoch
	r.beliefs[key] = belief

	candidateMemory.Lock()
	network := candidateMemory.networks[r.memoryID]
	if network == nil {
		network = &candidateNetworkMemory{
			epoch:   r.epoch,
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.memoryID] = network
	}
	network.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) recordSuccess(key candidateEdgeKey,
	totalAmt lnwire.MilliSatoshi) {

	belief := r.beliefs[key]

	if totalAmt > belief.lowerOK {
		belief.lowerOK = totalAmt
	}

	// Settlements are truthful and therefore override conflicting blame.
	if belief.upperFail > 0 && totalAmt >= belief.upperFail {
		belief.upperFail = 0
	}
	if belief.suspectAmt > 0 &&
		totalAmt >= belief.suspectAmt {

		belief.suspectAmt = 0
		belief.suspectVotes = 0
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) recordFailure(key candidateEdgeKey,
	totalAmt lnwire.MilliSatoshi) {

	belief := r.beliefs[key]

	corroborates := false
	if belief.suspectAmt > 0 {
		low := belief.suspectAmt * 65 / 100
		high := belief.suspectAmt * 145 / 100
		corroborates = totalAmt >= low && totalAmt <= high
	}

	if corroborates {
		if belief.suspectVotes < 255 {
			belief.suspectVotes++
		}
		if totalAmt < belief.suspectAmt {
			belief.suspectAmt = totalAmt
		}
	} else {
		belief.suspectAmt = totalAmt
		belief.suspectVotes = 1
	}

	requiredVotes := uint8(3)
	if belief.lowerOK > 0 && totalAmt <= belief.lowerOK {
		// A failure that contradicts a truthful settlement is especially
		// likely to be shifted, although genuine drift remains possible.
		requiredVotes = 4
	}

	if belief.suspectVotes >= requiredVotes {
		if totalAmt <= belief.lowerOK {
			belief.lowerOK = 0
		}

		if belief.upperFail == 0 ||
			belief.suspectAmt < belief.upperFail {

			belief.upperFail = belief.suspectAmt
		}
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) noteFailureAmount(
	delivered lnwire.MilliSatoshi) {

	similar := false
	if r.lastFailedAmt > 0 {
		low := r.lastFailedAmt * 70 / 100
		high := r.lastFailedAmt * 140 / 100
		similar = delivered >= low && delivered <= high
	}

	if similar {
		r.failureStreak++
	} else {
		r.failureStreak = 1
	}

	r.lastFailedAmt = delivered
}

func (r *candidateRouter) lowerPlanLimit(
	delivered lnwire.MilliSatoshi, percent int64) {

	reduced := delivered *
		lnwire.MilliSatoshi(percent) / 100
	if reduced <= 0 {
		return
	}

	if r.planLimit == 0 || reduced < r.planLimit {
		r.planLimit = reduced
	}
}

// ReportAttempt treats success as hard evidence, but treats failure
// attribution as noisy. Reported and neighboring edges receive local soft
// penalties so a one-hop shifted blame still moves routing away from the
// true area. Only repeated compatible blame enters persistent beliefs.
func (r *candidateRouter) ReportAttempt(attemptID uint64,
	rt *route.Route, result routing.SimHtlcResult) error {

	_ = attemptID

	if rt == nil || len(rt.Hops) == 0 {
		return nil
	}

	delivered := rt.Hops[len(rt.Hops)-1].AmtToForward

	if result.Failure == nil {
		for i := range rt.Hops {
			key := candidateRouteEdgeKey(rt, i)
			amtOver := candidateRouteAmount(rt, i)
			totalAmt := amtOver + r.reserved[key]

			r.recordSuccess(key, totalAmt)
			r.reserved[key] += amtOver
			r.edgePenalty[key] *= 0.25
		}

		r.failureStreak = 0
		r.lastFailedAmt = 0
		return nil
	}

	r.noteFailureAmount(delivered)

	// The route certainly failed even when its error cannot be decrypted.
	// Penalizing the route locally extracts that truthful information
	// without poisoning persistent channel beliefs.
	for i := range rt.Hops {
		key := candidateRouteEdgeKey(rt, i)
		r.edgePenalty[key] = math.Min(
			12, r.edgePenalty[key]+0.18,
		)
	}

	failIndex := candidateFailureEdge(
		rt, result.FailureSource,
	)
	attributed := failIndex >= 0 &&
		failIndex < len(rt.Hops)

	if attributed {
		key := candidateRouteEdgeKey(rt, failIndex)
		extra := 0.9
		if candidateIsPolicyFailure(result.Failure) {
			extra = 1.25
		}
		r.edgePenalty[key] = math.Min(
			12, r.edgePenalty[key]+extra,
		)

		// Shifted attribution is constrained to a neighboring hop. Giving
		// both neighbors smaller penalties makes the true edge less likely
		// to be selected again without pretending to know which one it is.
		for _, adjacent := range []int{
			failIndex - 1, failIndex + 1,
		} {
			if adjacent < 0 || adjacent >= len(rt.Hops) {
				continue
			}

			adjacentKey := candidateRouteEdgeKey(
				rt, adjacent,
			)
			r.edgePenalty[adjacentKey] = math.Min(
				12,
				r.edgePenalty[adjacentKey]+0.38,
			)
		}
	}

	if candidateIsLiquidityFailure(result.Failure) {
		if attributed {
			key := candidateRouteEdgeKey(rt, failIndex)
			amtOver := candidateRouteAmount(rt, failIndex)
			totalAmt := amtOver + r.reserved[key]
			r.recordFailure(key, totalAmt)
		}

		// First try another corridor at the jointly planned size. Only
		// repeated failure changes the partition, avoiding probe ladders.
		if r.failureStreak >= 2 {
			r.lowerPlanLimit(delivered, 78)
		}

		return nil
	}

	if candidateIsPolicyFailure(result.Failure) {
		// The encoded route was formed from gossip, so policy failures are
		// normally stale or shifted information. Change paths, not size.
		return nil
	}

	// An unreadable failure conveys no channel identity. Several failures
	// at the same size can still justify a modest shard-size adjustment.
	if r.failureStreak >= 4 {
		r.lowerPlanLimit(delivered, 85)
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	conf      uint8

	suspectAmt   lnwire.MilliSatoshi
	suspectVotes uint8
}

var candidateBeliefStore = struct {
	sync.Mutex
	beliefs map[candidateEdgeKey]*candidateBelief
}{
	beliefs: make(map[candidateEdgeKey]*candidateBelief),
}

type candidateLocalObservation struct {
	upper  lnwire.MilliSatoshi
	weight float64
}

type candidateTraversal struct {
	key  candidateEdgeKey
	edge *candidateEdge
	amt  lnwire.MilliSatoshi
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	reserved    map[candidateEdgeKey]lnwire.MilliSatoshi
	usedTotals  map[candidateEdgeKey]lnwire.MilliSatoshi
	localObs    map[candidateEdgeKey]candidateLocalObservation
	edgePenalty map[candidateEdgeKey]float64

	plannedParts uint32
	failures     uint32
	unknownFails uint32
	retryCap     lnwire.MilliSatoshi
	delivered    lnwire.MilliSatoshi
	settled      bool
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[candidateEdgeKey]*candidateEdge),
		localBalances: localBalances,
		reserved:      make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		usedTotals:    make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		localObs:      make(map[candidateEdgeKey]candidateLocalObservation),
		edgePenalty:   make(map[candidateEdgeKey]float64),
	}

	r.plannedParts = r.initialPartCount(spec.Amount)
	if spec.MaxParts != 0 && r.plannedParts > spec.MaxParts {
		r.plannedParts = spec.MaxParts
	}
	if r.plannedParts == 0 {
		r.plannedParts = 1
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[key] = edge

				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func (r *candidateRouter) initialPartCount(
	amt lnwire.MilliSatoshi) uint32 {

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}

	switch {
	case amt <= 20_000_000:
		return 1

	case amt <= 60_000_000:
		if maxParts < 2 {
			return maxParts
		}
		return 2

	default:
		// Larger payments benefit from committing a broad route set
		// immediately. Failed small shards can later be compensated by
		// larger shards on corridors that reveal more headroom.
		return maxParts
	}
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.003
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.48 * math.Exp(-x/0.025)
	highMode := 0.50 / (1 + math.Exp((x-0.90)/0.025))
	p := 0.005 + lowMode + highMode

	switch {
	case p < 0.005:
		return 0.005
	case p > 0.985:
		return 0.985
	default:
		return p
	}
}

func candidateLogisticProbability(amt, estimate,
	capacity lnwire.MilliSatoshi) float64 {

	if capacity <= 0 {
		return 0.005
	}

	scale := 0.065 * float64(capacity)
	if scale < 1 {
		scale = 1
	}

	z := (float64(amt) - float64(estimate)) / scale
	switch {
	case z > 30:
		return 0.005
	case z < -30:
		return 0.995
	default:
		return 1 / (1 + math.Exp(z))
	}
}

func (r *candidateRouter) copiedBelief(
	key candidateEdgeKey) (candidateBelief, bool) {

	candidateBeliefStore.Lock()
	defer candidateBeliefStore.Unlock()

	b := candidateBeliefStore.beliefs[key]
	if b == nil {
		return candidateBelief{}, false
	}

	return *b, true
}

func (r *candidateRouter) edgeProbability(e *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	required := amt + r.reserved[e.key]
	if required > e.capacity {
		return 0.001
	}

	if e.key.from == r.source {
		if r.localBalances[e.key.chanID] < required {
			return 0.001
		}
		return 0.999
	}

	p := candidatePrior(required, e.capacity)
	belief, ok := r.copiedBelief(e.key)

	if ok {
		if belief.estimate > 0 && belief.conf > 0 {
			estimatedP := candidateLogisticProbability(
				required, belief.estimate, e.capacity,
			)
			weight := 0.12 * float64(belief.conf)
			if weight > 0.72 {
				weight = 0.72
			}
			p = (1-weight)*p + weight*estimatedP
		}

		if belief.lowerOK > 0 && required <= belief.lowerOK {
			p = math.Max(p, 0.995)
		}

		if belief.upperFail > 0 {
			switch {
			case required >= belief.upperFail:
				// Even corroborated failure reports are not absolute:
				// liquidity can move and attribution can be shifted.
				p = math.Min(p, 0.025)

			case belief.lowerOK > 0 &&
				belief.upperFail > belief.lowerOK &&
				required > belief.lowerOK:

				span := float64(
					belief.upperFail - belief.lowerOK,
				)
				pos := float64(
					required - belief.lowerOK,
				) / span
				bounded := 0.995*(1-pos) + 0.025*pos
				p = 0.30*p + 0.70*bounded
			}
		}
	}

	if observation, exists := r.localObs[e.key]; exists &&
		observation.upper > 0 {

		ratio := float64(required) / float64(observation.upper)
		if ratio >= 1 {
			p *= math.Exp(-1.25 * observation.weight)
		} else {
			// A failure at a larger amount should encourage an actual
			// lower-amount retry, not blacklist the direction.
			p *= math.Exp(
				-0.16 * observation.weight *
					math.Pow(ratio, 5),
			)
		}
	}

	switch {
	case p < 0.003:
		return 0.003
	case p > 0.995:
		return 0.995
	default:
		return p
	}
}

func (r *candidateRouter) edgeCost(e *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	p := r.edgeProbability(e, amt)
	cost := -math.Log(p) + 0.015 + r.edgePenalty[e.key]

	if reserved := r.reserved[e.key]; reserved > 0 &&
		e.capacity > 0 {

		// Successful siblings prove some liquidity, but in atomic MPP
		// they also hold it. Prefer a fresh corridor while still allowing
		// reuse when the graph has no alternative.
		cost += 0.55 +
			1.80*float64(reserved)/float64(e.capacity)
	}

	return cost
}

type candidateDijkstraItem struct {
	node  route.Vertex
	score float64
	amt   lnwire.MilliSatoshi
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *candidateDijkstraQueue) Push(x any) {
	*q = append(*q, x.(*candidateDijkstraItem))
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]
	return item
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}

	scores := make(map[route.Vertex]float64)
	arriving := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)

	scores[r.spec.Target] = 0
	arriving[r.spec.Target] = amt

	pq := &candidateDijkstraQueue{}
	heap.Push(pq, &candidateDijkstraItem{
		node: r.spec.Target,
		amt:  amt,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)

		best, exists := scores[item.node]
		if !exists || item.score > best+1e-12 {
			continue
		}
		if arriving[item.node] != item.amt {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOverEdge := item.amt
			if !edge.policyAllows(amtOverEdge) {
				continue
			}

			required := amtOverEdge + r.reserved[edge.key]
			if required > edge.capacity {
				continue
			}
			if edge.key.from == r.source &&
				r.localBalances[edge.key.chanID] < required {

				continue
			}

			sending := amtOverEdge
			feeCost := 0.0
			if edge.key.from != r.source {
				fee := edge.fee(amtOverEdge)
				sending += fee

				denom := math.Max(float64(amt), 1)
				feeCost = 25 * float64(fee) / denom
			}

			newScore := item.score +
				r.edgeCost(edge, amtOverEdge) + feeCost

			old, seen := scores[edge.key.from]
			if seen && newScore >= old {
				continue
			}

			scores[edge.key.from] = newScore
			arriving[edge.key.from] = sending
			next[edge.key.from] = edge
			heap.Push(pq, &candidateDijkstraItem{
				node:  edge.key.from,
				score: newScore,
				amt:   sending,
			})
		}
	}

	if _, ok := scores[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}

	pathProbability := 1.0
	for _, traversal := range r.routeTraversals(rt) {
		pathProbability *= r.edgeProbability(
			traversal.edge, traversal.amt,
		)
	}

	return rt, pathProbability, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forwardAmt := amt
		outgoingExpiry := uint32(finalCltvDelta)

		if i < last {
			forwardAmt = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forwardAmt,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateCeilDiv(amt lnwire.MilliSatoshi,
	parts uint32) lnwire.MilliSatoshi {

	if parts <= 1 {
		return amt
	}

	divisor := lnwire.MilliSatoshi(parts)
	return (amt + divisor - 1) / divisor
}

func (r *candidateRouter) targetPartCount() uint32 {
	target := r.plannedParts + r.failures

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if target > maxParts {
		target = maxParts
	}
	if target == 0 {
		target = 1
	}

	return target
}

func candidateRouteQuality(rt *route.Route, probability float64) float64 {
	if rt == nil || len(rt.Hops) == 0 || probability <= 0 {
		return 0
	}

	return math.Pow(probability, 1/float64(len(rt.Hops)))
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum parts already in flight")
	}

	partsLeft := maxParts - inFlightHtlcs

	wholeRoute, wholeProbability, wholeErr := r.findRoute(amt)
	if wholeErr == nil && r.failures == 0 {
		if maxParts == 1 || r.plannedParts == 1 ||
			wholeProbability >= 0.86 {

			return wholeRoute, nil
		}
	}

	targetParts := r.targetPartCount()
	desiredSlots := uint32(1)
	if targetParts > inFlightHtlcs {
		desiredSlots = targetParts - inFlightHtlcs
	}
	if desiredSlots > partsLeft {
		desiredSlots = partsLeft
	}

	shard := candidateCeilDiv(amt, desiredSlots)

	// Failed attempts do not consume a part slot. A lower-than-average
	// shard can therefore be retried now and balanced by a larger shard
	// later, which is essential for unequal corridors.
	if r.retryCap > 0 && r.retryCap < shard && partsLeft > 1 {
		shard = r.retryCap
	}

	hardFloor := amt
	if partsLeft > 1 {
		hardFloor = candidateCeilDiv(amt, partsLeft*2)
	}
	if shard < hardFloor {
		shard = hardFloor
	}
	if shard > amt {
		shard = amt
	}

	baseRoute, baseProbability, err := r.findRoute(shard)
	for err != nil && shard > hardFloor {
		nextShard := shard * 2 / 3
		if nextShard < hardFloor {
			nextShard = hardFloor
		}
		if nextShard == shard {
			nextShard--
		}

		shard = nextShard
		baseRoute, baseProbability, err = r.findRoute(shard)
	}

	if err != nil {
		if wholeErr == nil {
			return wholeRoute, nil
		}
		return nil, err
	}

	// With clean evidence, greedily give a reliable, high-headroom
	// corridor more than an equal share. Reservations then make the
	// next call seek another corridor, yielding an unequal route set.
	if r.retryCap == 0 && desiredSlots > 1 {
		bestRoute := baseRoute
		bestProbability := baseProbability
		bestAmt := shard
		baseQuality := candidateRouteQuality(
			baseRoute, baseProbability,
		)

		factors := []int64{5, 3, 7}
		divisors := []int64{4, 2, 4}

		for i := range factors {
			candidateAmt := lnwire.MilliSatoshi(
				int64(shard) * factors[i] / divisors[i],
			)
			if candidateAmt <= bestAmt || candidateAmt >= amt {
				continue
			}

			rt, probability, routeErr := r.findRoute(candidateAmt)
			if routeErr != nil {
				continue
			}

			quality := candidateRouteQuality(rt, probability)
			qualityFloor := math.Max(0.62, baseQuality*0.94)
			if quality < qualityFloor {
				continue
			}

			bestRoute = rt
			bestProbability = probability
			bestAmt = candidateAmt
		}

		_ = bestProbability
		return bestRoute, nil
	}

	return baseRoute, nil
}

func (r *candidateRouter) routeTraversals(
	rt *route.Route) []candidateTraversal {

	traversals := make([]candidateTraversal, 0, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		key := candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		edge := r.edges[key]
		if edge == nil {
			from = hop.PubKeyBytes
			continue
		}

		amt := rt.TotalAmount
		if i > 0 {
			amt = rt.Hops[i-1].AmtToForward
		}

		traversals = append(traversals, candidateTraversal{
			key:  key,
			edge: edge,
			amt:  amt,
		})
		from = hop.PubKeyBytes
	}

	return traversals
}

func candidateDeliveredAmount(rt *route.Route) lnwire.MilliSatoshi {
	if len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func (r *candidateRouter) observeLocal(
	traversal candidateTraversal, weight float64) {

	if weight <= 0 {
		return
	}

	required := traversal.amt + r.reserved[traversal.key]
	observation := r.localObs[traversal.key]

	if observation.upper == 0 || required < observation.upper {
		observation.upper = required
	}
	observation.weight += weight
	if observation.weight > 4 {
		observation.weight = 4
	}

	r.localObs[traversal.key] = observation
}

func (r *candidateRouter) recordPersistentFailure(
	traversal candidateTraversal) {

	if traversal.key.from == r.source {
		return
	}

	required := traversal.amt + r.reserved[traversal.key]

	candidateBeliefStore.Lock()
	defer candidateBeliefStore.Unlock()

	b := candidateBeliefStore.beliefs[traversal.key]
	if b == nil {
		b = &candidateBelief{}
		candidateBeliefStore.beliefs[traversal.key] = b
	}

	if b.suspectVotes == 0 {
		b.suspectAmt = required
		b.suspectVotes = 1
		return
	}

	if required < b.suspectAmt || b.suspectAmt == 0 {
		b.suspectAmt = required
	}
	if b.suspectVotes < 255 {
		b.suspectVotes++
	}

	// Requiring three reports keeps a single shifted attribution, and
	// even an unlucky pair, out of the persistent hard-bound store.
	if b.suspectVotes < 3 {
		return
	}

	if b.upperFail == 0 || b.suspectAmt < b.upperFail {
		b.upperFail = b.suspectAmt
	}

	failedEstimate := b.suspectAmt * 70 / 100
	if b.estimate == 0 || failedEstimate < b.estimate {
		b.estimate = failedEstimate
	}
	if b.conf < 8 {
		b.conf++
	}
}

func (r *candidateRouter) recordSuccess(rt *route.Route) {
	traversals := r.routeTraversals(rt)

	candidateBeliefStore.Lock()
	for _, traversal := range traversals {
		required := traversal.amt + r.reserved[traversal.key]

		b := candidateBeliefStore.beliefs[traversal.key]
		if b == nil {
			b = &candidateBelief{}
			candidateBeliefStore.beliefs[traversal.key] = b
		}

		if required > b.lowerOK {
			b.lowerOK = required
		}

		highEstimate := traversal.edge.capacity * 90 / 100
		if required > highEstimate {
			highEstimate = required
		}
		if highEstimate > b.estimate {
			b.estimate = highEstimate
		}
		if b.conf < 8 {
			b.conf++
		}

		if b.upperFail > 0 && required >= b.upperFail {
			b.upperFail = 0
		}
		if b.suspectAmt > 0 && required >= b.suspectAmt {
			b.suspectAmt = 0
			b.suspectVotes = 0
		}
	}
	candidateBeliefStore.Unlock()

	for _, traversal := range traversals {
		required := traversal.amt + r.reserved[traversal.key]

		if observation, ok := r.localObs[traversal.key]; ok &&
			required >= observation.upper {

			delete(r.localObs, traversal.key)
		}

		r.edgePenalty[traversal.key] *= 0.20
		r.reserved[traversal.key] += traversal.amt
		r.usedTotals[traversal.key] += traversal.amt
	}

	r.delivered += candidateDeliveredAmount(rt)
	if r.delivered >= r.spec.Amount && !r.settled {
		r.recordSettlement()
		r.settled = true
	}
}

func (r *candidateRouter) recordSettlement() {
	candidateBeliefStore.Lock()
	defer candidateBeliefStore.Unlock()

	for key, used := range r.usedTotals {
		if used <= 0 {
			continue
		}

		if b := candidateBeliefStore.beliefs[key]; b != nil {
			if b.lowerOK > used {
				b.lowerOK -= used
			} else {
				b.lowerOK = 0
			}

			if b.estimate > used {
				b.estimate -= used
			} else {
				b.estimate = 0
			}

			if b.upperFail > used {
				b.upperFail -= used
			} else {
				b.upperFail = 0
			}

			if b.suspectAmt > used {
				b.suspectAmt -= used
			} else {
				b.suspectAmt = 0
				b.suspectVotes = 0
			}
		}

		reverse := candidateEdgeKey{
			chanID: key.chanID,
			from:   key.to,
			to:     key.from,
		}
		reverseBelief := candidateBeliefStore.beliefs[reverse]
		if reverseBelief == nil {
			reverseBelief = &candidateBelief{}
			candidateBeliefStore.beliefs[reverse] = reverseBelief
		}

		reverseCapacity := lnwire.MilliSatoshi(0)
		if edge := r.edges[reverse]; edge != nil {
			reverseCapacity = edge.capacity
		} else if edge := r.edges[key]; edge != nil {
			reverseCapacity = edge.capacity
		}

		reverseBelief.lowerOK += used
		reverseBelief.estimate += used

		if reverseCapacity > 0 {
			if reverseBelief.lowerOK > reverseCapacity {
				reverseBelief.lowerOK = reverseCapacity
			}
			if reverseBelief.estimate > reverseCapacity {
				reverseBelief.estimate = reverseCapacity
			}
		}

		if reverseBelief.upperFail > 0 {
			reverseBelief.upperFail += used
			if reverseCapacity > 0 &&
				reverseBelief.upperFail > reverseCapacity {

				reverseBelief.upperFail = reverseCapacity
			}
		}
	}
}

func (r *candidateRouter) failureIndex(rt *route.Route,
	source route.Vertex, traversals []candidateTraversal) (int, bool) {

	if len(traversals) != len(rt.Hops) {
		return 0, false
	}

	if source == rt.SourcePubKey {
		return 0, len(traversals) > 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes != source {
			continue
		}

		index := i + 1
		if index >= len(traversals) {
			return 0, false
		}
		return index, true
	}

	return 0, false
}

func (r *candidateRouter) attributionCredibility(
	traversal candidateTraversal) float64 {

	required := traversal.amt + r.reserved[traversal.key]

	// A temporary failure attributed to an outgoing channel whose exact
	// local balance covers the HTLC is almost certainly shifted blame.
	if traversal.key.from == r.source &&
		r.localBalances[traversal.key.chanID] >= required {

		return 0.05
	}

	belief, ok := r.copiedBelief(traversal.key)
	if ok && belief.lowerOK >= required {
		return 0.40
	}

	return 1
}

func (r *candidateRouter) ReportAttempt(attemptID uint64,
	rt *route.Route, result routing.SimHtlcResult) error {

	if result.Failure == nil {
		r.retryCap = 0
		r.recordSuccess(rt)
		return nil
	}

	r.failures++
	traversals := r.routeTraversals(rt)

	// The route failure is real even when its attribution is not. These
	// weak, payment-local observations diversify retries without writing
	// false persistent bounds.
	for _, traversal := range traversals {
		r.observeLocal(traversal, 0.045)
		r.edgePenalty[traversal.key] += 0.018
	}

	code := result.Failure.Code()
	index, attributed := r.failureIndex(
		rt, result.FailureSource, traversals,
	)

	if code == lnwire.CodeTemporaryChannelFailure && attributed {
		credibility := r.attributionCredibility(traversals[index])
		r.observeLocal(traversals[index], 1.15*credibility)
		r.edgePenalty[traversals[index].key] +=
			0.50 * credibility

		neighborWeight := 0.42
		if credibility < 0.5 {
			neighborWeight = 0.90
		}

		if index > 0 {
			r.observeLocal(
				traversals[index-1], neighborWeight,
			)
			r.edgePenalty[traversals[index-1].key] +=
				0.16 * neighborWeight
		}
		if index+1 < len(traversals) {
			r.observeLocal(
				traversals[index+1], neighborWeight,
			)
			r.edgePenalty[traversals[index+1].key] +=
				0.16 * neighborWeight
		}

		if credibility >= 0.8 {
			r.recordPersistentFailure(traversals[index])
		}

		delivered := candidateDeliveredAmount(rt)
		if delivered > 1 {
			r.retryCap = delivered * 62 / 100
		}

		return nil
	}

	if !attributed {
		r.unknownFails++
		for _, traversal := range traversals {
			r.observeLocal(traversal, 0.055)
			r.edgePenalty[traversal.key] += 0.045
		}

		if r.unknownFails%2 == 0 {
			delivered := candidateDeliveredAmount(rt)
			if delivered > 1 {
				r.retryCap = delivered * 72 / 100
			}
		}

		return nil
	}

	if code == lnwire.CodeFeeInsufficient ||
		code == lnwire.CodeIncorrectCltvExpiry {

		r.edgePenalty[traversals[index].key] += 2.5
		if index > 0 {
			r.edgePenalty[traversals[index-1].key] += 0.55
		}
		if index+1 < len(traversals) {
			r.edgePenalty[traversals[index+1].key] += 0.55
		}
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	conf      uint8

	suspectAmt   lnwire.MilliSatoshi
	suspectVotes uint8
}

var candidateBeliefStore = struct {
	sync.Mutex
	beliefs map[candidateEdgeKey]*candidateBelief
}{
	beliefs: make(map[candidateEdgeKey]*candidateBelief),
}

type candidateLocalFailure struct {
	upper lnwire.MilliSatoshi
	count uint8
}

type candidateTraversal struct {
	key  candidateEdgeKey
	edge *candidateEdge
	amt  lnwire.MilliSatoshi
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	reserved    map[candidateEdgeKey]lnwire.MilliSatoshi
	usedTotals  map[candidateEdgeKey]lnwire.MilliSatoshi
	localFails  map[candidateEdgeKey]candidateLocalFailure
	edgePenalty map[candidateEdgeKey]float64

	plannedParts       uint32
	failures           uint32
	unknownFails       uint32
	consecutiveFailures uint32
	retryCap           lnwire.MilliSatoshi
	delivered          lnwire.MilliSatoshi
	settled            bool
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[candidateEdgeKey]*candidateEdge),
		localBalances: localBalances,
		reserved:      make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		usedTotals:    make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		localFails:    make(map[candidateEdgeKey]candidateLocalFailure),
		edgePenalty:   make(map[candidateEdgeKey]float64),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}

	r.plannedParts = r.initialPartCount(spec.Amount)
	if spec.Amount > 250_000_000 {
		r.plannedParts = maxParts
	}
	if r.plannedParts > maxParts {
		r.plannedParts = maxParts
	}
	if r.plannedParts == 0 {
		r.plannedParts = 1
	}

	ctx := context.Background()
	seen := make(map[route.Vertex]bool)
	queue := []route.Vertex{source}
	seen[source] = true

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[key] = edge

				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func (r *candidateRouter) initialPartCount(
	amt lnwire.MilliSatoshi) uint32 {

	switch {
	case amt <= 25_000_000:
		return 1
	case amt <= 100_000_000:
		return 2
	case amt <= 250_000_000:
		return 4
	default:
		return 8
	}
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.003
	}

	x := float64(amt) / float64(capacity)

	lowMode := 0.48 * math.Exp(-x/0.025)
	highMode := 0.50 / (1 + math.Exp((x-0.90)/0.025))
	p := 0.005 + lowMode + highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func candidateLogisticProbability(amt, estimate,
	capacity lnwire.MilliSatoshi) float64 {

	if capacity <= 0 {
		return 0.005
	}

	scale := 0.07 * float64(capacity)
	if scale < 1 {
		scale = 1
	}

	z := (float64(amt) - float64(estimate)) / scale
	if z > 30 {
		return 0.005
	}
	if z < -30 {
		return 0.995
	}

	return 1 / (1 + math.Exp(z))
}

func (r *candidateRouter) edgeProbability(e *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	required := amt + r.reserved[e.key]
	if required > e.capacity {
		return 0.001
	}

	if e.key.from == r.source {
		if r.localBalances[e.key.chanID] < required {
			return 0.001
		}
		return 0.999
	}

	p := candidatePrior(required, e.capacity)

	candidateBeliefStore.Lock()
	stored, ok := candidateBeliefStore.beliefs[e.key]
	var belief candidateBelief
	if ok {
		belief = *stored
	}
	candidateBeliefStore.Unlock()

	if ok {
		if belief.estimate > 0 && belief.conf > 0 {
			q := candidateLogisticProbability(
				required, belief.estimate, e.capacity,
			)
			weight := 0.14 * float64(belief.conf)
			if weight > 0.70 {
				weight = 0.70
			}
			p = (1-weight)*p + weight*q
		}

		if belief.lowerOK > 0 && required <= belief.lowerOK {
			p = math.Max(p, 0.995)
		}

		if belief.upperFail > 0 {
			switch {
			case required >= belief.upperFail:
				p = math.Min(p, 0.008)

			case belief.lowerOK > 0 &&
				belief.upperFail > belief.lowerOK:

				span := float64(
					belief.upperFail - belief.lowerOK,
				)
				pos := float64(
					required - belief.lowerOK,
				) / span
				if pos > 0 {
					bounded := 0.995*(1-pos) + 0.008*pos
					p = 0.35*p + 0.65*bounded
				}
			}
		}
	}

	if local, exists := r.localFails[e.key]; exists &&
		required >= local.upper {

		if local.count >= 2 {
			p = math.Min(p, 0.004)
		} else {
			p *= 0.08
		}
	}

	if p < 0.003 {
		return 0.003
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

func (r *candidateRouter) addEdgePenalty(key candidateEdgeKey,
	delta float64) {

	next := r.edgePenalty[key] + delta
	if next > 5 {
		next = 5
	}
	r.edgePenalty[key] = next
}

func (r *candidateRouter) edgeCost(e *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	p := r.edgeProbability(e, amt)
	cost := -math.Log(p) + 0.025 + r.edgePenalty[e.key]

	if reserved := r.reserved[e.key]; reserved > 0 &&
		e.capacity > 0 {

		required := amt + reserved

		candidateBeliefStore.Lock()
		b := candidateBeliefStore.beliefs[e.key]
		proven := b != nil && b.lowerOK >= required
		candidateBeliefStore.Unlock()

		if proven {
			cost += 0.10 +
				0.25*float64(reserved)/float64(e.capacity)
		} else {
			cost += 0.65 +
				0.90*float64(reserved)/float64(e.capacity)
		}
	}

	return cost
}

type candidateDijkstraItem struct {
	node  route.Vertex
	score float64
	amt   lnwire.MilliSatoshi
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *candidateDijkstraQueue) Push(x any) {
	*q = append(*q, x.(*candidateDijkstraItem))
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}

	score := make(map[route.Vertex]float64)
	arriving := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)

	score[r.spec.Target] = 0
	arriving[r.spec.Target] = amt

	pq := &candidateDijkstraQueue{}
	heap.Push(pq, &candidateDijkstraItem{
		node: r.spec.Target,
		amt:  amt,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)

		bestScore, ok := score[item.node]
		if !ok || item.score > bestScore+1e-12 {
			continue
		}
		if item.amt != arriving[item.node] {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOver := item.amt
			if !edge.policyAllows(amtOver) {
				continue
			}

			required := amtOver + r.reserved[edge.key]
			if required > edge.capacity {
				continue
			}
			if edge.key.from == r.source &&
				r.localBalances[edge.key.chanID] < required {

				continue
			}

			sending := amtOver
			feeCost := 0.0
			if edge.key.from != r.source {
				fee := edge.fee(amtOver)
				sending += fee

				denom := float64(amt)
				if denom < 1 {
					denom = 1
				}
				feeCost = 30 * float64(fee) / denom
			}

			newScore := item.score +
				r.edgeCost(edge, amtOver) + feeCost

			oldScore, exists := score[edge.key.from]
			if exists && newScore >= oldScore {
				continue
			}

			score[edge.key.from] = newScore
			arriving[edge.key.from] = sending
			next[edge.key.from] = edge

			heap.Push(pq, &candidateDijkstraItem{
				node:  edge.key.from,
				score: newScore,
				amt:   sending,
			})
		}
	}

	if _, ok := score[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}

	pathProbability := 1.0
	for _, traversal := range r.routeTraversals(rt) {
		pathProbability *= r.edgeProbability(
			traversal.edge, traversal.amt,
		)
	}

	return rt, pathProbability, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]

		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)

		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateCeilDiv(amt lnwire.MilliSatoshi,
	parts uint32) lnwire.MilliSatoshi {

	if parts <= 1 {
		return amt
	}

	divisor := lnwire.MilliSatoshi(parts)
	return (amt + divisor - 1) / divisor
}

func candidateMin(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if a < b {
		return a
	}
	return b
}

func (r *candidateRouter) targetPartCount() uint32 {
	target := r.plannedParts

	if r.failures > 0 {
		target += 1 + r.failures/3
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if target > maxParts {
		target = maxParts
	}
	if target == 0 {
		target = 1
	}

	return target
}

func (r *candidateRouter) routeLiquidityLimit(
	rt *route.Route) lnwire.MilliSatoshi {

	delivered := candidateDeliveredAmount(rt)
	if delivered <= 0 {
		return 0
	}

	var targetLimit lnwire.MilliSatoshi

	for _, traversal := range r.routeTraversals(rt) {
		edge := traversal.edge
		reserved := r.reserved[traversal.key]

		available := edge.capacity - reserved
		if available <= 0 {
			return 0
		}

		if traversal.key.from == r.source {
			local := r.localBalances[traversal.key.chanID] -
				reserved
			if local <= 0 {
				return 0
			}
			available = candidateMin(available, local)
		} else {
			candidateBeliefStore.Lock()
			stored := candidateBeliefStore.beliefs[traversal.key]
			var belief candidateBelief
			if stored != nil {
				belief = *stored
			}
			candidateBeliefStore.Unlock()

			liquidityEstimate := edge.capacity * 82 / 100
			if belief.estimate > liquidityEstimate {
				liquidityEstimate = belief.estimate
			}
			if belief.lowerOK > liquidityEstimate {
				liquidityEstimate = belief.lowerOK
			}

			if belief.upperFail > reserved {
				belowFailure := (belief.upperFail - reserved) * 58 / 100
				if belowFailure < liquidityEstimate-reserved {
					liquidityEstimate = reserved + belowFailure
				}
			}

			if liquidityEstimate <= reserved {
				return 0
			}
			available = candidateMin(
				available, liquidityEstimate-reserved,
			)
		}

		if edge.maxHTLC > 0 {
			available = candidateMin(available, edge.maxHTLC)
		}

		if available <= 0 || traversal.amt <= 0 {
			return 0
		}

		limit := lnwire.MilliSatoshi(
			float64(delivered) * float64(available) /
				float64(traversal.amt),
		)
		if targetLimit == 0 || limit < targetLimit {
			targetLimit = limit
		}
	}

	return targetLimit
}

func (r *candidateRouter) plannedAverage(
	amt lnwire.MilliSatoshi, inFlightHtlcs,
	partsLeft uint32) lnwire.MilliSatoshi {

	target := r.targetPartCount()
	var slots uint32

	if target > inFlightHtlcs {
		slots = target - inFlightHtlcs
	} else {
		slots = 1
	}
	if slots > partsLeft {
		slots = partsLeft
	}
	if slots == 0 {
		slots = 1
	}

	return candidateCeilDiv(amt, slots)
}

func (r *candidateRouter) chooseFreshShard(
	amt, average lnwire.MilliSatoshi) (*route.Route, error) {

	baseRoute, baseProbability, err := r.findRoute(average)
	if err != nil {
		floor := average / 2
		if floor < 1 {
			floor = 1
		}

		for shard := average * 4 / 5; shard >= floor; {
			if rt, _, findErr := r.findRoute(shard); findErr == nil {
				return rt, nil
			}
			if shard == floor {
				break
			}

			next := shard * 4 / 5
			if next < floor {
				next = floor
			}
			if next == shard {
				break
			}
			shard = next
		}

		if average != amt {
			if rt, _, wholeErr := r.findRoute(amt); wholeErr == nil {
				return rt, nil
			}
		}
		return nil, err
	}

	limit := r.routeLiquidityLimit(baseRoute)
	if limit <= average {
		return baseRoute, nil
	}

	desired := limit * 3 / 4
	maxShard := average * 9 / 4
	if desired > maxShard {
		desired = maxShard
	}
	if desired > amt {
		desired = amt
	}
	if desired <= average {
		return baseRoute, nil
	}

	if rt, probability, findErr := r.findRoute(desired); findErr == nil {
		if probability >= baseProbability*0.22 {
			return rt, nil
		}
	}

	middle := average * 3 / 2
	if middle > amt {
		middle = amt
	}
	if middle > average {
		if rt, probability, findErr := r.findRoute(middle); findErr == nil {
			if probability >= baseProbability*0.38 {
				return rt, nil
			}
		}
	}

	return baseRoute, nil
}

func (r *candidateRouter) chooseRetryShard(
	amt, average, completionAverage lnwire.MilliSatoshi) (
	*route.Route, error) {

	floor := completionAverage * 2 / 5
	if floor < 1 {
		floor = 1
	}

	shard := r.retryCap
	if shard <= 0 || r.consecutiveFailures%5 == 0 {
		shard = average
	}
	if shard < floor {
		shard = floor
	}
	if shard > average {
		shard = average
	}
	if shard > amt {
		shard = amt
	}

	if rt, _, err := r.findRoute(shard); err == nil {
		return rt, nil
	}

	if shard != average {
		if rt, _, err := r.findRoute(average); err == nil {
			return rt, nil
		}
	}

	for candidate := shard * 4 / 5; candidate >= floor; {
		if rt, _, err := r.findRoute(candidate); err == nil {
			return rt, nil
		}
		if candidate == floor {
			break
		}

		next := candidate * 4 / 5
		if next < floor {
			next = floor
		}
		if next == candidate {
			break
		}
		candidate = next
	}

	if rt, _, err := r.findRoute(amt); err == nil {
		return rt, nil
	}

	return nil, errors.New("no route found")
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum parts already in flight")
	}

	partsLeft := maxParts - inFlightHtlcs
	completionAverage := candidateCeilDiv(amt, partsLeft)

	if inFlightHtlcs == 0 && r.failures == 0 {
		if rt, probability, err := r.findRoute(amt); err == nil {
			if r.plannedParts == 1 || probability >= 0.75 {
				return rt, nil
			}
		}
	}

	average := r.plannedAverage(
		amt, inFlightHtlcs, partsLeft,
	)
	if average < completionAverage {
		average = completionAverage
	}
	if average > amt {
		average = amt
	}

	if r.consecutiveFailures > 0 {
		return r.chooseRetryShard(
			amt, average, completionAverage,
		)
	}

	return r.chooseFreshShard(amt, average)
}

func (r *candidateRouter) routeTraversals(
	rt *route.Route) []candidateTraversal {

	traversals := make([]candidateTraversal, 0, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		key := candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		edge := r.edges[key]
		if edge == nil {
			from = hop.PubKeyBytes
			continue
		}

		amt := rt.TotalAmount
		if i > 0 {
			amt = rt.Hops[i-1].AmtToForward
		}

		traversals = append(traversals, candidateTraversal{
			key:  key,
			edge: edge,
			amt:  amt,
		})
		from = hop.PubKeyBytes
	}

	return traversals
}

func candidateDeliveredAmount(rt *route.Route) lnwire.MilliSatoshi {
	if len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func (r *candidateRouter) recordSuccess(rt *route.Route) {
	traversals := r.routeTraversals(rt)

	candidateBeliefStore.Lock()
	for _, traversal := range traversals {
		required := traversal.amt + r.reserved[traversal.key]

		b := candidateBeliefStore.beliefs[traversal.key]
		if b == nil {
			b = &candidateBelief{}
			candidateBeliefStore.beliefs[traversal.key] = b
		}

		if required > b.lowerOK {
			b.lowerOK = required
		}

		highEstimate := traversal.edge.capacity * 88 / 100
		if required > highEstimate {
			highEstimate = required
		}
		if highEstimate > b.estimate {
			b.estimate = highEstimate
		}
		if b.conf < 8 {
			b.conf++
		}

		if b.upperFail > 0 && required >= b.upperFail {
			b.upperFail = 0
		}
		if b.suspectAmt > 0 && required >= b.suspectAmt {
			b.suspectAmt = 0
			b.suspectVotes = 0
		}
	}
	candidateBeliefStore.Unlock()

	for _, traversal := range traversals {
		required := traversal.amt + r.reserved[traversal.key]

		if local, ok := r.localFails[traversal.key]; ok &&
			required >= local.upper {

			delete(r.localFails, traversal.key)
		}

		r.reserved[traversal.key] += traversal.amt
		r.usedTotals[traversal.key] += traversal.amt
	}

	r.delivered += candidateDeliveredAmount(rt)
	if r.delivered >= r.spec.Amount && !r.settled {
		r.recordSettlement()
		r.settled = true
	}
}

func (r *candidateRouter) recordSettlement() {
	candidateBeliefStore.Lock()
	defer candidateBeliefStore.Unlock()

	for key, used := range r.usedTotals {
		if used <= 0 {
			continue
		}

		if b := candidateBeliefStore.beliefs[key]; b != nil {
			if b.lowerOK > used {
				b.lowerOK -= used
			} else {
				b.lowerOK = 0
			}

			if b.estimate > used {
				b.estimate -= used
			} else {
				b.estimate = 0
			}

			if b.upperFail > used {
				b.upperFail -= used
			} else {
				b.upperFail = 0
			}

			if b.suspectAmt > used {
				b.suspectAmt -= used
			} else {
				b.suspectAmt = 0
				b.suspectVotes = 0
			}
		}

		reverse := candidateEdgeKey{
			chanID: key.chanID,
			from:   key.to,
			to:     key.from,
		}
		reverseBelief := candidateBeliefStore.beliefs[reverse]
		if reverseBelief == nil {
			reverseBelief = &candidateBelief{}
			candidateBeliefStore.beliefs[reverse] = reverseBelief
		}

		reverseCapacity := lnwire.MilliSatoshi(0)
		if edge := r.edges[reverse]; edge != nil {
			reverseCapacity = edge.capacity
		} else if edge := r.edges[key]; edge != nil {
			reverseCapacity = edge.capacity
		}

		reverseBelief.lowerOK += used
		reverseBelief.estimate += used

		if reverseCapacity > 0 {
			if reverseBelief.lowerOK > reverseCapacity {
				reverseBelief.lowerOK = reverseCapacity
			}
			if reverseBelief.estimate > reverseCapacity {
				reverseBelief.estimate = reverseCapacity
			}
		}

		if reverseBelief.upperFail > 0 {
			reverseBelief.upperFail += used
			if reverseCapacity > 0 &&
				reverseBelief.upperFail > reverseCapacity {

				reverseBelief.upperFail = reverseCapacity
			}
		}
	}
}

func (r *candidateRouter) failureEdge(rt *route.Route,
	source route.Vertex) (candidateTraversal, bool) {

	traversals := r.routeTraversals(rt)
	if len(traversals) != len(rt.Hops) {
		return candidateTraversal{}, false
	}

	index := -1
	if source == rt.SourcePubKey {
		index = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == source {
				index = i + 1
				break
			}
		}
	}

	if index < 0 || index >= len(traversals) {
		return candidateTraversal{}, false
	}

	return traversals[index], true
}

func (r *candidateRouter) recordAttributedLiquidityFailure(
	traversal candidateTraversal) bool {

	required := traversal.amt + r.reserved[traversal.key]

	// The sender's balance is exact. A report contradicting it is shifted
	// attribution and must not poison that channel.
	if traversal.key.from == r.source &&
		r.localBalances[traversal.key.chanID] >= required {

		return false
	}

	local := r.localFails[traversal.key]
	if local.upper == 0 || required < local.upper {
		local.upper = required
	}
	if local.count < 255 {
		local.count++
	}
	r.localFails[traversal.key] = local

	if traversal.key.from == r.source {
		return true
	}

	candidateBeliefStore.Lock()
	defer candidateBeliefStore.Unlock()

	b := candidateBeliefStore.beliefs[traversal.key]
	if b == nil {
		b = &candidateBelief{}
		candidateBeliefStore.beliefs[traversal.key] = b
	}

	if b.suspectVotes == 0 {
		b.suspectAmt = required
		b.suspectVotes = 1
		return true
	}

	if required < b.suspectAmt || b.suspectAmt == 0 {
		b.suspectAmt = required
	}
	if b.suspectVotes < 255 {
		b.suspectVotes++
	}

	// Persistent bounds require corroboration inside this payment. This
	// keeps isolated shifted reports from accumulating across payments.
	if local.count >= 2 && b.suspectVotes >= 2 {
		if b.upperFail == 0 || b.suspectAmt < b.upperFail {
			b.upperFail = b.suspectAmt
		}

		failedEstimate := required * 70 / 100
		if b.estimate == 0 || failedEstimate < b.estimate {
			b.estimate = failedEstimate
		}
		if b.conf < 8 {
			b.conf++
		}
	}

	return true
}

func (r *candidateRouter) recordUnknownRouteFailure(
	traversals []candidateTraversal) {

	if len(traversals) == 0 {
		return
	}

	weights := make([]float64, len(traversals))
	total := 0.0

	for i, traversal := range traversals {
		p := r.edgeProbability(traversal.edge, traversal.amt)
		weight := 1 - p
		if weight < 0.01 {
			weight = 0.01
		}
		weights[i] = weight
		total += weight
	}

	if total <= 0 {
		return
	}

	for i, traversal := range traversals {
		// One unreadable failure contributes one bounded unit of route
		// diversification instead of penalizing every edge equally.
		r.addEdgePenalty(
			traversal.key, 0.90*weights[i]/total,
		)
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64,
	rt *route.Route, result routing.SimHtlcResult) error {

	if result.Failure == nil {
		r.retryCap = 0
		r.consecutiveFailures = 0
		r.recordSuccess(rt)
		return nil
	}

	r.failures++
	r.consecutiveFailures++

	traversals := r.routeTraversals(rt)
	code := result.Failure.Code()

	if code == lnwire.CodeTemporaryChannelFailure {
		if traversal, ok := r.failureEdge(
			rt, result.FailureSource,
		); ok {
			if r.recordAttributedLiquidityFailure(traversal) {
				delivered := candidateDeliveredAmount(rt)
				if delivered > 1 {
					r.retryCap = delivered * 58 / 100
				}
				return nil
			}
		}
	}

	r.unknownFails++
	r.recordUnknownRouteFailure(traversals)

	if code == lnwire.CodeFeeInsufficient ||
		code == lnwire.CodeIncorrectCltvExpiry {

		if traversal, ok := r.failureEdge(
			rt, result.FailureSource,
		); ok {
			r.addEdgePenalty(traversal.key, 0.75)
		}
	}

	delivered := candidateDeliveredAmount(rt)
	if delivered > 1 {
		switch {
		case r.consecutiveFailures <= 2:
			r.retryCap = delivered * 68 / 100
		case r.consecutiveFailures%5 == 0:
			r.retryCap = 0
		default:
			r.retryCap = delivered * 55 / 100
		}
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi

	suspectAmt   lnwire.MilliSatoshi
	suspectVotes uint8
	stamp        uint64
}

var candidateMemory = struct {
	sync.Mutex
	epoch   uint64
	beliefs map[candidateEdgeKey]candidateBelief
}{
	beliefs: make(map[candidateEdgeKey]candidateBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec
	epoch  uint64

	incomingEdges map[route.Vertex][]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[candidateEdgeKey]candidateBelief

	// Successful shards consume or hold this much liquidity. Including these
	// reservations in every later path calculation is essential for atomic
	// MPP, and is also correct after an immediately settled shard.
	reserved map[candidateEdgeKey]lnwire.MilliSatoshi

	// Penalties are payment-local. They diversify siblings and failed
	// attempts without converting unreadable failures into persistent facts.
	edgePenalty map[candidateEdgeKey]float64

	retryLimit         lnwire.MilliSatoshi
	consecutiveFailure uint8
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	candidateMemory.Lock()
	candidateMemory.epoch++
	epoch := candidateMemory.epoch

	snapshot := make(map[candidateEdgeKey]candidateBelief,
		len(candidateMemory.beliefs))
	for key, belief := range candidateMemory.beliefs {
		snapshot[key] = belief
	}
	candidateMemory.Unlock()

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		epoch:         epoch,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		localBalances: localBalances,
		beliefs:       snapshot,
		reserved:      make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		edgePenalty:   make(map[candidateEdgeKey]float64),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
					},
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: policy.FeeBaseMSat,
					feeRatePPM: policy.
						FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func candidateClampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005
	case p > 0.995:
		return 0.995
	default:
		return p
	}
}

// The prior reflects a channel that is usually near one endpoint rather
// than uniformly distributed. Reducing a medium-sized shard helps mainly
// by crossing the low-mode exponential or the high-mode capacity cliff.
func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.025)
	highMode := 1 / (1 + math.Exp(18*(x-0.82)))

	return candidateClampProbability(0.5*lowMode + 0.5*highMode)
}

func (r *candidateRouter) evidenceConfidence(b candidateBelief) float64 {
	if b.stamp == 0 || r.epoch <= b.stamp+3 {
		return 1
	}

	age := float64(r.epoch - b.stamp - 3)
	return math.Max(0.12, math.Exp(-age/12))
}

func (r *candidateRouter) probability(edge *candidateEdge,
	totalAmt lnwire.MilliSatoshi) float64 {

	if edge.from == r.source {
		if totalAmt <= r.localBalances[edge.chanID] {
			return 0.999
		}
		return 0.001
	}

	prior := candidatePrior(totalAmt, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok || belief.stamp == 0 {
		return prior
	}

	learned := prior

	switch {
	case belief.lowerOK > 0 && totalAmt <= belief.lowerOK:
		learned = 0.995

	case belief.upperFail > 0 && totalAmt >= belief.upperFail:
		learned = 0.008

	case belief.lowerOK > 0 && belief.upperFail > belief.lowerOK:
		span := float64(belief.upperFail - belief.lowerOK)
		pos := float64(totalAmt-belief.lowerOK) / span
		pos = math.Max(0, math.Min(1, pos))
		learned = 0.995*(1-pos) + 0.008*pos

	case belief.lowerOK > 0 && totalAmt > belief.lowerOK:
		ratio := float64(belief.lowerOK) / float64(totalAmt)
		learned = prior + (0.995-prior)*ratio*ratio

	case belief.upperFail > 0 && totalAmt < belief.upperFail:
		ratio := float64(totalAmt) / float64(belief.upperFail)
		learned = prior * (1 - 0.72*ratio*ratio)
	}

	if belief.upperFail == 0 && belief.suspectAmt > 0 &&
		totalAmt >= belief.suspectAmt {

		learned *= 0.58
	}

	confidence := r.evidenceConfidence(belief)
	return candidateClampProbability(
		confidence*learned + (1-confidence)*prior,
	)
}

type candidateItem struct {
	node  route.Vertex
	score float64
}

type candidateQueue []*candidateItem

func (q candidateQueue) Len() int {
	return len(q)
}

func (q candidateQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *candidateQueue) Push(value any) {
	*q = append(*q, value.(*candidateItem))
}

func (q *candidateQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]
	return last
}

type candidatePath struct {
	route       *route.Route
	edges       []*candidateEdge
	probability float64
	pressure    float64
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*candidatePath, error) {

	return r.findRouteWithPenalty(amt, nil)
}

func (r *candidateRouter) findRouteWithPenalty(
	amt lnwire.MilliSatoshi,
	extra map[candidateEdgeKey]float64) (*candidatePath, error) {

	if amt <= 0 {
		return nil, errors.New("invalid payment amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is target")
	}

	scores := make(map[route.Vertex]float64)
	amounts := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)

	scores[r.spec.Target] = 0
	amounts[r.spec.Target] = amt

	pq := &candidateQueue{}
	heap.Push(pq, &candidateItem{
		node:  r.spec.Target,
		score: 0,
	})

	for pq.Len() != 0 {
		item := heap.Pop(pq).(*candidateItem)
		bestScore, ok := scores[item.node]
		if !ok || item.score > bestScore+1e-12 {
			continue
		}
		if item.node == r.source {
			break
		}

		arriving := amounts[item.node]

		for _, edge := range r.incomingEdges[item.node] {
			if !edge.usable(arriving) {
				continue
			}

			totalLiquidity := arriving + r.reserved[edge.key]
			if totalLiquidity < arriving ||
				totalLiquidity > edge.capacity {

				continue
			}

			if edge.from == r.source &&
				totalLiquidity > r.localBalances[edge.chanID] {

				continue
			}

			sending := arriving
			fee := lnwire.MilliSatoshi(0)
			if edge.from != r.source {
				fee = edge.fee(arriving)
				sending += fee
				if sending < arriving {
					continue
				}
			}

			p := r.probability(edge, totalLiquidity)
			edgeCost := -math.Log(p) + 0.02
			if arriving > 0 {
				edgeCost += 4.0 * float64(fee) /
					float64(arriving)
			}

			edgeCost += r.edgePenalty[edge.key]
			if r.reserved[edge.key] > 0 &&
				edge.from != r.source {

				edgeCost += 0.45
			}
			if extra != nil {
				edgeCost += extra[edge.key]
			}

			newScore := item.score + edgeCost
			oldScore, visited := scores[edge.from]
			if visited && newScore >= oldScore {
				continue
			}

			scores[edge.from] = newScore
			amounts[edge.from] = sending
			next[edge.from] = edge
			heap.Push(pq, &candidateItem{
				node:  edge.from,
				score: newScore,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	rt, path, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, err
	}

	return r.assessPath(rt, path), nil
}

func (r *candidateRouter) assessPath(rt *route.Route,
	path []*candidateEdge) *candidatePath {

	probability := 1.0
	pressure := 0.0

	for i, edge := range path {
		amtOver := candidateRouteAmount(rt, i)
		totalLiquidity := amtOver + r.reserved[edge.key]

		probability *= r.probability(edge, totalLiquidity)

		denominator := edge.capacity
		if edge.from == r.source {
			denominator = r.localBalances[edge.chanID]
		}

		if denominator > 0 {
			ratio := float64(totalLiquidity) /
				float64(denominator)
			if ratio > pressure {
				pressure = ratio
			}
		}
	}

	return &candidatePath{
		route:       rt,
		edges:       path,
		probability: probability,
		pressure:    pressure,
	}
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route,
	[]*candidateEdge, error) {

	var path []*candidateEdge
	seen := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if seen[node] {
			return nil, nil, errors.New("cycle in route")
		}
		seen[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.to
	}

	rt, err := r.buildFixedRoute(amt, path)
	return rt, path, err
}

func (r *candidateRouter) buildFixedRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, error) {

	const finalCltvDelta = uint32(40)

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	for i := 1; i < len(path); i++ {
		if path[i-1].to != path[i].from {
			return nil, errors.New("disconnected route")
		}
	}
	if path[0].from != r.source ||
		path[len(path)-1].to != r.spec.Target {

		return nil, errors.New("route endpoints do not match")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		fee := forwardingEdge.fee(amtOver[i+1])
		amtOver[i] = amtOver[i+1] + fee
		if amtOver[i] < amtOver[i+1] {
			return nil, errors.New("amount overflow")
		}

		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
		if expiryOver[i] < expiryOver[i+1] {
			return nil, errors.New("cltv overflow")
		}
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := finalCltvDelta

		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

// candidateLiquidityLimit provides two planning envelopes. The safe envelope
// avoids the prior's capacity cliff. The hard envelope permits deliberate
// unequal allocations when the payment cannot fit otherwise. Neither is used
// to blacklist an edge during ordinary pathfinding.
func (r *candidateRouter) candidateLiquidityLimit(
	edge *candidateEdge, safe bool) lnwire.MilliSatoshi {

	if edge.from == r.source {
		return r.localBalances[edge.chanID]
	}

	limit := edge.capacity
	if safe {
		limit = edge.capacity * 82 / 100
	}

	belief, ok := r.beliefs[edge.key]
	if !ok || belief.stamp == 0 {
		return limit
	}

	confidence := r.evidenceConfidence(belief)
	if belief.lowerOK > limit && confidence >= 0.45 {
		limit = belief.lowerOK
	}

	if belief.upperFail > 0 && confidence >= 0.72 {
		failureLimit := belief.upperFail * 98 / 100
		if safe {
			failureLimit = belief.upperFail * 72 / 100
		}
		if belief.lowerOK > failureLimit {
			failureLimit = belief.lowerOK
		}
		if failureLimit < limit {
			limit = failureLimit
		}
	}

	if limit > edge.capacity {
		limit = edge.capacity
	}
	return limit
}

func (r *candidateRouter) fixedPathAt(amt lnwire.MilliSatoshi,
	edges []*candidateEdge, safe bool) (*candidatePath, error) {

	rt, err := r.buildFixedRoute(amt, edges)
	if err != nil {
		return nil, err
	}

	for i, edge := range edges {
		amtOver := candidateRouteAmount(rt, i)
		if !edge.usable(amtOver) {
			return nil, errors.New("path violates htlc limits")
		}

		total := amtOver + r.reserved[edge.key]
		if total < amtOver ||
			total > r.candidateLiquidityLimit(edge, safe) {

			return nil, errors.New("path exceeds liquidity envelope")
		}
	}

	return r.assessPath(rt, edges), nil
}

func (r *candidateRouter) minimumFixedAmount(
	edges []*candidateEdge,
	known lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if known <= 0 {
		return 0
	}
	if _, err := r.fixedPathAt(known, edges, false); err != nil {
		return 0
	}

	low := lnwire.MilliSatoshi(1)
	high := known
	for low < high {
		mid := low + (high-low)/2
		if _, err := r.fixedPathAt(mid, edges, false); err == nil {
			high = mid
		} else {
			low = mid + 1
		}
	}

	return low
}

func (r *candidateRouter) maximumFixedAmount(
	edges []*candidateEdge, minimum, maximum lnwire.MilliSatoshi,
	safe bool) lnwire.MilliSatoshi {

	if minimum <= 0 || maximum < minimum {
		return 0
	}
	if _, err := r.fixedPathAt(minimum, edges, safe); err != nil {
		return 0
	}
	if _, err := r.fixedPathAt(maximum, edges, safe); err == nil {
		return maximum
	}

	low := minimum
	high := maximum
	for low < high {
		mid := low + (high-low+1)/2
		if _, err := r.fixedPathAt(mid, edges, safe); err == nil {
			low = mid
		} else {
			high = mid - 1
		}
	}

	return low
}

type candidatePlanPath struct {
	edges   []*candidateEdge
	minimum lnwire.MilliSatoshi
	safe    lnwire.MilliSatoshi
	hard    lnwire.MilliSatoshi
}

func candidateSamePath(a, b []*candidateEdge) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i].key != b[i].key {
			return false
		}
	}
	return true
}

// Source channels may legitimately feed several independent corridors and
// have exact known balances. Other shared channels make two planned shards
// compete for the same hidden directional liquidity.
func candidatePathsConflict(a, b []*candidateEdge) bool {
	for _, left := range a {
		if left.from == left.to {
			continue
		}
		for _, right := range b {
			if left.key == right.key && left.from != right.from {
				continue
			}
			if left.key == right.key && left.from != (route.Vertex{}) {
				// Sharing the sender's known local channel is allowed.
				if left.from == a[0].from &&
					right.from == b[0].from {

					continue
				}
				return true
			}
		}
	}
	return false
}

func (r *candidateRouter) enumeratePlanPaths(
	amt lnwire.MilliSatoshi, slots uint32) []candidatePlanPath {

	minimumShard := lnwire.MilliSatoshi(1_000_000)
	equal := candidateCeilDiv(amt, slots)

	seeds := []lnwire.MilliSatoshi{
		equal,
		minimumShard,
		50_000_000,
		amt,
	}

	raw := make([]candidatePlanPath, 0, 12)

	for _, seed := range seeds {
		if seed <= 0 || seed > amt {
			continue
		}

		extra := make(map[candidateEdgeKey]float64)
		tries := int(slots) + 2
		if tries > 8 {
			tries = 8
		}

		for attempt := 0; attempt < tries; attempt++ {
			path, err := r.findRouteWithPenalty(seed, extra)
			if err != nil {
				break
			}

			found := false
			for i := range raw {
				if candidateSamePath(raw[i].edges, path.edges) {
					found = true
					break
				}
			}

			if !found && len(raw) < 12 {
				edges := append(
					[]*candidateEdge(nil), path.edges...,
				)
				raw = append(raw, candidatePlanPath{
					edges: edges,
				})
			}

			for _, edge := range path.edges {
				penalty := 2.2
				if edge.from == r.source {
					penalty = 0.35
				}
				extra[edge.key] += penalty
			}
		}
	}

	plans := make([]candidatePlanPath, 0, len(raw))
	for _, plan := range raw {
		known := amt
		if path, err := r.findMatchingSeed(plan.edges, seeds); err == nil {
			known = path
		}

		minimum := r.minimumFixedAmount(plan.edges, known)
		if minimum == 0 {
			continue
		}

		plan.minimum = minimum
		plan.hard = r.maximumFixedAmount(
			plan.edges, minimum, amt, false,
		)
		plan.safe = r.maximumFixedAmount(
			plan.edges, minimum, amt, true,
		)
		if plan.hard > 0 {
			plans = append(plans, plan)
		}
	}

	return plans
}

func (r *candidateRouter) findMatchingSeed(edges []*candidateEdge,
	seeds []lnwire.MilliSatoshi) (lnwire.MilliSatoshi, error) {

	best := lnwire.MilliSatoshi(0)
	for _, seed := range seeds {
		if seed <= 0 {
			continue
		}
		if _, err := r.fixedPathAt(seed, edges, false); err == nil {
			if best == 0 || seed < best {
				best = seed
			}
		}
	}
	if best == 0 {
		return 0, errors.New("no feasible seed")
	}
	return best, nil
}

func (r *candidateRouter) alternativeCapacity(
	plans []candidatePlanPath, skip int, slots int) lnwire.MilliSatoshi {

	if slots <= 0 {
		return 0
	}

	order := make([]int, 0, len(plans))
	for i := range plans {
		if i != skip {
			order = append(order, i)
		}
	}
	sort.Slice(order, func(i, j int) bool {
		return plans[order[i]].hard > plans[order[j]].hard
	})

	chosen := make([]int, 0, slots)
	total := lnwire.MilliSatoshi(0)

	for _, index := range order {
		if candidatePathsConflict(
			plans[skip].edges, plans[index].edges,
		) {
			continue
		}

		conflict := false
		for _, prior := range chosen {
			if candidatePathsConflict(
				plans[prior].edges,
				plans[index].edges,
			) {
				conflict = true
				break
			}
		}
		if conflict {
			continue
		}

		chosen = append(chosen, index)
		total += plans[index].hard
		if len(chosen) == slots {
			break
		}
	}

	return total
}

// planShard jointly considers several distinct route corridors and their
// feasible amount envelopes. It chooses the current shard large enough that
// the remaining corridors can cover the rest, which naturally produces
// unequal splits for unequal channel capacities.
func (r *candidateRouter) planShard(
	amt lnwire.MilliSatoshi, partsLeft uint32) (*candidatePath, error) {

	slots := partsLeft
	if slots > 6 {
		slots = 6
	}
	if slots < 2 {
		return nil, errors.New("not enough parts for planning")
	}

	plans := r.enumeratePlanPaths(amt, slots)
	if len(plans) == 0 {
		return nil, errors.New("no splittable route set")
	}

	equal := candidateCeilDiv(amt, slots)
	bestScore := math.Inf(1)
	var best *candidatePath

	for i := range plans {
		other := r.alternativeCapacity(
			plans, i, int(slots)-1,
		)

		required := equal
		if other < amt {
			needed := amt - other
			if needed > required {
				required = needed
			}
		}
		if required < plans[i].minimum {
			required = plans[i].minimum
		}
		if required > plans[i].hard || required > amt {
			continue
		}

		path, err := r.fixedPathAt(
			required, plans[i].edges, false,
		)
		if err != nil {
			continue
		}

		fee := path.route.TotalAmount - required
		score := -math.Log(path.probability)
		if required > 0 {
			score += 3 * float64(fee) / float64(required)
		}

		if plans[i].safe > 0 && required > plans[i].safe {
			span := plans[i].hard - plans[i].safe
			if span > 0 {
				score += 0.7 * float64(
					required-plans[i].safe,
				) / float64(span)
			}
		}

		// Prefer a deliberate non-trivial commitment over tiny shards
		// when route-set coverage and reliability are otherwise similar.
		score += 0.04 * float64(equal) / float64(required)

		if score < bestScore {
			bestScore = score
			best = path
		}
	}

	if best == nil {
		return nil, errors.New("route set cannot cover remainder")
	}
	return best, nil
}

func candidateCeilDiv(a lnwire.MilliSatoshi,
	b uint32) lnwire.MilliSatoshi {

	if b <= 1 {
		return a
	}
	divisor := lnwire.MilliSatoshi(b)
	return a/divisor + func() lnwire.MilliSatoshi {
		if a%divisor != 0 {
			return 1
		}
		return 0
	}()
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid remaining amount")
	}

	partsLeft := uint32(1)
	if r.spec.MaxParts > inFlightHtlcs {
		partsLeft = r.spec.MaxParts - inFlightHtlcs
	}

	if partsLeft <= 1 {
		path, err := r.findRoute(amt)
		if err != nil {
			return nil, err
		}
		return path.route, nil
	}

	full, fullErr := r.findRoute(amt)
	if fullErr == nil &&
		(amt <= 10_000_000 ||
			full.probability >= 0.80 ||
			(full.probability >= 0.62 &&
				full.pressure < 0.18)) {

		return full.route, nil
	}

	if planned, err := r.planShard(amt, partsLeft); err == nil {
		return planned.route, nil
	}

	// A lower retry can be impossible solely because of min-HTLC policy.
	// Search several legal allocations and finally retry the whole amount
	// instead of terminally giving up while a route still exists.
	amounts := make([]lnwire.MilliSatoshi, 0, 10)
	if r.retryLimit > 0 && r.retryLimit <= amt {
		amounts = append(amounts, r.retryLimit)
	}

	slots := partsLeft
	if slots > 6 {
		slots = 6
	}
	for n := slots; n >= 2; n-- {
		amounts = append(amounts, candidateCeilDiv(amt, n))
	}
	amounts = append(amounts, amt)

	var lastErr error
	seen := make(map[lnwire.MilliSatoshi]bool)
	for _, candidateAmt := range amounts {
		if candidateAmt <= 0 || candidateAmt > amt ||
			seen[candidateAmt] {

			continue
		}
		seen[candidateAmt] = true

		path, err := r.findRoute(candidateAmt)
		if err == nil {
			return path.route, nil
		}
		lastErr = err
	}

	if fullErr == nil {
		return full.route, nil
	}
	if lastErr != nil {
		return nil, lastErr
	}
	return nil, fullErr
}

func candidateRouteAmount(rt *route.Route,
	edgeIndex int) lnwire.MilliSatoshi {

	if edgeIndex == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[edgeIndex-1].AmtToForward
}

func candidateRouteEdgeKey(rt *route.Route,
	edgeIndex int) candidateEdgeKey {

	from := rt.SourcePubKey
	if edgeIndex > 0 {
		from = rt.Hops[edgeIndex-1].PubKeyBytes
	}

	return candidateEdgeKey{
		chanID: rt.Hops[edgeIndex].ChannelID,
		from:   from,
	}
}

func candidateFailureEdge(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func candidateIsLiquidityFailure(failure any) bool {
	_, ok := failure.(*lnwire.FailTemporaryChannelFailure)
	return ok
}

func candidateIsPolicyFailure(failure any) bool {
	switch failure.(type) {
	case *lnwire.FailFeeInsufficient,
		*lnwire.FailIncorrectCltvExpiry:
		return true
	default:
		return false
	}
}

func (r *candidateRouter) saveBelief(
	key candidateEdgeKey, belief candidateBelief) {

	belief.stamp = r.epoch
	r.beliefs[key] = belief

	candidateMemory.Lock()
	candidateMemory.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) recordSuccess(key candidateEdgeKey,
	totalAmt lnwire.MilliSatoshi) {

	belief := r.beliefs[key]

	if totalAmt > belief.lowerOK {
		belief.lowerOK = totalAmt
	}

	// Success attribution is always truthful and invalidates incompatible
	// failure observations immediately.
	if belief.upperFail > 0 && totalAmt >= belief.upperFail {
		belief.upperFail = 0
	}
	if belief.suspectAmt > 0 && totalAmt >= belief.suspectAmt {
		belief.suspectAmt = 0
		belief.suspectVotes = 0
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) recordFailure(key candidateEdgeKey,
	totalAmt lnwire.MilliSatoshi) {

	belief := r.beliefs[key]

	// Do not allow an isolated old accusation to corroborate a new one
	// after background traffic has had several payments to move liquidity.
	if belief.stamp > 0 && r.epoch > belief.stamp+4 {
		belief.suspectAmt = 0
		belief.suspectVotes = 0
	}

	corroborates := false
	if belief.suspectAmt > 0 {
		low := belief.suspectAmt * 60 / 100
		high := belief.suspectAmt * 150 / 100
		corroborates = totalAmt >= low && totalAmt <= high
	}

	if corroborates {
		if belief.suspectVotes < 255 {
			belief.suspectVotes++
		}
		if totalAmt < belief.suspectAmt {
			belief.suspectAmt = totalAmt
		}
	} else {
		belief.suspectAmt = totalAmt
		belief.suspectVotes = 1
	}

	requiredVotes := uint8(2)
	if belief.lowerOK > 0 && totalAmt <= belief.lowerOK {
		requiredVotes = 3
	}

	if belief.suspectVotes >= requiredVotes {
		if totalAmt <= belief.lowerOK {
			belief.lowerOK = 0
		}
		if belief.upperFail == 0 ||
			belief.suspectAmt < belief.upperFail {

			belief.upperFail = belief.suspectAmt
		}
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if rt == nil || len(rt.Hops) == 0 {
		return nil
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key := candidateRouteEdgeKey(rt, i)
			amtOver := candidateRouteAmount(rt, i)
			totalAmt := amtOver + r.reserved[key]

			r.recordSuccess(key, totalAmt)
			r.reserved[key] += amtOver

			// A held shard is reliable evidence, but a modest diversity
			// cost keeps the next sibling from consuming the same hidden
			// corridor merely because it just succeeded.
			if i > 0 {
				r.edgePenalty[key] = math.Max(
					0, r.edgePenalty[key]*0.30+0.25,
				)
			} else {
				r.edgePenalty[key] *= 0.30
			}
		}

		r.retryLimit = 0
		r.consecutiveFailure = 0
		return nil
	}

	if r.consecutiveFailure < 255 {
		r.consecutiveFailure++
	}

	// Unreadable failure conveys route-level information only. Its small
	// diversity penalty is deliberately too weak to become a liquidity
	// ceiling or poison persistent memory.
	for i := range rt.Hops {
		key := candidateRouteEdgeKey(rt, i)
		r.edgePenalty[key] = math.Min(
			3, r.edgePenalty[key]+0.10,
		)
	}

	failIndex := candidateFailureEdge(
		rt, result.FailureSource,
	)
	attributed := failIndex >= 0 && failIndex < len(rt.Hops)
	delivered := rt.Hops[len(rt.Hops)-1].AmtToForward

	if candidateIsLiquidityFailure(result.Failure) && attributed {
		key := candidateRouteEdgeKey(rt, failIndex)
		amtOver := candidateRouteAmount(rt, failIndex)
		totalAmt := amtOver + r.reserved[key]

		r.recordFailure(key, totalAmt)
		r.edgePenalty[key] = math.Min(
			6, r.edgePenalty[key]+0.85,
		)

		// Shifted blame is usually adjacent. Give neighboring edges only a
		// transient hint; repeated direct blame is still required before
		// any persistent bound is written.
		if failIndex > 0 {
			neighbor := candidateRouteEdgeKey(
				rt, failIndex-1,
			)
			r.edgePenalty[neighbor] = math.Min(
				3, r.edgePenalty[neighbor]+0.12,
			)
		}
		if failIndex+1 < len(rt.Hops) {
			neighbor := candidateRouteEdgeKey(
				rt, failIndex+1,
			)
			r.edgePenalty[neighbor] = math.Min(
				3, r.edgePenalty[neighbor]+0.12,
			)
		}

		// First try another corridor at the same deliberate shard size.
		// Only repeated failure starts lowering the shard.
		if r.consecutiveFailure == 1 {
			r.retryLimit = delivered
		} else {
			lower := delivered * 70 / 100
			if lower < 1_000_000 {
				lower = 1_000_000
			}
			r.retryLimit = lower
		}

		return nil
	}

	if candidateIsPolicyFailure(result.Failure) && attributed {
		key := candidateRouteEdgeKey(rt, failIndex)
		r.edgePenalty[key] = math.Min(
			6, r.edgePenalty[key]+1.6,
		)
	}

	// Unknown attribution and policy failures should preserve the shard
	// size and seek a different route.
	r.retryLimit = delivered
	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	chanID  uint64
	from    route.Vertex
	to      route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi

	suspectAmt   lnwire.MilliSatoshi
	suspectVotes uint8

	stamp uint64
}

var candidateMemory = struct {
	sync.Mutex
	epoch   uint64
	beliefs map[candidateEdgeKey]candidateBelief
}{
	beliefs: make(map[candidateEdgeKey]candidateBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec
	epoch  uint64

	incomingEdges map[route.Vertex][]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[candidateEdgeKey]candidateBelief

	// Reserved tracks liquidity already consumed or held by successful
	// shards in this payment.
	reserved map[candidateEdgeKey]lnwire.MilliSatoshi

	// Penalties are payment-local. They diversify retries and MPP shards
	// without turning unreadable failures into persistent channel facts.
	edgePenalty map[candidateEdgeKey]float64

	// A corroborated liquidity failure requests a smaller first shard when
	// the next route set is planned.
	retryLimit lnwire.MilliSatoshi

	// A route set is built jointly before the first shard is returned. Later
	// calls consume this plan while the remaining amount matches.
	plan         []*route.Route
	planExpected lnwire.MilliSatoshi
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	candidateMemory.Lock()
	candidateMemory.epoch++
	epoch := candidateMemory.epoch

	snapshot := make(map[candidateEdgeKey]candidateBelief,
		len(candidateMemory.beliefs))
	for key, belief := range candidateMemory.beliefs {
		snapshot[key] = belief
	}
	candidateMemory.Unlock()

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		epoch:         epoch,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		localBalances: localBalances,
		beliefs:       snapshot,
		reserved:      make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		edgePenalty:   make(map[candidateEdgeKey]float64),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}

				edge := &candidateEdge{
					key:      key,
					chanID:   ch.ChannelID,
					from:     ch.OtherNode,
					to:       node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func candidateClampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005
	case p > 0.995:
		return 0.995
	default:
		return p
	}
}

// candidatePrior models the dominant bimodal balance distribution. Tiny
// amounts fit in either balance mode; larger amounts generally require the
// channel's full mode, followed by a steep capacity cliff.
func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.024)
	highMode := 1 / (1 + math.Exp(19*(x-0.81)))

	return candidateClampProbability(0.5*lowMode + 0.5*highMode)
}

func (r *candidateRouter) evidenceConfidence(b candidateBelief) float64 {
	if b.stamp == 0 || r.epoch <= b.stamp+4 {
		return 1
	}

	age := float64(r.epoch - b.stamp - 4)
	return math.Max(0.15, math.Exp(-age/14))
}

func (r *candidateRouter) probability(edge *candidateEdge,
	totalAmt lnwire.MilliSatoshi) float64 {

	if edge.from == r.source {
		if totalAmt <= r.localBalances[edge.chanID] {
			return 0.999
		}

		return 0.001
	}

	prior := candidatePrior(totalAmt, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok || belief.stamp == 0 {
		return prior
	}

	learned := prior

	switch {
	case belief.lowerOK > 0 && totalAmt <= belief.lowerOK:
		learned = 0.995

	case belief.upperFail > 0 && totalAmt >= belief.upperFail:
		// Corroborated failures remain a strong warning, but never make an
		// edge impossible. This avoids terminal route loss after shifted
		// attribution or genuine liquidity movement.
		learned = 0.018

	case belief.lowerOK > 0 && belief.upperFail > belief.lowerOK:
		span := float64(belief.upperFail - belief.lowerOK)
		pos := float64(totalAmt-belief.lowerOK) / span
		pos = math.Max(0, math.Min(1, pos))
		learned = 0.995*(1-pos) + 0.018*pos

	case belief.lowerOK > 0 && totalAmt > belief.lowerOK:
		ratio := float64(belief.lowerOK) / float64(totalAmt)
		learned = prior + (0.995-prior)*ratio*ratio

	case belief.upperFail > 0 && totalAmt < belief.upperFail:
		ratio := float64(totalAmt) / float64(belief.upperFail)
		learned = prior * (1 - 0.72*ratio*ratio)
	}

	// A single attribution is quarantined as a soft hint. It is useful for
	// immediate diversification but cannot create a hard exclusion.
	if belief.upperFail == 0 && belief.suspectAmt > 0 &&
		totalAmt >= belief.suspectAmt {

		learned *= 0.62
	}

	confidence := r.evidenceConfidence(belief)
	return candidateClampProbability(
		confidence*learned + (1-confidence)*prior,
	)
}

type candidateItem struct {
	node  route.Vertex
	score float64
}

type candidateQueue []*candidateItem

func (q candidateQueue) Len() int {
	return len(q)
}

func (q candidateQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *candidateQueue) Push(value any) {
	*q = append(*q, value.(*candidateItem))
}

func (q *candidateQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]
	return last
}

type candidatePath struct {
	route       *route.Route
	edges       []*candidateEdge
	probability float64
	pressure    float64
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*candidatePath, error) {

	if amt <= 0 {
		return nil, errors.New("invalid payment amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is target")
	}

	scores := make(map[route.Vertex]float64)
	amounts := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)

	scores[r.spec.Target] = 0
	amounts[r.spec.Target] = amt

	pq := &candidateQueue{}
	heap.Push(pq, &candidateItem{
		node:  r.spec.Target,
		score: 0,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateItem)
		bestScore, ok := scores[item.node]
		if !ok || item.score > bestScore+1e-12 {
			continue
		}
		if item.node == r.source {
			break
		}

		arriving := amounts[item.node]

		for _, edge := range r.incomingEdges[item.node] {
			if !edge.usable(arriving) {
				continue
			}

			totalLiquidity := arriving + r.reserved[edge.key]
			if totalLiquidity < arriving ||
				totalLiquidity > edge.capacity {

				continue
			}

			if edge.from == r.source &&
				totalLiquidity > r.localBalances[edge.chanID] {

				continue
			}

			sending := arriving
			fee := lnwire.MilliSatoshi(0)
			if edge.from != r.source {
				fee = edge.fee(arriving)
				sending += fee
				if sending < arriving {
					continue
				}
			}

			p := r.probability(edge, totalLiquidity)

			// Reliability dominates. A meaningful per-hop charge prevents
			// tiny apparent probability gains from producing needlessly
			// long routes, while fees remain a secondary tie breaker.
			edgeCost := -math.Log(p) + 0.075
			if arriving > 0 {
				edgeCost += 11 * float64(fee) /
					float64(arriving)
			}

			load := float64(totalLiquidity) /
				float64(edge.capacity)
			edgeCost += 0.10 * load * load * load * load
			edgeCost += r.edgePenalty[edge.key]

			newScore := item.score + edgeCost
			oldScore, visited := scores[edge.from]
			if visited && newScore >= oldScore {
				continue
			}

			scores[edge.from] = newScore
			amounts[edge.from] = sending
			next[edge.from] = edge

			heap.Push(pq, &candidateItem{
				node:  edge.from,
				score: newScore,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	rt, path, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, err
	}

	probability := 1.0
	pressure := 0.0

	for i, edge := range path {
		amtOver := candidateRouteAmount(rt, i)
		totalLiquidity := amtOver + r.reserved[edge.key]

		probability *= r.probability(edge, totalLiquidity)

		denominator := edge.capacity
		if edge.from == r.source {
			denominator = r.localBalances[edge.chanID]
		} else if belief, ok := r.beliefs[edge.key]; ok &&
			belief.upperFail > 0 &&
			r.evidenceConfidence(belief) >= 0.72 &&
			belief.upperFail < denominator {

			denominator = belief.upperFail
		}

		if denominator > 0 {
			load := float64(totalLiquidity) /
				float64(denominator)
			if load > pressure {
				pressure = load
			}
		}
	}

	return &candidatePath{
		route:       rt,
		edges:       path,
		probability: math.Max(probability, 1e-300),
		pressure:    pressure,
	}, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route,
	[]*candidateEdge, error) {

	const finalCltvDelta = uint32(40)

	var path []*candidateEdge
	seen := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if seen[node] {
			return nil, nil, errors.New("cycle in route")
		}
		seen[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.to
	}

	if len(path) == 0 {
		return nil, nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		if amtOver[i] < amtOver[i+1] {
			return nil, nil, errors.New("amount overflow")
		}

		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := finalCltvDelta

		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, path, nil
}

func candidateCeilDiv(a lnwire.MilliSatoshi,
	b uint32) lnwire.MilliSatoshi {

	if b <= 1 {
		return a
	}

	divisor := lnwire.MilliSatoshi(b)
	return a/divisor + boolToMSat(a%divisor != 0)
}

func boolToMSat(value bool) lnwire.MilliSatoshi {
	if value {
		return 1
	}

	return 0
}

func candidateRouteAmount(rt *route.Route,
	edgeIndex int) lnwire.MilliSatoshi {

	if edgeIndex == 0 {
		return rt.TotalAmount
	}

	return rt.Hops[edgeIndex-1].AmtToForward
}

func candidateRouteDelivered(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}

	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateRouteEdgeKey(rt *route.Route,
	edgeIndex int) candidateEdgeKey {

	from := rt.SourcePubKey
	if edgeIndex > 0 {
		from = rt.Hops[edgeIndex-1].PubKeyBytes
	}

	return candidateEdgeKey{
		chanID: rt.Hops[edgeIndex].ChannelID,
		from:   from,
		to:     rt.Hops[edgeIndex].PubKeyBytes,
	}
}

func candidateCopyAmounts(
	source map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	result := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(source))
	for key, value := range source {
		result[key] = value
	}

	return result
}

func candidateCopyPenalties(
	source map[candidateEdgeKey]float64,
) map[candidateEdgeKey]float64 {

	result := make(map[candidateEdgeKey]float64, len(source))
	for key, value := range source {
		result[key] = value
	}

	return result
}

type candidatePlan struct {
	routes []*route.Route
	score  float64
}

func (r *candidateRouter) addPlannedReservation(path *candidatePath) {
	for i, edge := range path.edges {
		amtOver := candidateRouteAmount(path.route, i)
		r.reserved[edge.key] += amtOver

		// Planned siblings should prefer independent corridors. Shared
		// bottlenecks remain possible when the topology requires them.
		r.edgePenalty[edge.key] += 0.62
	}
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	numParts uint32, firstLimit lnwire.MilliSatoshi) *candidatePlan {

	if numParts == 0 || total <= 0 {
		return nil
	}

	const minimumShard = lnwire.MilliSatoshi(1_000_000)

	savedReserved := candidateCopyAmounts(r.reserved)
	savedPenalty := candidateCopyPenalties(r.edgePenalty)
	defer func() {
		r.reserved = savedReserved
		r.edgePenalty = savedPenalty
	}()

	remaining := total
	routes := make([]*route.Route, 0, numParts)
	score := 0.0

	for part := uint32(0); part < numParts; part++ {
		slots := numParts - part
		if remaining <= 0 {
			return nil
		}

		floor := candidateCeilDiv(remaining, slots)
		desired := floor

		maxDesired := remaining
		if slots > 1 {
			minimumTail := minimumShard *
				lnwire.MilliSatoshi(slots-1)
			if remaining <= minimumTail {
				return nil
			}
			maxDesired = remaining - minimumTail
		}

		if part == 0 && firstLimit > 0 &&
			firstLimit < desired {

			desired = firstLimit
		} else if slots > 1 {
			high := floor * 5 / 4
			if high > maxDesired {
				high = maxDesired
			}

			if high > floor {
				floorPath, floorErr := r.findRoute(floor)
				highPath, highErr := r.findRoute(high)

				if floorErr != nil && highErr != nil {
					return nil
				}

				if highErr == nil &&
					(floorErr != nil ||
						(highPath.probability >=
							floorPath.probability*0.80 &&
							highPath.pressure <= 0.72)) {

					desired = high
				}
			}
		}

		if desired > maxDesired {
			desired = maxDesired
		}
		if desired <= 0 || desired > remaining {
			return nil
		}

		path, err := r.findRoute(desired)
		if err != nil {
			return nil
		}

		delivered := candidateRouteDelivered(path.route)
		if delivered <= 0 || delivered > remaining {
			return nil
		}

		fee := path.route.TotalAmount - delivered
		feeCost := 0.0
		if delivered > 0 && fee > 0 {
			feeCost = 8 * float64(fee) / float64(delivered)
		}

		score += math.Log(path.probability) - feeCost - 0.035
		routes = append(routes, path.route)
		r.addPlannedReservation(path)
		remaining -= delivered
	}

	if remaining != 0 {
		return nil
	}

	return &candidatePlan{
		routes: routes,
		score:  score,
	}
}

func candidatePlanWidths(partsLeft uint32) []uint32 {
	if partsLeft <= 1 {
		return []uint32{1}
	}

	seen := make(map[uint32]bool)
	widths := make([]uint32, 0, 12)

	add := func(width uint32) {
		if width == 0 || width > partsLeft || seen[width] {
			return
		}
		seen[width] = true
		widths = append(widths, width)
	}

	for width := uint32(1); width <= partsLeft && width <= 8; width++ {
		add(width)
	}

	add(10)
	add(12)
	add(16)
	add(24)
	add(32)
	add(partsLeft)

	return widths
}

func (r *candidateRouter) buildBestPlan(
	amt lnwire.MilliSatoshi, partsLeft uint32) bool {

	var best *candidatePlan

	for _, width := range candidatePlanWidths(partsLeft) {
		plan := r.makePlan(amt, width, r.retryLimit)
		if plan == nil {
			continue
		}

		if best == nil || plan.score > best.score {
			best = plan
		}
	}

	// A lower retry limit can make every proposed route set infeasible.
	// Retry planning without it before terminally giving up.
	if best == nil && r.retryLimit > 0 {
		for _, width := range candidatePlanWidths(partsLeft) {
			plan := r.makePlan(amt, width, 0)
			if plan == nil {
				continue
			}

			if best == nil || plan.score > best.score {
				best = plan
			}
		}
	}

	if best == nil || len(best.routes) == 0 {
		return false
	}

	r.plan = best.routes
	r.planExpected = amt
	return true
}

func (r *candidateRouter) clearPlan() {
	r.plan = nil
	r.planExpected = 0
}

// RequestRoute selects an entire route set in memory before committing its
// first shard. Reservations and diversity penalties used during planning
// make later shards account for earlier atomic-MPP holds.
func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid remaining amount")
	}

	partsLeft := uint32(1)
	if r.spec.MaxParts > inFlightHtlcs {
		partsLeft = r.spec.MaxParts - inFlightHtlcs
	}

	if len(r.plan) > 0 && r.planExpected != amt {
		r.clearPlan()
	}

	if len(r.plan) == 0 {
		if !r.buildBestPlan(amt, partsLeft) {
			// Retain a reactive fallback for unusual policy/min-HTLC
			// combinations that cannot form a complete planned set.
			desired := candidateCeilDiv(amt, partsLeft)
			if r.retryLimit > 0 && r.retryLimit < desired {
				desired = r.retryLimit
			}

			const minimumShard =
				lnwire.MilliSatoshi(1_000_000)

			var lastErr error
			for desired > 0 {
				path, err := r.findRoute(desired)
				if err == nil {
					return path.route, nil
				}
				lastErr = err

				if desired <= minimumShard {
					break
				}

				next := desired * 72 / 100
				if next < minimumShard {
					next = minimumShard
				}
				if next >= desired {
					break
				}
				desired = next
			}

			if lastErr == nil {
				lastErr = errors.New("no route found")
			}
			return nil, lastErr
		}
	}

	rt := r.plan[0]
	r.plan = r.plan[1:]

	delivered := candidateRouteDelivered(rt)
	if delivered <= 0 || delivered > r.planExpected {
		r.clearPlan()
		return nil, errors.New("invalid planned route")
	}

	r.planExpected -= delivered
	return rt, nil
}

func candidateFailureEdge(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func candidateIsLiquidityFailure(failure any) bool {
	switch failure.(type) {
	case *lnwire.FailTemporaryChannelFailure:
		return true
	default:
		return false
	}
}

func candidateIsPolicyFailure(failure any) bool {
	switch failure.(type) {
	case *lnwire.FailFeeInsufficient,
		*lnwire.FailIncorrectCltvExpiry:

		return true
	default:
		return false
	}
}

func (r *candidateRouter) saveBelief(
	key candidateEdgeKey, belief candidateBelief) {

	belief.stamp = r.epoch
	r.beliefs[key] = belief

	candidateMemory.Lock()
	candidateMemory.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) recordSuccess(key candidateEdgeKey,
	totalAmt lnwire.MilliSatoshi) {

	belief := r.beliefs[key]

	if totalAmt > belief.lowerOK {
		belief.lowerOK = totalAmt
	}

	// Success is truthful and therefore disproves conflicting failure
	// evidence immediately.
	if belief.upperFail > 0 && totalAmt >= belief.upperFail {
		belief.upperFail = 0
	}
	if belief.suspectAmt > 0 && totalAmt >= belief.suspectAmt {
		belief.suspectAmt = 0
		belief.suspectVotes = 0
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) recordFailure(key candidateEdgeKey,
	totalAmt lnwire.MilliSatoshi) {

	belief := r.beliefs[key]

	corroborates := false
	if belief.suspectAmt > 0 {
		low := belief.suspectAmt * 60 / 100
		high := belief.suspectAmt * 150 / 100
		corroborates = totalAmt >= low && totalAmt <= high
	}

	if corroborates {
		if belief.suspectVotes < 255 {
			belief.suspectVotes++
		}
		if totalAmt < belief.suspectAmt {
			belief.suspectAmt = totalAmt
		}
	} else {
		belief.suspectAmt = totalAmt
		belief.suspectVotes = 1
	}

	requiredVotes := uint8(2)
	if belief.lowerOK > 0 && totalAmt <= belief.lowerOK {
		// A shifted attribution should not overturn truthful success.
		requiredVotes = 3
	}

	if belief.suspectVotes >= requiredVotes {
		if totalAmt <= belief.lowerOK {
			belief.lowerOK = 0
		}

		if belief.upperFail == 0 ||
			belief.suspectAmt < belief.upperFail {

			belief.upperFail = belief.suspectAmt
		}
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) penalizeNeighborEdges(
	rt *route.Route, failIndex int) {

	for _, index := range []int{failIndex - 1, failIndex + 1} {
		if index < 0 || index >= len(rt.Hops) {
			continue
		}

		key := candidateRouteEdgeKey(rt, index)
		r.edgePenalty[key] = math.Min(
			4, r.edgePenalty[key]+0.24,
		)
	}
}

// ReportAttempt treats success as hard evidence, quarantines attributed
// liquidity failures until corroborated, and never writes persistent
// channel knowledge from an unreadable failure.
func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if rt == nil || len(rt.Hops) == 0 {
		return nil
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key := candidateRouteEdgeKey(rt, i)
			amtOver := candidateRouteAmount(rt, i)
			totalAmt := amtOver + r.reserved[key]

			r.recordSuccess(key, totalAmt)
			r.reserved[key] += amtOver

			// If the precomputed plan is later exhausted, continue to
			// prefer another corridor for any additional shard.
			r.edgePenalty[key] = math.Min(
				4, r.edgePenalty[key]+0.42,
			)
		}

		r.retryLimit = 0
		return nil
	}

	// A failed planned shard invalidates the rest of the joint plan.
	r.clearPlan()

	// Route-local diversity is safe even when the error is unreadable:
	// unlike a belief, it does not survive this payment.
	for i := range rt.Hops {
		key := candidateRouteEdgeKey(rt, i)
		r.edgePenalty[key] = math.Min(
			4, r.edgePenalty[key]+0.22,
		)
	}

	failIndex := candidateFailureEdge(
		rt, result.FailureSource,
	)
	attributed := failIndex >= 0 && failIndex < len(rt.Hops)

	if candidateIsLiquidityFailure(result.Failure) && attributed {
		key := candidateRouteEdgeKey(rt, failIndex)
		amtOver := candidateRouteAmount(rt, failIndex)
		totalAmt := amtOver + r.reserved[key]

		r.recordFailure(key, totalAmt)
		r.edgePenalty[key] = math.Min(
			7, r.edgePenalty[key]+1.05,
		)

		// Shifted blame is normally adjacent to the real failure. Apply
		// only temporary, weak penalties to those neighbors.
		r.penalizeNeighborEdges(rt, failIndex)

		delivered := candidateRouteDelivered(rt)
		lowerRetry := delivered * 68 / 100
		if lowerRetry < 1_000_000 {
			lowerRetry = 1_000_000
		}
		r.retryLimit = lowerRetry

		return nil
	}

	if candidateIsPolicyFailure(result.Failure) && attributed {
		key := candidateRouteEdgeKey(rt, failIndex)
		r.edgePenalty[key] = math.Min(
			7, r.edgePenalty[key]+1.7,
		)
		r.penalizeNeighborEdges(rt, failIndex)
	}

	// Unknown and policy failures request a fresh route set at the same
	// scale. They never create liquidity bounds.
	r.retryLimit = 0
	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return amt <= e.capacity
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	softFail  lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	failVotes uint8
	conf      float64
	epoch     uint64
}

var candidateKnowledge = struct {
	sync.Mutex
	epoch   uint64
	beliefs map[candidateEdgeKey]candidateBelief
}{
	beliefs: make(map[candidateEdgeKey]candidateBelief),
}

type candidateMetaEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi
	amt      lnwire.MilliSatoshi
	reserved lnwire.MilliSatoshi
}

type candidateAttemptMeta struct {
	edges     []candidateMetaEdge
	delivered lnwire.MilliSatoshi
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec
	epoch  uint64

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeByKey     map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	beliefs       map[candidateEdgeKey]candidateBelief
	reserved      map[candidateEdgeKey]lnwire.MilliSatoshi
	routePenalty  map[candidateEdgeKey]float64
	policyVotes   map[candidateEdgeKey]uint8
	policyBad     map[candidateEdgeKey]bool
	pending       map[*route.Route]*candidateAttemptMeta
	maxShard      lnwire.MilliSatoshi
	consecutive   int
	successfulAmt lnwire.MilliSatoshi
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edgeByKey:      make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		routePenalty:   make(map[candidateEdgeKey]float64),
		policyVotes:    make(map[candidateEdgeKey]uint8),
		policyBad:      make(map[candidateEdgeKey]bool),
		pending:        make(map[*route.Route]*candidateAttemptMeta),
		maxShard:       spec.Amount,
		successfulAmt:  0,
		consecutive:    0,
	}

	ctx := context.Background()
	seen := make(map[route.Vertex]bool)
	queue := []route.Vertex{source}
	seen[source] = true

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edgeByKey[key] = edge
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	candidateKnowledge.Lock()
	candidateKnowledge.epoch++
	r.epoch = candidateKnowledge.epoch

	for key := range r.edgeByKey {
		b, ok := candidateKnowledge.beliefs[key]
		if !ok {
			continue
		}

		age := r.epoch - b.epoch
		b.conf *= math.Pow(0.96, float64(age))
		if b.conf < 0.08 {
			continue
		}
		r.beliefs[key] = b
	}
	candidateKnowledge.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	if x < 0 {
		x = 0
	}
	if x > 1.2 {
		x = 1.2
	}

	lowMode := math.Exp(-x / 0.03)
	highMode := 1 / (1 + math.Exp((x-0.86)/0.065))
	p := 0.005 + 0.98*(0.48*lowMode+0.52*highMode)

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func (r *candidateRouter) edgeProbability(e *candidateEdge,
	total lnwire.MilliSatoshi) float64 {

	if e.key.from == r.source {
		return 0.999
	}

	prior := candidatePrior(total, e.capacity)
	b, ok := r.beliefs[e.key]
	if !ok || b.conf <= 0 {
		return prior
	}

	observed := prior
	switch {
	case b.lowerOK > 0 && total <= b.lowerOK:
		observed = 0.995

	case b.upperFail > 0 && total >= b.upperFail:
		observed = 0.003

	case b.estimate > 0:
		width := float64(e.capacity) * 0.12
		if width < 1 {
			width = 1
		}
		z := (float64(total) - float64(b.estimate)) / width
		observed = 0.01 + 0.98/(1+math.Exp(z))
	}

	conf := b.conf
	if conf > 0.995 {
		conf = 0.995
	}
	p := prior*(1-conf) + observed*conf

	if b.softFail > 0 && total >= b.softFail*3/4 {
		p *= 1 - 0.55*conf
	}

	p *= math.Exp(-0.35 * r.routePenalty[e.key])
	if p < 0.001 {
		return 0.001
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

type candidateDijkstraItem struct {
	node   route.Vertex
	amount lnwire.MilliSatoshi
	score  float64
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *candidateDijkstraQueue) Push(x any) {
	*q = append(*q, x.(*candidateDijkstraItem))
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]
	return item
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}

	bestScore := make(map[route.Vertex]float64)
	needed := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	needed[r.spec.Target] = amt

	pq := &candidateDijkstraQueue{}
	heap.Push(pq, &candidateDijkstraItem{
		node:   r.spec.Target,
		amount: amt,
		score:  0,
	})

	for pq.Len() != 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)
		best, ok := bestScore[item.node]
		if !ok || item.score > best+0.5 {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.policyBad[edge.key] || !edge.usable(item.amount) {
				continue
			}

			totalLiquidity := item.amount + r.reserved[edge.key]
			if totalLiquidity > edge.capacity {
				continue
			}
			if edge.key.from == r.source &&
				totalLiquidity > r.localBalances[edge.key.chanID] {

				continue
			}

			sending := item.amount
			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(item.amount)
				sending += fee
			}

			p := r.edgeProbability(edge, totalLiquidity)
			riskBudget := 5_000 + 0.007*float64(item.amount)
			edgeScore := float64(fee) -
				math.Log(p)*riskBudget + 1_000
			score := item.score + edgeScore

			old, exists := bestScore[edge.key.from]
			if exists && score >= old {
				continue
			}

			bestScore[edge.key.from] = score
			needed[edge.key.from] = sending
			next[edge.key.from] = edge
			heap.Push(pq, &candidateDijkstraItem{
				node:   edge.key.from,
				amount: sending,
				score:  score,
			})
		}
	}

	if _, ok := needed[r.source]; !ok {
		return nil, errors.New("no route found")
	}
	return r.buildRoute(amt, next)
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	const finalCltvDelta uint32 = 40

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))
	last := len(path) - 1

	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		outgoing := path[i+1]
		amtOver[i] = amtOver[i+1] + outgoing.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forward := amt
		expiry := finalCltvDelta
		if i < last {
			forward = amtOver[i+1]
			expiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func routeChannelAmount(rt *route.Route,
	index int) lnwire.MilliSatoshi {

	if index == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[index-1].AmtToForward
}

func (r *candidateRouter) rememberRoute(rt *route.Route) {
	meta := &candidateAttemptMeta{
		edges: make([]candidateMetaEdge, 0, len(rt.Hops)),
	}
	if len(rt.Hops) != 0 {
		meta.delivered = rt.Hops[len(rt.Hops)-1].AmtToForward
	}

	from := rt.SourcePubKey
	for i, hop := range rt.Hops {
		key := candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		capacity := lnwire.MilliSatoshi(0)
		if edge := r.edgeByKey[key]; edge != nil {
			capacity = edge.capacity
		}
		meta.edges = append(meta.edges, candidateMetaEdge{
			key:      key,
			capacity: capacity,
			amt:      routeChannelAmount(rt, i),
			reserved: r.reserved[key],
		})
		from = hop.PubKeyBytes
	}
	r.pending[rt] = meta
}

func (r *candidateRouter) largestFeasibleRoute(upper,
	floor lnwire.MilliSatoshi) (*route.Route, error) {

	if floor < 1 {
		floor = 1
	}
	if upper < floor {
		upper = floor
	}

	const probes = 12
	var (
		best     *route.Route
		bestAmt  lnwire.MilliSatoshi
		failedAt = upper
	)

	span := upper - floor
	for i := 0; i <= probes; i++ {
		testAmt := upper - span*lnwire.MilliSatoshi(i)/probes
		rt, err := r.findRoute(testAmt)
		if err != nil {
			failedAt = testAmt
			continue
		}
		best = rt
		bestAmt = testAmt
		break
	}

	if best == nil {
		return nil, errors.New("no feasible shard route")
	}

	low := bestAmt
	high := failedAt
	if high <= low {
		return best, nil
	}

	for i := 0; i < 8 && high-low > 1_000; i++ {
		mid := low + (high-low)/2
		rt, err := r.findRoute(mid)
		if err != nil {
			high = mid
			continue
		}
		low = mid
		best = rt
	}

	return best, nil
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts reached")
	}

	partsLeft := maxParts - inFlightHtlcs
	minShard := (amt + lnwire.MilliSatoshi(partsLeft) - 1) /
		lnwire.MilliSatoshi(partsLeft)

	upper := amt
	if r.maxShard > 0 && r.maxShard < upper {
		upper = r.maxShard
	}
	if upper < minShard {
		upper = minShard
	}

	rt, err := r.findRoute(upper)
	if err != nil {
		if partsLeft <= 1 {
			return nil, err
		}
		rt, err = r.largestFeasibleRoute(upper, minShard)
		if err != nil {
			return nil, err
		}
	}

	r.rememberRoute(rt)
	return rt, nil
}

func (r *candidateRouter) metaForRoute(
	rt *route.Route) *candidateAttemptMeta {

	if meta, ok := r.pending[rt]; ok {
		delete(r.pending, rt)
		return meta
	}

	r.rememberRoute(rt)
	meta := r.pending[rt]
	delete(r.pending, rt)
	return meta
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	b candidateBelief) {

	b.epoch = r.epoch
	r.beliefs[key] = b

	candidateKnowledge.Lock()
	old, ok := candidateKnowledge.beliefs[key]
	if ok && old.epoch > b.epoch {
		candidateKnowledge.Unlock()
		return
	}
	candidateKnowledge.beliefs[key] = b
	candidateKnowledge.Unlock()
}

func (r *candidateRouter) recordSuccess(edge candidateMetaEdge) {
	total := edge.reserved + edge.amt
	b := r.beliefs[edge.key]

	if total > b.lowerOK {
		b.lowerOK = total
	}
	if b.upperFail > 0 && total >= b.upperFail {
		b.upperFail = 0
	}
	if b.softFail > 0 && total >= b.softFail {
		b.softFail = 0
		b.failVotes = 0
	}

	highEstimate := edge.capacity * 85 / 100
	if total > highEstimate {
		highEstimate = total
	}
	if highEstimate > b.estimate {
		b.estimate = highEstimate
	}

	b.conf = 0.995
	r.storeBelief(edge.key, b)
}

func candidateComparableAmounts(a,
	b lnwire.MilliSatoshi) bool {

	if a <= 0 || b <= 0 {
		return false
	}
	af := float64(a)
	bf := float64(b)
	return af <= 4*bf && bf <= 4*af
}

func (r *candidateRouter) recordLiquidityFailure(
	edge candidateMetaEdge) {

	total := edge.reserved + edge.amt
	b := r.beliefs[edge.key]

	if b.lowerOK > 0 && total <= b.lowerOK {
		if b.softFail == 0 || total < b.softFail {
			b.softFail = total
		}
		if b.conf < 0.25 {
			b.conf = 0.25
		}
		r.storeBelief(edge.key, b)
		return
	}

	if b.softFail == 0 || total < b.softFail {
		if b.softFail != 0 &&
			!candidateComparableAmounts(total, b.softFail) {

			b.failVotes = 0
		}
		b.softFail = total
	}

	if b.failVotes < 2 {
		b.failVotes++
	}

	if b.failVotes >= 2 {
		if b.upperFail == 0 || total < b.upperFail {
			b.upperFail = total
		}
		estimate := total / 2
		if b.estimate == 0 || estimate < b.estimate {
			b.estimate = estimate
		}
		if b.conf < 0.92 {
			b.conf = 0.92
		}
	} else if b.conf < 0.65 {
		b.conf = 0.65
	}

	r.storeBelief(edge.key, b)
}

func (r *candidateRouter) failureEdge(meta *candidateAttemptMeta,
	rt *route.Route, source route.Vertex) (candidateMetaEdge, bool) {

	index := -1
	if source == rt.SourcePubKey {
		index = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == source {
				index = i + 1
				break
			}
		}
	}

	if index < 0 || index >= len(meta.edges) {
		return candidateMetaEdge{}, false
	}
	return meta.edges[index], true
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	meta := r.metaForRoute(rt)
	if meta == nil {
		return nil
	}

	if result.Failure == nil {
		r.consecutive = 0
		r.successfulAmt += meta.delivered

		for _, edge := range meta.edges {
			r.recordSuccess(edge)
			r.reserved[edge.key] += edge.amt

			r.routePenalty[edge.key] *= 0.5
			r.routePenalty[edge.key] += 0.25
		}
		return nil
	}

	r.consecutive++
	for _, edge := range meta.edges {
		r.routePenalty[edge.key] += 0.08
	}

	failedEdge, attributed := r.failureEdge(
		meta, rt, result.FailureSource,
	)
	code := result.Failure.Code()

	switch {
	case attributed &&
		code == lnwire.CodeTemporaryChannelFailure:

		r.routePenalty[failedEdge.key] += 1.25
		r.recordLiquidityFailure(failedEdge)

	case attributed &&
		(code == lnwire.CodeFeeInsufficient ||
			code == lnwire.CodeIncorrectCltvExpiry):

		r.routePenalty[failedEdge.key] += 2
		r.policyVotes[failedEdge.key]++
		if r.policyVotes[failedEdge.key] >= 2 {
			r.policyBad[failedEdge.key] = true
		}

	case !attributed:
		for _, edge := range meta.edges {
			r.routePenalty[edge.key] += 0.12
		}
	}

	if r.consecutive%2 == 0 && r.spec.MaxParts > 1 {
		reduced := meta.delivered * 7 / 10
		if reduced < 1 {
			reduced = 1
		}
		if r.maxShard == 0 || reduced < r.maxShard {
			r.maxShard = reduced
		}
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
}

type candidateMemoryKey struct {
	network uint64
	edge    candidateEdgeKey
}

type candidateEdge struct {
	key      candidateEdgeKey
	chanID  uint64
	from    route.Vertex
	to      route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi

	suspectAmt   lnwire.MilliSatoshi
	suspectVotes uint8

	stamp uint64
}

var candidateMemory = struct {
	sync.Mutex
	epochs  map[uint64]uint64
	beliefs map[candidateMemoryKey]candidateBelief
}{
	epochs:  make(map[uint64]uint64),
	beliefs: make(map[candidateMemoryKey]candidateBelief),
}

type candidateRouter struct {
	source  route.Vertex
	spec    *routing.SimPaymentSpec
	network uint64
	epoch   uint64

	incomingEdges map[route.Vertex][]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[candidateEdgeKey]candidateBelief

	reserved   map[candidateEdgeKey]lnwire.MilliSatoshi
	edgePenalty map[candidateEdgeKey]float64

	plan       []*candidatePlanned
	retryLimit lnwire.MilliSatoshi

	attempts       uint32
	failureStreak  uint32
	amountFailures map[lnwire.MilliSatoshi]uint16
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	x ^= x >> 31
	return x
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	h := uint64(1469598103934665603)
	add := func(v uint64) {
		for i := 0; i < 8; i++ {
			h ^= v & 0xff
			h *= 1099511628211
			v >>= 8
		}
	}

	add(e.chanID)
	add(uint64(e.capacity))
	add(uint64(e.baseFeeMsat))
	add(uint64(e.feeRatePPM))
	add(uint64(e.timeLockDelta))
	add(uint64(e.minHTLC))
	add(uint64(e.maxHTLC))

	for _, b := range e.from {
		h ^= uint64(b)
		h *= 1099511628211
	}
	for _, b := range e.to {
		h ^= uint64(b)
		h *= 1099511628211
	}

	return h
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		edgePenalty:    make(map[candidateEdgeKey]float64),
		amountFailures: make(map[lnwire.MilliSatoshi]uint16),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	var signatureSum uint64
	var signatureXor uint64
	var edgeCount uint64

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
					},
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: policy.FeeBaseMSat,
					feeRatePPM: policy.
						FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				h := candidateMix64(candidateEdgeHash(edge))
				signatureSum += h
				signatureXor ^= candidateMix64(
					h + 0x9e3779b97f4a7c15,
				)
				edgeCount++

				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	rotated := signatureXor<<17 | signatureXor>>47
	r.network = candidateMix64(
		signatureSum ^ rotated ^ candidateMix64(edgeCount),
	)

	candidateMemory.Lock()
	candidateMemory.epochs[r.network]++
	r.epoch = candidateMemory.epochs[r.network]

	for key, belief := range candidateMemory.beliefs {
		if key.network == r.network {
			r.beliefs[key.edge] = belief
		}
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidateClampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005
	case p > 0.995:
		return 0.995
	default:
		return p
	}
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.025)
	highMode := 1 / (1 + math.Exp(18*(x-0.82)))

	return candidateClampProbability(0.5*lowMode + 0.5*highMode)
}

func (r *candidateRouter) evidenceConfidence(b candidateBelief) float64 {
	if b.stamp == 0 || r.epoch <= b.stamp+3 {
		return 1
	}

	age := float64(r.epoch - b.stamp - 3)
	return math.Max(0.12, math.Exp(-age/12))
}

func (r *candidateRouter) probability(edge *candidateEdge,
	totalAmt lnwire.MilliSatoshi) float64 {

	if edge.from == r.source {
		if totalAmt <= r.localBalances[edge.chanID] {
			return 0.999
		}
		return 0.001
	}

	prior := candidatePrior(totalAmt, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok || belief.stamp == 0 {
		return prior
	}

	learned := prior

	switch {
	case belief.lowerOK > 0 && totalAmt <= belief.lowerOK:
		learned = 0.995

	case belief.upperFail > 0 && totalAmt >= belief.upperFail:
		learned = 0.008

	case belief.lowerOK > 0 && belief.upperFail > belief.lowerOK:
		span := float64(belief.upperFail - belief.lowerOK)
		pos := float64(totalAmt-belief.lowerOK) / span
		pos = math.Max(0, math.Min(1, pos))
		learned = 0.995*(1-pos) + 0.008*pos

	case belief.lowerOK > 0 && totalAmt > belief.lowerOK:
		ratio := float64(belief.lowerOK) / float64(totalAmt)
		learned = prior + (0.995-prior)*ratio*ratio

	case belief.upperFail > 0 && totalAmt < belief.upperFail:
		ratio := float64(totalAmt) / float64(belief.upperFail)
		learned = prior * (1 - 0.75*ratio*ratio)
	}

	if belief.upperFail == 0 && belief.suspectAmt > 0 &&
		totalAmt >= belief.suspectAmt {

		learned *= 0.62
	}

	confidence := r.evidenceConfidence(belief)
	return candidateClampProbability(
		confidence*learned + (1-confidence)*prior,
	)
}

func (r *candidateRouter) hardFailed(edge *candidateEdge,
	totalAmt lnwire.MilliSatoshi) bool {

	belief, ok := r.beliefs[edge.key]
	if !ok || belief.upperFail == 0 {
		return false
	}

	return r.evidenceConfidence(belief) >= 0.72 &&
		totalAmt >= belief.upperFail
}

type candidateItem struct {
	node  route.Vertex
	score float64
}

type candidateQueue []*candidateItem

func (q candidateQueue) Len() int {
	return len(q)
}

func (q candidateQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *candidateQueue) Push(value any) {
	*q = append(*q, value.(*candidateItem))
}

func (q *candidateQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]
	return last
}

type candidatePath struct {
	route       *route.Route
	edges       []*candidateEdge
	probability float64
	pressure    float64
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*candidatePath, error) {

	if amt <= 0 {
		return nil, errors.New("invalid payment amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is target")
	}

	scores := make(map[route.Vertex]float64)
	amounts := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)

	scores[r.spec.Target] = 0
	amounts[r.spec.Target] = amt

	pq := &candidateQueue{}
	heap.Push(pq, &candidateItem{
		node:  r.spec.Target,
		score: 0,
	})

	for pq.Len() != 0 {
		item := heap.Pop(pq).(*candidateItem)
		bestScore, ok := scores[item.node]
		if !ok || item.score > bestScore+1e-12 {
			continue
		}
		if item.node == r.source {
			break
		}

		arriving := amounts[item.node]

		for _, edge := range r.incomingEdges[item.node] {
			if !edge.usable(arriving) {
				continue
			}

			totalLiquidity := arriving + r.reserved[edge.key]
			if totalLiquidity < arriving ||
				totalLiquidity > edge.capacity {

				continue
			}

			if edge.from == r.source {
				if totalLiquidity >
					r.localBalances[edge.chanID] {

					continue
				}
			} else if r.hardFailed(edge, totalLiquidity) {
				continue
			}

			sending := arriving
			fee := lnwire.MilliSatoshi(0)
			if edge.from != r.source {
				fee = edge.fee(arriving)
				sending += fee
				if sending < arriving {
					continue
				}
			}

			probability := r.probability(edge, totalLiquidity)
			edgeCost := -math.Log(probability) + 0.065
			if arriving > 0 {
				edgeCost += 7 * float64(fee) /
					float64(arriving)
			}
			edgeCost += r.edgePenalty[edge.key]

			newScore := item.score + edgeCost
			oldScore, visited := scores[edge.from]
			if visited && newScore >= oldScore {
				continue
			}

			scores[edge.from] = newScore
			amounts[edge.from] = sending
			next[edge.from] = edge
			heap.Push(pq, &candidateItem{
				node:  edge.from,
				score: newScore,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	rt, path, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, err
	}

	probability := 1.0
	pressure := 0.0

	for i, edge := range path {
		amtOver := candidateRouteAmount(rt, i)
		totalLiquidity := amtOver + r.reserved[edge.key]

		probability *= r.probability(edge, totalLiquidity)

		denominator := edge.capacity
		if edge.from == r.source {
			denominator = r.localBalances[edge.chanID]
		} else if belief, ok := r.beliefs[edge.key]; ok &&
			belief.upperFail > 0 &&
			r.evidenceConfidence(belief) >= 0.72 &&
			belief.upperFail < denominator {

			denominator = belief.upperFail
		}

		if denominator > 0 {
			ratio := float64(totalLiquidity) /
				float64(denominator)
			if ratio > pressure {
				pressure = ratio
			}
		}
	}

	return &candidatePath{
		route:       rt,
		edges:       path,
		probability: probability,
		pressure:    pressure,
	}, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route,
	[]*candidateEdge, error) {

	const finalCltvDelta = uint32(40)

	var path []*candidateEdge
	seen := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if seen[node] {
			return nil, nil, errors.New("cycle in route")
		}
		seen[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.to
	}

	if len(path) == 0 {
		return nil, nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := finalCltvDelta

		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, path, nil
}

type candidatePlanned struct {
	path      *candidatePath
	delivered lnwire.MilliSatoshi
}

func candidateCopyAmounts(
	src map[candidateEdgeKey]lnwire.MilliSatoshi) map[
	candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, value := range src {
		dst[key] = value
	}
	return dst
}

func candidateCopyPenalties(
	src map[candidateEdgeKey]float64) map[candidateEdgeKey]float64 {

	dst := make(map[candidateEdgeKey]float64, len(src))
	for key, value := range src {
		dst[key] = value
	}
	return dst
}

func candidateWeightSets(parts int) [][]int {
	switch parts {
	case 1:
		return [][]int{{1}}

	case 2:
		return [][]int{
			{1, 1},
			{2, 3},
			{3, 2},
			{1, 2},
			{2, 1},
		}

	case 3:
		return [][]int{
			{1, 1, 1},
			{1, 2, 2},
			{2, 2, 1},
			{1, 2, 3},
			{3, 2, 1},
		}

	case 4:
		return [][]int{
			{1, 1, 1, 1},
			{1, 1, 2, 2},
			{2, 2, 1, 1},
			{1, 2, 2, 3},
			{3, 2, 2, 1},
		}
	}

	equal := make([]int, parts)
	rising := make([]int, parts)
	falling := make([]int, parts)
	for i := 0; i < parts; i++ {
		equal[i] = 1
		rising[i] = i/2 + 1
		falling[parts-1-i] = rising[i]
	}

	return [][]int{equal, rising, falling}
}

func candidateAmountsFromWeights(total lnwire.MilliSatoshi,
	weights []int) ([]lnwire.MilliSatoshi, bool) {

	const minimumShard = lnwire.MilliSatoshi(1_000_000)

	sum := 0
	for _, weight := range weights {
		if weight <= 0 {
			return nil, false
		}
		sum += weight
	}

	amounts := make([]lnwire.MilliSatoshi, len(weights))
	remaining := total

	for i, weight := range weights {
		if i == len(weights)-1 {
			amounts[i] = remaining
			break
		}

		amount := total * lnwire.MilliSatoshi(weight) /
			lnwire.MilliSatoshi(sum)
		if amount < minimumShard {
			return nil, false
		}

		amounts[i] = amount
		remaining -= amount
	}

	for _, amount := range amounts {
		if amount < minimumShard {
			return nil, false
		}
	}

	return amounts, true
}

func (r *candidateRouter) makePlan(
	amounts []lnwire.MilliSatoshi) ([]*candidatePlanned, error) {

	realReserved := r.reserved
	realPenalty := r.edgePenalty

	r.reserved = candidateCopyAmounts(realReserved)
	r.edgePenalty = candidateCopyPenalties(realPenalty)

	defer func() {
		r.reserved = realReserved
		r.edgePenalty = realPenalty
	}()

	plans := make([]*candidatePlanned, 0, len(amounts))

	for _, amount := range amounts {
		path, err := r.findRoute(amount)
		if err != nil {
			return nil, err
		}

		plans = append(plans, &candidatePlanned{
			path:      path,
			delivered: amount,
		})

		for i, edge := range path.edges {
			amtOver := candidateRouteAmount(path.route, i)
			r.reserved[edge.key] += amtOver

			// The next planned shard should prefer another corridor.
			// Aggregate reservations still allow reuse when necessary.
			r.edgePenalty[edge.key] += 0.48
		}
	}

	return plans, nil
}

func (r *candidateRouter) planCost(plans []*candidatePlanned,
	total lnwire.MilliSatoshi) float64 {

	increments := make(map[candidateEdgeKey]lnwire.MilliSatoshi)
	edges := make(map[candidateEdgeKey]*candidateEdge)

	var totalFees lnwire.MilliSatoshi
	hopCount := 0

	for _, planned := range plans {
		rt := planned.path.route
		if rt.TotalAmount >= planned.delivered {
			totalFees += rt.TotalAmount - planned.delivered
		}

		hopCount += len(planned.path.edges)
		for i, edge := range planned.path.edges {
			amtOver := candidateRouteAmount(rt, i)
			increments[edge.key] += amtOver
			edges[edge.key] = edge
		}
	}

	cost := 0.0

	for key, increment := range increments {
		edge := edges[key]
		aggregate := r.reserved[key] + increment
		if aggregate < increment || aggregate > edge.capacity {
			return math.Inf(1)
		}
		if edge.from == r.source &&
			aggregate > r.localBalances[edge.chanID] {

			return math.Inf(1)
		}

		cost -= math.Log(r.probability(edge, aggregate))
		cost += 0.10 * r.edgePenalty[key]
	}

	if total > 0 {
		cost += 7 * float64(totalFees) / float64(total)
	}

	cost += 0.035 * float64(hopCount)
	cost += 0.10 * float64(len(plans)-1)

	if total < 50_000_000 {
		cost += 0.35 * float64(len(plans)-1)
	}

	return cost
}

func (r *candidateRouter) selectPlan(amt lnwire.MilliSatoshi,
	partsLeft uint32) ([]*candidatePlanned, error) {

	maxParts := int(partsLeft)
	if maxParts > 6 {
		maxParts = 6
	}
	if maxParts < 1 {
		maxParts = 1
	}

	var best []*candidatePlanned
	bestCost := math.Inf(1)
	var lastErr error

	for parts := 1; parts <= maxParts; parts++ {
		for _, weights := range candidateWeightSets(parts) {
			amounts, ok := candidateAmountsFromWeights(amt, weights)
			if !ok {
				continue
			}

			if r.retryLimit > 0 && amounts[0] > r.retryLimit {
				continue
			}

			plans, err := r.makePlan(amounts)
			if err != nil {
				lastErr = err
				continue
			}

			cost := r.planCost(plans, amt)
			if cost < bestCost {
				bestCost = cost
				best = plans
			}
		}
	}

	if len(best) == 0 {
		if lastErr == nil {
			lastErr = errors.New("no route found")
		}
		return nil, lastErr
	}

	return best, nil
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid remaining amount")
	}

	// Feasible payments normally resolve well before this point. This
	// prevents impossible payments from repeatedly probing a moving
	// network until the simulator's much larger outer attempt limit.
	if r.attempts >= 64 {
		return nil, errors.New("route search exhausted")
	}

	partsLeft := uint32(1)
	if r.spec.MaxParts > inFlightHtlcs {
		partsLeft = r.spec.MaxParts - inFlightHtlcs
	}

	if len(r.plan) != 0 {
		var plannedTotal lnwire.MilliSatoshi
		for _, planned := range r.plan {
			plannedTotal += planned.delivered
		}

		if plannedTotal == amt &&
			uint32(len(r.plan)) <= partsLeft {

			planned := r.plan[0]
			r.plan = r.plan[1:]
			r.attempts++
			return planned.path.route, nil
		}

		r.plan = nil
	}

	plan, err := r.selectPlan(amt, partsLeft)
	if err == nil && len(plan) != 0 {
		r.plan = plan[1:]
		r.attempts++
		return plan[0].path.route, nil
	}

	const minimumShard = lnwire.MilliSatoshi(1_000_000)

	desired := r.retryLimit
	if desired <= 0 || desired > amt {
		desired = amt
	}

	var lastErr = err
	for desired >= minimumShard {
		path, routeErr := r.findRoute(desired)
		if routeErr == nil {
			r.attempts++
			return path.route, nil
		}

		lastErr = routeErr
		smaller := desired * 70 / 100
		if smaller < minimumShard {
			smaller = minimumShard
		}
		if smaller >= desired {
			break
		}
		desired = smaller
	}

	if lastErr == nil {
		lastErr = errors.New("no route found")
	}
	return nil, lastErr
}

func candidateRouteAmount(rt *route.Route,
	edgeIndex int) lnwire.MilliSatoshi {

	if edgeIndex == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[edgeIndex-1].AmtToForward
}

func candidateRouteEdgeKey(rt *route.Route,
	edgeIndex int) candidateEdgeKey {

	from := rt.SourcePubKey
	if edgeIndex > 0 {
		from = rt.Hops[edgeIndex-1].PubKeyBytes
	}

	return candidateEdgeKey{
		chanID: rt.Hops[edgeIndex].ChannelID,
		from:   from,
	}
}

func candidateFailureEdge(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func candidateIsLiquidityFailure(failure any) bool {
	switch failure.(type) {
	case *lnwire.FailTemporaryChannelFailure:
		return true
	default:
		return false
	}
}

func candidateIsPolicyFailure(failure any) bool {
	switch failure.(type) {
	case *lnwire.FailFeeInsufficient,
		*lnwire.FailIncorrectCltvExpiry:

		return true
	default:
		return false
	}
}

func (r *candidateRouter) saveBelief(
	key candidateEdgeKey, belief candidateBelief) {

	belief.stamp = r.epoch
	r.beliefs[key] = belief

	candidateMemory.Lock()
	candidateMemory.beliefs[candidateMemoryKey{
		network: r.network,
		edge:    key,
	}] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) recordSuccess(key candidateEdgeKey,
	totalAmt lnwire.MilliSatoshi) {

	belief := r.beliefs[key]

	if totalAmt > belief.lowerOK {
		belief.lowerOK = totalAmt
	}

	if belief.upperFail > 0 && totalAmt >= belief.upperFail {
		belief.upperFail = 0
	}
	if belief.suspectAmt > 0 && totalAmt >= belief.suspectAmt {
		belief.suspectAmt = 0
		belief.suspectVotes = 0
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) recordFailure(key candidateEdgeKey,
	totalAmt lnwire.MilliSatoshi) {

	belief := r.beliefs[key]

	corroborates := false
	if belief.suspectAmt > 0 {
		low := belief.suspectAmt * 60 / 100
		high := belief.suspectAmt * 150 / 100
		corroborates = totalAmt >= low && totalAmt <= high
	}

	if corroborates {
		if belief.suspectVotes < 255 {
			belief.suspectVotes++
		}
		if totalAmt < belief.suspectAmt {
			belief.suspectAmt = totalAmt
		}
	} else {
		belief.suspectAmt = totalAmt
		belief.suspectVotes = 1
	}

	requiredVotes := uint8(2)
	if belief.lowerOK > 0 && totalAmt <= belief.lowerOK {
		requiredVotes = 3
	}

	if belief.suspectVotes >= requiredVotes {
		if totalAmt <= belief.lowerOK {
			belief.lowerOK = 0
		}

		if belief.upperFail == 0 ||
			belief.suspectAmt < belief.upperFail {

			belief.upperFail = belief.suspectAmt
		}
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if rt == nil || len(rt.Hops) == 0 {
		return nil
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key := candidateRouteEdgeKey(rt, i)
			amtOver := candidateRouteAmount(rt, i)
			totalAmt := amtOver + r.reserved[key]

			r.recordSuccess(key, totalAmt)
			r.reserved[key] += amtOver
			r.edgePenalty[key] *= 0.30
		}

		r.failureStreak = 0
		r.retryLimit = 0
		return nil
	}

	r.plan = nil
	r.failureStreak++

	delivered := rt.Hops[len(rt.Hops)-1].AmtToForward
	r.amountFailures[delivered]++

	for i := range rt.Hops {
		key := candidateRouteEdgeKey(rt, i)
		r.edgePenalty[key] = math.Min(
			4, r.edgePenalty[key]+0.18,
		)
	}

	failIndex := candidateFailureEdge(
		rt, result.FailureSource,
	)
	attributed := failIndex >= 0 && failIndex < len(rt.Hops)

	if candidateIsLiquidityFailure(result.Failure) && attributed {
		key := candidateRouteEdgeKey(rt, failIndex)
		amtOver := candidateRouteAmount(rt, failIndex)
		totalAmt := amtOver + r.reserved[key]

		r.recordFailure(key, totalAmt)
		r.edgePenalty[key] = math.Min(
			7, r.edgePenalty[key]+1.15,
		)

		// Adjacent edges receive only a local diversity hint. Shifted
		// attribution therefore cannot create a neighboring hard bound.
		if failIndex > 0 {
			adjacent := candidateRouteEdgeKey(rt, failIndex-1)
			r.edgePenalty[adjacent] = math.Min(
				4, r.edgePenalty[adjacent]+0.12,
			)
		}
		if failIndex+1 < len(rt.Hops) {
			adjacent := candidateRouteEdgeKey(rt, failIndex+1)
			r.edgePenalty[adjacent] = math.Min(
				4, r.edgePenalty[adjacent]+0.12,
			)
		}

		lowerRetry := delivered * 70 / 100
		if lowerRetry < 1_000_000 {
			lowerRetry = 1_000_000
		}
		r.retryLimit = lowerRetry
		return nil
	}

	if candidateIsPolicyFailure(result.Failure) && attributed {
		key := candidateRouteEdgeKey(rt, failIndex)
		r.edgePenalty[key] = math.Min(
			7, r.edgePenalty[key]+2.0,
		)

		// Keep the amount unchanged: policy errors call for another
		// route, not a fictitious liquidity ceiling.
		r.retryLimit = delivered
		return nil
	}

	// An unreadable failure only proves that this route failed. Try route
	// diversity first and reduce the shard only after repeated failures at
	// the same amount.
	if r.amountFailures[delivered] >= 3 {
		lowerRetry := delivered * 78 / 100
		if lowerRetry < 1_000_000 {
			lowerRetry = 1_000_000
		}
		r.retryLimit = lowerRetry
	} else {
		r.retryLimit = delivered
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdge struct {
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type beliefKey struct {
	network uint64
	chanID  uint64
	from    route.Vertex
	to      route.Vertex
}

type liquidityBelief struct {
	lowerOK    lnwire.MilliSatoshi
	upperFail  lnwire.MilliSatoshi
	estimate   lnwire.MilliSatoshi
	suspectAmt lnwire.MilliSatoshi
	failVotes  uint16
	successes  uint16
}

var sharedBeliefs = struct {
	sync.Mutex
	m map[beliefKey]liquidityBelief
}{
	m: make(map[beliefKey]liquidityBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	network       uint64
	incomingEdges map[route.Vertex][]*candidateEdge
	edgeIndex     map[beliefKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[beliefKey]liquidityBelief

	// Amount already committed by successful shards in this payment.
	reserved map[beliefKey]lnwire.MilliSatoshi

	// Per-payment evidence encourages route diversity without turning an
	// unreadable or shifted failure into a permanent liquidity bound.
	routePenalty map[beliefKey]float64
	failAt       map[beliefKey]lnwire.MilliSatoshi
	policyVotes  map[beliefKey]uint16

	currentShard lnwire.MilliSatoshi
	failStreak   uint32
	requests     uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edgeIndex:     make(map[beliefKey]*candidateEdge),
		localBalances: localBalances,
		beliefs:       make(map[beliefKey]liquidityBelief),
		reserved:      make(map[beliefKey]lnwire.MilliSatoshi),
		routePenalty:  make(map[beliefKey]float64),
		failAt:        make(map[beliefKey]lnwire.MilliSatoshi),
		policyVotes:   make(map[beliefKey]uint16),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var graphFingerprint uint64
	var edgeCount uint64

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: pol.FeeBaseMSat,
					feeRatePPM: pol.
						FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[edge.to] = append(
					r.incomingEdges[edge.to], edge,
				)
				graphFingerprint ^= fingerprintEdge(edge)
				edgeCount++
				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.network = graphFingerprint ^ mix64(edgeCount)

	sharedBeliefs.Lock()
	for _, edges := range r.incomingEdges {
		for _, edge := range edges {
			key := r.key(edge)
			r.edgeIndex[key] = edge
			if belief, ok := sharedBeliefs.m[key]; ok {
				r.beliefs[key] = belief
			}
		}
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func mix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func fingerprintEdge(edge *candidateEdge) uint64 {
	h := mix64(edge.chanID) ^ mix64(uint64(edge.capacity))
	for i, b := range edge.from {
		h ^= mix64(uint64(b) + uint64(i+1)*257)
	}
	for i, b := range edge.to {
		h ^= mix64(uint64(b) + uint64(i+1)*65537)
	}
	return mix64(h)
}

func (r *candidateRouter) key(edge *candidateEdge) beliefKey {
	return beliefKey{
		network: r.network,
		chanID:  edge.chanID,
		from:    edge.from,
		to:      edge.to,
	}
}

type dijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(x any) {
	*q = append(*q, x.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]
	return last
}

func clampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005
	case p > 0.995:
		return 0.995
	default:
		return p
	}
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.49 * math.Exp(-x/0.035)
	highMode := 0.49 / (1 + math.Exp((x-0.93)/0.035))
	return clampProbability(0.005 + lowMode + highMode)
}

func subtractFloor(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if b >= a {
		return 0
	}
	return a - b
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	key := r.key(edge)
	held := r.reserved[key]

	if edge.from == r.source {
		available := subtractFloor(
			r.localBalances[edge.chanID], held,
		)
		if amt <= available {
			return 0.999
		}
		return 0.001
	}

	available := subtractFloor(edge.capacity, held)
	if amt > available {
		return 0.001
	}

	prior := bimodalPrior(amt, available)
	belief, ok := r.beliefs[key]
	if !ok {
		return prior
	}

	lower := subtractFloor(belief.lowerOK, held)
	upper := subtractFloor(belief.upperFail, held)
	estimate := subtractFloor(belief.estimate, held)
	suspect := subtractFloor(belief.suspectAmt, held)

	if lower > 0 && amt <= lower {
		return 0.995
	}
	if belief.upperFail > 0 && upper == 0 {
		return 0.005
	}
	if upper > 0 && amt >= upper {
		return 0.007
	}

	p := prior
	observations := float64(belief.successes) +
		math.Min(float64(belief.failVotes)/2, 4)

	if estimate > 0 {
		width := math.Max(float64(available)*0.08, 1)
		z := (float64(amt) - float64(estimate)) / width
		if z > 30 {
			z = 30
		} else if z < -30 {
			z = -30
		}
		pointP := 1 / (1 + math.Exp(z))
		weight := math.Min(0.82, 0.22*observations)
		p = (1-weight)*p + weight*pointP
	}

	if lower > 0 && upper > lower && amt > lower && amt < upper {
		position := float64(amt-lower) / float64(upper-lower)
		boundedP := 0.99*(1-position) + 0.01*position
		p = 0.25*p + 0.75*boundedP
	}

	// One readable report is only a suspect observation. It influences
	// route ordering, but cannot create a hard exclusion.
	if belief.failVotes == 1 && suspect > 0 &&
		amt*4 >= suspect*3 {

		p *= 0.45
	}

	return clampProbability(p)
}

func (r *candidateRouter) hardAvailable(edge *candidateEdge,
	amt lnwire.MilliSatoshi) bool {

	key := r.key(edge)
	held := r.reserved[key]

	if amt > subtractFloor(edge.capacity, held) {
		return false
	}
	if edge.from == r.source {
		return amt <= subtractFloor(
			r.localBalances[edge.chanID], held,
		)
	}
	return true
}

func (r *candidateRouter) findRouteMode(amt lnwire.MilliSatoshi,
	relaxed bool) (*route.Route, error) {

	bestScore := make(map[route.Vertex]float64)
	required := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	required[r.spec.Target] = amt

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	for pq.Len() != 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		node := item.node

		score, ok := bestScore[node]
		if !ok || item.score > score+1e-12 {
			continue
		}
		if item.required != required[node] {
			continue
		}
		if node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[node] {
			amtOver := item.required
			if !edge.usable(amtOver) ||
				!r.hardAvailable(edge, amtOver) {

				continue
			}

			key := r.key(edge)
			belief := r.beliefs[key]
			upper := subtractFloor(
				belief.upperFail, r.reserved[key],
			)

			if !relaxed && belief.failVotes >= 3 &&
				belief.upperFail > 0 &&
				(upper == 0 || amtOver >= upper) {

				continue
			}

			p := r.edgeProbability(edge, amtOver)
			stepScore := -math.Log(p) + 0.008

			fee := edge.fee(amtOver)
			sending := amtOver + fee
			if edge.from == r.source {
				sending = amtOver
				fee = 0
			}

			denom := math.Max(float64(amtOver), 1)
			stepScore += 4 * float64(fee) / denom
			stepScore += r.routePenalty[key]

			if failedAt := r.failAt[key]; failedAt > 0 {
				if amtOver*10 >= failedAt*7 {
					stepScore += 1.35
				} else {
					stepScore += 0.04
				}
			}
			if votes := r.policyVotes[key]; votes > 0 {
				stepScore += 0.8 * float64(votes)
			}

			newScore := item.score + stepScore
			oldScore, seen := bestScore[edge.from]
			if seen && newScore >= oldScore {
				continue
			}

			bestScore[edge.from] = newScore
			required[edge.from] = sending
			next[edge.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:     edge.from,
				score:    newScore,
				required: sending,
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, errors.New("no route found")
	}
	return r.buildRoute(amt, next)
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*route.Route, error) {

	rt, err := r.findRouteMode(amt, false)
	if err == nil {
		return rt, nil
	}

	// Hard failure bounds are deliberately reversible. If all paths have
	// suspect bounds, retry the best one instead of terminally poisoning
	// the only corridor.
	return r.findRouteMode(amt, true)
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.to
	}

	if len(path) == 0 {
		return &route.Route{
			TotalTimeLock: finalCltvDelta,
			TotalAmount:   amt,
			SourcePubKey:  r.source,
		}, nil
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))
	last := len(path) - 1

	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forwardAmt := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			forwardAmt = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     forwardAmt,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func (r *candidateRouter) routeLogProbability(rt *route.Route) float64 {
	logP := 0.0
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		key := beliefKey{
			network: r.network,
			chanID:  hop.ChannelID,
			from:    from,
			to:      hop.PubKeyBytes,
		}
		edge := r.edgeIndex[key]
		if edge == nil {
			return math.Log(0.005)
		}

		amtOver := rt.TotalAmount
		if i > 0 {
			amtOver = rt.Hops[i-1].AmtToForward
		}
		logP += math.Log(r.edgeProbability(edge, amtOver))
		from = hop.PubKeyBytes
	}

	return logP
}

func ceilShard(amt lnwire.MilliSatoshi,
	parts uint32) lnwire.MilliSatoshi {

	if parts <= 1 {
		return amt
	}
	p := lnwire.MilliSatoshi(parts)
	return (amt + p - 1) / p
}

// selectInitialShard compares complete route-set sizes without consuming
// attempts. Equal allocations are only the initial plan: after each accepted
// shard, reservations and the remaining amount produce unequal allocations
// across the surviving corridors.
func (r *candidateRouter) selectInitialShard(amt lnwire.MilliSatoshi,
	parts uint32) (*route.Route, lnwire.MilliSatoshi, error) {

	if parts <= 1 {
		rt, err := r.findRoute(amt)
		return rt, amt, err
	}

	limit := parts
	if limit > 16 {
		limit = 16
	}

	bestScore := math.Inf(-1)
	var bestRoute *route.Route
	var bestAmt lnwire.MilliSatoshi

	evaluate := func(n uint32) {
		shard := ceilShard(amt, n)
		rt, err := r.findRoute(shard)
		if err != nil {
			return
		}

		// Approximate the probability of the whole planned route set.
		// The small part penalty breaks close ties toward faster commit.
		score := float64(n)*r.routeLogProbability(rt) -
			0.018*float64(n)
		if score > bestScore {
			bestScore = score
			bestRoute = rt
			bestAmt = shard
		}
	}

	for n := uint32(1); n <= limit; n++ {
		evaluate(n)
	}
	if parts > limit {
		evaluate(parts)
	}

	if bestRoute == nil {
		return nil, 0, errors.New("no route found")
	}
	return bestRoute, bestAmt, nil
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid payment amount")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum parts in flight")
	}

	partsLeft := maxParts - inFlightHtlcs
	minShard := ceilShard(amt, partsLeft)

	if r.currentShard == 0 {
		rt, shard, err := r.selectInitialShard(amt, partsLeft)
		if err != nil {
			return nil, err
		}
		r.currentShard = shard
		r.requests++
		return rt, nil
	}

	if r.currentShard > amt {
		r.currentShard = amt
	}
	if r.currentShard < minShard {
		r.currentShard = minShard
	}

	for {
		rt, err := r.findRoute(r.currentShard)
		if err == nil {
			r.requests++
			return rt, nil
		}
		if r.currentShard <= minShard {
			return nil, err
		}

		next := r.currentShard * 72 / 100
		if next < minShard || next >= r.currentShard {
			next = minShard
		}
		r.currentShard = next
	}
}

func (r *candidateRouter) routeEdges(rt *route.Route,
	fn func(beliefKey, *candidateEdge, lnwire.MilliSatoshi)) {

	from := rt.SourcePubKey
	for i, hop := range rt.Hops {
		key := beliefKey{
			network: r.network,
			chanID:  hop.ChannelID,
			from:    from,
			to:      hop.PubKeyBytes,
		}
		amtOver := rt.TotalAmount
		if i > 0 {
			amtOver = rt.Hops[i-1].AmtToForward
		}
		fn(key, r.edgeIndex[key], amtOver)
		from = hop.PubKeyBytes
	}
}

func (r *candidateRouter) storeBelief(key beliefKey,
	belief liquidityBelief) {

	r.beliefs[key] = belief
	sharedBeliefs.Lock()
	sharedBeliefs.m[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) recordSuccess(key beliefKey,
	edge *candidateEdge, amt lnwire.MilliSatoshi) {

	if edge == nil || edge.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}

	estimate := amt
	if edge.capacity > amt {
		estimate += (edge.capacity - amt) * 7 / 10
	}
	if estimate > belief.estimate {
		belief.estimate = estimate
	}

	if belief.successes < ^uint16(0) {
		belief.successes++
	}

	// Truthful success disproves any contradictory failure attribution.
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}
	if belief.suspectAmt > 0 && amt >= belief.suspectAmt {
		belief.suspectAmt = 0
		belief.failVotes = 0
	}

	r.storeBelief(key, belief)
}

func (r *candidateRouter) recordLiquidityFailure(key beliefKey,
	edge *candidateEdge, amt lnwire.MilliSatoshi) {

	if edge == nil || edge.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.suspectAmt == 0 || amt < belief.suspectAmt {
		belief.suspectAmt = amt
	}
	if belief.failVotes < ^uint16(0) {
		belief.failVotes++
	}

	// Require corroboration before writing a hard upper bound.
	if belief.failVotes >= 2 {
		if belief.upperFail == 0 || amt < belief.upperFail {
			belief.upperFail = amt
		}

		estimate := amt * 45 / 100
		if belief.estimate == 0 || estimate < belief.estimate {
			belief.estimate = estimate
		}
	}

	// A later, smaller failure can invalidate an old lower bound. This is
	// also how beliefs recover when background traffic moves liquidity.
	if belief.lowerOK >= amt && belief.failVotes >= 2 {
		belief.lowerOK = 0
	}

	r.storeBelief(key, belief)
}

func (r *candidateRouter) attributedFailure(rt *route.Route,
	source route.Vertex) (beliefKey, *candidateEdge,
	lnwire.MilliSatoshi, bool) {

	failIdx := -1
	if source == rt.SourcePubKey {
		failIdx = 0
	}
	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			failIdx = i + 1
			break
		}
	}

	if failIdx < 0 || failIdx >= len(rt.Hops) {
		return beliefKey{}, nil, 0, false
	}

	from := rt.SourcePubKey
	if failIdx > 0 {
		from = rt.Hops[failIdx-1].PubKeyBytes
	}
	hop := rt.Hops[failIdx]
	key := beliefKey{
		network: r.network,
		chanID:  hop.ChannelID,
		from:    from,
		to:      hop.PubKeyBytes,
	}

	amtOver := rt.TotalAmount
	if failIdx > 0 {
		amtOver = rt.Hops[failIdx-1].AmtToForward
	}

	return key, r.edgeIndex[key], amtOver, true
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if result.Failure == nil {
		r.failStreak = 0
		r.currentShard = 0

		r.routeEdges(rt, func(key beliefKey, edge *candidateEdge,
			amt lnwire.MilliSatoshi) {

			r.reserved[key] += amt
			r.recordSuccess(key, edge, amt)
		})
		return nil
	}

	r.failStreak++

	// A failed route is weak evidence for diversification, even when its
	// onion error cannot be read. It never creates a global bound.
	r.routeEdges(rt, func(key beliefKey, _ *candidateEdge,
		_ lnwire.MilliSatoshi) {

		r.routePenalty[key] += 0.055
	})

	key, edge, failedAmt, attributed := r.attributedFailure(
		rt, result.FailureSource,
	)

	code := result.Failure.Code()
	liquidityFailure := code == lnwire.CodeTemporaryChannelFailure
	policyFailure := code == lnwire.CodeFeeInsufficient ||
		code == lnwire.CodeIncorrectCltvExpiry

	if attributed {
		switch {
		case liquidityFailure:
			if old := r.failAt[key]; old == 0 || failedAmt < old {
				r.failAt[key] = failedAmt
			}
			r.recordLiquidityFailure(key, edge, failedAmt)

		case policyFailure:
			if r.policyVotes[key] < ^uint16(0) {
				r.policyVotes[key]++
			}
		}
	}

	// Try route diversity at the same size once, then descend smoothly.
	// Unattributed failures can trigger sizing changes but never poison a
	// particular directed channel.
	if !policyFailure && r.failStreak >= 2 {
		shard := rt.Hops[len(rt.Hops)-1].AmtToForward
		factor := lnwire.MilliSatoshi(70)
		if attributed && liquidityFailure &&
			r.beliefs[key].failVotes >= 2 {

			factor = 62
		}
		next := shard * factor / 100
		if next > 0 && (r.currentShard == 0 ||
			next < r.currentShard) {

			r.currentShard = next
		}
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	conf      uint8

	suspectAmt   lnwire.MilliSatoshi
	suspectVotes uint8
}

var candidateBeliefStore = struct {
	sync.Mutex
	beliefs map[candidateEdgeKey]*candidateBelief
}{
	beliefs: make(map[candidateEdgeKey]*candidateBelief),
}

type candidateObservation struct {
	amt    lnwire.MilliSatoshi
	weight float64
}

type candidateTraversal struct {
	key  candidateEdgeKey
	edge *candidateEdge
	amt  lnwire.MilliSatoshi
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	reserved   map[candidateEdgeKey]lnwire.MilliSatoshi
	usedTotals map[candidateEdgeKey]lnwire.MilliSatoshi
	evidence   map[candidateEdgeKey][]candidateObservation

	plannedParts uint32
	failures     uint32
	unknownFails uint32
	retryCap     lnwire.MilliSatoshi
	delivered    lnwire.MilliSatoshi
	settled      bool
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	if spec == nil {
		return nil, errors.New("nil payment specification")
	}

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[candidateEdgeKey]*candidateEdge),
		localBalances: localBalances,
		reserved:      make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		usedTotals:    make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		evidence:      make(map[candidateEdgeKey][]candidateObservation),
	}

	r.plannedParts = r.initialPartCount(spec.Amount)
	if spec.MaxParts != 0 && r.plannedParts > spec.MaxParts {
		r.plannedParts = spec.MaxParts
	}
	if r.plannedParts == 0 {
		r.plannedParts = 1
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[key] = edge

				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func (r *candidateRouter) initialPartCount(
	amt lnwire.MilliSatoshi) uint32 {

	const desiredShard = lnwire.MilliSatoshi(50_000_000)

	if amt <= 20_000_000 {
		return 1
	}

	parts := uint32((amt + desiredShard - 1) / desiredShard)
	if parts < 2 {
		parts = 2
	}
	return parts
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.003
	}

	x := float64(amt) / float64(capacity)

	lowMode := 0.48 * math.Exp(-x/0.025)
	highMode := 0.50 / (1 + math.Exp((x-0.90)/0.025))
	p := 0.005 + lowMode + highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func candidateLogisticProbability(amt, estimate,
	capacity lnwire.MilliSatoshi) float64 {

	if capacity <= 0 {
		return 0.005
	}

	scale := 0.07 * float64(capacity)
	if scale < 1 {
		scale = 1
	}

	z := (float64(amt) - float64(estimate)) / scale
	switch {
	case z > 30:
		return 0.005
	case z < -30:
		return 0.995
	default:
		return 1 / (1 + math.Exp(z))
	}
}

func (r *candidateRouter) edgeProbability(e *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	required := amt + r.reserved[e.key]
	if required > e.capacity {
		return 0.001
	}

	if e.key.from == r.source {
		if r.localBalances[e.key.chanID] < required {
			return 0.001
		}
		return 0.999
	}

	p := candidatePrior(required, e.capacity)

	candidateBeliefStore.Lock()
	stored, ok := candidateBeliefStore.beliefs[e.key]
	var belief candidateBelief
	if ok {
		belief = *stored
	}
	candidateBeliefStore.Unlock()

	if ok {
		if belief.estimate > 0 && belief.conf > 0 {
			q := candidateLogisticProbability(
				required, belief.estimate, e.capacity,
			)
			weight := 0.12 * float64(belief.conf)
			if weight > 0.72 {
				weight = 0.72
			}
			p = (1-weight)*p + weight*q
		}

		if belief.lowerOK > 0 && required <= belief.lowerOK {
			p = math.Max(p, 0.995)
		}

		if belief.upperFail > 0 {
			switch {
			case required >= belief.upperFail:
				p = math.Min(p, 0.025)

			case belief.lowerOK > 0 &&
				belief.upperFail > belief.lowerOK:

				span := float64(
					belief.upperFail - belief.lowerOK,
				)
				pos := float64(
					required - belief.lowerOK,
				) / span
				if pos > 0 {
					bounded := 0.995*(1-pos) + 0.025*pos
					p = 0.4*p + 0.6*bounded
				}
			}
		}
	}

	if p < 0.003 {
		return 0.003
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

func candidateObservationScale(required,
	failedAt lnwire.MilliSatoshi) float64 {

	if failedAt <= 0 || required >= failedAt {
		return 1
	}

	ratio := float64(required) / float64(failedAt)
	if ratio <= 0.40 {
		return 0.03
	}

	x := (ratio - 0.40) / 0.60
	return 0.03 + 0.97*x*x
}

func (r *candidateRouter) evidencePenalty(key candidateEdgeKey,
	required lnwire.MilliSatoshi) float64 {

	total := 0.0
	for _, observation := range r.evidence[key] {
		total += observation.weight *
			candidateObservationScale(required, observation.amt)
	}

	if total > 7 {
		return 7
	}
	return total
}

func (r *candidateRouter) addEvidence(key candidateEdgeKey,
	amt lnwire.MilliSatoshi, weight float64) {

	if amt <= 0 || weight <= 0 {
		return
	}

	observations := r.evidence[key]
	if len(observations) < 24 {
		r.evidence[key] = append(observations, candidateObservation{
			amt:    amt,
			weight: weight,
		})
		return
	}

	closest := 0
	bestDistance := math.MaxFloat64
	for i, observation := range observations {
		distance := math.Abs(
			float64(observation.amt-amt) /
				math.Max(1, float64(observation.amt)),
		)
		if distance < bestDistance {
			bestDistance = distance
			closest = i
		}
	}

	observations[closest].weight += weight
	if observations[closest].weight > 6 {
		observations[closest].weight = 6
	}
	if amt < observations[closest].amt {
		observations[closest].amt = amt
	}
	r.evidence[key] = observations
}

func (r *candidateRouter) clearDisprovedEvidence(key candidateEdgeKey,
	successAmt lnwire.MilliSatoshi) {

	observations := r.evidence[key]
	kept := observations[:0]
	for _, observation := range observations {
		if observation.amt > successAmt {
			kept = append(kept, observation)
		}
	}

	if len(kept) == 0 {
		delete(r.evidence, key)
		return
	}
	r.evidence[key] = kept
}

func (r *candidateRouter) edgeCost(e *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	required := amt + r.reserved[e.key]
	p := r.edgeProbability(e, amt)
	cost := -math.Log(p) + 0.01 +
		r.evidencePenalty(e.key, required)

	if reserved := r.reserved[e.key]; reserved > 0 &&
		e.capacity > 0 {

		cost += 0.25 +
			0.90*float64(reserved)/float64(e.capacity)
	}

	return cost
}

type candidateDijkstraItem struct {
	node  route.Vertex
	score float64
	amt   lnwire.MilliSatoshi
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *candidateDijkstraQueue) Push(x any) {
	*q = append(*q, x.(*candidateDijkstraItem))
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]
	return item
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}

	score := make(map[route.Vertex]float64)
	arriving := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)

	score[r.spec.Target] = 0
	arriving[r.spec.Target] = amt

	pq := &candidateDijkstraQueue{}
	heap.Push(pq, &candidateDijkstraItem{
		node: r.spec.Target,
		amt:  amt,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)
		bestScore, ok := score[item.node]
		if !ok || item.score > bestScore+1e-12 {
			continue
		}
		if item.amt != arriving[item.node] {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOver := item.amt
			if !edge.policyAllows(amtOver) {
				continue
			}

			required := amtOver + r.reserved[edge.key]
			if required > edge.capacity {
				continue
			}
			if edge.key.from == r.source &&
				r.localBalances[edge.key.chanID] < required {

				continue
			}

			sending := amtOver
			feeCost := 0.0
			if edge.key.from != r.source {
				fee := edge.fee(amtOver)
				sending += fee

				denom := math.Max(1, float64(amt))
				feeCost = 7 * float64(fee) / denom
			}

			newScore := item.score +
				r.edgeCost(edge, amtOver) + feeCost

			oldScore, exists := score[edge.key.from]
			if exists && newScore >= oldScore {
				continue
			}

			score[edge.key.from] = newScore
			arriving[edge.key.from] = sending
			next[edge.key.from] = edge
			heap.Push(pq, &candidateDijkstraItem{
				node:  edge.key.from,
				score: newScore,
				amt:   sending,
			})
		}
	}

	if _, ok := score[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}

	pathProbability := 1.0
	for _, traversal := range r.routeTraversals(rt) {
		pathProbability *= r.edgeProbability(
			traversal.edge, traversal.amt,
		)
	}

	return rt, pathProbability, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateCeilDiv(amt lnwire.MilliSatoshi,
	parts uint32) lnwire.MilliSatoshi {

	if parts <= 1 {
		return amt
	}

	divisor := lnwire.MilliSatoshi(parts)
	return (amt + divisor - 1) / divisor
}

func (r *candidateRouter) targetPartCount() uint32 {
	target := r.plannedParts + r.failures/2
	if r.unknownFails >= 3 {
		target++
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if target > maxParts {
		target = maxParts
	}
	if target == 0 {
		target = 1
	}
	return target
}

func (r *candidateRouter) routeProven(rt *route.Route) bool {
	traversals := r.routeTraversals(rt)
	if len(traversals) != len(rt.Hops) {
		return false
	}

	candidateBeliefStore.Lock()
	defer candidateBeliefStore.Unlock()

	for _, traversal := range traversals {
		required := traversal.amt + r.reserved[traversal.key]

		if traversal.key.from == r.source {
			if r.localBalances[traversal.key.chanID] < required {
				return false
			}
			continue
		}

		belief := candidateBeliefStore.beliefs[traversal.key]
		if belief == nil || belief.lowerOK < required {
			return false
		}
	}

	return true
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum parts already in flight")
	}

	partsLeft := maxParts - inFlightHtlcs
	minimumShard := candidateCeilDiv(amt, partsLeft)

	var wholeRoute *route.Route
	if rt, probability, err := r.findRoute(amt); err == nil {
		wholeRoute = rt
		if r.plannedParts == 1 ||
			(r.failures == 0 && probability >= 0.82 &&
				r.routeProven(rt)) {

			return rt, nil
		}
	}

	targetParts := r.targetPartCount()
	desiredSlots := uint32(1)
	if targetParts > inFlightHtlcs {
		desiredSlots = targetParts - inFlightHtlcs
	}
	if desiredSlots > partsLeft {
		desiredSlots = partsLeft
	}

	baseShard := candidateCeilDiv(amt, desiredSlots)
	if baseShard > amt {
		baseShard = amt
	}

	floor := minimumShard
	if partsLeft > 1 {
		floor = minimumShard * 55 / 100
		if floor < 1 {
			floor = 1
		}
	}

	if r.retryCap == 0 && desiredSlots > 1 {
		candidates := []lnwire.MilliSatoshi{
			baseShard * 2,
			baseShard * 3 / 2,
			baseShard * 5 / 4,
			baseShard,
		}

		var last lnwire.MilliSatoshi
		for _, shard := range candidates {
			if shard > amt {
				shard = amt
			}
			if shard < floor {
				shard = floor
			}
			if shard == last {
				continue
			}
			last = shard

			rt, probability, err := r.findRoute(shard)
			if err != nil {
				continue
			}
			if shard == baseShard || probability >= 0.48 ||
				r.routeProven(rt) {

				return rt, nil
			}
		}
	}

	shard := baseShard
	if r.retryCap > 0 && r.retryCap < shard {
		shard = r.retryCap
	}
	if shard < floor {
		shard = floor
	}
	if shard > amt {
		shard = amt
	}

	var lastErr error
	for {
		rt, _, err := r.findRoute(shard)
		if err == nil {
			return rt, nil
		}
		lastErr = err

		if shard <= floor {
			break
		}

		nextShard := shard * 3 / 4
		if nextShard < floor {
			nextShard = floor
		}
		if nextShard == shard {
			nextShard--
		}
		shard = nextShard
	}

	if wholeRoute != nil && shard != amt {
		return wholeRoute, nil
	}
	return nil, lastErr
}

func (r *candidateRouter) routeTraversals(
	rt *route.Route) []candidateTraversal {

	traversals := make([]candidateTraversal, 0, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		key := candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		edge := r.edges[key]
		if edge == nil {
			from = hop.PubKeyBytes
			continue
		}

		amt := rt.TotalAmount
		if i > 0 {
			amt = rt.Hops[i-1].AmtToForward
		}

		traversals = append(traversals, candidateTraversal{
			key:  key,
			edge: edge,
			amt:  amt,
		})
		from = hop.PubKeyBytes
	}

	return traversals
}

func candidateDeliveredAmount(rt *route.Route) lnwire.MilliSatoshi {
	if len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func (r *candidateRouter) recordSuccess(rt *route.Route) {
	traversals := r.routeTraversals(rt)

	candidateBeliefStore.Lock()
	for _, traversal := range traversals {
		required := traversal.amt + r.reserved[traversal.key]
		belief := candidateBeliefStore.beliefs[traversal.key]
		if belief == nil {
			belief = &candidateBelief{}
			candidateBeliefStore.beliefs[traversal.key] = belief
		}

		if required > belief.lowerOK {
			belief.lowerOK = required
		}

		highEstimate := traversal.edge.capacity * 88 / 100
		if required > highEstimate {
			highEstimate = required
		}
		if highEstimate > belief.estimate {
			belief.estimate = highEstimate
		}
		if belief.conf < 8 {
			belief.conf++
		}

		if belief.upperFail > 0 && required >= belief.upperFail {
			belief.upperFail = 0
		}
		if belief.suspectAmt > 0 &&
			required >= belief.suspectAmt {

			belief.suspectAmt = 0
			belief.suspectVotes = 0
		}
	}
	candidateBeliefStore.Unlock()

	for _, traversal := range traversals {
		required := traversal.amt + r.reserved[traversal.key]
		r.clearDisprovedEvidence(traversal.key, required)
		r.reserved[traversal.key] += traversal.amt
		r.usedTotals[traversal.key] += traversal.amt
	}

	r.delivered += candidateDeliveredAmount(rt)
	if r.delivered >= r.spec.Amount && !r.settled {
		r.recordSettlement()
		r.settled = true
	}
}

func (r *candidateRouter) recordSettlement() {
	candidateBeliefStore.Lock()
	defer candidateBeliefStore.Unlock()

	for key, used := range r.usedTotals {
		if used <= 0 {
			continue
		}

		if belief := candidateBeliefStore.beliefs[key]; belief != nil {
			if belief.lowerOK > used {
				belief.lowerOK -= used
			} else {
				belief.lowerOK = 0
			}
			if belief.estimate > used {
				belief.estimate -= used
			} else {
				belief.estimate = 0
			}
			if belief.upperFail > used {
				belief.upperFail -= used
			} else {
				belief.upperFail = 0
			}
			if belief.suspectAmt > used {
				belief.suspectAmt -= used
			} else {
				belief.suspectAmt = 0
				belief.suspectVotes = 0
			}
		}

		reverse := candidateEdgeKey{
			chanID: key.chanID,
			from:   key.to,
			to:     key.from,
		}
		reverseBelief := candidateBeliefStore.beliefs[reverse]
		if reverseBelief == nil {
			reverseBelief = &candidateBelief{}
			candidateBeliefStore.beliefs[reverse] = reverseBelief
		}

		reverseCapacity := lnwire.MilliSatoshi(0)
		if edge := r.edges[reverse]; edge != nil {
			reverseCapacity = edge.capacity
		} else if edge := r.edges[key]; edge != nil {
			reverseCapacity = edge.capacity
		}

		reverseBelief.lowerOK += used
		reverseBelief.estimate += used

		if reverseCapacity > 0 {
			if reverseBelief.lowerOK > reverseCapacity {
				reverseBelief.lowerOK = reverseCapacity
			}
			if reverseBelief.estimate > reverseCapacity {
				reverseBelief.estimate = reverseCapacity
			}
		}

		if reverseBelief.upperFail > 0 {
			reverseBelief.upperFail += used
			if reverseCapacity > 0 &&
				reverseBelief.upperFail > reverseCapacity {

				reverseBelief.upperFail = reverseCapacity
			}
		}
	}
}

func (r *candidateRouter) failureIndex(rt *route.Route,
	source route.Vertex) ([]candidateTraversal, int, bool) {

	traversals := r.routeTraversals(rt)
	if len(traversals) != len(rt.Hops) {
		return traversals, -1, false
	}

	if source == rt.SourcePubKey {
		return traversals, 0, len(traversals) > 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes != source {
			continue
		}

		index := i + 1
		if index >= len(traversals) {
			return traversals, -1, false
		}
		return traversals, index, true
	}

	return traversals, -1, false
}

func (r *candidateRouter) recordPersistentFailure(
	traversal candidateTraversal) {

	if traversal.key.from == r.source {
		return
	}

	required := traversal.amt + r.reserved[traversal.key]

	candidateBeliefStore.Lock()
	defer candidateBeliefStore.Unlock()

	belief := candidateBeliefStore.beliefs[traversal.key]
	if belief == nil {
		belief = &candidateBelief{}
		candidateBeliefStore.beliefs[traversal.key] = belief
	}

	if belief.suspectVotes == 0 {
		belief.suspectAmt = required
		belief.suspectVotes = 1
		return
	}

	if belief.suspectAmt == 0 || required < belief.suspectAmt {
		belief.suspectAmt = required
	}
	if belief.suspectVotes < 255 {
		belief.suspectVotes++
	}

	if belief.suspectVotes < 3 {
		return
	}

	if belief.upperFail == 0 ||
		belief.suspectAmt < belief.upperFail {

		belief.upperFail = belief.suspectAmt
	}

	failedEstimate := belief.suspectAmt * 60 / 100
	if belief.estimate == 0 || failedEstimate < belief.estimate {
		belief.estimate = failedEstimate
	}
	if belief.conf < 8 {
		belief.conf++
	}
}

func (r *candidateRouter) recordRouteEvidence(
	traversals []candidateTraversal, weight float64) {

	for _, traversal := range traversals {
		required := traversal.amt + r.reserved[traversal.key]
		r.addEvidence(traversal.key, required, weight)
	}
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if result.Failure == nil {
		r.retryCap = 0
		r.recordSuccess(rt)
		return nil
	}

	r.failures++
	traversals, index, attributed := r.failureIndex(
		rt, result.FailureSource,
	)
	code := result.Failure.Code()
	delivered := candidateDeliveredAmount(rt)

	switch code {
	case lnwire.CodeTemporaryChannelFailure:
		// Every failed route contains the true bottleneck, even when the
		// onion error cannot be read. Weak route-wide evidence permits
		// intersection across retries without persistent poisoning.
		r.recordRouteEvidence(traversals, 0.09)

		if attributed {
			failed := traversals[index]
			required := failed.amt + r.reserved[failed.key]
			r.addEvidence(failed.key, required, 0.52)

			// Shifted attribution is normally one adjacent hop away.
			// Giving both neighbors smaller votes lets repeated routes
			// identify the edge that consistently remains implicated.
			if index > 0 {
				neighbor := traversals[index-1]
				neighborAmt := neighbor.amt +
					r.reserved[neighbor.key]
				r.addEvidence(
					neighbor.key, neighborAmt, 0.20,
				)
			}
			if index+1 < len(traversals) {
				neighbor := traversals[index+1]
				neighborAmt := neighbor.amt +
					r.reserved[neighbor.key]
				r.addEvidence(
					neighbor.key, neighborAmt, 0.20,
				)
			}

			r.recordPersistentFailure(failed)
		} else {
			r.unknownFails++
		}

		if delivered > 1 {
			r.retryCap = delivered * 60 / 100
			if r.retryCap < 1 {
				r.retryCap = 1
			}
		}

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.recordRouteEvidence(traversals, 0.04)
		if attributed {
			failed := traversals[index]
			required := failed.amt + r.reserved[failed.key]
			r.addEvidence(failed.key, required, 1.1)

			if index > 0 {
				neighbor := traversals[index-1]
				neighborAmt := neighbor.amt +
					r.reserved[neighbor.key]
				r.addEvidence(
					neighbor.key, neighborAmt, 0.18,
				)
			}
			if index+1 < len(traversals) {
				neighbor := traversals[index+1]
				neighborAmt := neighbor.amt +
					r.reserved[neighbor.key]
				r.addEvidence(
					neighbor.key, neighborAmt, 0.18,
				)
			}
		} else {
			r.unknownFails++
		}

	default:
		r.unknownFails++
		r.recordRouteEvidence(traversals, 0.07)

		if r.unknownFails%2 == 0 && delivered > 1 {
			r.retryCap = delivered * 70 / 100
			if r.retryCap < 1 {
				r.retryCap = 1
			}
		}
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	conf      uint8

	suspectAmt   lnwire.MilliSatoshi
	suspectVotes uint8
}

var candidateBeliefStore = struct {
	sync.Mutex
	beliefs map[candidateEdgeKey]*candidateBelief
}{
	beliefs: make(map[candidateEdgeKey]*candidateBelief),
}

type candidateLocalFailure struct {
	upper lnwire.MilliSatoshi
	count uint8
}

type candidateTraversal struct {
	key  candidateEdgeKey
	edge *candidateEdge
	amt  lnwire.MilliSatoshi
}

type candidatePlanPart struct {
	amt  lnwire.MilliSatoshi
	path []*candidateEdge
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	reserved    map[candidateEdgeKey]lnwire.MilliSatoshi
	usedTotals  map[candidateEdgeKey]lnwire.MilliSatoshi
	localFails  map[candidateEdgeKey]candidateLocalFailure
	diversion   map[candidateEdgeKey]float64
	policyFails map[candidateEdgeKey]uint8

	plannedParts uint32
	failures     uint32
	unknownFails uint32
	requestNo    uint64
	searchSalt   uint64
	retryCap     lnwire.MilliSatoshi
	delivered    lnwire.MilliSatoshi
	settled      bool

	plan        []candidatePlanPart
	planIndex   int
	pendingPlan bool
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[candidateEdgeKey]*candidateEdge),
		localBalances: localBalances,
		reserved:      make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		usedTotals:    make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		localFails:    make(map[candidateEdgeKey]candidateLocalFailure),
		diversion:     make(map[candidateEdgeKey]float64),
		policyFails:   make(map[candidateEdgeKey]uint8),
	}

	r.plannedParts = r.initialPartCount(spec.Amount)
	if spec.MaxParts != 0 && r.plannedParts > spec.MaxParts {
		r.plannedParts = spec.MaxParts
	}
	if r.plannedParts == 0 {
		r.plannedParts = 1
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[key] = edge

				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func (r *candidateRouter) initialPartCount(
	amt lnwire.MilliSatoshi) uint32 {

	switch {
	case amt <= 20_000_000:
		return 1
	case amt <= 100_000_000:
		return 2
	case amt <= 400_000_000:
		return 4
	case amt <= 1_000_000_000:
		return 6
	case amt <= 3_000_000_000:
		return 10
	default:
		if r.spec.MaxParts != 0 {
			return r.spec.MaxParts
		}
		return 12
	}
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.002
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.48 * math.Exp(-x/0.025)
	highMode := 0.50 / (1 + math.Exp((x-0.90)/0.025))
	p := 0.005 + lowMode + highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func candidateLogisticProbability(amt, estimate,
	capacity lnwire.MilliSatoshi) float64 {

	if capacity <= 0 {
		return 0.005
	}

	scale := 0.06 * float64(capacity)
	if scale < 1 {
		scale = 1
	}

	z := (float64(amt) - float64(estimate)) / scale
	switch {
	case z > 30:
		return 0.005
	case z < -30:
		return 0.995
	default:
		return 1 / (1 + math.Exp(z))
	}
}

func (r *candidateRouter) edgeProbability(e *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	required := amt + r.reserved[e.key]
	if required > e.capacity {
		return 0.001
	}

	if e.key.from == r.source {
		if r.localBalances[e.key.chanID] < required {
			return 0.001
		}
		return 0.999
	}

	p := candidatePrior(required, e.capacity)

	candidateBeliefStore.Lock()
	stored, ok := candidateBeliefStore.beliefs[e.key]
	var belief candidateBelief
	if ok {
		belief = *stored
	}
	candidateBeliefStore.Unlock()

	if ok {
		if belief.estimate > 0 && belief.conf > 0 {
			q := candidateLogisticProbability(
				required, belief.estimate, e.capacity,
			)
			weight := 0.13 * float64(belief.conf)
			if weight > 0.68 {
				weight = 0.68
			}
			p = (1-weight)*p + weight*q
		}

		if belief.lowerOK > 0 && required <= belief.lowerOK {
			p = math.Max(p, 0.995)
		}

		if belief.upperFail > 0 {
			switch {
			case required >= belief.upperFail:
				p = math.Min(p, 0.022)

			case belief.lowerOK > 0 &&
				belief.upperFail > belief.lowerOK &&
				required > belief.lowerOK:

				span := float64(
					belief.upperFail - belief.lowerOK,
				)
				pos := float64(
					required - belief.lowerOK,
				) / span
				bounded := 0.995*(1-pos) + 0.022*pos
				p = 0.35*p + 0.65*bounded
			}
		}
	}

	if local, exists := r.localFails[e.key]; exists &&
		required >= local.upper {

		switch {
		case local.count >= 3:
			p *= 0.035
		case local.count == 2:
			p *= 0.12
		default:
			p *= 0.45
		}
	}

	if p < 0.002 {
		return 0.002
	}
	if p > 0.997 {
		return 0.997
	}
	return p
}

func candidateEdgeHash(key candidateEdgeKey, salt uint64) float64 {
	h := key.chanID ^ salt ^ 0x9e3779b97f4a7c15
	for _, b := range key.from {
		h ^= uint64(b)
		h *= 0x100000001b3
	}
	for _, b := range key.to {
		h ^= uint64(b) + 0x9d
		h *= 0x100000001b3
	}

	h ^= h >> 30
	h *= 0xbf58476d1ce4e5b9
	h ^= h >> 27
	h *= 0x94d049bb133111eb
	h ^= h >> 31

	return float64(h>>11) / float64(uint64(1)<<53)
}

func (r *candidateRouter) edgeCost(e *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	p := r.edgeProbability(e, amt)
	cost := -math.Log(p) + 0.008
	cost += r.diversion[e.key]

	if reserved := r.reserved[e.key]; reserved > 0 &&
		e.capacity > 0 {

		cost += 2.25 +
			3.25*float64(reserved)/float64(e.capacity)
	}

	if r.failures > 0 {
		exploration := 0.08 + 0.02*float64(r.failures)
		if exploration > 0.55 {
			exploration = 0.55
		}
		cost += exploration * candidateEdgeHash(
			e.key, r.searchSalt,
		)
	}

	return cost
}

type candidateLabel struct {
	node     route.Vertex
	score    float64
	amt      lnwire.MilliSatoshi
	nextEdge *candidateEdge
	next     *candidateLabel
	active   bool
}

type candidateLabelQueue []*candidateLabel

func (q candidateLabelQueue) Len() int {
	return len(q)
}

func (q candidateLabelQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateLabelQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *candidateLabelQueue) Push(x any) {
	*q = append(*q, x.(*candidateLabel))
}

func (q *candidateLabelQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func candidateLabelContains(label *candidateLabel,
	node route.Vertex) bool {

	for current := label; current != nil; current = current.next {
		if current.node == node {
			return true
		}
	}
	return false
}

func candidateAddLabel(labels map[route.Vertex][]*candidateLabel,
	label *candidateLabel) bool {

	existing := labels[label.node]
	activeCount := 0

	for _, old := range existing {
		if !old.active {
			continue
		}
		activeCount++

		if old.score <= label.score && old.amt <= label.amt {
			return false
		}
	}

	for _, old := range existing {
		if !old.active {
			continue
		}
		if label.score <= old.score && label.amt <= old.amt {
			old.active = false
			activeCount--
		}
	}

	if activeCount >= 10 {
		var worst *candidateLabel
		for _, old := range existing {
			if !old.active {
				continue
			}
			if worst == nil || old.score > worst.score {
				worst = old
			}
		}
		if worst != nil && worst.score <= label.score {
			return false
		}
		if worst != nil {
			worst.active = false
		}
	}

	label.active = true
	labels[label.node] = append(existing, label)
	return true
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}

	target := &candidateLabel{
		node:   r.spec.Target,
		score:  0,
		amt:    amt,
		active: true,
	}
	labels := map[route.Vertex][]*candidateLabel{
		r.spec.Target: {target},
	}
	pq := &candidateLabelQueue{}
	heap.Push(pq, target)

	var sourceLabel *candidateLabel

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateLabel)
		if !item.active {
			continue
		}
		if item.node == r.source {
			sourceLabel = item
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if candidateLabelContains(item, edge.key.from) {
				continue
			}

			amtOver := item.amt
			if !edge.policyAllows(amtOver) {
				continue
			}

			required := amtOver + r.reserved[edge.key]
			if required > edge.capacity {
				continue
			}
			if edge.key.from == r.source &&
				r.localBalances[edge.key.chanID] < required {

				continue
			}

			sending := amtOver
			feeCost := 0.0
			if edge.key.from != r.source {
				fee := edge.fee(amtOver)
				sending += fee

				denom := float64(amt)
				if denom < 1 {
					denom = 1
				}
				feeCost = 8 * float64(fee) / denom
			}

			label := &candidateLabel{
				node:     edge.key.from,
				score: item.score +
					r.edgeCost(edge, amtOver) + feeCost,
				amt:      sending,
				nextEdge: edge,
				next:     item,
			}
			if candidateAddLabel(labels, label) {
				heap.Push(pq, label)
			}
		}
	}

	if sourceLabel == nil {
		return nil, 0, errors.New("no route found")
	}

	path := make([]*candidateEdge, 0, 8)
	for label := sourceLabel; label.nextEdge != nil; label = label.next {
		path = append(path, label.nextEdge)
	}

	rt, err := r.buildRoute(amt, path)
	if err != nil {
		return nil, 0, err
	}

	probability := 1.0
	for _, traversal := range r.routeTraversals(rt) {
		probability *= r.edgeProbability(
			traversal.edge, traversal.amt,
		)
	}

	return rt, probability, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, error) {

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateCeilDiv(amt lnwire.MilliSatoshi,
	parts uint32) lnwire.MilliSatoshi {

	if parts <= 1 {
		return amt
	}
	divisor := lnwire.MilliSatoshi(parts)
	return (amt + divisor - 1) / divisor
}

func candidateAppendAmount(amounts []lnwire.MilliSatoshi,
	amt, maximum lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if amt > maximum {
		amt = maximum
	}
	if amt <= 0 {
		return amounts
	}

	for _, existing := range amounts {
		if existing == amt {
			return amounts
		}
	}
	return append(amounts, amt)
}

func candidateDeliveredAmount(rt *route.Route) lnwire.MilliSatoshi {
	if len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateRoutePath(rt *route.Route,
	traversals []candidateTraversal) []*candidateEdge {

	path := make([]*candidateEdge, 0, len(traversals))
	if len(traversals) != len(rt.Hops) {
		return path
	}
	for _, traversal := range traversals {
		path = append(path, traversal.edge)
	}
	return path
}

func candidateRouteUtility(rt *route.Route, probability float64,
	shard, reference lnwire.MilliSatoshi) float64 {

	if probability < 1e-12 {
		probability = 1e-12
	}

	progress := float64(shard) / float64(reference)
	if progress < 1e-9 {
		progress = 1e-9
	}

	delivered := candidateDeliveredAmount(rt)
	feeRatio := 0.0
	if delivered > 0 && rt.TotalAmount > delivered {
		feeRatio = float64(rt.TotalAmount-delivered) /
			float64(delivered)
	}

	return math.Log(probability) +
		0.62*math.Log(progress) - 3.0*feeRatio
}

func (r *candidateRouter) desiredPlanParts(inFlight uint32) uint32 {
	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlight >= maxParts {
		return 0
	}

	target := r.plannedParts
	if r.failures > 1 {
		target += (r.failures + 1) / 3
	}
	if target > maxParts {
		target = maxParts
	}
	if target <= inFlight {
		return 1
	}
	return target - inFlight
}

func (r *candidateRouter) tryPlan(amt lnwire.MilliSatoshi,
	parts uint32) ([]candidatePlanPart, bool) {

	if parts == 0 || amt <= 0 {
		return nil, false
	}

	realReserved := r.reserved
	virtual := make(map[candidateEdgeKey]lnwire.MilliSatoshi,
		len(realReserved))
	for key, value := range realReserved {
		virtual[key] = value
	}
	r.reserved = virtual
	defer func() {
		r.reserved = realReserved
	}()

	remaining := amt
	plan := make([]candidatePlanPart, 0, parts)

	for slot := uint32(0); slot < parts; slot++ {
		slotsLeft := parts - slot
		equal := candidateCeilDiv(remaining, slotsLeft)

		maximum := remaining
		if slotsLeft > 1 {
			maximum = remaining -
				lnwire.MilliSatoshi(slotsLeft-1)
		}

		amounts := make([]lnwire.MilliSatoshi, 0, 5)
		amounts = candidateAppendAmount(amounts, equal, maximum)
		amounts = candidateAppendAmount(
			amounts, equal*5/4, maximum,
		)
		amounts = candidateAppendAmount(
			amounts, equal*3/2, maximum,
		)
		amounts = candidateAppendAmount(
			amounts, equal*2, maximum,
		)
		amounts = candidateAppendAmount(
			amounts, maximum, maximum,
		)

		var bestRoute *route.Route
		var bestPath []*candidateEdge
		bestScore := math.Inf(-1)

		for _, shard := range amounts {
			rt, probability, err := r.findRoute(shard)
			if err != nil {
				continue
			}

			traversals := r.routeTraversals(rt)
			path := candidateRoutePath(rt, traversals)
			if len(path) != len(rt.Hops) {
				continue
			}

			score := candidateRouteUtility(
				rt, probability, shard, equal,
			)
			if score > bestScore {
				bestScore = score
				bestRoute = rt
				bestPath = path
			}
		}

		if bestRoute == nil {
			return nil, false
		}

		shard := candidateDeliveredAmount(bestRoute)
		plan = append(plan, candidatePlanPart{
			amt:  shard,
			path: bestPath,
		})

		for _, traversal := range r.routeTraversals(bestRoute) {
			r.reserved[traversal.key] += traversal.amt
		}

		remaining -= shard
	}

	if remaining != 0 {
		return nil, false
	}
	return plan, true
}

func (r *candidateRouter) makePlan(amt lnwire.MilliSatoshi,
	inFlight uint32) {

	desired := r.desiredPlanParts(inFlight)
	if desired == 0 {
		return
	}

	for parts := desired; parts >= 1; parts-- {
		plan, ok := r.tryPlan(amt, parts)
		if ok {
			r.plan = plan
			r.planIndex = 0
			return
		}
		if parts == 1 {
			break
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum parts already in flight")
	}

	r.requestNo++
	r.searchSalt = r.requestNo*0x9e3779b97f4a7c15 +
		uint64(r.failures)*0xbf58476d1ce4e5b9

	if r.plan == nil {
		r.makePlan(amt, inFlightHtlcs)
	}
	if r.planIndex < len(r.plan) {
		part := r.plan[r.planIndex]
		if part.amt > 0 && part.amt <= amt {
			rt, err := r.buildRoute(part.amt, part.path)
			if err == nil {
				r.pendingPlan = true
				return rt, nil
			}
		}
		r.plan = nil
		r.planIndex = 0
	}

	partsLeft := maxParts - inFlightHtlcs
	if partsLeft == 1 {
		return r.findRouteOnly(amt)
	}

	equal := candidateCeilDiv(amt, partsLeft)
	amounts := make([]lnwire.MilliSatoshi, 0, 8)

	if r.retryCap > 0 {
		amounts = candidateAppendAmount(
			amounts, r.retryCap*3/4, amt,
		)
		amounts = candidateAppendAmount(
			amounts, r.retryCap, amt,
		)
		amounts = candidateAppendAmount(
			amounts, r.retryCap*5/4, amt,
		)
	}

	amounts = candidateAppendAmount(amounts, equal/2, amt)
	amounts = candidateAppendAmount(amounts, equal, amt)
	amounts = candidateAppendAmount(amounts, equal*5/4, amt)
	amounts = candidateAppendAmount(amounts, equal*3/2, amt)
	amounts = candidateAppendAmount(amounts, amt, amt)

	var bestRoute *route.Route
	bestScore := math.Inf(-1)
	var lastErr error

	for _, shard := range amounts {
		rt, probability, err := r.findRoute(shard)
		if err != nil {
			lastErr = err
			continue
		}

		score := candidateRouteUtility(
			rt, probability, shard, equal,
		)

		if shard < equal {
			debt := float64(equal-shard) / float64(equal)
			score -= 0.16 * debt
		}

		if score > bestScore {
			bestScore = score
			bestRoute = rt
		}
	}

	if bestRoute != nil {
		r.pendingPlan = false
		return bestRoute, nil
	}
	if lastErr != nil {
		return nil, lastErr
	}
	return nil, errors.New("no route found")
}

func (r *candidateRouter) findRouteOnly(
	amt lnwire.MilliSatoshi) (*route.Route, error) {

	rt, _, err := r.findRoute(amt)
	if err != nil {
		return nil, err
	}
	r.pendingPlan = false
	return rt, nil
}

func (r *candidateRouter) routeTraversals(
	rt *route.Route) []candidateTraversal {

	traversals := make([]candidateTraversal, 0, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		key := candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		edge := r.edges[key]
		if edge == nil {
			from = hop.PubKeyBytes
			continue
		}

		amt := rt.TotalAmount
		if i > 0 {
			amt = rt.Hops[i-1].AmtToForward
		}

		traversals = append(traversals, candidateTraversal{
			key:  key,
			edge: edge,
			amt:  amt,
		})
		from = hop.PubKeyBytes
	}

	return traversals
}

func (r *candidateRouter) recordSuccess(rt *route.Route) {
	traversals := r.routeTraversals(rt)

	candidateBeliefStore.Lock()
	for _, traversal := range traversals {
		required := traversal.amt + r.reserved[traversal.key]
		belief := candidateBeliefStore.beliefs[traversal.key]
		if belief == nil {
			belief = &candidateBelief{}
			candidateBeliefStore.beliefs[traversal.key] = belief
		}

		if required > belief.lowerOK {
			belief.lowerOK = required
		}

		estimate := traversal.edge.capacity * 92 / 100
		if required > estimate {
			estimate = required
		}
		if estimate > belief.estimate {
			belief.estimate = estimate
		}
		if belief.conf < 8 {
			belief.conf++
		}

		if belief.upperFail > 0 && required >= belief.upperFail {
			belief.upperFail = 0
		}
		if belief.suspectAmt > 0 && required >= belief.suspectAmt {
			belief.suspectAmt = 0
			belief.suspectVotes = 0
		}
	}
	candidateBeliefStore.Unlock()

	for _, traversal := range traversals {
		required := traversal.amt + r.reserved[traversal.key]
		if local, ok := r.localFails[traversal.key]; ok &&
			required >= local.upper {

			delete(r.localFails, traversal.key)
		}

		r.diversion[traversal.key] *= 0.20
		r.policyFails[traversal.key] = 0
		r.reserved[traversal.key] += traversal.amt
		r.usedTotals[traversal.key] += traversal.amt
	}

	r.delivered += candidateDeliveredAmount(rt)
	if r.delivered >= r.spec.Amount && !r.settled {
		r.recordSettlement()
		r.settled = true
	}
}

func (r *candidateRouter) recordSettlement() {
	candidateBeliefStore.Lock()
	defer candidateBeliefStore.Unlock()

	for key, used := range r.usedTotals {
		if used <= 0 {
			continue
		}

		if belief := candidateBeliefStore.beliefs[key]; belief != nil {
			if belief.lowerOK > used {
				belief.lowerOK -= used
			} else {
				belief.lowerOK = 0
			}
			if belief.estimate > used {
				belief.estimate -= used
			} else {
				belief.estimate = 0
			}
			if belief.upperFail > used {
				belief.upperFail -= used
			} else {
				belief.upperFail = 0
			}
			if belief.suspectAmt > used {
				belief.suspectAmt -= used
			} else {
				belief.suspectAmt = 0
				belief.suspectVotes = 0
			}
		}

		reverse := candidateEdgeKey{
			chanID: key.chanID,
			from:   key.to,
			to:     key.from,
		}
		reverseBelief := candidateBeliefStore.beliefs[reverse]
		if reverseBelief == nil {
			reverseBelief = &candidateBelief{}
			candidateBeliefStore.beliefs[reverse] = reverseBelief
		}

		capacity := lnwire.MilliSatoshi(0)
		if edge := r.edges[reverse]; edge != nil {
			capacity = edge.capacity
		} else if edge := r.edges[key]; edge != nil {
			capacity = edge.capacity
		}

		reverseBelief.lowerOK += used
		reverseBelief.estimate += used
		if capacity > 0 {
			if reverseBelief.lowerOK > capacity {
				reverseBelief.lowerOK = capacity
			}
			if reverseBelief.estimate > capacity {
				reverseBelief.estimate = capacity
			}
		}

		if reverseBelief.upperFail > 0 {
			reverseBelief.upperFail += used
			if capacity > 0 &&
				reverseBelief.upperFail > capacity {

				reverseBelief.upperFail = capacity
			}
		}
	}
}

func (r *candidateRouter) failureIndex(rt *route.Route,
	source route.Vertex, traversals []candidateTraversal) (int, bool) {

	if len(traversals) != len(rt.Hops) {
		return 0, false
	}

	if source == rt.SourcePubKey {
		return 0, len(traversals) > 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes != source {
			continue
		}

		index := i + 1
		if index >= len(traversals) {
			return 0, false
		}
		return index, true
	}

	return 0, false
}

func (r *candidateRouter) addDiversion(
	key candidateEdgeKey, amount float64) {

	r.diversion[key] += amount
	if r.diversion[key] > 7.0 {
		r.diversion[key] = 7.0
	}
}

func (r *candidateRouter) recordAttributedLiquidityFailure(
	traversals []candidateTraversal, index int) {

	traversal := traversals[index]
	required := traversal.amt + r.reserved[traversal.key]

	r.addDiversion(traversal.key, 1.05)
	if index > 0 {
		r.addDiversion(traversals[index-1].key, 0.14)
	}
	if index+1 < len(traversals) {
		r.addDiversion(traversals[index+1].key, 0.14)
	}

	if traversal.key.from == r.source {
		return
	}

	local := r.localFails[traversal.key]
	if local.upper == 0 || required < local.upper {
		local.upper = required
	}
	if local.count < 255 {
		local.count++
	}
	r.localFails[traversal.key] = local

	candidateBeliefStore.Lock()
	defer candidateBeliefStore.Unlock()

	belief := candidateBeliefStore.beliefs[traversal.key]
	if belief == nil {
		belief = &candidateBelief{}
		candidateBeliefStore.beliefs[traversal.key] = belief
	}

	if belief.suspectVotes == 0 {
		belief.suspectAmt = required
		belief.suspectVotes = 1
		return
	}

	if required < belief.suspectAmt {
		belief.suspectAmt = required
	}
	if belief.suspectVotes < 255 {
		belief.suspectVotes++
	}

	votesNeeded := uint8(2)
	if belief.lowerOK > 0 &&
		belief.suspectAmt <= belief.lowerOK {

		votesNeeded = 3
	}
	if belief.suspectVotes < votesNeeded {
		return
	}

	if belief.lowerOK > 0 &&
		belief.suspectAmt <= belief.lowerOK {

		if belief.suspectAmt > 1 {
			belief.lowerOK = belief.suspectAmt - 1
		} else {
			belief.lowerOK = 0
		}
	}

	if belief.upperFail == 0 ||
		belief.suspectAmt < belief.upperFail {

		belief.upperFail = belief.suspectAmt
	}

	failedEstimate := belief.suspectAmt * 60 / 100
	if belief.estimate == 0 || failedEstimate < belief.estimate {
		belief.estimate = failedEstimate
	}
	if belief.conf < 8 {
		belief.conf++
	}
}

func (r *candidateRouter) diversifyUnknown(
	traversals []candidateTraversal) {

	if len(traversals) == 0 {
		return
	}

	index := int((r.requestNo +
		uint64(r.unknownFails)*0x9e3779b97f4a7c15) %
		uint64(len(traversals)))

	r.addDiversion(traversals[index].key, 0.85)

	if r.unknownFails%12 == 0 {
		for key, penalty := range r.diversion {
			penalty *= 0.35
			if penalty < 0.01 {
				delete(r.diversion, key)
			} else {
				r.diversion[key] = penalty
			}
		}
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64,
	rt *route.Route, result routing.SimHtlcResult) error {

	wasPlanned := r.pendingPlan
	r.pendingPlan = false

	if result.Failure == nil {
		r.retryCap = 0
		r.recordSuccess(rt)
		if wasPlanned {
			r.planIndex++
		}
		return nil
	}

	if wasPlanned {
		r.plan = nil
		r.planIndex = 0
	}

	r.failures++
	traversals := r.routeTraversals(rt)
	code := result.Failure.Code()

	if code == lnwire.CodeTemporaryChannelFailure {
		if index, ok := r.failureIndex(
			rt, result.FailureSource, traversals,
		); ok {
			r.recordAttributedLiquidityFailure(
				traversals, index,
			)

			delivered := candidateDeliveredAmount(rt)
			if delivered > 1 {
				factor := lnwire.MilliSatoshi(62)
				local := r.localFails[
					traversals[index].key]
				if local.count >= 2 {
					factor = 50
				}
				r.retryCap = delivered * factor / 100
			}
			return nil
		}
	}

	r.unknownFails++

	if code == lnwire.CodeFeeInsufficient ||
		code == lnwire.CodeIncorrectCltvExpiry {

		if index, ok := r.failureIndex(
			rt, result.FailureSource, traversals,
		); ok {
			key := traversals[index].key
			count := r.policyFails[key]
			if count < 255 {
				count++
			}
			r.policyFails[key] = count

			if count >= 2 {
				r.addDiversion(key, 4.0)
			} else {
				r.addDiversion(key, 1.5)
			}
			return nil
		}
	}

	r.diversifyUnknown(traversals)
	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	conf      uint8

	suspectAmt   lnwire.MilliSatoshi
	suspectVotes uint8
}

var candidateBeliefStore = struct {
	sync.Mutex
	beliefs map[candidateEdgeKey]*candidateBelief
}{
	beliefs: make(map[candidateEdgeKey]*candidateBelief),
}

type candidateLocalFailure struct {
	upper lnwire.MilliSatoshi
	count uint8
}

type candidateTraversal struct {
	key  candidateEdgeKey
	edge *candidateEdge
	amt  lnwire.MilliSatoshi
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	reserved    map[candidateEdgeKey]lnwire.MilliSatoshi
	usedTotals  map[candidateEdgeKey]lnwire.MilliSatoshi
	localFails  map[candidateEdgeKey]candidateLocalFailure
	edgePenalty map[candidateEdgeKey]float64

	plannedParts uint32
	failures     uint32
	unknownFails uint32
	retryCap     lnwire.MilliSatoshi
	delivered    lnwire.MilliSatoshi
	settled      bool
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[candidateEdgeKey]*candidateEdge),
		localBalances: localBalances,
		reserved:      make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		usedTotals:    make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		localFails:    make(map[candidateEdgeKey]candidateLocalFailure),
		edgePenalty:   make(map[candidateEdgeKey]float64),
	}

	r.plannedParts = r.initialPartCount(spec.Amount)
	if spec.MaxParts != 0 && r.plannedParts > spec.MaxParts {
		r.plannedParts = spec.MaxParts
	}
	if r.plannedParts == 0 {
		r.plannedParts = 1
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[key] = edge

				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func (r *candidateRouter) initialPartCount(
	amt lnwire.MilliSatoshi) uint32 {

	switch {
	case amt <= 25_000_000:
		return 1
	case amt <= 150_000_000:
		return 3
	case amt <= 500_000_000:
		return 4
	case amt <= 1_500_000_000:
		return 6
	case amt <= 3_000_000_000:
		return 8
	default:
		return 12
	}
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.003
	}

	x := float64(amt) / float64(capacity)

	lowMode := 0.48 * math.Exp(-x/0.025)
	highMode := 0.50 / (1 + math.Exp((x-0.90)/0.025))
	p := 0.005 + lowMode + highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func candidateLogisticProbability(amt, estimate,
	capacity lnwire.MilliSatoshi) float64 {

	if capacity <= 0 {
		return 0.005
	}

	scale := 0.06 * float64(capacity)
	if scale < 1 {
		scale = 1
	}

	z := (float64(amt) - float64(estimate)) / scale
	switch {
	case z > 30:
		return 0.005
	case z < -30:
		return 0.995
	default:
		return 1 / (1 + math.Exp(z))
	}
}

func (r *candidateRouter) edgeProbability(e *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	required := amt + r.reserved[e.key]
	if required > e.capacity {
		return 0.001
	}

	if e.key.from == r.source {
		if r.localBalances[e.key.chanID] < required {
			return 0.001
		}
		return 0.999
	}

	p := candidatePrior(required, e.capacity)

	candidateBeliefStore.Lock()
	stored, ok := candidateBeliefStore.beliefs[e.key]
	var belief candidateBelief
	if ok {
		belief = *stored
	}
	candidateBeliefStore.Unlock()

	if ok {
		if belief.estimate > 0 && belief.conf > 0 {
			estimated := candidateLogisticProbability(
				required, belief.estimate, e.capacity,
			)
			weight := 0.15 * float64(belief.conf)
			if weight > 0.75 {
				weight = 0.75
			}
			p = (1-weight)*p + weight*estimated
		}

		if belief.lowerOK > 0 && required <= belief.lowerOK {
			p = math.Max(p, 0.995)
		}

		if belief.upperFail > 0 {
			switch {
			case required >= belief.upperFail:
				p = math.Min(p, 0.008)

			case belief.lowerOK > 0 &&
				belief.upperFail > belief.lowerOK:

				span := float64(
					belief.upperFail - belief.lowerOK,
				)
				position := float64(
					required - belief.lowerOK,
				) / span
				if position > 0 {
					bounded := 0.995*(1-position) +
						0.008*position
					p = 0.30*p + 0.70*bounded
				}
			}
		}
	}

	if local, ok := r.localFails[e.key]; ok &&
		required >= local.upper {

		if local.count >= 2 {
			p = math.Min(p, 0.004)
		} else {
			p *= 0.07
		}
	}

	if p < 0.003 {
		return 0.003
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

func (r *candidateRouter) edgeCost(e *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	p := r.edgeProbability(e, amt)

	// Reliability and short paths dominate. Fees remain a secondary
	// objective and are added separately by the backward search.
	cost := -math.Log(p) + 0.07 + r.edgePenalty[e.key]

	// Held or previously settled shards should normally use separate
	// corridors. This is especially important for atomic MPP, where a
	// successful sibling still occupies real liquidity.
	if reserved := r.reserved[e.key]; reserved > 0 &&
		e.capacity > 0 {

		ratio := float64(reserved) / float64(e.capacity)
		cost += 1.75 + 1.50*ratio
	}

	return cost
}

type candidateDijkstraItem struct {
	node  route.Vertex
	score float64
	amt   lnwire.MilliSatoshi
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *candidateDijkstraQueue) Push(x any) {
	*q = append(*q, x.(*candidateDijkstraItem))
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]
	return item
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}

	score := make(map[route.Vertex]float64)
	arriving := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)

	score[r.spec.Target] = 0
	arriving[r.spec.Target] = amt

	queue := &candidateDijkstraQueue{}
	heap.Push(queue, &candidateDijkstraItem{
		node: r.spec.Target,
		amt:  amt,
	})

	for queue.Len() > 0 {
		item := heap.Pop(queue).(*candidateDijkstraItem)

		best, ok := score[item.node]
		if !ok || item.score > best+1e-12 {
			continue
		}
		if arriving[item.node] != item.amt {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOverEdge := item.amt
			if !edge.policyAllows(amtOverEdge) {
				continue
			}

			required := amtOverEdge + r.reserved[edge.key]
			if required > edge.capacity {
				continue
			}
			if edge.key.from == r.source &&
				r.localBalances[edge.key.chanID] < required {

				continue
			}

			sending := amtOverEdge
			feeCost := 0.0
			if edge.key.from != r.source {
				fee := edge.fee(amtOverEdge)
				sending += fee

				denominator := float64(amt)
				if denominator < 1 {
					denominator = 1
				}

				// Fees matter, but should not purchase a long,
				// low-reliability detour.
				feeCost = 5 * float64(fee) / denominator
			}

			newScore := item.score +
				r.edgeCost(edge, amtOverEdge) + feeCost

			oldScore, exists := score[edge.key.from]
			if exists && newScore >= oldScore {
				continue
			}

			score[edge.key.from] = newScore
			arriving[edge.key.from] = sending
			next[edge.key.from] = edge

			heap.Push(queue, &candidateDijkstraItem{
				node:  edge.key.from,
				score: newScore,
				amt:   sending,
			})
		}
	}

	if _, ok := score[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}

	pathProbability := 1.0
	for _, traversal := range r.routeTraversals(rt) {
		pathProbability *= r.edgeProbability(
			traversal.edge, traversal.amt,
		)
	}

	return rt, pathProbability, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	seen := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if seen[node] {
			return nil, errors.New("cycle in route")
		}
		seen[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)

		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateCeilDiv(amt lnwire.MilliSatoshi,
	parts uint32) lnwire.MilliSatoshi {

	if parts <= 1 {
		return amt
	}

	divisor := lnwire.MilliSatoshi(parts)
	return (amt + divisor - 1) / divisor
}

func candidateScaledAmount(amt lnwire.MilliSatoshi,
	numerator int64) lnwire.MilliSatoshi {

	if amt <= 0 || numerator <= 0 {
		return 0
	}
	return amt * lnwire.MilliSatoshi(numerator) / 100
}

func candidateAppendAmount(amounts []lnwire.MilliSatoshi,
	amt, limit lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if amt <= 0 {
		return amounts
	}
	if amt > limit {
		amt = limit
	}
	for _, existing := range amounts {
		if existing == amt {
			return amounts
		}
	}
	return append(amounts, amt)
}

func (r *candidateRouter) targetPartCount() uint32 {
	target := r.plannedParts

	// Spare part slots are opened after failures, but not so quickly
	// that a sequence of tiny probes consumes the entire MPP budget.
	target += r.failures / 2
	if r.unknownFails >= 3 {
		target++
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if target > maxParts {
		target = maxParts
	}
	if target == 0 {
		target = 1
	}

	return target
}

func (r *candidateRouter) routeUtility(rt *route.Route,
	pathProbability float64, shard,
	reference lnwire.MilliSatoshi) float64 {

	hops := len(rt.Hops)
	if hops == 0 || shard <= 0 {
		return math.Inf(-1)
	}

	if pathProbability < 1e-300 {
		pathProbability = 1e-300
	}

	// Compare candidate shard sizes by geometric path reliability. This
	// prevents long paths from looking artificially attractive while
	// still rewarding a shard that commits meaningful value.
	averageLogProbability := math.Log(pathProbability) / float64(hops)

	ref := float64(reference)
	if ref < 1 {
		ref = 1
	}
	sizeUtility := math.Log(float64(shard) / ref)

	delivered := candidateDeliveredAmount(rt)
	feePenalty := 0.0
	if delivered > 0 && rt.TotalAmount > delivered {
		feePenalty = 2 * float64(
			rt.TotalAmount-delivered,
		) / float64(delivered)
	}

	return 0.85*averageLogProbability +
		1.10*sizeUtility -
		0.025*float64(hops) -
		feePenalty
}

func (r *candidateRouter) selectShardRoute(
	amt lnwire.MilliSatoshi, inFlightHtlcs,
	partsLeft uint32) (*route.Route, error) {

	if partsLeft <= 1 {
		rt, _, err := r.findRoute(amt)
		return rt, err
	}

	targetParts := r.targetPartCount()
	desiredSlots := uint32(1)
	if targetParts > inFlightHtlcs {
		desiredSlots = targetParts - inFlightHtlcs
	}
	if desiredSlots > partsLeft {
		desiredSlots = partsLeft
	}

	reference := candidateCeilDiv(amt, desiredSlots)
	amounts := make([]lnwire.MilliSatoshi, 0, 8)

	if r.retryCap > 0 {
		capAmount := r.retryCap
		if capAmount > amt {
			capAmount = amt
		}

		// A liquidity failure changes the amount, not just the path.
		// Several sizes are compared because the bimodal prior often
		// makes either a much smaller shard or a new full corridor best.
		amounts = candidateAppendAmount(
			amounts, capAmount, amt,
		)
		amounts = candidateAppendAmount(
			amounts, candidateScaledAmount(capAmount, 78), amt,
		)
		amounts = candidateAppendAmount(
			amounts, candidateScaledAmount(capAmount, 58), amt,
		)
	} else {
		// Jointly choose the shard size and its route. Larger candidates
		// fill high-mode corridors efficiently; smaller candidates win
		// when they cross into the near-certain low-amount prior.
		amounts = candidateAppendAmount(
			amounts, candidateScaledAmount(reference, 145), amt,
		)
		amounts = candidateAppendAmount(
			amounts, candidateScaledAmount(reference, 120), amt,
		)
		amounts = candidateAppendAmount(
			amounts, reference, amt,
		)
		amounts = candidateAppendAmount(
			amounts, candidateScaledAmount(reference, 82), amt,
		)
		amounts = candidateAppendAmount(
			amounts, candidateScaledAmount(reference, 62), amt,
		)
	}

	var bestRoute *route.Route
	bestUtility := math.Inf(-1)
	var lastErr error

	for _, shard := range amounts {
		rt, probability, err := r.findRoute(shard)
		if err != nil {
			lastErr = err
			continue
		}

		utility := r.routeUtility(
			rt, probability, shard, reference,
		)
		if utility > bestUtility {
			bestUtility = utility
			bestRoute = rt
		}
	}

	if bestRoute != nil {
		return bestRoute, nil
	}

	// Structural constraints can make all planned sizes impossible.
	// Search downward without imposing the old amount/parts floor:
	// failed probes do not consume a part, and unequal shards are legal.
	shard := reference
	if r.retryCap > 0 && r.retryCap < shard {
		shard = r.retryCap
	}
	if shard > amt {
		shard = amt
	}

	for shard > 1 {
		rt, _, err := r.findRoute(shard)
		if err == nil {
			return rt, nil
		}
		lastErr = err

		next := shard * 2 / 3
		if next >= shard {
			next = shard - 1
		}
		shard = next
	}

	if lastErr == nil {
		lastErr = errors.New("no route found")
	}
	return nil, lastErr
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum parts already in flight")
	}

	partsLeft := maxParts - inFlightHtlcs

	// A one-part payment should not be converted into a probe ladder.
	if maxParts == 1 || r.plannedParts == 1 {
		rt, _, err := r.findRoute(amt)
		return rt, err
	}

	return r.selectShardRoute(amt, inFlightHtlcs, partsLeft)
}

func (r *candidateRouter) routeTraversals(
	rt *route.Route) []candidateTraversal {

	traversals := make([]candidateTraversal, 0, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		key := candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		edge := r.edges[key]
		if edge == nil {
			from = hop.PubKeyBytes
			continue
		}

		amt := rt.TotalAmount
		if i > 0 {
			amt = rt.Hops[i-1].AmtToForward
		}

		traversals = append(traversals, candidateTraversal{
			key:  key,
			edge: edge,
			amt:  amt,
		})
		from = hop.PubKeyBytes
	}

	return traversals
}

func candidateDeliveredAmount(rt *route.Route) lnwire.MilliSatoshi {
	if len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func (r *candidateRouter) recordSuccess(rt *route.Route) {
	traversals := r.routeTraversals(rt)

	candidateBeliefStore.Lock()
	for _, traversal := range traversals {
		required := traversal.amt + r.reserved[traversal.key]

		belief := candidateBeliefStore.beliefs[traversal.key]
		if belief == nil {
			belief = &candidateBelief{}
			candidateBeliefStore.beliefs[traversal.key] = belief
		}

		if required > belief.lowerOK {
			belief.lowerOK = required
		}

		highEstimate := traversal.edge.capacity * 88 / 100
		if required > highEstimate {
			highEstimate = required
		}
		if highEstimate > belief.estimate {
			belief.estimate = highEstimate
		}
		if belief.conf < 8 {
			belief.conf++
		}

		// Success is truthful and therefore overrides conflicting,
		// potentially shifted failure attribution.
		if belief.upperFail > 0 &&
			required >= belief.upperFail {

			belief.upperFail = 0
		}
		if belief.suspectAmt > 0 &&
			required >= belief.suspectAmt {

			belief.suspectAmt = 0
			belief.suspectVotes = 0
		}
	}
	candidateBeliefStore.Unlock()

	for _, traversal := range traversals {
		required := traversal.amt + r.reserved[traversal.key]

		if local, ok := r.localFails[traversal.key]; ok &&
			required >= local.upper {

			delete(r.localFails, traversal.key)
		}

		r.reserved[traversal.key] += traversal.amt
		r.usedTotals[traversal.key] += traversal.amt
	}

	r.delivered += candidateDeliveredAmount(rt)
	if r.delivered >= r.spec.Amount && !r.settled {
		r.recordSettlement()
		r.settled = true
	}
}

func (r *candidateRouter) recordSettlement() {
	candidateBeliefStore.Lock()
	defer candidateBeliefStore.Unlock()

	for key, used := range r.usedTotals {
		if used <= 0 {
			continue
		}

		if belief := candidateBeliefStore.beliefs[key]; belief != nil {
			if belief.lowerOK > used {
				belief.lowerOK -= used
			} else {
				belief.lowerOK = 0
			}

			if belief.estimate > used {
				belief.estimate -= used
			} else {
				belief.estimate = 0
			}

			if belief.upperFail > used {
				belief.upperFail -= used
			} else {
				belief.upperFail = 0
			}

			if belief.suspectAmt > used {
				belief.suspectAmt -= used
			} else {
				belief.suspectAmt = 0
				belief.suspectVotes = 0
			}
		}

		reverse := candidateEdgeKey{
			chanID: key.chanID,
			from:   key.to,
			to:     key.from,
		}

		reverseBelief := candidateBeliefStore.beliefs[reverse]
		if reverseBelief == nil {
			reverseBelief = &candidateBelief{}
			candidateBeliefStore.beliefs[reverse] = reverseBelief
		}

		reverseCapacity := lnwire.MilliSatoshi(0)
		if edge := r.edges[reverse]; edge != nil {
			reverseCapacity = edge.capacity
		} else if edge := r.edges[key]; edge != nil {
			reverseCapacity = edge.capacity
		}

		reverseBelief.lowerOK += used
		reverseBelief.estimate += used

		if reverseCapacity > 0 {
			if reverseBelief.lowerOK > reverseCapacity {
				reverseBelief.lowerOK = reverseCapacity
			}
			if reverseBelief.estimate > reverseCapacity {
				reverseBelief.estimate = reverseCapacity
			}
		}

		if reverseBelief.upperFail > 0 {
			reverseBelief.upperFail += used
			if reverseCapacity > 0 &&
				reverseBelief.upperFail > reverseCapacity {

				reverseBelief.upperFail = reverseCapacity
			}
		}
	}
}

func (r *candidateRouter) failureEdge(rt *route.Route,
	source route.Vertex) (candidateTraversal, bool) {

	traversals := r.routeTraversals(rt)
	if len(traversals) != len(rt.Hops) {
		return candidateTraversal{}, false
	}

	index := -1
	if source == rt.SourcePubKey {
		index = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == source {
				index = i + 1
				break
			}
		}
	}

	if index < 0 || index >= len(traversals) {
		return candidateTraversal{}, false
	}

	return traversals[index], true
}

func (r *candidateRouter) recordAttributedLiquidityFailure(
	traversal candidateTraversal) uint8 {

	required := traversal.amt + r.reserved[traversal.key]

	local := r.localFails[traversal.key]
	if local.upper == 0 || required < local.upper {
		local.upper = required
	}
	if local.count < 255 {
		local.count++
	}
	r.localFails[traversal.key] = local

	r.edgePenalty[traversal.key] += 1.8

	// Exact source balances are more trustworthy than remote blame.
	if traversal.key.from == r.source {
		return local.count
	}

	candidateBeliefStore.Lock()
	defer candidateBeliefStore.Unlock()

	belief := candidateBeliefStore.beliefs[traversal.key]
	if belief == nil {
		belief = &candidateBelief{}
		candidateBeliefStore.beliefs[traversal.key] = belief
	}

	if belief.suspectVotes == 0 {
		belief.suspectAmt = required
		belief.suspectVotes = 1
		return local.count
	}

	if belief.suspectAmt == 0 || required < belief.suspectAmt {
		belief.suspectAmt = required
	}
	if belief.suspectVotes < 255 {
		belief.suspectVotes++
	}

	// A single plausible attribution only changes this payment's route.
	// Persistent bounds require corroboration because blame can shift to
	// an adjacent node.
	if belief.suspectVotes >= 2 {
		if belief.upperFail == 0 ||
			belief.suspectAmt < belief.upperFail {

			belief.upperFail = belief.suspectAmt
		}

		failedEstimate := belief.suspectAmt * 68 / 100
		if belief.estimate == 0 ||
			failedEstimate < belief.estimate {

			belief.estimate = failedEstimate
		}
		if belief.conf < 8 {
			belief.conf++
		}
	}

	return local.count
}

func (r *candidateRouter) ReportAttempt(attemptID uint64,
	rt *route.Route, result routing.SimHtlcResult) error {

	if result.Failure == nil {
		r.retryCap = 0
		r.recordSuccess(rt)
		return nil
	}

	r.failures++

	traversals := r.routeTraversals(rt)
	for _, traversal := range traversals {
		r.edgePenalty[traversal.key] += 0.08
	}

	delivered := candidateDeliveredAmount(rt)
	code := result.Failure.Code()

	if code == lnwire.CodeTemporaryChannelFailure {
		if traversal, ok := r.failureEdge(
			rt, result.FailureSource,
		); ok {
			count := r.recordAttributedLiquidityFailure(
				traversal,
			)

			if delivered > 1 {
				factor := int64(64)
				if count >= 2 {
					factor = 54
				}
				r.retryCap = candidateScaledAmount(
					delivered, factor,
				)
			}
			return nil
		}
	}

	// Off-route sources explicitly carry no channel information. Only
	// ephemeral route-diversification penalties are written.
	r.unknownFails++
	for _, traversal := range traversals {
		r.edgePenalty[traversal.key] += 0.28
	}

	if code == lnwire.CodeFeeInsufficient ||
		code == lnwire.CodeIncorrectCltvExpiry {

		if traversal, ok := r.failureEdge(
			rt, result.FailureSource,
		); ok {
			r.edgePenalty[traversal.key] += 2.4
		}
	}

	if r.unknownFails%2 == 0 && delivered > 1 {
		r.retryCap = candidateScaledAmount(delivered, 70)
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40
	riskCostMsat   = 100000.0
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

// Beliefs intentionally outlive a router instance. The simulator creates a
// new router for each payment, while channel liquidity persists across a
// scenario batch.
type candidateBelief struct {
	lowerOK lnwire.MilliSatoshi

	// upperFail is installed only after repeated attribution to the same
	// directed edge. This avoids turning one shifted failure into a hard
	// and persistent false bound.
	upperFail lnwire.MilliSatoshi

	suspectAmt   lnwire.MilliSatoshi
	suspectCount uint8
}

var candidateBeliefs = struct {
	sync.RWMutex
	m map[candidateEdgeKey]candidateBelief
}{
	m: make(map[candidateEdgeKey]candidateBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	// used is liquidity already consumed or held by successful sibling
	// shards. Evaluating the aggregate amount prevents atomic MPP shards
	// from repeatedly leaning on the same corridor.
	used map[candidateEdgeKey]lnwire.MilliSatoshi

	// Per-payment evidence is deliberately softer than persistent belief.
	// Any failure diversifies the next route, while an attributed liquidity
	// failure discourages only amounts at or above the observed ceiling.
	penalty  map[candidateEdgeKey]float64
	failCeil map[candidateEdgeKey]lnwire.MilliSatoshi

	successfulParts uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		localBalances: make(map[uint64]lnwire.MilliSatoshi),
		used:          make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		penalty:       make(map[candidateEdgeKey]float64),
		failCeil:      make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}
	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: policy.FeeBaseMSat,
					feeRatePPM: policy.
						FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func clampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005
	case p > 0.995:
		return 0.995
	default:
		return p
	}
}

// bimodalPrior models a channel as usually being almost full or almost
// empty in a particular direction. Tiny transfers can succeed in either
// mode, while larger transfers increasingly require the high-liquidity
// mode.
func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.025)
	highMode := 1 / (1 + math.Exp((x-0.91)/0.035))

	return clampProbability(0.5*lowMode + 0.5*highMode)
}

func edgeBeliefProbability(key candidateEdgeKey,
	amt, capacity lnwire.MilliSatoshi) float64 {

	prior := bimodalPrior(amt, capacity)

	candidateBeliefs.RLock()
	belief, ok := candidateBeliefs.m[key]
	candidateBeliefs.RUnlock()
	if !ok {
		return prior
	}

	if belief.lowerOK > 0 && amt <= belief.lowerOK {
		return 0.995
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		return 0.006
	}

	p := prior
	if belief.lowerOK > 0 {
		excess := amt - belief.lowerOK
		if excess < 0 {
			excess = 0
		}
		scale := math.Max(float64(capacity)*0.25, 1)
		successTail := 0.93 * math.Exp(-float64(excess)/scale)
		if successTail > p {
			p = successTail
		}
	}

	if belief.lowerOK > 0 && belief.upperFail > belief.lowerOK {
		span := float64(belief.upperFail - belief.lowerOK)
		pos := float64(amt-belief.lowerOK) / span
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}
		bounded := 0.985 - 0.965*pos
		p = 0.65*bounded + 0.35*prior
	}

	if belief.suspectCount == 1 &&
		belief.suspectAmt > 0 &&
		amt >= belief.suspectAmt {

		p *= 0.55
	}

	return clampProbability(p)
}

func recordCandidateSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	candidateBeliefs.Lock()
	defer candidateBeliefs.Unlock()

	belief := candidateBeliefs.m[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}

	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}
	if belief.suspectAmt > 0 && amt >= belief.suspectAmt {
		belief.suspectAmt = 0
		belief.suspectCount = 0
	}

	candidateBeliefs.m[key] = belief
}

func recordCandidateFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	candidateBeliefs.Lock()
	defer candidateBeliefs.Unlock()

	belief := candidateBeliefs.m[key]

	if belief.suspectCount == 0 {
		belief.suspectAmt = amt
		belief.suspectCount = 1
		candidateBeliefs.m[key] = belief
		return
	}

	if amt < belief.suspectAmt || belief.suspectAmt == 0 {
		belief.suspectAmt = amt
	}
	if belief.suspectCount < 255 {
		belief.suspectCount++
	}

	if belief.suspectCount >= 2 {
		if belief.upperFail == 0 ||
			belief.suspectAmt < belief.upperFail {

			belief.upperFail = belief.suspectAmt
		}
	}

	candidateBeliefs.m[key] = belief
}

type candidateQueueItem struct {
	node    route.Vertex
	amount  lnwire.MilliSatoshi
	score   float64
	quality float64
	index   int
}

type candidateQueue []*candidateQueueItem

func (q candidateQueue) Len() int {
	return len(q)
}

func (q candidateQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index = i
	q[j].index = j
}

func (q *candidateQueue) Push(x any) {
	item := x.(*candidateQueueItem)
	item.index = len(*q)
	*q = append(*q, item)
}

func (q *candidateQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]
	return item
}

type candidateRoutePlan struct {
	route   *route.Route
	quality float64
	fee     lnwire.MilliSatoshi
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) (float64, bool) {

	aggregate := amt + r.used[edge.key]
	if aggregate > edge.capacity {
		return 0, false
	}

	if edge.key.from == r.source {
		balance := r.localBalances[edge.key.chanID]
		if aggregate > balance {
			return 0, false
		}
		return 0.995, true
	}

	return edgeBeliefProbability(
		edge.key, aggregate, edge.capacity,
	), true
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*candidateRoutePlan, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}

	best := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)

	best[r.spec.Target] = 0
	pq := &candidateQueue{}
	heap.Push(pq, &candidateQueueItem{
		node:   r.spec.Target,
		amount: amt,
	})

	var sourceQuality float64
	found := false

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateQueueItem)
		currentBest, ok := best[item.node]
		if !ok || item.score > currentBest+0.000001 {
			continue
		}

		if item.node == r.source {
			sourceQuality = item.quality
			found = true
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOver := item.amount
			if !edge.usable(amtOver) {
				continue
			}

			probability, usable := r.edgeProbability(edge, amtOver)
			if !usable {
				continue
			}

			aggregate := amtOver + r.used[edge.key]
			localPenalty := r.penalty[edge.key]
			if ceiling := r.failCeil[edge.key]; ceiling > 0 &&
				aggregate >= ceiling {

				localPenalty += 2.0
			}

			// Reusing a corridor is allowed when it plausibly has room,
			// but increasingly expensive. This naturally produces
			// disjoint atomic-MPP route sets when alternatives exist.
			if edge.capacity > 0 && r.used[edge.key] > 0 {
				localPenalty += 1.2 *
					float64(r.used[edge.key]) /
					float64(edge.capacity)
			}

			fee := lnwire.MilliSatoshi(0)
			sending := amtOver
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
				sending += fee
			}

			logProbability := math.Log(
				clampProbability(probability),
			)
			edgeRisk := -logProbability + localPenalty
			score := item.score + float64(fee) +
				riskCostMsat*edgeRisk
			quality := item.quality + logProbability -
				localPenalty

			old, exists := best[edge.key.from]
			if exists && score >= old {
				continue
			}

			best[edge.key.from] = score
			next[edge.key.from] = edge
			heap.Push(pq, &candidateQueueItem{
				node:    edge.key.from,
				amount:  sending,
				score:   score,
				quality: quality,
			})
		}
	}

	if !found {
		return nil, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, err
	}

	return &candidateRoutePlan{
		route:   rt,
		quality: sourceQuality,
		fee:     rt.TotalAmount - amt,
	}, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))

	last := len(path) - 1
	amounts[last] = amt
	expiries[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amounts[i] = amounts[i+1] +
			forwardingEdge.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func appendCandidateAmount(amounts []lnwire.MilliSatoshi,
	amt, limit, minimum lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if amt < minimum {
		amt = minimum
	}
	if amt > limit {
		amt = limit
	}
	if amt <= 0 {
		return amounts
	}

	for _, existing := range amounts {
		if existing == amt {
			return amounts
		}
	}
	return append(amounts, amt)
}

// RequestRoute jointly considers several feasible shard sizes. It chooses
// the amount and route together instead of discovering every split through
// a ladder of failed full-size probes.
func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid payment remainder")
	}

	partsUsed := r.successfulParts
	if inFlightHtlcs > partsUsed {
		partsUsed = inFlightHtlcs
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if partsUsed >= maxParts {
		return nil, errors.New("maximum number of parts reached")
	}

	partsLeft := maxParts - partsUsed
	if partsLeft == 1 {
		plan, err := r.findRoute(amt)
		if err != nil {
			return nil, err
		}
		return plan.route, nil
	}

	minimum := (amt + lnwire.MilliSatoshi(partsLeft) - 1) /
		lnwire.MilliSatoshi(partsLeft)

	amounts := make([]lnwire.MilliSatoshi, 0, 12)
	amounts = appendCandidateAmount(amounts, amt, amt, minimum)

	divisorLimit := partsLeft
	if divisorLimit > 8 {
		divisorLimit = 8
	}
	for divisor := uint32(2); divisor <= divisorLimit; divisor++ {
		shard := (amt + lnwire.MilliSatoshi(divisor) - 1) /
			lnwire.MilliSatoshi(divisor)
		amounts = appendCandidateAmount(
			amounts, shard, amt, minimum,
		)
	}

	amounts = appendCandidateAmount(
		amounts, minimum, amt, minimum,
	)
	amounts = appendCandidateAmount(
		amounts, minimum+minimum/2, amt, minimum,
	)
	amounts = appendCandidateAmount(
		amounts, minimum*2, amt, minimum,
	)

	var bestPlan *candidateRoutePlan
	bestUtility := math.Inf(-1)

	for _, shard := range amounts {
		plan, err := r.findRoute(shard)
		if err != nil {
			continue
		}

		// The amount term favors committing useful liquidity quickly.
		// Total path probability favors shards that avoid the bimodal
		// cliff. Fees remain a secondary tie breaker.
		feeRatio := float64(plan.fee) /
			math.Max(float64(shard), 1)
		utility := math.Log(float64(shard)) +
			0.55*plan.quality - 20*feeRatio

		if bestPlan == nil || utility > bestUtility ||
			(utility == bestUtility &&
				shard > bestPlan.route.Hops[
					len(bestPlan.route.Hops)-1].AmtToForward) {

			bestPlan = plan
			bestUtility = utility
		}
	}

	if bestPlan == nil {
		return nil, errors.New("no route found")
	}

	return bestPlan.route, nil
}

type candidateRouteEdge struct {
	key candidateEdgeKey
	amt lnwire.MilliSatoshi
}

func routeEdges(rt *route.Route) []candidateRouteEdge {
	edges := make([]candidateRouteEdge, 0, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		amtOver := rt.TotalAmount
		if i > 0 {
			amtOver = rt.Hops[i-1].AmtToForward
		}

		edges = append(edges, candidateRouteEdge{
			key: candidateEdgeKey{
				chanID: hop.ChannelID,
				from:   from,
				to:     hop.PubKeyBytes,
			},
			amt: amtOver,
		})
		from = hop.PubKeyBytes
	}

	return edges
}

func failureEdgeIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	edges := routeEdges(rt)

	if result.Failure == nil {
		for _, edge := range edges {
			aggregate := edge.amt + r.used[edge.key]
			recordCandidateSuccess(edge.key, aggregate)
			r.used[edge.key] = aggregate
		}
		r.successfulParts++
		return nil
	}

	// A route-wide, payment-local penalty extracts the only trustworthy
	// fact from an unreadable failure: this exact corridor just failed.
	// It does not contaminate persistent liquidity beliefs.
	for _, edge := range edges {
		r.penalty[edge.key] += 0.16
	}

	failIdx := failureEdgeIndex(rt, result.FailureSource)
	if failIdx < 0 || failIdx >= len(edges) {
		return nil
	}

	// Policy errors should cause route diversification, but they are not
	// evidence about hidden liquidity.
	if result.Failure.Code() !=
		lnwire.CodeTemporaryChannelFailure {

		r.penalty[edges[failIdx].key] += 0.8
		return nil
	}

	failedEdge := edges[failIdx]
	aggregate := failedEdge.amt + r.used[failedEdge.key]

	oldCeiling := r.failCeil[failedEdge.key]
	if oldCeiling == 0 || aggregate < oldCeiling {
		r.failCeil[failedEdge.key] = aggregate
	}

	// Persistent hard evidence requires corroboration. A first report is
	// only a soft suspicion because otherwise a shifted source can poison
	// future payments.
	recordCandidateFailure(failedEdge.key, aggregate)

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(
	amt lnwire.MilliSatoshi) bool {

	if amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	conf      uint8

	suspectAmt    lnwire.MilliSatoshi
	suspectWeight float64
}

var candidateBeliefStore = struct {
	sync.Mutex
	beliefs map[candidateEdgeKey]*candidateBelief
}{
	beliefs: make(map[candidateEdgeKey]*candidateBelief),
}

type candidateLocalFailure struct {
	upper  lnwire.MilliSatoshi
	weight float64
}

type candidateTraversal struct {
	key  candidateEdgeKey
	edge *candidateEdge
	amt  lnwire.MilliSatoshi
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	reserved    map[candidateEdgeKey]lnwire.MilliSatoshi
	usedTotals  map[candidateEdgeKey]lnwire.MilliSatoshi
	localFails  map[candidateEdgeKey]candidateLocalFailure
	edgePenalty map[candidateEdgeKey]float64

	plannedParts   uint32
	failures       uint32
	unknownFails   uint32
	successfulParts uint32
	retryCap       lnwire.MilliSatoshi
	delivered      lnwire.MilliSatoshi
	settled        bool
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[candidateEdgeKey]*candidateEdge),
		localBalances: localBalances,
		reserved:      make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		usedTotals:    make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		localFails:    make(map[candidateEdgeKey]candidateLocalFailure),
		edgePenalty:   make(map[candidateEdgeKey]float64),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[key] = edge

				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.plannedParts = r.initialPartCount(spec.Amount)
	if spec.MaxParts != 0 && r.plannedParts > spec.MaxParts {
		r.plannedParts = spec.MaxParts
	}
	if r.plannedParts == 0 {
		r.plannedParts = 1
	}

	return r, nil
}

func (r *candidateRouter) initialPartCount(
	amt lnwire.MilliSatoshi) uint32 {

	switch {
	case amt <= 20_000_000:
		return 1

	case amt <= 75_000_000:
		return 3

	case amt <= 200_000_000:
		return 5

	case amt <= 400_000_000:
		return 8

	case amt <= 900_000_000:
		return 10

	case amt <= 2_000_000_000:
		return 12

	default:
		return 16
	}
}

func candidatePrior(amt,
	capacity lnwire.MilliSatoshi) float64 {

	if capacity <= 0 || amt > capacity {
		return 0.003
	}

	x := float64(amt) / float64(capacity)

	lowMode := 0.48 * math.Exp(-x/0.025)
	highMode := 0.50 / (1 + math.Exp((x-0.90)/0.025))
	p := 0.005 + lowMode + highMode

	switch {
	case p < 0.005:
		return 0.005

	case p > 0.985:
		return 0.985

	default:
		return p
	}
}

func candidateLogisticProbability(amt, estimate,
	capacity lnwire.MilliSatoshi) float64 {

	if capacity <= 0 {
		return 0.005
	}

	scale := 0.065 * float64(capacity)
	if scale < 1 {
		scale = 1
	}

	z := (float64(amt) - float64(estimate)) / scale
	switch {
	case z > 30:
		return 0.005

	case z < -30:
		return 0.995

	default:
		return 1 / (1 + math.Exp(z))
	}
}

func candidateClampProbability(p float64) float64 {
	switch {
	case p < 0.003:
		return 0.003

	case p > 0.995:
		return 0.995

	default:
		return p
	}
}

func (r *candidateRouter) edgeProbability(e *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	required := amt + r.reserved[e.key]
	if required > e.capacity {
		return 0.001
	}

	if e.key.from == r.source {
		if r.localBalances[e.key.chanID] < required {
			return 0.001
		}

		return 0.999
	}

	p := candidatePrior(required, e.capacity)

	candidateBeliefStore.Lock()
	stored := candidateBeliefStore.beliefs[e.key]
	var belief candidateBelief
	if stored != nil {
		belief = *stored
	}
	candidateBeliefStore.Unlock()

	if stored != nil {
		if belief.estimate > 0 && belief.conf > 0 {
			estimateP := candidateLogisticProbability(
				required, belief.estimate, e.capacity,
			)

			weight := 0.13 * float64(belief.conf)
			if weight > 0.78 {
				weight = 0.78
			}
			p = (1-weight)*p + weight*estimateP
		}

		if belief.lowerOK > 0 && required <= belief.lowerOK {
			p = math.Max(p, 0.995)
		}

		if belief.upperFail > 0 {
			switch {
			case required >= belief.upperFail:
				p = math.Min(p, 0.012)

			case belief.lowerOK > 0 &&
				belief.upperFail > belief.lowerOK &&
				required > belief.lowerOK:

				span := float64(
					belief.upperFail - belief.lowerOK,
				)
				position := float64(
					required - belief.lowerOK,
				) / span

				bounded := 0.995*(1-position) +
					0.012*position
				p = 0.30*p + 0.70*bounded
			}
		}
	}

	if local, ok := r.localFails[e.key]; ok &&
		local.upper > 0 && required >= local.upper {

		p *= math.Exp(-1.85 * local.weight)
	}

	return candidateClampProbability(p)
}

func (r *candidateRouter) edgeCost(e *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	p := r.edgeProbability(e, amt)
	cost := -math.Log(p) + 0.018 + r.edgePenalty[e.key]

	if reserved := r.reserved[e.key]; reserved > 0 &&
		e.capacity > 0 {

		ratio := float64(reserved) / float64(e.capacity)

		// A successful shard is evidence that the corridor is live, so
		// reuse remains possible. The increasing marginal charge keeps
		// atomic siblings from all leaning on a narrow channel.
		cost += 0.08 + 0.65*ratio*ratio
	}

	return cost
}

type candidateDijkstraItem struct {
	node  route.Vertex
	score float64
	amt   lnwire.MilliSatoshi
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *candidateDijkstraQueue) Push(x any) {
	*q = append(*q, x.(*candidateDijkstraItem))
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]

	return item
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}

	score := make(map[route.Vertex]float64)
	arriving := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)

	score[r.spec.Target] = 0
	arriving[r.spec.Target] = amt

	pq := &candidateDijkstraQueue{}
	heap.Push(pq, &candidateDijkstraItem{
		node: r.spec.Target,
		amt:  amt,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)

		bestScore, ok := score[item.node]
		if !ok || item.score > bestScore+1e-12 {
			continue
		}
		if arriving[item.node] != item.amt {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOverEdge := item.amt
			if !edge.policyAllows(amtOverEdge) {
				continue
			}

			required := amtOverEdge + r.reserved[edge.key]
			if required > edge.capacity {
				continue
			}
			if edge.key.from == r.source &&
				r.localBalances[edge.key.chanID] < required {

				continue
			}

			sending := amtOverEdge
			feeCost := 0.0
			if edge.key.from != r.source {
				fee := edge.fee(amtOverEdge)
				sending += fee

				denominator := float64(amt)
				if denominator < 1 {
					denominator = 1
				}
				feeCost = 42 * float64(fee) / denominator
			}

			newScore := item.score +
				r.edgeCost(edge, amtOverEdge) + feeCost

			oldScore, exists := score[edge.key.from]
			if exists && newScore >= oldScore {
				continue
			}

			score[edge.key.from] = newScore
			arriving[edge.key.from] = sending
			next[edge.key.from] = edge

			heap.Push(pq, &candidateDijkstraItem{
				node:  edge.key.from,
				score: newScore,
				amt:   sending,
			})
		}
	}

	if _, ok := score[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}

	probability := 1.0
	for _, traversal := range r.routeTraversals(rt) {
		probability *= r.edgeProbability(
			traversal.edge, traversal.amt,
		)
	}

	return rt, probability, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))

	last := len(path) - 1
	amounts[last] = amt
	expiries[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]

		amounts[i] = amounts[i+1] +
			forwardingEdge.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amountToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)

		if i < last {
			amountToForward = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amountToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateCeilDiv(amt lnwire.MilliSatoshi,
	parts uint32) lnwire.MilliSatoshi {

	if parts <= 1 {
		return amt
	}

	divisor := lnwire.MilliSatoshi(parts)
	return (amt + divisor - 1) / divisor
}

func (r *candidateRouter) targetPartCount() uint32 {
	target := r.plannedParts

	// Failed large shards make additional slots valuable. Unknown
	// failures diversify routes but do not immediately force a probing
	// ladder because they carry no amount bound.
	target += r.failures / 3
	if r.unknownFails >= 4 {
		target++
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if target > maxParts {
		target = maxParts
	}
	if target == 0 {
		target = 1
	}

	return target
}

func (r *candidateRouter) tryExpandedShard(
	base lnwire.MilliSatoshi, amt lnwire.MilliSatoshi,
	baseRoute *route.Route, baseProbability float64) *route.Route {

	if r.successfulParts == 0 || base >= amt {
		return baseRoute
	}

	bestRoute := baseRoute
	bestAmount := base
	bestProbability := baseProbability

	candidates := []lnwire.MilliSatoshi{
		base * 3 / 2,
		base * 2,
		base * 3,
		amt,
	}

	for _, candidate := range candidates {
		if candidate <= bestAmount || candidate > amt {
			continue
		}

		rt, probability, err := r.findRoute(candidate)
		if err != nil {
			continue
		}

		// Scaling is reserved for corridors supported by truthful recent
		// success. This creates unequal MPP allocations without probing
		// an unproven large shard.
		requiredProbability := 0.74
		if len(rt.Hops) >= 12 {
			requiredProbability = 0.68
		}
		if probability < requiredProbability {
			continue
		}
		if probability+0.08 < bestProbability {
			continue
		}

		bestRoute = rt
		bestAmount = candidate
		bestProbability = probability
	}

	return bestRoute
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum parts already in flight")
	}

	partsLeft := maxParts - inFlightHtlcs
	minimumShard := candidateCeilDiv(amt, partsLeft)

	var wholeRoute *route.Route
	if rt, probability, err := r.findRoute(amt); err == nil {
		wholeRoute = rt

		if r.plannedParts == 1 || probability >= 0.82 {
			return rt, nil
		}
	}

	targetParts := r.targetPartCount()
	desiredSlots := uint32(1)
	if targetParts > inFlightHtlcs {
		desiredSlots = targetParts - inFlightHtlcs
	}
	if desiredSlots > partsLeft {
		desiredSlots = partsLeft
	}

	shard := candidateCeilDiv(amt, desiredSlots)
	if r.retryCap > 0 && r.retryCap < shard {
		shard = r.retryCap
	}
	if shard < minimumShard {
		shard = minimumShard
	}
	if shard > amt {
		shard = amt
	}

	for {
		rt, probability, err := r.findRoute(shard)
		if err == nil {
			return r.tryExpandedShard(
				shard, amt, rt, probability,
			), nil
		}

		if shard <= minimumShard {
			if wholeRoute != nil && shard != amt {
				return wholeRoute, nil
			}

			return nil, err
		}

		nextShard := shard * 2 / 3
		if nextShard < minimumShard {
			nextShard = minimumShard
		}
		if nextShard == shard {
			nextShard--
		}

		shard = nextShard
	}
}

func (r *candidateRouter) routeTraversals(
	rt *route.Route) []candidateTraversal {

	traversals := make(
		[]candidateTraversal, 0, len(rt.Hops),
	)
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		key := candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		edge := r.edges[key]
		if edge == nil {
			from = hop.PubKeyBytes
			continue
		}

		amount := rt.TotalAmount
		if i > 0 {
			amount = rt.Hops[i-1].AmtToForward
		}

		traversals = append(traversals, candidateTraversal{
			key:  key,
			edge: edge,
			amt:  amount,
		})
		from = hop.PubKeyBytes
	}

	return traversals
}

func candidateDeliveredAmount(
	rt *route.Route) lnwire.MilliSatoshi {

	if len(rt.Hops) == 0 {
		return 0
	}

	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func (r *candidateRouter) recordSuccess(rt *route.Route) {
	traversals := r.routeTraversals(rt)

	candidateBeliefStore.Lock()
	for _, traversal := range traversals {
		required := traversal.amt + r.reserved[traversal.key]

		belief := candidateBeliefStore.beliefs[traversal.key]
		if belief == nil {
			belief = &candidateBelief{}
			candidateBeliefStore.beliefs[traversal.key] = belief
		}

		if required > belief.lowerOK {
			belief.lowerOK = required
		}

		highEstimate := traversal.edge.capacity * 88 / 100
		if required > highEstimate {
			highEstimate = required
		}
		if highEstimate > belief.estimate {
			belief.estimate = highEstimate
		}
		if belief.conf < 8 {
			belief.conf++
		}

		if belief.upperFail > 0 &&
			required >= belief.upperFail {

			belief.upperFail = 0
		}
		if belief.suspectAmt > 0 &&
			required >= belief.suspectAmt {

			belief.suspectAmt = 0
			belief.suspectWeight = 0
		}
	}
	candidateBeliefStore.Unlock()

	for _, traversal := range traversals {
		required := traversal.amt + r.reserved[traversal.key]

		if local, ok := r.localFails[traversal.key]; ok &&
			required >= local.upper {

			delete(r.localFails, traversal.key)
		}

		r.reserved[traversal.key] += traversal.amt
		r.usedTotals[traversal.key] += traversal.amt

		// A successful edge should rapidly recover from route-level
		// diversification penalties.
		r.edgePenalty[traversal.key] *= 0.30
	}

	r.successfulParts++
	r.delivered += candidateDeliveredAmount(rt)

	if r.delivered >= r.spec.Amount && !r.settled {
		r.recordSettlement()
		r.settled = true
	}
}

func candidateSubtractFloor(value,
	delta lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if value > delta {
		return value - delta
	}

	return 0
}

func (r *candidateRouter) recordSettlement() {
	candidateBeliefStore.Lock()
	defer candidateBeliefStore.Unlock()

	for key, used := range r.usedTotals {
		if used <= 0 {
			continue
		}

		if belief := candidateBeliefStore.beliefs[key]; belief != nil {
			belief.lowerOK = candidateSubtractFloor(
				belief.lowerOK, used,
			)
			belief.estimate = candidateSubtractFloor(
				belief.estimate, used,
			)
			belief.upperFail = candidateSubtractFloor(
				belief.upperFail, used,
			)
			belief.suspectAmt = candidateSubtractFloor(
				belief.suspectAmt, used,
			)
			if belief.suspectAmt == 0 {
				belief.suspectWeight = 0
			}
		}

		reverse := candidateEdgeKey{
			chanID: key.chanID,
			from:   key.to,
			to:     key.from,
		}
		reverseBelief := candidateBeliefStore.beliefs[reverse]
		if reverseBelief == nil {
			reverseBelief = &candidateBelief{}
			candidateBeliefStore.beliefs[reverse] = reverseBelief
		}

		reverseCapacity := lnwire.MilliSatoshi(0)
		if edge := r.edges[reverse]; edge != nil {
			reverseCapacity = edge.capacity
		} else if edge := r.edges[key]; edge != nil {
			reverseCapacity = edge.capacity
		}

		reverseBelief.lowerOK += used
		reverseBelief.estimate += used

		if reverseCapacity > 0 {
			if reverseBelief.lowerOK > reverseCapacity {
				reverseBelief.lowerOK = reverseCapacity
			}
			if reverseBelief.estimate > reverseCapacity {
				reverseBelief.estimate = reverseCapacity
			}
		}

		if reverseBelief.upperFail > 0 {
			reverseBelief.upperFail += used
			if reverseCapacity > 0 &&
				reverseBelief.upperFail > reverseCapacity {

				reverseBelief.upperFail = reverseCapacity
			}
		}
	}
}

func (r *candidateRouter) failureTraversalIndex(
	rt *route.Route, source route.Vertex) (int, bool) {

	if source == rt.SourcePubKey {
		return 0, len(rt.Hops) > 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes != source {
			continue
		}

		index := i + 1
		if index >= len(rt.Hops) {
			return 0, false
		}

		return index, true
	}

	return 0, false
}

func (r *candidateRouter) addLocalFailure(
	traversal candidateTraversal, weight float64) {

	required := traversal.amt + r.reserved[traversal.key]

	local := r.localFails[traversal.key]
	if local.upper == 0 || required < local.upper {
		local.upper = required
	}
	local.weight += weight
	if local.weight > 4 {
		local.weight = 4
	}
	r.localFails[traversal.key] = local
}

func (r *candidateRouter) recordPersistentFailure(
	traversal candidateTraversal, weight float64) {

	if traversal.key.from == r.source {
		return
	}

	required := traversal.amt + r.reserved[traversal.key]

	candidateBeliefStore.Lock()
	defer candidateBeliefStore.Unlock()

	belief := candidateBeliefStore.beliefs[traversal.key]
	if belief == nil {
		belief = &candidateBelief{}
		candidateBeliefStore.beliefs[traversal.key] = belief
	}

	if belief.suspectAmt == 0 || required < belief.suspectAmt {
		belief.suspectAmt = required
	}
	belief.suspectWeight += weight

	// Three direct reports are needed before noisy attribution becomes
	// a persistent bound. Until then it affects only this payment.
	if belief.suspectWeight < 2.05 {
		return
	}

	if belief.upperFail == 0 ||
		belief.suspectAmt < belief.upperFail {

		belief.upperFail = belief.suspectAmt
	}

	failedEstimate := belief.suspectAmt * 68 / 100
	if belief.estimate == 0 ||
		failedEstimate < belief.estimate {

		belief.estimate = failedEstimate
	}
	if belief.conf < 8 {
		belief.conf++
	}
}

func (r *candidateRouter) recordAttributedLiquidityFailure(
	traversals []candidateTraversal, claimed int) {

	for offset := -1; offset <= 1; offset++ {
		index := claimed + offset
		if index < 0 || index >= len(traversals) {
			continue
		}

		weight := 0.14
		penalty := 0.20
		if offset == 0 {
			weight = 0.72
			penalty = 1.05
		}

		traversal := traversals[index]
		r.addLocalFailure(traversal, weight)
		r.edgePenalty[traversal.key] += penalty

		// Only the reported edge contributes to persistent evidence.
		// Adjacent weights are useful inside this payment for shifted
		// blame, but are too ambiguous to retain across payments.
		if offset == 0 {
			r.recordPersistentFailure(traversal, weight)
		}
	}
}

func (r *candidateRouter) recordPolicyFailure(
	traversals []candidateTraversal, claimed int) {

	for offset := -1; offset <= 1; offset++ {
		index := claimed + offset
		if index < 0 || index >= len(traversals) {
			continue
		}

		penalty := 0.35
		if offset == 0 {
			penalty = 1.80
		}
		r.edgePenalty[traversals[index].key] += penalty
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64,
	rt *route.Route, result routing.SimHtlcResult) error {

	if result.Failure == nil {
		r.retryCap = 0
		r.recordSuccess(rt)
		return nil
	}

	r.failures++

	traversals := r.routeTraversals(rt)
	if len(traversals) != len(rt.Hops) {
		r.unknownFails++
		return nil
	}

	for _, traversal := range traversals {
		r.edgePenalty[traversal.key] += 0.025
	}

	code := result.Failure.Code()
	claimed, attributed := r.failureTraversalIndex(
		rt, result.FailureSource,
	)

	switch code {
	case lnwire.CodeTemporaryChannelFailure:
		if attributed {
			r.recordAttributedLiquidityFailure(
				traversals, claimed,
			)

			delivered := candidateDeliveredAmount(rt)
			if delivered > 1 {
				next := delivered * 58 / 100
				if r.retryCap == 0 || next < r.retryCap {
					r.retryCap = next
				}
			}

			return nil
		}

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		if attributed {
			r.recordPolicyFailure(traversals, claimed)
			return nil
		}
	}

	// Unreadable failures write no liquidity observation. A modest
	// payment-local route penalty encourages a genuinely different
	// attempt without poisoning shared beliefs or forcing tiny probes.
	r.unknownFails++
	routePenalty := 0.16
	if len(traversals) > 12 {
		routePenalty = 0.11
	}
	for _, traversal := range traversals {
		r.edgePenalty[traversal.key] += routePenalty
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	conf      uint8

	suspectAmt   lnwire.MilliSatoshi
	suspectVotes uint8
}

var candidateBeliefStore = struct {
	sync.Mutex
	beliefs map[candidateEdgeKey]*candidateBelief
}{
	beliefs: make(map[candidateEdgeKey]*candidateBelief),
}

type candidateLocalFailure struct {
	upper lnwire.MilliSatoshi
	count uint8
}

type candidateTraversal struct {
	key  candidateEdgeKey
	edge *candidateEdge
	amt  lnwire.MilliSatoshi
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	reserved     map[candidateEdgeKey]lnwire.MilliSatoshi
	usedTotals   map[candidateEdgeKey]lnwire.MilliSatoshi
	localFails   map[candidateEdgeKey]candidateLocalFailure
	edgePenalty  map[candidateEdgeKey]float64
	routeFailure map[uint64]uint8

	plannedParts uint32
	failures     uint32
	unknownFails uint32
	attempts     uint32
	delivered    lnwire.MilliSatoshi
	settled      bool
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[candidateEdgeKey]*candidateEdge),
		localBalances: localBalances,
		reserved:      make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		usedTotals:    make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		localFails:    make(map[candidateEdgeKey]candidateLocalFailure),
		edgePenalty:   make(map[candidateEdgeKey]float64),
		routeFailure:  make(map[uint64]uint8),
	}

	r.plannedParts = r.initialPartCount(spec.Amount)
	maxParts := r.maxParts()
	if r.plannedParts > maxParts {
		r.plannedParts = maxParts
	}
	if r.plannedParts == 0 {
		r.plannedParts = 1
	}

	ctx := context.Background()
	seen := make(map[route.Vertex]bool)
	queue := []route.Vertex{source}
	seen[source] = true

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[key] = edge

				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func (r *candidateRouter) maxParts() uint32 {
	if r.spec.MaxParts == 0 {
		return 1
	}
	return r.spec.MaxParts
}

func (r *candidateRouter) initialPartCount(
	amt lnwire.MilliSatoshi) uint32 {

	maxParts := r.maxParts()

	switch {
	case amt <= 25_000_000:
		return 1

	case amt <= 100_000_000:
		if maxParts < 4 {
			return maxParts
		}
		return 4

	default:
		// Large payments benefit from committing the available part
		// budget immediately. Limit extreme part counts because fixed
		// per-hop fees eventually dominate tiny shards.
		if maxParts > 20 {
			return 20
		}
		return maxParts
	}
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.003
	}

	x := float64(amt) / float64(capacity)

	lowMode := 0.48 * math.Exp(-x/0.025)
	highMode := 0.50 / (1 + math.Exp((x-0.90)/0.025))
	p := 0.005 + lowMode + highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func candidateLogisticProbability(amt, estimate,
	capacity lnwire.MilliSatoshi) float64 {

	if capacity <= 0 {
		return 0.005
	}

	scale := 0.07 * float64(capacity)
	if scale < 1 {
		scale = 1
	}

	z := (float64(amt) - float64(estimate)) / scale
	if z > 30 {
		return 0.005
	}
	if z < -30 {
		return 0.995
	}

	return 1 / (1 + math.Exp(z))
}

func (r *candidateRouter) edgeProbability(e *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	required := amt + r.reserved[e.key]
	if required > e.capacity {
		return 0.001
	}

	if e.key.from == r.source {
		if r.localBalances[e.key.chanID] < required {
			return 0.001
		}
		return 0.999
	}

	p := candidatePrior(required, e.capacity)

	candidateBeliefStore.Lock()
	stored, ok := candidateBeliefStore.beliefs[e.key]
	var belief candidateBelief
	if ok {
		belief = *stored
	}
	candidateBeliefStore.Unlock()

	if ok {
		if belief.estimate > 0 && belief.conf > 0 {
			q := candidateLogisticProbability(
				required, belief.estimate, e.capacity,
			)
			weight := 0.14 * float64(belief.conf)
			if weight > 0.70 {
				weight = 0.70
			}
			p = (1-weight)*p + weight*q
		}

		if belief.lowerOK > 0 && required <= belief.lowerOK {
			p = math.Max(p, 0.995)
		}

		if belief.upperFail > 0 {
			switch {
			case required >= belief.upperFail:
				p = math.Min(p, 0.008)

			case belief.lowerOK > 0 &&
				belief.upperFail > belief.lowerOK:

				span := float64(
					belief.upperFail - belief.lowerOK,
				)
				position := float64(
					required - belief.lowerOK,
				) / span
				if position > 0 {
					bounded := 0.995*(1-position) +
						0.008*position
					p = 0.35*p + 0.65*bounded
				}
			}
		}
	}

	if local, ok := r.localFails[e.key]; ok &&
		required >= local.upper {

		if local.count >= 2 {
			p = math.Min(p, 0.004)
		} else {
			p *= 0.10
		}
	}

	if p < 0.003 {
		return 0.003
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

func (r *candidateRouter) edgeCost(e *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	p := r.edgeProbability(e, amt)
	cost := -math.Log(p) + 0.01 + r.edgePenalty[e.key]

	if reserved := r.reserved[e.key]; reserved > 0 &&
		e.capacity > 0 {

		share := float64(reserved) / float64(e.capacity)
		cost += 0.08 + 0.70*share
	}

	return cost
}

type candidateLabel struct {
	node   route.Vertex
	score  float64
	amt    lnwire.MilliSatoshi
	edge   *candidateEdge
	next   *candidateLabel
	active bool
}

type candidateLabelQueue []*candidateLabel

func (q candidateLabelQueue) Len() int {
	return len(q)
}

func (q candidateLabelQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateLabelQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *candidateLabelQueue) Push(x any) {
	*q = append(*q, x.(*candidateLabel))
}

func (q *candidateLabelQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func candidateDominates(aScore float64, aAmt lnwire.MilliSatoshi,
	bScore float64, bAmt lnwire.MilliSatoshi) bool {

	return aScore <= bScore+1e-12 && aAmt <= bAmt
}

func candidateInsertLabel(labels map[route.Vertex][]*candidateLabel,
	label *candidateLabel, paymentAmt lnwire.MilliSatoshi) bool {

	current := labels[label.node]
	for _, old := range current {
		if old.active && candidateDominates(
			old.score, old.amt, label.score, label.amt,
		) {
			return false
		}
	}

	for _, old := range current {
		if old.active && candidateDominates(
			label.score, label.amt, old.score, old.amt,
		) {
			old.active = false
		}
	}

	label.active = true
	current = append(current, label)
	labels[label.node] = current

	activeCount := 0
	for _, old := range current {
		if old.active {
			activeCount++
		}
	}
	if activeCount <= 12 {
		return true
	}

	denom := float64(paymentAmt)
	if denom < 1 {
		denom = 1
	}

	var worst *candidateLabel
	worstValue := math.Inf(-1)
	for _, old := range current {
		if !old.active {
			continue
		}

		value := old.score + 0.45*float64(old.amt)/denom
		if value > worstValue {
			worstValue = value
			worst = old
		}
	}

	if worst != nil {
		worst.active = false
	}
	return label.active
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}

	target := &candidateLabel{
		node:   r.spec.Target,
		score:  0,
		amt:    amt,
		active: true,
	}
	labels := map[route.Vertex][]*candidateLabel{
		r.spec.Target: {target},
	}

	pq := &candidateLabelQueue{}
	heap.Push(pq, target)

	var sourceLabel *candidateLabel

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateLabel)
		if !item.active {
			continue
		}
		if item.node == r.source {
			sourceLabel = item
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOver := item.amt
			if !edge.policyAllows(amtOver) {
				continue
			}

			required := amtOver + r.reserved[edge.key]
			if required > edge.capacity {
				continue
			}
			if edge.key.from == r.source &&
				r.localBalances[edge.key.chanID] < required {

				continue
			}

			sending := amtOver
			feeCost := 0.0
			if edge.key.from != r.source {
				fee := edge.fee(amtOver)
				sending += fee

				denom := float64(amt)
				if denom < 1 {
					denom = 1
				}
				feeCost = 18 * float64(fee) / denom
			}

			label := &candidateLabel{
				node:  edge.key.from,
				score: item.score +
					r.edgeCost(edge, amtOver) + feeCost,
				amt:  sending,
				edge: edge,
				next: item,
			}

			if candidateInsertLabel(labels, label, amt) {
				heap.Push(pq, label)
			}
		}
	}

	if sourceLabel == nil {
		return nil, 0, errors.New("no route found")
	}

	var path []*candidateEdge
	for label := sourceLabel; label != nil && label.edge != nil;
		label = label.next {

		path = append(path, label.edge)
	}

	rt, err := r.buildRoute(amt, path)
	if err != nil {
		return nil, 0, err
	}

	return rt, sourceLabel.score, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, error) {

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}
	if path[0].key.from != r.source {
		return nil, errors.New("path does not start at source")
	}
	if path[len(path)-1].key.to != r.spec.Target {
		return nil, errors.New("path does not end at target")
	}

	for i := 1; i < len(path); i++ {
		if path[i-1].key.to != path[i].key.from {
			return nil, fmt.Errorf("broken path at hop %d", i)
		}
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateCeilDiv(amt lnwire.MilliSatoshi,
	parts uint32) lnwire.MilliSatoshi {

	if parts <= 1 {
		return amt
	}

	divisor := lnwire.MilliSatoshi(parts)
	return (amt + divisor - 1) / divisor
}

func candidateScaled(amt lnwire.MilliSatoshi,
	numerator, denominator int64) lnwire.MilliSatoshi {

	if denominator <= 0 {
		return amt
	}

	result := amt / lnwire.MilliSatoshi(denominator) *
		lnwire.MilliSatoshi(numerator)
	result += amt % lnwire.MilliSatoshi(denominator) *
		lnwire.MilliSatoshi(numerator) /
		lnwire.MilliSatoshi(denominator)

	if result <= 0 {
		return 1
	}
	return result
}

func candidateAppendAmount(amounts []lnwire.MilliSatoshi,
	amt, maximum lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if amt <= 0 {
		amt = 1
	}
	if amt > maximum {
		amt = maximum
	}

	for _, existing := range amounts {
		if existing == amt {
			return amounts
		}
	}
	return append(amounts, amt)
}

func (r *candidateRouter) targetPartCount() uint32 {
	target := r.plannedParts
	maxParts := r.maxParts()

	if r.failures >= 2 {
		target += 1 + r.failures/4
	}
	if r.unknownFails >= 2 {
		target++
	}

	if target > maxParts {
		target = maxParts
	}
	if target == 0 {
		target = 1
	}
	return target
}

func (r *candidateRouter) attemptLimit() uint32 {
	limit := uint32(48) + 5*r.maxParts()
	if limit < 72 {
		limit = 72
	}
	if limit > 160 {
		limit = 160
	}
	return limit
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	for _, traversal := range r.routeTraversals(rt) {
		r.reserved[traversal.key] += traversal.amt
	}
}

func (r *candidateRouter) unreserveRoute(rt *route.Route) {
	for _, traversal := range r.routeTraversals(rt) {
		current := r.reserved[traversal.key]
		if current <= traversal.amt {
			delete(r.reserved, traversal.key)
		} else {
			r.reserved[traversal.key] = current - traversal.amt
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if r.attempts >= r.attemptLimit() {
		return nil, errors.New("routing attempt limit reached")
	}

	maxParts := r.maxParts()
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum parts already in flight")
	}

	partsLeft := maxParts - inFlightHtlcs
	targetParts := r.targetPartCount()

	var planSlots uint32
	if targetParts > inFlightHtlcs {
		planSlots = targetParts - inFlightHtlcs
	} else {
		planSlots = 1
	}
	if planSlots > partsLeft {
		planSlots = partsLeft
	}
	if planSlots == 0 {
		planSlots = 1
	}

	base := candidateCeilDiv(amt, planSlots)
	amounts := make([]lnwire.MilliSatoshi, 0, 8)

	// Once a corridor fails, consider a genuinely smaller retry. A
	// one-step lookahead below prevents that retry from consuming a part
	// slot when the remaining amount cannot plausibly fit later.
	if r.failures > 0 && planSlots > 1 {
		amounts = candidateAppendAmount(
			amounts, candidateScaled(base, 3, 5), amt,
		)
		amounts = candidateAppendAmount(
			amounts, candidateScaled(base, 4, 5), amt,
		)
	}

	amounts = candidateAppendAmount(amounts, base, amt)
	amounts = candidateAppendAmount(
		amounts, candidateScaled(base, 5, 4), amt,
	)
	amounts = candidateAppendAmount(
		amounts, candidateScaled(base, 3, 2), amt,
	)
	amounts = candidateAppendAmount(
		amounts, candidateScaled(base, 2, 1), amt,
	)
	amounts = candidateAppendAmount(
		amounts, candidateScaled(base, 3, 1), amt,
	)
	amounts = candidateAppendAmount(amounts, amt, amt)

	var bestRoute *route.Route
	bestObjective := math.Inf(1)
	var lastErr error

	for _, shard := range amounts {
		rt, routeScore, err := r.findRoute(shard)
		if err != nil {
			lastErr = err
			continue
		}

		progress := float64(shard) / float64(base)
		if progress < 0.05 {
			progress = 0.05
		}

		// This is expected-progress selection: use a larger shard only
		// when its route remains reliable enough to justify doing so.
		objective := routeScore - 0.90*math.Log(progress)

		remaining := amt - shard
		if remaining > 0 && planSlots > 1 {
			r.reserveRoute(rt)

			futureSlots := planSlots - 1
			futureAmt := candidateCeilDiv(
				remaining, futureSlots,
			)
			_, futureScore, futureErr := r.findRoute(futureAmt)

			r.unreserveRoute(rt)

			if futureErr != nil {
				// Keep the candidate as a last resort, but strongly
				// prefer a shard that leaves a routable continuation.
				objective += 6.0
			} else {
				objective += 0.25 * futureScore
			}
		} else if remaining > 0 {
			objective += 8.0
		}

		if objective < bestObjective {
			bestObjective = objective
			bestRoute = rt
		}
	}

	if bestRoute != nil {
		return bestRoute, nil
	}
	if lastErr != nil {
		return nil, lastErr
	}
	return nil, errors.New("no route found")
}

func (r *candidateRouter) routeTraversals(
	rt *route.Route) []candidateTraversal {

	traversals := make([]candidateTraversal, 0, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		key := candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		edge := r.edges[key]
		if edge == nil {
			from = hop.PubKeyBytes
			continue
		}

		amt := rt.TotalAmount
		if i > 0 {
			amt = rt.Hops[i-1].AmtToForward
		}

		traversals = append(traversals, candidateTraversal{
			key:  key,
			edge: edge,
			amt:  amt,
		})
		from = hop.PubKeyBytes
	}

	return traversals
}

func candidateDeliveredAmount(rt *route.Route) lnwire.MilliSatoshi {
	if len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateRouteFingerprint(rt *route.Route) uint64 {
	hash := uint64(1469598103934665603)

	for i, hop := range rt.Hops {
		hash ^= hop.ChannelID + uint64(i+1)*0x9e3779b97f4a7c15
		hash *= 1099511628211
	}

	hash ^= uint64(candidateDeliveredAmount(rt) / 1000)
	hash *= 1099511628211

	return hash
}

func (r *candidateRouter) recordSuccess(rt *route.Route) {
	traversals := r.routeTraversals(rt)

	candidateBeliefStore.Lock()
	for _, traversal := range traversals {
		required := traversal.amt + r.reserved[traversal.key]
		b := candidateBeliefStore.beliefs[traversal.key]
		if b == nil {
			b = &candidateBelief{}
			candidateBeliefStore.beliefs[traversal.key] = b
		}

		if required > b.lowerOK {
			b.lowerOK = required
		}

		highEstimate := traversal.edge.capacity * 88 / 100
		if required > highEstimate {
			highEstimate = required
		}
		if highEstimate > b.estimate {
			b.estimate = highEstimate
		}
		if b.conf < 8 {
			b.conf++
		}

		if b.upperFail > 0 && required >= b.upperFail {
			b.upperFail = 0
		}
		if b.suspectAmt > 0 && required >= b.suspectAmt {
			b.suspectAmt = 0
			b.suspectVotes = 0
		}
	}
	candidateBeliefStore.Unlock()

	for _, traversal := range traversals {
		required := traversal.amt + r.reserved[traversal.key]
		if local, ok := r.localFails[traversal.key]; ok &&
			required >= local.upper {

			delete(r.localFails, traversal.key)
		}

		r.reserved[traversal.key] += traversal.amt
		r.usedTotals[traversal.key] += traversal.amt

		if r.edgePenalty[traversal.key] > 0.05 {
			r.edgePenalty[traversal.key] *= 0.65
		}
	}

	r.delivered += candidateDeliveredAmount(rt)
	if r.delivered >= r.spec.Amount && !r.settled {
		r.recordSettlement()
		r.settled = true
	}
}

func (r *candidateRouter) recordSettlement() {
	candidateBeliefStore.Lock()
	defer candidateBeliefStore.Unlock()

	for key, used := range r.usedTotals {
		if used <= 0 {
			continue
		}

		if b := candidateBeliefStore.beliefs[key]; b != nil {
			if b.lowerOK > used {
				b.lowerOK -= used
			} else {
				b.lowerOK = 0
			}

			if b.estimate > used {
				b.estimate -= used
			} else {
				b.estimate = 0
			}

			if b.upperFail > used {
				b.upperFail -= used
			} else {
				b.upperFail = 0
			}

			if b.suspectAmt > used {
				b.suspectAmt -= used
			} else {
				b.suspectAmt = 0
				b.suspectVotes = 0
			}
		}

		reverse := candidateEdgeKey{
			chanID: key.chanID,
			from:   key.to,
			to:     key.from,
		}
		reverseBelief := candidateBeliefStore.beliefs[reverse]
		if reverseBelief == nil {
			reverseBelief = &candidateBelief{}
			candidateBeliefStore.beliefs[reverse] = reverseBelief
		}

		reverseCapacity := lnwire.MilliSatoshi(0)
		if edge := r.edges[reverse]; edge != nil {
			reverseCapacity = edge.capacity
		} else if edge := r.edges[key]; edge != nil {
			reverseCapacity = edge.capacity
		}

		reverseBelief.lowerOK += used
		reverseBelief.estimate += used

		if reverseCapacity > 0 {
			if reverseBelief.lowerOK > reverseCapacity {
				reverseBelief.lowerOK = reverseCapacity
			}
			if reverseBelief.estimate > reverseCapacity {
				reverseBelief.estimate = reverseCapacity
			}
		}

		if reverseBelief.upperFail > 0 {
			reverseBelief.upperFail += used
			if reverseCapacity > 0 &&
				reverseBelief.upperFail > reverseCapacity {

				reverseBelief.upperFail = reverseCapacity
			}
		}
	}
}

func (r *candidateRouter) failureEdge(rt *route.Route,
	source route.Vertex) (candidateTraversal, bool) {

	traversals := r.routeTraversals(rt)
	if len(traversals) != len(rt.Hops) {
		return candidateTraversal{}, false
	}

	index := -1
	if source == rt.SourcePubKey {
		index = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == source {
				index = i + 1
				break
			}
		}
	}

	if index < 0 || index >= len(traversals) {
		return candidateTraversal{}, false
	}

	return traversals[index], true
}

func (r *candidateRouter) recordAttributedLiquidityFailure(
	traversal candidateTraversal) {

	required := traversal.amt + r.reserved[traversal.key]

	local := r.localFails[traversal.key]
	if local.upper == 0 || required < local.upper {
		local.upper = required
	}
	if local.count < 255 {
		local.count++
	}
	r.localFails[traversal.key] = local

	// Keep the amount-independent penalty small so the same channel can
	// immediately compete again at a lower amount.
	r.edgePenalty[traversal.key] += 0.18

	if traversal.key.from == r.source {
		return
	}

	candidateBeliefStore.Lock()
	defer candidateBeliefStore.Unlock()

	b := candidateBeliefStore.beliefs[traversal.key]
	if b == nil {
		b = &candidateBelief{}
		candidateBeliefStore.beliefs[traversal.key] = b
	}

	if b.suspectVotes == 0 {
		b.suspectAmt = required
		b.suspectVotes = 1
		return
	}

	if b.suspectAmt == 0 || required < b.suspectAmt {
		b.suspectAmt = required
	}
	if b.suspectVotes < 255 {
		b.suspectVotes++
	}

	// A single shifted attribution stays local to this payment. Only
	// corroborated reports become persistent, and even then the bound
	// remains soft and can be overturned by a truthful success.
	if b.suspectVotes >= 2 {
		if b.upperFail == 0 || b.suspectAmt < b.upperFail {
			b.upperFail = b.suspectAmt
		}

		failedEstimate := b.suspectAmt * 70 / 100
		if b.estimate == 0 || failedEstimate < b.estimate {
			b.estimate = failedEstimate
		}
		if b.conf < 8 {
			b.conf++
		}
	}
}

func (r *candidateRouter) penalizeFailedRoute(rt *route.Route,
	base float64) {

	fingerprint := candidateRouteFingerprint(rt)
	count := r.routeFailure[fingerprint]
	if count < 255 {
		count++
	}
	r.routeFailure[fingerprint] = count

	repeat := float64(count-1) * 0.06
	if repeat > 0.60 {
		repeat = 0.60
	}

	for _, traversal := range r.routeTraversals(rt) {
		r.edgePenalty[traversal.key] += base + repeat
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64,
	rt *route.Route, result routing.SimHtlcResult) error {

	r.attempts++

	if result.Failure == nil {
		r.recordSuccess(rt)
		return nil
	}

	r.failures++
	code := result.Failure.Code()

	if code == lnwire.CodeTemporaryChannelFailure {
		if traversal, ok := r.failureEdge(
			rt, result.FailureSource,
		); ok {

			// Diversify exact repeats without destroying the lower-amount
			// retry path for the specifically blamed channel.
			r.penalizeFailedRoute(rt, 0.035)
			r.recordAttributedLiquidityFailure(traversal)
			return nil
		}
	}

	if code == lnwire.CodeFeeInsufficient ||
		code == lnwire.CodeIncorrectCltvExpiry {

		r.penalizeFailedRoute(rt, 0.12)
		if traversal, ok := r.failureEdge(
			rt, result.FailureSource,
		); ok {

			r.edgePenalty[traversal.key] += 1.25
			return nil
		}
	}

	// Empty codes and off-route sources contain no channel evidence.
	// They influence only this router's exploration order.
	r.unknownFails++
	r.penalizeFailedRoute(rt, 0.20)

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40
	minShardAmt    = lnwire.MilliSatoshi(10_000_000)
	targetShardAmt = lnwire.MilliSatoshi(75_000_000)
)

type edgeKey struct {
	chanID uint64
	from   route.Vertex
}

type candidateEdge struct {
	key      edgeKey
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi

	suspectAmt   lnwire.MilliSatoshi
	failureVotes uint8
	updated      time.Time
}

var sharedBeliefs = struct {
	sync.Mutex
	m map[edgeKey]liquidityBelief
}{
	m: make(map[edgeKey]liquidityBelief),
}

type localFailure struct {
	amt   lnwire.MilliSatoshi
	votes int
}

type planEntry struct {
	rt *route.Route
}

type candidateRouter struct {
	view   routing.SimNetworkView
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	beliefs       map[edgeKey]liquidityBelief
	reserved      map[edgeKey]lnwire.MilliSatoshi
	localFailures map[edgeKey]localFailure
	policyStrikes map[edgeKey]int

	failedRoutes map[uint64]int
	routeFailAmt map[uint64]lnwire.MilliSatoshi

	plan        []planEntry
	retryHint   lnwire.MilliSatoshi
	attempts    int
	planVersion uint64
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		view:           view,
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[edgeKey]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[edgeKey]liquidityBelief),
		reserved:       make(map[edgeKey]lnwire.MilliSatoshi),
		localFailures:  make(map[edgeKey]localFailure),
		policyStrikes:  make(map[edgeKey]int),
		failedRoutes:   make(map[uint64]int),
		routeFailAmt:   make(map[uint64]lnwire.MilliSatoshi),
		retryHint:      spec.Amount,
		planVersion:    1,
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: edgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
					},
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: pol.FeeBaseMSat,
					feeRatePPM: pol.
						FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[edge.key] = edge

				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key := range r.edges {
		if belief, ok := sharedBeliefs.m[key]; ok {
			r.beliefs[key] = belief
		}
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func clampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005
	case p > 0.995:
		return 0.995
	default:
		return p
	}
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.025)
	highMode := 1 / (1 + math.Exp((x-0.94)/0.035))

	return clampProbability(0.5*lowMode + 0.5*highMode)
}

func (r *candidateRouter) evidenceWeight(b liquidityBelief) float64 {
	if b.updated.IsZero() {
		return 0
	}

	now := r.view.Now()
	if now.Before(b.updated) {
		return 0
	}

	age := now.Sub(b.updated)
	return math.Exp(-float64(age) / float64(180*time.Minute))
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if edge.from == r.source {
		available := r.localBalances[edge.chanID]
		if amt <= available {
			return 0.999
		}
		return 0.001
	}

	prior := bimodalPrior(amt, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return prior
	}

	weight := r.evidenceWeight(belief)
	if weight < 0.01 {
		return prior
	}

	p := prior

	if belief.lowerOK > 0 {
		if amt <= belief.lowerOK {
			p += weight * (0.995 - p)
		} else {
			ratio := float64(amt-belief.lowerOK) /
				float64(maxMSat(1, edge.capacity-belief.lowerOK))
			boost := (0.995 - p) * math.Exp(-5*ratio)
			p += weight * boost
		}
	}

	if belief.failureVotes >= 2 && belief.upperBad > 0 {
		if amt >= belief.upperBad {
			p = p*(1-weight) + 0.005*weight
		} else if belief.lowerOK > 0 &&
			belief.upperBad > belief.lowerOK {

			x := float64(amt-belief.lowerOK) /
				float64(belief.upperBad-belief.lowerOK)
			if x > 0 {
				evidenceP := clampProbability(0.995 - 0.99*x)
				p = p*(1-weight) + evidenceP*weight
			}
		} else {
			x := float64(amt) / float64(belief.upperBad)
			if x > 0.45 {
				penalty := weight * 0.8 *
					(x - 0.45) / 0.55
				if penalty > 0.8 {
					penalty = 0.8
				}
				p *= 1 - penalty
			}
		}
	} else if belief.failureVotes == 1 && belief.suspectAmt > 0 {
		x := float64(amt) / float64(belief.suspectAmt)
		if x > 1 {
			x = 1
		}
		p *= 1 - 0.30*weight*x*x*x
	}

	return clampProbability(p)
}

type pathLabel struct {
	score float64
	need  lnwire.MilliSatoshi
}

type dijkstraItem struct {
	node  route.Vertex
	score float64
	need  lnwire.MilliSatoshi
	index int
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	if q[i].score == q[j].score {
		return q[i].need < q[j].need
	}
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index = i
	q[j].index = j
}

func (q *dijkstraQueue) Push(x any) {
	item := x.(*dijkstraItem)
	item.index = len(*q)
	*q = append(*q, item)
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) findPath(amt lnwire.MilliSatoshi,
	extraReserved map[edgeKey]lnwire.MilliSatoshi,
	banned map[edgeKey]bool) ([]*candidateEdge, error) {

	labels := make(map[route.Vertex]pathLabel)
	next := make(map[route.Vertex]*candidateEdge)

	labels[r.spec.Target] = pathLabel{
		score: 0,
		need:  amt,
	}

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node: r.spec.Target,
		need: amt,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		label, ok := labels[item.node]
		if !ok || item.score > label.score+0.000001 {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if banned != nil && banned[edge.key] {
				continue
			}

			amtOver := item.need
			if !edge.usable(amtOver) {
				continue
			}

			reserved := r.reserved[edge.key]
			if extraReserved != nil {
				reserved += extraReserved[edge.key]
			}
			combined := amtOver + reserved
			if combined > edge.capacity {
				continue
			}

			if edge.from == r.source {
				if combined > r.localBalances[edge.chanID] {
					continue
				}
			}

			p := r.edgeProbability(edge, combined)
			riskCost := -math.Log(p) * 250_000

			if failure, ok := r.localFailures[edge.key]; ok &&
				failure.amt > 0 {

				x := float64(combined) / float64(failure.amt)
				if x > 1 {
					x = 1
				}
				riskCost += float64(failure.votes) *
					300_000 * x * x * x * x
			}

			if strikes := r.policyStrikes[edge.key]; strikes > 0 {
				riskCost += float64(strikes) * 1_500_000
			}

			sending := amtOver
			feeCost := float64(0)
			if edge.from != r.source {
				fee := edge.fee(amtOver)
				sending += fee
				feeCost = float64(fee)
			}

			score := item.score + riskCost + feeCost + 50
			old, exists := labels[edge.from]
			if exists && score >= old.score {
				continue
			}

			labels[edge.from] = pathLabel{
				score: score,
				need:  sending,
			}
			next[edge.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:  edge.from,
				score: score,
				need:  sending,
			})
		}
	}

	if _, ok := labels[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	var path []*candidateEdge
	seen := make(map[route.Vertex]bool)
	for node := r.source; node != r.spec.Target; {
		if seen[node] {
			return nil, errors.New("routing cycle")
		}
		seen[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	return path, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, error) {

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forwardAmt := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			forwardAmt = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     forwardAmt,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func pathHash(path []*candidateEdge) uint64 {
	hash := uint64(1469598103934665603)
	for _, edge := range path {
		hash ^= edge.chanID
		hash *= 1099511628211
		for _, b := range edge.from {
			hash ^= uint64(b)
			hash *= 1099511628211
		}
	}
	return hash
}

func routeHash(rt *route.Route) uint64 {
	hash := uint64(1469598103934665603)
	from := rt.SourcePubKey
	for _, hop := range rt.Hops {
		hash ^= hop.ChannelID
		hash *= 1099511628211
		for _, b := range from {
			hash ^= uint64(b)
			hash *= 1099511628211
		}
		from = hop.PubKeyBytes
	}
	return hash
}

func (r *candidateRouter) findAlternative(amt lnwire.MilliSatoshi,
	extraReserved map[edgeKey]lnwire.MilliSatoshi) (
	[]*candidateEdge, error) {

	banned := make(map[edgeKey]bool)
	var fallback []*candidateEdge

	for tries := 0; tries < 12; tries++ {
		path, err := r.findPath(amt, extraReserved, banned)
		if err != nil {
			break
		}
		if fallback == nil {
			fallback = path
		}

		hash := pathHash(path)
		failures := r.failedRoutes[hash]
		failedAmt := r.routeFailAmt[hash]
		if failures == 0 || failedAmt == 0 ||
			amt*100 <= failedAmt*65 {

			return path, nil
		}

		index := (failures + tries + len(path)/2) % len(path)
		banned[path[index].key] = true
	}

	if fallback != nil {
		return fallback, nil
	}

	return nil, errors.New("no route found")
}

func routeDeliveredAmt(rt *route.Route) lnwire.MilliSatoshi {
	if len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func routeEdgeAmt(rt *route.Route, index int) lnwire.MilliSatoshi {
	if index == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[index-1].AmtToForward
}

func (r *candidateRouter) routeProbability(rt *route.Route,
	extraReserved map[edgeKey]lnwire.MilliSatoshi) float64 {

	p := 1.0
	from := rt.SourcePubKey
	for i, hop := range rt.Hops {
		key := edgeKey{
			chanID: hop.ChannelID,
			from:   from,
		}
		edge, ok := r.edges[key]
		if !ok {
			return 0.005
		}

		combined := routeEdgeAmt(rt, i) + r.reserved[key]
		if extraReserved != nil {
			combined += extraReserved[key]
		}
		p *= r.edgeProbability(edge, combined)
		from = hop.PubKeyBytes
	}

	return clampProbability(p)
}

func (r *candidateRouter) routeFeasible(rt *route.Route,
	extraReserved map[edgeKey]lnwire.MilliSatoshi) bool {

	from := rt.SourcePubKey
	for i, hop := range rt.Hops {
		key := edgeKey{
			chanID: hop.ChannelID,
			from:   from,
		}
		edge, ok := r.edges[key]
		if !ok {
			return false
		}

		individual := routeEdgeAmt(rt, i)
		if !edge.usable(individual) {
			return false
		}

		combined := individual + r.reserved[key]
		if extraReserved != nil {
			combined += extraReserved[key]
		}
		if combined > edge.capacity {
			return false
		}
		if edge.from == r.source &&
			combined > r.localBalances[edge.chanID] {

			return false
		}

		from = hop.PubKeyBytes
	}

	return true
}

func reserveRoute(rt *route.Route,
	reservations map[edgeKey]lnwire.MilliSatoshi) {

	from := rt.SourcePubKey
	for i, hop := range rt.Hops {
		key := edgeKey{
			chanID: hop.ChannelID,
			from:   from,
		}
		reservations[key] += routeEdgeAmt(rt, i)
		from = hop.PubKeyBytes
	}
}

func (r *candidateRouter) tryPlan(total lnwire.MilliSatoshi, parts int,
	unequal bool) ([]planEntry, bool) {

	if parts < 1 {
		return nil, false
	}

	remaining := total
	planned := make(map[edgeKey]lnwire.MilliSatoshi)
	entries := make([]planEntry, 0, parts)

	for i := 0; i < parts && remaining > 0; i++ {
		left := parts - i
		deliver := (remaining + lnwire.MilliSatoshi(left) - 1) /
			lnwire.MilliSatoshi(left)

		path, err := r.findAlternative(deliver, planned)
		if err != nil {
			return entries, false
		}

		rt, err := r.buildRoute(deliver, path)
		if err != nil {
			return entries, false
		}

		if unequal && left > 1 {
			maxExtra := deliver / 2
			minForRest := minShardAmt *
				lnwire.MilliSatoshi(left-1)
			if remaining > deliver+minForRest {
				room := remaining - deliver - minForRest
				if maxExtra > room {
					maxExtra = room
				}
			} else {
				maxExtra = 0
			}

			if maxExtra > 0 {
				larger, buildErr := r.buildRoute(
					deliver+maxExtra, path,
				)
				if buildErr == nil &&
					r.routeFeasible(larger, planned) &&
					r.routeProbability(larger, planned) >= 0.03 {

					rt = larger
					deliver += maxExtra
				}
			}
		}

		if !r.routeFeasible(rt, planned) {
			return entries, false
		}

		entries = append(entries, planEntry{rt: rt})
		reserveRoute(rt, planned)
		remaining -= deliver
	}

	return entries, remaining == 0
}

func (r *candidateRouter) createPlan(total lnwire.MilliSatoshi,
	inFlight uint32) error {

	if total <= 0 {
		return errors.New("no amount remaining")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlight >= maxParts {
		return errors.New("maximum parts already in flight")
	}
	slots := int(maxParts - inFlight)

	fullPath, fullErr := r.findAlternative(total, nil)
	if fullErr == nil {
		fullRoute, buildErr := r.buildRoute(total, fullPath)
		if buildErr == nil {
			fullP := r.routeProbability(fullRoute, nil)
			if slots == 1 ||
				(r.attempts == 0 && inFlight == 0 && fullP >= 0.12) {

				r.plan = []planEntry{{rt: fullRoute}}
				return nil
			}
		}
	}

	if slots == 1 {
		if fullErr != nil {
			return fullErr
		}
		rt, err := r.buildRoute(total, fullPath)
		if err != nil {
			return err
		}
		r.plan = []planEntry{{rt: rt}}
		return nil
	}

	desired := targetShardAmt
	if r.retryHint > 0 && r.retryHint < desired {
		desired = r.retryHint
	}
	if desired < minShardAmt {
		desired = minShardAmt
	}

	parts := int((total + desired - 1) / desired)
	if parts < 2 {
		parts = 2
	}
	if parts > slots {
		parts = slots
	}

	var best []planEntry
	for count := parts; count <= slots; count++ {
		entries, complete := r.tryPlan(total, count, true)
		if len(entries) > len(best) {
			best = entries
		}
		if complete {
			r.plan = entries
			return nil
		}

		entries, complete = r.tryPlan(total, count, false)
		if len(entries) > len(best) {
			best = entries
		}
		if complete {
			r.plan = entries
			return nil
		}
	}

	if len(best) > 0 {
		r.plan = best
		return nil
	}

	if fullErr != nil {
		return fullErr
	}
	rt, err := r.buildRoute(total, fullPath)
	if err != nil {
		return err
	}
	r.plan = []planEntry{{rt: rt}}
	return nil
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	for {
		for len(r.plan) > 0 {
			entry := r.plan[0]
			r.plan = r.plan[1:]

			deliver := routeDeliveredAmt(entry.rt)
			if deliver <= 0 || deliver > amt {
				continue
			}

			hash := routeHash(entry.rt)
			if failedAmt := r.routeFailAmt[hash]; failedAmt > 0 &&
				deliver*100 > failedAmt*65 {

				continue
			}

			r.attempts++
			return entry.rt, nil
		}

		if err := r.createPlan(amt, inFlightHtlcs); err != nil {
			return nil, err
		}
	}
}

func (r *candidateRouter) updateShared(key edgeKey,
	update func(*liquidityBelief)) {

	belief := r.beliefs[key]
	update(&belief)
	belief.updated = r.view.Now()
	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	shared := sharedBeliefs.m[key]
	if !shared.updated.IsZero() &&
		belief.updated.Before(shared.updated) {

		sharedBeliefs.Unlock()
		return
	}
	sharedBeliefs.m[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) recordSuccess(rt *route.Route) {
	from := rt.SourcePubKey
	for i, hop := range rt.Hops {
		key := edgeKey{
			chanID: hop.ChannelID,
			from:   from,
		}
		amtOver := routeEdgeAmt(rt, i)

		r.reserved[key] += amtOver

		failure := r.localFailures[key]
		if failure.amt > 0 && amtOver >= failure.amt {
			delete(r.localFailures, key)
		} else if failure.votes > 0 {
			failure.votes--
			r.localFailures[key] = failure
		}
		delete(r.policyStrikes, key)

		if from != r.source {
			r.updateShared(key, func(b *liquidityBelief) {
				if amtOver > b.lowerOK {
					b.lowerOK = amtOver
				}
				if b.upperBad > 0 &&
					amtOver >= b.upperBad {

					b.upperBad = 0
					b.failureVotes = 0
					b.suspectAmt = 0
				} else if b.failureVotes > 0 {
					b.failureVotes--
				}
			})
		}

		from = hop.PubKeyBytes
	}
}

func locateFailure(rt *route.Route,
	source route.Vertex) (int, edgeKey, bool) {

	failIndex := -1
	if source == rt.SourcePubKey {
		failIndex = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == source {
				failIndex = i + 1
				break
			}
		}
	}

	if failIndex < 0 || failIndex >= len(rt.Hops) {
		return 0, edgeKey{}, false
	}

	from := rt.SourcePubKey
	if failIndex > 0 {
		from = rt.Hops[failIndex-1].PubKeyBytes
	}

	return failIndex, edgeKey{
		chanID: rt.Hops[failIndex].ChannelID,
		from:   from,
	}, true
}

func routeContainsKey(rt *route.Route, wanted edgeKey) bool {
	from := rt.SourcePubKey
	for _, hop := range rt.Hops {
		key := edgeKey{
			chanID: hop.ChannelID,
			from:   from,
		}
		if key == wanted {
			return true
		}
		from = hop.PubKeyBytes
	}
	return false
}

func (r *candidateRouter) removePlansUsing(key edgeKey) {
	filtered := r.plan[:0]
	for _, entry := range r.plan {
		if !routeContainsKey(entry.rt, key) {
			filtered = append(filtered, entry)
		}
	}
	r.plan = filtered
	r.planVersion++
}

func (r *candidateRouter) recordLiquidityFailure(key edgeKey,
	amt lnwire.MilliSatoshi) {

	local := r.localFailures[key]
	if local.amt == 0 || amt < local.amt {
		local.amt = amt
	}
	local.votes++
	r.localFailures[key] = local

	if key.from == r.source {
		return
	}

	r.updateShared(key, func(b *liquidityBelief) {
		now := r.view.Now()
		stale := !b.updated.IsZero() &&
			(now.Before(b.updated) ||
				now.Sub(b.updated) > 180*time.Minute)

		if stale {
			b.failureVotes = 0
			b.upperBad = 0
			b.suspectAmt = 0
		}

		if b.suspectAmt == 0 {
			b.suspectAmt = amt
			b.failureVotes = 1
			return
		}

		large := maxMSat(amt, b.suspectAmt)
		small := minMSat(amt, b.suspectAmt)
		if small*4 < large {
			b.suspectAmt = amt
			b.failureVotes = 1
			return
		}

		if b.failureVotes < 255 {
			b.failureVotes++
		}
		if amt < b.suspectAmt {
			b.suspectAmt = amt
		}

		if b.failureVotes >= 2 {
			if b.upperBad == 0 || amt < b.upperBad {
				b.upperBad = amt
			}
			if b.lowerOK >= b.upperBad {
				b.lowerOK = 0
			}
		}
	})
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if result.Failure == nil {
		r.recordSuccess(rt)
		return nil
	}

	hash := routeHash(rt)
	r.failedRoutes[hash]++
	delivered := routeDeliveredAmt(rt)
	if old := r.routeFailAmt[hash]; old == 0 || delivered < old {
		r.routeFailAmt[hash] = delivered
	}

	if delivered > minShardAmt {
		hint := delivered * 55 / 100
		if hint < minShardAmt {
			hint = minShardAmt
		}
		if r.retryHint == 0 || hint < r.retryHint {
			r.retryHint = hint
		}
	}

	index, key, attributed := locateFailure(
		rt, result.FailureSource,
	)
	if !attributed {
		return nil
	}

	amtOver := routeEdgeAmt(rt, index)
	r.removePlansUsing(key)

	if result.Failure.Code() == lnwire.CodeTemporaryChannelFailure {
		r.recordLiquidityFailure(key, amtOver)
		return nil
	}

	r.policyStrikes[key]++
	return nil
}

func minMSat(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if a < b {
		return a
	}
	return b
}

func maxMSat(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if a > b {
		return a
	}
	return b
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"reflect"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt, reserved lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	if reserved >= e.capacity {
		return false
	}
	return amt <= e.capacity-reserved
}

type candidateBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi

	softBad lnwire.MilliSatoshi
	badSeen uint8
}

type candidateScopedKey struct {
	scope uintptr
	edge  candidateEdgeKey
}

var candidateKnowledge = struct {
	sync.Mutex
	beliefs map[candidateScopedKey]candidateBelief
}{
	beliefs: make(map[candidateScopedKey]candidateBelief),
}

type candidatePenalty struct {
	amount lnwire.MilliSatoshi
	weight float64
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec
	scope  uintptr

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	beliefs map[candidateEdgeKey]candidateBelief

	// reserved accounts for both atomic-MPP holds and liquidity already
	// consumed by successful non-atomic shards.
	reserved map[candidateEdgeKey]lnwire.MilliSatoshi

	// Penalties are payment-local. They diversify retries without turning
	// unreliable failure attribution into permanent graph poisoning.
	penalties map[candidateEdgeKey]candidatePenalty

	targetShard       lnwire.MilliSatoshi
	requests          uint32
	failuresSincePass uint32
	totalFailures     uint32
}

func candidateViewScope(view routing.SimNetworkView) uintptr {
	v := reflect.ValueOf(view)
	switch v.Kind() {
	case reflect.Chan, reflect.Func, reflect.Map, reflect.Ptr,
		reflect.Slice, reflect.UnsafePointer:

		return v.Pointer()
	default:
		return 0
	}
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		scope:         candidateViewScope(view),
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[candidateEdgeKey]*candidateEdge),
		localBalances: localBalances,
		beliefs:       make(map[candidateEdgeKey]candidateBelief),
		reserved:      make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		penalties:     make(map[candidateEdgeKey]candidatePenalty),
	}

	ctx := context.Background()
	seen := make(map[route.Vertex]bool)
	queue := []route.Vertex{source}
	seen[source] = true

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[key] = edge
				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	candidateKnowledge.Lock()
	for key := range r.edges {
		r.beliefs[key] = candidateKnowledge.beliefs[
			candidateScopedKey{scope: r.scope, edge: key},
		]
	}
	candidateKnowledge.Unlock()

	return r, nil
}

func candidateClampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005
	case p > 0.995:
		return 0.995
	default:
		return p
	}
}

// candidatePrior models a channel as a roughly equal mixture of a depleted
// and a well-funded direction. Tiny HTLCs can pass in either mode, while
// amounts near capacity encounter the rich-mode cliff.
func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if amt <= 0 {
		return 0.985
	}
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.5 * math.Exp(-x/0.025)
	richMode := 0.5 / (1 + math.Exp((x-0.92)/0.045))

	return candidateClampProbability(lowMode + richMode)
}

func candidateBeliefProbability(b candidateBelief, amt,
	capacity lnwire.MilliSatoshi) float64 {

	prior := candidatePrior(amt, capacity)

	if b.lowerOK > 0 && amt <= b.lowerOK {
		return 0.995
	}
	if b.upperBad > 0 && amt >= b.upperBad {
		return 0.006
	}

	if b.lowerOK > 0 && b.upperBad > b.lowerOK &&
		amt > b.lowerOK && amt < b.upperBad {

		t := float64(amt-b.lowerOK) /
			float64(b.upperBad-b.lowerOK)
		bounded := 0.995*(1-t) + 0.006*t
		prior = 0.25*prior + 0.75*bounded
	}

	// A single attributed failure is only a soft hint. A second compatible
	// observation is required before upperBad becomes a hard bound.
	if b.softBad > 0 {
		ratio := float64(amt) / float64(b.softBad)
		if ratio > 1 {
			ratio = 1
		}
		if ratio > 0 {
			prior *= 1 - 0.55*ratio*ratio
		}
	}

	return candidateClampProbability(prior)
}

func candidateObserveSuccess(b candidateBelief,
	amt lnwire.MilliSatoshi) candidateBelief {

	if amt > b.lowerOK {
		b.lowerOK = amt
	}
	if b.upperBad > 0 && amt >= b.upperBad {
		b.upperBad = 0
	}
	if b.softBad > 0 && amt >= b.softBad {
		b.softBad = 0
		b.badSeen = 0
	}
	return b
}

func candidateObserveFailure(b candidateBelief,
	amt lnwire.MilliSatoshi) candidateBelief {

	if amt <= 0 {
		return b
	}

	if b.softBad == 0 {
		b.softBad = amt
		b.badSeen = 1
		return b
	}

	lo, hi := b.softBad, amt
	if lo > hi {
		lo, hi = hi, lo
	}

	// Require two observations within a factor of two. Correct blame tends
	// to recur at similar amounts; shifted blame usually does not.
	if lo > 0 && hi <= lo*2 {
		if b.badSeen < 255 {
			b.badSeen++
		}
		if amt < b.softBad {
			b.softBad = amt
		}
		if b.badSeen >= 2 &&
			(b.upperBad == 0 || hi < b.upperBad) {

			b.upperBad = hi
		}
	} else if amt < b.softBad {
		b.softBad = amt
		b.badSeen = 1
	}

	return b
}

func candidateResidualBelief(b candidateBelief,
	amt lnwire.MilliSatoshi) candidateBelief {

	if b.lowerOK > amt {
		b.lowerOK -= amt
	} else {
		b.lowerOK = 0
	}
	if b.upperBad > amt {
		b.upperBad -= amt
	} else {
		b.upperBad = 0
	}
	if b.softBad > amt {
		b.softBad -= amt
	} else {
		b.softBad = 0
		b.badSeen = 0
	}

	return b
}

type candidateDijkstraItem struct {
	node   route.Vertex
	amount lnwire.MilliSatoshi
	score  float64
	risk   float64
	index  int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index = i
	q[j].index = j
}

func (q *candidateDijkstraQueue) Push(x any) {
	item := x.(*candidateDijkstraItem)
	item.index = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	reserved := r.reserved[edge.key]
	need := amt + reserved

	if edge.key.from == r.source {
		balance := r.localBalances[edge.key.chanID]
		if need > balance {
			return 0.005
		}
		return 0.999
	}

	return candidateBeliefProbability(
		r.beliefs[edge.key], need, edge.capacity,
	)
}

func (r *candidateRouter) edgePenalty(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	p, ok := r.penalties[edge.key]
	if !ok || p.amount <= 0 {
		return 0
	}

	need := amt + r.reserved[edge.key]
	ratio := float64(need) / float64(p.amount)
	if ratio > 1 {
		ratio = 1
	}
	if ratio < 0 {
		ratio = 0
	}

	return p.weight * ratio * ratio
}

func (r *candidateRouter) addPenalty(key candidateEdgeKey,
	amt lnwire.MilliSatoshi, weight float64) {

	if amt <= 0 || weight <= 0 {
		return
	}

	p := r.penalties[key]
	if p.amount == 0 || amt < p.amount {
		p.amount = amt
	}
	p.weight += weight
	if p.weight > 16 {
		p.weight = 16
	}
	r.penalties[key] = p
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi) (
	*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}

	best := make(map[route.Vertex]float64)
	bestRisk := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)

	best[r.spec.Target] = 0
	pq := &candidateDijkstraQueue{}
	heap.Push(pq, &candidateDijkstraItem{
		node:   r.spec.Target,
		amount: amt,
	})

	for pq.Len() != 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)
		if score, ok := best[item.node]; ok &&
			item.score > score+1e-12 {

			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			reserved := r.reserved[edge.key]
			if !edge.usable(item.amount, reserved) {
				continue
			}

			if edge.key.from == r.source {
				balance := r.localBalances[edge.key.chanID]
				if item.amount > balance ||
					reserved > balance-item.amount {

					continue
				}
			}

			probability := r.edgeProbability(edge, item.amount)
			if probability <= 0 {
				continue
			}

			sending := item.amount
			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(item.amount)
				sending += fee
			}

			edgeRisk := -math.Log(probability)
			feeCost := 0.0
			if item.amount > 0 {
				feeCost = 0.15 * float64(fee) /
					float64(item.amount)
			}

			score := item.score + edgeRisk + feeCost + 0.01 +
				r.edgePenalty(edge, item.amount)
			risk := item.risk + edgeRisk

			old, ok := best[edge.key.from]
			if !ok || score < old {
				best[edge.key.from] = score
				bestRisk[edge.key.from] = risk
				next[edge.key.from] = edge
				heap.Push(pq, &candidateDijkstraItem{
					node:   edge.key.from,
					amount: sending,
					score:  score,
					risk:   risk,
				})
			}
		}
	}

	if _, ok := best[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}

	return rt, math.Exp(-bestRisk[r.source]), nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	node := r.source
	for node != r.spec.Target {
		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.key.to

		if len(path) > 1000 {
			return nil, errors.New("route contains a cycle")
		}
	}

	if len(path) == 0 {
		return nil, errors.New("source is payment target")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))

	last := len(path) - 1
	amounts[last] = amt
	expiries[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amounts[i] = amounts[i+1] +
			forwardingEdge.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forward := amt
		expiry := uint32(finalCltvDelta)
		if i < last {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateCeilDiv(amount lnwire.MilliSatoshi,
	parts uint32) lnwire.MilliSatoshi {

	if parts <= 1 {
		return amount
	}
	p := lnwire.MilliSatoshi(parts)
	return amount/p + lnwire.MilliSatoshi(boolToInt(amount%p != 0))
}

func boolToInt(v bool) int64 {
	if v {
		return 1
	}
	return 0
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if r.requests >= 48 {
		return nil, errors.New("route attempt budget exhausted")
	}
	r.requests++

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum parts already in flight")
	}
	partsLeft := maxParts - inFlightHtlcs
	minShard := candidateCeilDiv(amt, partsLeft)

	if r.targetShard == 0 {
		fullRoute, fullProbability, fullErr := r.findRoute(amt)
		if fullErr == nil &&
			(partsLeft == 1 || fullProbability >= 0.18 ||
				amt < 10_000_000) {

			r.targetShard = amt
			return fullRoute, nil
		}

		plannedParts := uint32(2)
		if fullErr != nil {
			plannedParts = 2
		} else if fullProbability < 0.008 {
			plannedParts = 4
		} else if fullProbability < 0.025 {
			plannedParts = 3
		}
		if plannedParts > partsLeft {
			plannedParts = partsLeft
		}
		if plannedParts == 0 {
			plannedParts = 1
		}

		r.targetShard = candidateCeilDiv(amt, plannedParts)
	}

	desired := r.targetShard
	if desired > amt {
		desired = amt
	}
	if desired < minShard {
		desired = minShard
	}

	for {
		rt, _, err := r.findRoute(desired)
		if err == nil {
			r.targetShard = desired
			return rt, nil
		}

		if desired <= minShard {
			return nil, err
		}

		next := desired * 2 / 3
		if next < minShard {
			next = minShard
		}
		if next == desired {
			return nil, err
		}
		desired = next
	}
}

func (r *candidateRouter) routeEdges(rt *route.Route) (
	[]candidateEdgeKey, []lnwire.MilliSatoshi) {

	keys := make([]candidateEdgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))

	from := rt.SourcePubKey
	for i, hop := range rt.Hops {
		keys[i] = candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}
		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func (r *candidateRouter) reportedFailureIndex(
	rt *route.Route, source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}
	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}
	return -1
}

func (r *candidateRouter) persistFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	scoped := candidateScopedKey{scope: r.scope, edge: key}

	candidateKnowledge.Lock()
	b := candidateKnowledge.beliefs[scoped]
	candidateKnowledge.beliefs[scoped] =
		candidateObserveFailure(b, amt)
	candidateKnowledge.Unlock()
}

func (r *candidateRouter) persistSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	scoped := candidateScopedKey{scope: r.scope, edge: key}
	reverseKey := candidateEdgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
	reverseScoped := candidateScopedKey{
		scope: r.scope,
		edge:  reverseKey,
	}

	candidateKnowledge.Lock()

	b := candidateKnowledge.beliefs[scoped]
	b = candidateObserveSuccess(b, amt)
	candidateKnowledge.beliefs[scoped] =
		candidateResidualBelief(b, amt)

	reverse := candidateKnowledge.beliefs[reverseScoped]
	reverse = candidateObserveSuccess(reverse, amt)
	candidateKnowledge.beliefs[reverseScoped] = reverse

	candidateKnowledge.Unlock()
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	keys, amounts := r.routeEdges(rt)

	if result.Failure == nil {
		r.failuresSincePass = 0

		for i, key := range keys {
			need := amounts[i] + r.reserved[key]
			r.beliefs[key] = candidateObserveSuccess(
				r.beliefs[key], need,
			)
			r.reserved[key] += amounts[i]

			// Prefer a distinct corridor for the next atomic shard, but
			// retain this one as a fallback at lower cumulative amounts.
			r.addPenalty(key, need, 0.8)
			r.persistSuccess(key, amounts[i])
		}
		return nil
	}

	r.totalFailures++
	r.failuresSincePass++

	failIndex := r.reportedFailureIndex(
		rt, result.FailureSource,
	)

	// Every failed route gets a small, payment-local diversification
	// penalty. Unreadable failures deliberately update no persistent
	// liquidity state.
	for i, key := range keys {
		need := amounts[i] + r.reserved[key]
		r.addPenalty(key, need, 0.45)
	}

	if failIndex >= 0 && failIndex < len(keys) {
		key := keys[failIndex]
		need := amounts[failIndex] + r.reserved[key]

		_, liquidityFailure :=
			result.Failure.(*lnwire.FailTemporaryChannelFailure)

		if liquidityFailure {
			r.addPenalty(key, need, 2.8)

			// Adjacent hops receive only weak local suspicion because the
			// simulator may shift blame by one hop.
			if failIndex > 0 {
				prevNeed := amounts[failIndex-1] +
					r.reserved[keys[failIndex-1]]
				r.addPenalty(
					keys[failIndex-1], prevNeed, 0.35,
				)
			}
			if failIndex+1 < len(keys) {
				nextNeed := amounts[failIndex+1] +
					r.reserved[keys[failIndex+1]]
				r.addPenalty(
					keys[failIndex+1], nextNeed, 0.35,
				)
			}

			r.beliefs[key] = candidateObserveFailure(
				r.beliefs[key], need,
			)
			r.persistFailure(key, amounts[failIndex])
		} else {
			// A policy failure should not become a liquidity bound.
			r.addPenalty(key, need, 5.0)
		}
	}

	// Retry failed corridors at lower amounts instead of permanently
	// blacklisting them. Two same-size alternatives are explored before
	// reducing the planned shard.
	if r.failuresSincePass%2 == 0 && r.targetShard > 1 {
		r.targetShard = r.targetShard * 2 / 3
		if r.targetShard == 0 {
			r.targetShard = 1
		}
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	chanID   uint64
	from     route.Vertex
	to       route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

// Successes are trustworthy. Failures remain soft until several compatible
// reports corroborate the same directed channel.
type candidateBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi

	suspectAmt   lnwire.MilliSatoshi
	suspectVotes uint8

	stamp uint64
}

var candidateMemory = struct {
	sync.Mutex
	epoch   uint64
	beliefs map[candidateEdgeKey]candidateBelief
}{
	beliefs: make(map[candidateEdgeKey]candidateBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec
	epoch  uint64

	incomingEdges map[route.Vertex][]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[candidateEdgeKey]candidateBelief

	// Successful atomic-MPP shards reserve liquidity until completion. This
	// also models liquidity consumed by settled shards for the lifetime of
	// the current payment.
	reserved map[candidateEdgeKey]lnwire.MilliSatoshi

	// These penalties are deliberately payment-local. They diversify retries
	// without poisoning persistent beliefs when failure attribution lies.
	edgePenalty map[candidateEdgeKey]float64

	// Planned routes are constructed together using virtual reservations.
	// This makes the route set account for sibling contention before sending
	// the first shard.
	plannedRoutes []*route.Route

	retryLimit    lnwire.MilliSatoshi
	failedAttempts uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	candidateMemory.Lock()
	candidateMemory.epoch++
	epoch := candidateMemory.epoch

	snapshot := make(map[candidateEdgeKey]candidateBelief,
		len(candidateMemory.beliefs))
	for key, belief := range candidateMemory.beliefs {
		snapshot[key] = belief
	}
	candidateMemory.Unlock()

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		epoch:         epoch,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		localBalances: localBalances,
		beliefs:       snapshot,
		reserved:      make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		edgePenalty:   make(map[candidateEdgeKey]float64),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				// InPolicy is announced by OtherNode and governs the
				// directed edge OtherNode -> node.
				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
					},
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: policy.FeeBaseMSat,
					feeRatePPM: policy.
						FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func candidateClampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005
	case p > 0.995:
		return 0.995
	default:
		return p
	}
}

// Most channels are almost empty or almost full in one direction. The low
// mode falls rapidly, while the high mode has a cliff near usable capacity.
func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.022)
	highMode := 1 / (1 + math.Exp(20*(x-0.84)))

	return candidateClampProbability(
		0.48*lowMode + 0.52*highMode,
	)
}

func (r *candidateRouter) evidenceConfidence(b candidateBelief) float64 {
	if b.stamp == 0 || r.epoch <= b.stamp+4 {
		return 1
	}

	age := float64(r.epoch - b.stamp - 4)
	return math.Max(0.15, math.Exp(-age/14))
}

func (r *candidateRouter) probability(edge *candidateEdge,
	totalAmt lnwire.MilliSatoshi) float64 {

	if edge.from == r.source {
		if totalAmt <= r.localBalances[edge.chanID] {
			return 0.999
		}
		return 0.001
	}

	prior := candidatePrior(totalAmt, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok || belief.stamp == 0 {
		return prior
	}

	learned := prior

	switch {
	case belief.lowerOK > 0 && totalAmt <= belief.lowerOK:
		learned = 0.995

	case belief.upperFail > 0 && totalAmt >= belief.upperFail:
		learned = 0.008

	case belief.lowerOK > 0 && belief.upperFail > belief.lowerOK:
		span := float64(belief.upperFail - belief.lowerOK)
		pos := float64(totalAmt-belief.lowerOK) / span
		pos = math.Max(0, math.Min(1, pos))
		learned = 0.995*(1-pos) + 0.008*pos

	case belief.lowerOK > 0 && totalAmt > belief.lowerOK:
		ratio := float64(belief.lowerOK) / float64(totalAmt)
		learned = prior + (0.995-prior)*ratio*ratio

	case belief.upperFail > 0 && totalAmt < belief.upperFail:
		ratio := float64(totalAmt) / float64(belief.upperFail)
		learned = prior * (1 - 0.72*ratio*ratio)
	}

	// One plausible but uncorroborated report is only a hint because blame
	// may have moved to an adjacent hop.
	if belief.upperFail == 0 && belief.suspectAmt > 0 &&
		totalAmt >= belief.suspectAmt {

		learned *= 0.65
	}

	confidence := r.evidenceConfidence(belief)
	return candidateClampProbability(
		confidence*learned + (1-confidence)*prior,
	)
}

type candidateItem struct {
	node  route.Vertex
	score float64
}

type candidateQueue []*candidateItem

func (q candidateQueue) Len() int {
	return len(q)
}

func (q candidateQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *candidateQueue) Push(value any) {
	*q = append(*q, value.(*candidateItem))
}

func (q *candidateQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]
	return last
}

type candidatePath struct {
	route       *route.Route
	edges       []*candidateEdge
	probability float64
	pressure    float64
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*candidatePath, error) {

	if amt <= 0 {
		return nil, errors.New("invalid payment amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is target")
	}

	scores := make(map[route.Vertex]float64)
	amounts := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)

	scores[r.spec.Target] = 0
	amounts[r.spec.Target] = amt

	pq := &candidateQueue{}
	heap.Push(pq, &candidateItem{
		node:  r.spec.Target,
		score: 0,
	})

	for pq.Len() != 0 {
		item := heap.Pop(pq).(*candidateItem)
		bestScore, ok := scores[item.node]
		if !ok || item.score > bestScore+1e-12 {
			continue
		}
		if item.node == r.source {
			break
		}

		arriving := amounts[item.node]

		for _, edge := range r.incomingEdges[item.node] {
			if !edge.usable(arriving) {
				continue
			}

			totalLiquidity := arriving + r.reserved[edge.key]
			if totalLiquidity < arriving ||
				totalLiquidity > edge.capacity {

				continue
			}

			if edge.from == r.source &&
				totalLiquidity > r.localBalances[edge.chanID] {

				continue
			}

			sending := arriving
			fee := lnwire.MilliSatoshi(0)
			if edge.from != r.source {
				fee = edge.fee(arriving)
				sending += fee
				if sending < arriving {
					continue
				}
			}

			probability := r.probability(edge, totalLiquidity)
			edgeCost := -math.Log(probability) + 0.02

			if arriving > 0 {
				edgeCost += 4.2 * float64(fee) /
					float64(arriving)
			}

			edgeCost += r.edgePenalty[edge.key]

			// Reusing an already-held corridor remains possible, but a
			// fresh corridor is preferred for atomic-MPP siblings.
			if edge.from != r.source &&
				r.reserved[edge.key] > 0 &&
				edge.capacity > 0 {

				reuse := float64(r.reserved[edge.key]) /
					float64(edge.capacity)
				edgeCost += 0.35 + 0.9*math.Sqrt(reuse)
			}

			newScore := item.score + edgeCost
			oldScore, visited := scores[edge.from]
			if visited && newScore >= oldScore {
				continue
			}

			scores[edge.from] = newScore
			amounts[edge.from] = sending
			next[edge.from] = edge
			heap.Push(pq, &candidateItem{
				node:  edge.from,
				score: newScore,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	rt, path, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, err
	}

	probability := 1.0
	pressure := 0.0

	for i, edge := range path {
		amtOver := candidateRouteAmount(rt, i)
		totalLiquidity := amtOver + r.reserved[edge.key]

		probability *= r.probability(edge, totalLiquidity)

		denominator := edge.capacity
		if edge.from == r.source {
			denominator = r.localBalances[edge.chanID]
		} else if belief, ok := r.beliefs[edge.key]; ok &&
			belief.upperFail > 0 &&
			r.evidenceConfidence(belief) >= 0.75 &&
			belief.upperFail < denominator {

			denominator = belief.upperFail
		}

		if denominator > 0 {
			ratio := float64(totalLiquidity) /
				float64(denominator)
			if ratio > pressure {
				pressure = ratio
			}
		}
	}

	return &candidatePath{
		route:       rt,
		edges:       path,
		probability: probability,
		pressure:    pressure,
	}, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route,
	[]*candidateEdge, error) {

	const finalCltvDelta = uint32(40)

	var path []*candidateEdge
	seen := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if seen[node] {
			return nil, nil, errors.New("cycle in route")
		}
		seen[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.to
	}

	if len(path) == 0 {
		return nil, nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := finalCltvDelta

		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, path, nil
}

func candidateCeilDiv(a lnwire.MilliSatoshi,
	b uint32) lnwire.MilliSatoshi {

	if b <= 1 {
		return a
	}

	divisor := lnwire.MilliSatoshi(b)
	return a/divisor + boolToMSat(a%divisor != 0)
}

func boolToMSat(value bool) lnwire.MilliSatoshi {
	if value {
		return 1
	}
	return 0
}

func candidateCloneAmountMap(
	source map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	result := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(source))
	for key, value := range source {
		result[key] = value
	}
	return result
}

func candidateClonePenaltyMap(
	source map[candidateEdgeKey]float64,
) map[candidateEdgeKey]float64 {

	result := make(map[candidateEdgeKey]float64, len(source))
	for key, value := range source {
		result[key] = value
	}
	return result
}

// planRouteSet chooses all shard routes against virtual reservations. Later
// shards therefore see the capacity claimed by earlier siblings, and route
// diversity is selected before attempts allow the network to drift.
func (r *candidateRouter) planRouteSet(
	total lnwire.MilliSatoshi, numParts uint32) ([]*route.Route, error) {

	if numParts < 2 {
		return nil, errors.New("route set requires multiple parts")
	}

	savedReserved := r.reserved
	savedPenalty := r.edgePenalty

	r.reserved = candidateCloneAmountMap(savedReserved)
	r.edgePenalty = candidateClonePenaltyMap(savedPenalty)

	defer func() {
		r.reserved = savedReserved
		r.edgePenalty = savedPenalty
	}()

	routes := make([]*route.Route, 0, numParts)
	remaining := total

	for part := uint32(0); part < numParts; part++ {
		partsRemaining := numParts - part
		shard := candidateCeilDiv(remaining, partsRemaining)

		path, err := r.findRoute(shard)
		if err != nil {
			return nil, err
		}

		routes = append(routes, path.route)
		remaining -= shard

		for i, edge := range path.edges {
			key := edge.key
			r.reserved[key] += candidateRouteAmount(
				path.route, i,
			)

			// Sharing the sender's limited local channels is sometimes
			// unavoidable. Internal corridors receive a stronger virtual
			// diversity price.
			if edge.from == r.source {
				r.edgePenalty[key] += 0.12
			} else {
				r.edgePenalty[key] += 1.05
			}
		}
	}

	if remaining != 0 {
		return nil, errors.New("incomplete route set")
	}

	return routes, nil
}

func (r *candidateRouter) preferredPartCount(
	full *candidatePath, fullErr error,
	partsLeft uint32) uint32 {

	maxParts := partsLeft
	if maxParts > 12 {
		maxParts = 12
	}
	if maxParts < 2 {
		return 1
	}

	preferred := uint32(2)

	if fullErr != nil {
		preferred = 4
	} else {
		capacityParts := uint32(math.Ceil(
			full.pressure / 0.42,
		))
		if capacityParts > preferred {
			preferred = capacityParts
		}

		switch {
		case full.probability < 0.16:
			if preferred < 4 {
				preferred = 4
			}
		case full.probability < 0.38:
			if preferred < 3 {
				preferred = 3
			}
		}
	}

	if r.failedAttempts > 0 && preferred < 3 {
		preferred = 3
	}

	if preferred > maxParts {
		preferred = maxParts
	}
	return preferred
}

func candidateDeliveredAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func (r *candidateRouter) takePlannedRoute(
	remaining lnwire.MilliSatoshi,
	partsLeft uint32) (*route.Route, bool) {

	if len(r.plannedRoutes) == 0 {
		return nil, false
	}

	if partsLeft <= 1 {
		r.plannedRoutes = nil
		return nil, false
	}

	rt := r.plannedRoutes[0]
	delivered := candidateDeliveredAmount(rt)
	if delivered <= 0 || delivered > remaining {
		r.plannedRoutes = nil
		return nil, false
	}

	r.plannedRoutes = r.plannedRoutes[1:]
	return rt, true
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid remaining amount")
	}

	partsLeft := uint32(1)
	if r.spec.MaxParts > inFlightHtlcs {
		partsLeft = r.spec.MaxParts - inFlightHtlcs
	}

	if rt, ok := r.takePlannedRoute(amt, partsLeft); ok {
		return rt, nil
	}

	// The final available part must carry the complete remainder.
	if partsLeft <= 1 {
		path, err := r.findRoute(amt)
		if err != nil {
			return nil, err
		}
		return path.route, nil
	}

	full, fullErr := r.findRoute(amt)

	// Whole payments avoid unnecessary MPP fees when evidence makes the
	// route genuinely convincing. A previous failure raises this bar.
	wholeThreshold := 0.76
	if r.failedAttempts > 0 {
		wholeThreshold = 0.92
	}

	if fullErr == nil &&
		(full.probability >= wholeThreshold ||
			(amt <= 15_000_000 &&
				full.probability >= 0.48)) {

		return full.route, nil
	}

	preferred := r.preferredPartCount(
		full, fullErr, partsLeft,
	)

	maxPlanParts := partsLeft
	if maxPlanParts > 12 {
		maxPlanParts = 12
	}

	// Try increasingly fine joint plans. This is computation rather than a
	// probe ladder: no attempt is spent until a complete route set exists.
	for numParts := preferred; numParts <= maxPlanParts; numParts++ {
		plans, err := r.planRouteSet(amt, numParts)
		if err != nil {
			continue
		}

		r.plannedRoutes = plans
		rt := r.plannedRoutes[0]
		r.plannedRoutes = r.plannedRoutes[1:]
		return rt, nil
	}

	// If a complete route set cannot be formed, retain success-oriented
	// fallback behavior. Corroborated bounds are probabilities rather than
	// permanent exclusions, so a necessary corridor remains reachable.
	if fullErr == nil && r.failedAttempts == 0 {
		return full.route, nil
	}

	desired := r.retryLimit
	if desired <= 0 || desired > amt {
		desired = candidateCeilDiv(amt, partsLeft)
	}

	const minimumShard = lnwire.MilliSatoshi(500_000)
	var lastErr error

	for {
		path, err := r.findRoute(desired)
		if err == nil {
			return path.route, nil
		}
		lastErr = err

		if desired <= minimumShard {
			break
		}

		smaller := desired * 55 / 100
		if smaller < minimumShard {
			smaller = minimumShard
		}
		if smaller >= desired {
			break
		}

		desired = smaller
		r.retryLimit = smaller
	}

	if fullErr == nil {
		return full.route, nil
	}
	return nil, lastErr
}

func candidateRouteAmount(rt *route.Route,
	edgeIndex int) lnwire.MilliSatoshi {

	if edgeIndex == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[edgeIndex-1].AmtToForward
}

func candidateRouteEdgeKey(rt *route.Route,
	edgeIndex int) candidateEdgeKey {

	from := rt.SourcePubKey
	if edgeIndex > 0 {
		from = rt.Hops[edgeIndex-1].PubKeyBytes
	}

	return candidateEdgeKey{
		chanID: rt.Hops[edgeIndex].ChannelID,
		from:   from,
	}
}

func candidateFailureEdge(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func candidateIsLiquidityFailure(failure any) bool {
	switch failure.(type) {
	case *lnwire.FailTemporaryChannelFailure:
		return true
	default:
		return false
	}
}

func candidateIsPolicyFailure(failure any) bool {
	switch failure.(type) {
	case *lnwire.FailFeeInsufficient,
		*lnwire.FailIncorrectCltvExpiry:

		return true
	default:
		return false
	}
}

func (r *candidateRouter) saveBelief(
	key candidateEdgeKey, belief candidateBelief) {

	belief.stamp = r.epoch
	r.beliefs[key] = belief

	candidateMemory.Lock()
	candidateMemory.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) recordSuccess(key candidateEdgeKey,
	totalAmt lnwire.MilliSatoshi) {

	belief := r.beliefs[key]

	if totalAmt > belief.lowerOK {
		belief.lowerOK = totalAmt
	}

	// A truthful settlement disproves contradictory failure observations.
	if belief.upperFail > 0 && totalAmt >= belief.upperFail {
		belief.upperFail = 0
	}
	if belief.suspectAmt > 0 && totalAmt >= belief.suspectAmt {
		belief.suspectAmt = 0
		belief.suspectVotes = 0
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) recordFailure(key candidateEdgeKey,
	totalAmt lnwire.MilliSatoshi) {

	belief := r.beliefs[key]

	corroborates := false
	if belief.suspectAmt > 0 {
		low := belief.suspectAmt * 60 / 100
		high := belief.suspectAmt * 155 / 100
		corroborates = totalAmt >= low && totalAmt <= high
	}

	if corroborates {
		if belief.suspectVotes < 255 {
			belief.suspectVotes++
		}
		if totalAmt < belief.suspectAmt {
			belief.suspectAmt = totalAmt
		}
	} else {
		belief.suspectAmt = totalAmt
		belief.suspectVotes = 1
	}

	// Three compatible reports make accidental repeated shifted blame rare.
	requiredVotes := uint8(3)
	if belief.lowerOK > 0 && totalAmt <= belief.lowerOK {
		requiredVotes = 4
	}

	if belief.suspectVotes >= requiredVotes {
		if totalAmt <= belief.lowerOK {
			belief.lowerOK = 0
		}

		if belief.upperFail == 0 ||
			belief.suspectAmt < belief.upperFail {

			belief.upperFail = belief.suspectAmt
		}
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if rt == nil || len(rt.Hops) == 0 {
		return nil
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key := candidateRouteEdgeKey(rt, i)
			amtOver := candidateRouteAmount(rt, i)
			totalAmt := amtOver + r.reserved[key]

			r.recordSuccess(key, totalAmt)
			r.reserved[key] += amtOver
			r.edgePenalty[key] *= 0.35
		}
		return nil
	}

	r.failedAttempts++

	// The route certainly failed, even if its onion attribution is unreadable
	// or shifted. Diversify softly across every edge without persisting this
	// route-level fact as false liquidity knowledge.
	for i := range rt.Hops {
		key := candidateRouteEdgeKey(rt, i)
		r.edgePenalty[key] = math.Min(
			4.5, r.edgePenalty[key]+0.42,
		)
	}

	failIndex := candidateFailureEdge(
		rt, result.FailureSource,
	)
	attributed := failIndex >= 0 && failIndex < len(rt.Hops)

	delivered := candidateDeliveredAmount(rt)

	if candidateIsLiquidityFailure(result.Failure) && attributed {
		key := candidateRouteEdgeKey(rt, failIndex)
		amtOver := candidateRouteAmount(rt, failIndex)
		totalAmt := amtOver + r.reserved[key]

		r.recordFailure(key, totalAmt)
		r.edgePenalty[key] = math.Min(
			7, r.edgePenalty[key]+1.15,
		)

		lowerRetry := delivered * 55 / 100
		if lowerRetry < 500_000 {
			lowerRetry = 500_000
		}
		if r.retryLimit == 0 || lowerRetry < r.retryLimit {
			r.retryLimit = lowerRetry
		}

		return nil
	}

	if candidateIsPolicyFailure(result.Failure) && attributed {
		key := candidateRouteEdgeKey(rt, failIndex)
		r.edgePenalty[key] = math.Min(
			7, r.edgePenalty[key]+1.8,
		)
		return nil
	}

	// An unreadable failure supplies no channel-level evidence. Preserve any
	// jointly planned sibling routes; if they are exhausted, use a moderately
	// smaller fallback rather than repeating the same route indefinitely.
	lowerRetry := delivered * 70 / 100
	if lowerRetry < 500_000 {
		lowerRetry = 500_000
	}
	if r.retryLimit == 0 || lowerRetry < r.retryLimit {
		r.retryLimit = lowerRetry
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK lnwire.MilliSatoshi
	estimate lnwire.MilliSatoshi
	conf     uint8

	failAmt    lnwire.MilliSatoshi
	failWeight float64
}

var candidateBeliefStore = struct {
	sync.Mutex
	beliefs map[candidateEdgeKey]*candidateBelief
}{
	beliefs: make(map[candidateEdgeKey]*candidateBelief),
}

type candidateLocalFailure struct {
	upper  lnwire.MilliSatoshi
	weight float64
}

type candidateTraversal struct {
	key  candidateEdgeKey
	edge *candidateEdge
	amt  lnwire.MilliSatoshi
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	reserved    map[candidateEdgeKey]lnwire.MilliSatoshi
	usedTotals  map[candidateEdgeKey]lnwire.MilliSatoshi
	localFails  map[candidateEdgeKey]candidateLocalFailure
	edgePenalty map[candidateEdgeKey]float64
	routeFails  map[uint64]float64

	plannedParts uint32
	failures     uint32
	unknownFails uint32
	retryCap     lnwire.MilliSatoshi
	delivered    lnwire.MilliSatoshi
	settled      bool
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[candidateEdgeKey]*candidateEdge),
		localBalances: localBalances,
		reserved:      make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		usedTotals:    make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		localFails:    make(map[candidateEdgeKey]candidateLocalFailure),
		edgePenalty:   make(map[candidateEdgeKey]float64),
		routeFails:    make(map[uint64]float64),
	}

	r.plannedParts = r.initialPartCount(spec.Amount)
	if spec.MaxParts != 0 && r.plannedParts > spec.MaxParts {
		r.plannedParts = spec.MaxParts
	}
	if r.plannedParts == 0 {
		r.plannedParts = 1
	}

	ctx := context.Background()
	seen := make(map[route.Vertex]bool)
	queue := []route.Vertex{source}
	seen[source] = true

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[key] = edge
				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func (r *candidateRouter) initialPartCount(
	amt lnwire.MilliSatoshi) uint32 {

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}

	switch {
	case amt <= 25_000_000:
		return 1
	case amt <= 100_000_000:
		return minCandidateParts(2, maxParts)
	case amt <= 500_000_000:
		return minCandidateParts(4, maxParts)
	case amt <= 2_000_000_000:
		return minCandidateParts(8, maxParts)
	default:
		return maxParts
	}
}

func minCandidateParts(a, b uint32) uint32 {
	if a < b {
		return a
	}
	return b
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.003
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.48 * math.Exp(-x/0.025)
	highMode := 0.50 / (1 + math.Exp((x-0.90)/0.025))
	p := 0.005 + lowMode + highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func candidateLogisticProbability(amt, estimate,
	capacity lnwire.MilliSatoshi) float64 {

	if capacity <= 0 {
		return 0.005
	}

	scale := 0.065 * float64(capacity)
	if scale < 1 {
		scale = 1
	}

	z := (float64(amt) - float64(estimate)) / scale
	if z > 30 {
		return 0.005
	}
	if z < -30 {
		return 0.995
	}
	return 1 / (1 + math.Exp(z))
}

func (r *candidateRouter) edgeProbability(e *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	required := amt + r.reserved[e.key]
	if required > e.capacity {
		return 0.001
	}

	if e.key.from == r.source {
		if r.localBalances[e.key.chanID] < required {
			return 0.001
		}
		return 0.999
	}

	p := candidatePrior(required, e.capacity)

	candidateBeliefStore.Lock()
	stored, ok := candidateBeliefStore.beliefs[e.key]
	var belief candidateBelief
	if ok {
		belief = *stored
	}
	candidateBeliefStore.Unlock()

	if ok {
		if belief.estimate > 0 && belief.conf > 0 {
			q := candidateLogisticProbability(
				required, belief.estimate, e.capacity,
			)
			weight := 0.13 * float64(belief.conf)
			if weight > 0.72 {
				weight = 0.72
			}
			p = (1-weight)*p + weight*q
		}

		if belief.lowerOK > 0 && required <= belief.lowerOK {
			p = math.Max(p, 0.995)
		}

		if belief.failAmt > 0 && required >= belief.failAmt {
			if belief.failWeight >= 1.55 {
				p = math.Min(p, 0.009)
			} else {
				p *= math.Exp(-0.28 * belief.failWeight)
			}
		} else if belief.failAmt > belief.lowerOK &&
			belief.lowerOK > 0 && required > belief.lowerOK {

			span := float64(belief.failAmt - belief.lowerOK)
			pos := float64(required-belief.lowerOK) / span
			if pos > 1 {
				pos = 1
			}
			bounded := 0.995*(1-pos) + 0.009*pos
			weight := 0.25 + 0.25*math.Min(
				belief.failWeight, 1,
			)
			p = (1-weight)*p + weight*bounded
		}
	}

	if local, ok := r.localFails[e.key]; ok &&
		required >= local.upper {

		if local.weight >= 1.55 {
			p = math.Min(p, 0.005)
		} else {
			p *= math.Exp(-0.95 * local.weight)
		}
	}

	if p < 0.003 {
		return 0.003
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

func (r *candidateRouter) edgeCost(e *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	p := r.edgeProbability(e, amt)
	cost := -math.Log(p) + 0.012 + r.edgePenalty[e.key]

	if reserved := r.reserved[e.key]; reserved > 0 &&
		e.capacity > 0 {

		share := float64(reserved) / float64(e.capacity)
		cost += 0.90 + 0.80*share
	}

	return cost
}

type candidateDijkstraItem struct {
	node  route.Vertex
	score float64
	amt   lnwire.MilliSatoshi
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *candidateDijkstraQueue) Push(x any) {
	*q = append(*q, x.(*candidateDijkstraItem))
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}

	score := make(map[route.Vertex]float64)
	arriving := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)

	score[r.spec.Target] = 0
	arriving[r.spec.Target] = amt

	pq := &candidateDijkstraQueue{}
	heap.Push(pq, &candidateDijkstraItem{
		node: r.spec.Target,
		amt:  amt,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)
		bestScore, ok := score[item.node]
		if !ok || item.score > bestScore+1e-12 {
			continue
		}
		if item.amt != arriving[item.node] {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOver := item.amt
			if !edge.policyAllows(amtOver) {
				continue
			}

			required := amtOver + r.reserved[edge.key]
			if required > edge.capacity {
				continue
			}
			if edge.key.from == r.source &&
				r.localBalances[edge.key.chanID] < required {

				continue
			}

			sending := amtOver
			feeCost := 0.0
			if edge.key.from != r.source {
				fee := edge.fee(amtOver)
				sending += fee

				denom := float64(amt)
				if denom < 1 {
					denom = 1
				}
				feeCost = 16 * float64(fee) / denom
			}

			newScore := item.score +
				r.edgeCost(edge, amtOver) + feeCost

			oldScore, exists := score[edge.key.from]
			if exists && newScore >= oldScore {
				continue
			}

			score[edge.key.from] = newScore
			arriving[edge.key.from] = sending
			next[edge.key.from] = edge
			heap.Push(pq, &candidateDijkstraItem{
				node:  edge.key.from,
				score: newScore,
				amt:   sending,
			})
		}
	}

	if _, ok := score[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}

	pathProbability := 1.0
	for _, traversal := range r.routeTraversals(rt) {
		pathProbability *= r.edgeProbability(
			traversal.edge, traversal.amt,
		)
	}
	if pathProbability < 1e-300 {
		pathProbability = 1e-300
	}

	return rt, pathProbability, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateCeilDiv(amt lnwire.MilliSatoshi,
	parts uint32) lnwire.MilliSatoshi {

	if parts <= 1 {
		return amt
	}
	divisor := lnwire.MilliSatoshi(parts)
	return (amt + divisor - 1) / divisor
}

func (r *candidateRouter) targetPartCount() uint32 {
	target := r.plannedParts

	if r.failures > 0 {
		target += 1 + r.failures/3
	}
	if r.unknownFails >= 2 {
		target++
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if target > maxParts {
		target = maxParts
	}
	if target == 0 {
		target = 1
	}
	return target
}

func appendCandidateAmount(amounts *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, amt, minimum,
	maximum lnwire.MilliSatoshi) {

	if amt < minimum {
		amt = minimum
	}
	if amt > maximum {
		amt = maximum
	}
	if amt <= 0 || seen[amt] {
		return
	}

	seen[amt] = true
	*amounts = append(*amounts, amt)
}

func candidateRouteSignature(rt *route.Route) uint64 {
	const (
		offset = uint64(1469598103934665603)
		prime  = uint64(1099511628211)
	)

	h := offset
	for _, hop := range rt.Hops {
		v := hop.ChannelID
		for i := 0; i < 8; i++ {
			h ^= v & 0xff
			h *= prime
			v >>= 8
		}
	}
	return h
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum parts already in flight")
	}

	partsLeft := maxParts - inFlightHtlcs
	minimum := candidateCeilDiv(amt, partsLeft)

	targetParts := r.targetPartCount()
	desiredSlots := uint32(1)
	if targetParts > inFlightHtlcs {
		desiredSlots = targetParts - inFlightHtlcs
	}
	if desiredSlots > partsLeft {
		desiredSlots = partsLeft
	}

	desired := candidateCeilDiv(amt, desiredSlots)
	maximum := amt
	if r.retryCap > 0 && r.retryCap < maximum {
		maximum = r.retryCap
	}
	if maximum < minimum {
		maximum = minimum
	}

	var amounts []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)

	appendCandidateAmount(&amounts, seen, desired, minimum, maximum)
	appendCandidateAmount(
		&amounts, seen, desired+desired/3, minimum, maximum,
	)
	appendCandidateAmount(
		&amounts, seen, desired+desired/2, minimum, maximum,
	)
	appendCandidateAmount(
		&amounts, seen, desired*2, minimum, maximum,
	)
	appendCandidateAmount(&amounts, seen, maximum, minimum, maximum)
	appendCandidateAmount(
		&amounts, seen, (desired+minimum)/2, minimum, maximum,
	)
	appendCandidateAmount(&amounts, seen, minimum, minimum, maximum)

	var (
		bestRoute   *route.Route
		bestUtility = math.Inf(-1)
		lastErr     error
	)

	for _, shard := range amounts {
		rt, probability, err := r.findRoute(shard)
		if err != nil {
			lastErr = err
			continue
		}

		progress := float64(shard) / float64(minimum)
		if progress < 1 {
			progress = 1
		}

		delivered := candidateDeliveredAmount(rt)
		feeRatio := 0.0
		if delivered > 0 && rt.TotalAmount > delivered {
			feeRatio = float64(rt.TotalAmount-delivered) /
				float64(delivered)
		}

		signature := candidateRouteSignature(rt)
		utility := math.Log(probability) +
			0.28*math.Log(progress) -
			4.0*feeRatio -
			0.24*r.routeFails[signature]

		if utility > bestUtility {
			bestUtility = utility
			bestRoute = rt
		}
	}

	if bestRoute != nil {
		return bestRoute, nil
	}
	if lastErr != nil {
		return nil, lastErr
	}
	return nil, errors.New("no route found")
}

func (r *candidateRouter) routeTraversals(
	rt *route.Route) []candidateTraversal {

	traversals := make([]candidateTraversal, 0, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		key := candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		edge := r.edges[key]
		if edge == nil {
			from = hop.PubKeyBytes
			continue
		}

		amt := rt.TotalAmount
		if i > 0 {
			amt = rt.Hops[i-1].AmtToForward
		}

		traversals = append(traversals, candidateTraversal{
			key:  key,
			edge: edge,
			amt:  amt,
		})
		from = hop.PubKeyBytes
	}

	return traversals
}

func candidateDeliveredAmount(rt *route.Route) lnwire.MilliSatoshi {
	if len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func (r *candidateRouter) recordSuccess(rt *route.Route) {
	traversals := r.routeTraversals(rt)

	candidateBeliefStore.Lock()
	for _, traversal := range traversals {
		required := traversal.amt + r.reserved[traversal.key]
		b := candidateBeliefStore.beliefs[traversal.key]
		if b == nil {
			b = &candidateBelief{}
			candidateBeliefStore.beliefs[traversal.key] = b
		}

		if required > b.lowerOK {
			b.lowerOK = required
		}

		highEstimate := traversal.edge.capacity * 88 / 100
		if required > highEstimate {
			highEstimate = required
		}
		if highEstimate > b.estimate {
			b.estimate = highEstimate
		}
		if b.conf < 8 {
			b.conf++
		}

		if b.failAmt > 0 && required >= b.failAmt {
			b.failAmt = 0
			b.failWeight = 0
		}
	}
	candidateBeliefStore.Unlock()

	for _, traversal := range traversals {
		required := traversal.amt + r.reserved[traversal.key]
		if local, ok := r.localFails[traversal.key]; ok &&
			required >= local.upper {

			delete(r.localFails, traversal.key)
		}

		r.reserved[traversal.key] += traversal.amt
		r.usedTotals[traversal.key] += traversal.amt
	}

	delete(r.routeFails, candidateRouteSignature(rt))

	r.delivered += candidateDeliveredAmount(rt)
	if r.delivered >= r.spec.Amount && !r.settled {
		r.recordSettlement()
		r.settled = true
	}
}

func (r *candidateRouter) recordSettlement() {
	candidateBeliefStore.Lock()
	defer candidateBeliefStore.Unlock()

	for key, used := range r.usedTotals {
		if used <= 0 {
			continue
		}

		if b := candidateBeliefStore.beliefs[key]; b != nil {
			if b.lowerOK > used {
				b.lowerOK -= used
			} else {
				b.lowerOK = 0
			}
			if b.estimate > used {
				b.estimate -= used
			} else {
				b.estimate = 0
			}
			if b.failAmt > used {
				b.failAmt -= used
			} else {
				b.failAmt = 0
				b.failWeight = 0
			}
		}

		reverse := candidateEdgeKey{
			chanID: key.chanID,
			from:   key.to,
			to:     key.from,
		}
		reverseBelief := candidateBeliefStore.beliefs[reverse]
		if reverseBelief == nil {
			reverseBelief = &candidateBelief{}
			candidateBeliefStore.beliefs[reverse] = reverseBelief
		}

		reverseCapacity := lnwire.MilliSatoshi(0)
		if edge := r.edges[reverse]; edge != nil {
			reverseCapacity = edge.capacity
		} else if edge := r.edges[key]; edge != nil {
			reverseCapacity = edge.capacity
		}

		reverseBelief.lowerOK += used
		reverseBelief.estimate += used
		if reverseCapacity > 0 {
			if reverseBelief.lowerOK > reverseCapacity {
				reverseBelief.lowerOK = reverseCapacity
			}
			if reverseBelief.estimate > reverseCapacity {
				reverseBelief.estimate = reverseCapacity
			}
		}

		if reverseBelief.failAmt > 0 {
			reverseBelief.failAmt += used
			if reverseCapacity > 0 &&
				reverseBelief.failAmt > reverseCapacity {

				reverseBelief.failAmt = reverseCapacity
			}
		}
	}
}

func (r *candidateRouter) failureIndex(rt *route.Route,
	source route.Vertex) ([]candidateTraversal, int, bool) {

	traversals := r.routeTraversals(rt)
	if len(traversals) != len(rt.Hops) {
		return nil, -1, false
	}

	if source == rt.SourcePubKey {
		return traversals, 0, true
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes != source {
			continue
		}

		index := i + 1
		if index >= len(traversals) {
			return nil, -1, false
		}
		return traversals, index, true
	}

	return nil, -1, false
}

func (r *candidateRouter) observeLiquidityFailure(
	traversal candidateTraversal, weight float64) {

	if weight <= 0 || traversal.key.from == r.source {
		return
	}

	required := traversal.amt + r.reserved[traversal.key]

	local := r.localFails[traversal.key]
	if local.upper == 0 || required < local.upper {
		local.upper = required
	}
	local.weight += weight
	if local.weight > 4 {
		local.weight = 4
	}
	r.localFails[traversal.key] = local

	candidateBeliefStore.Lock()
	defer candidateBeliefStore.Unlock()

	b := candidateBeliefStore.beliefs[traversal.key]
	if b == nil {
		b = &candidateBelief{}
		candidateBeliefStore.beliefs[traversal.key] = b
	}

	if b.failAmt == 0 || required < b.failAmt {
		b.failAmt = required
	}
	b.failWeight += weight
	if b.failWeight > 4 {
		b.failWeight = 4
	}

	if b.failWeight >= 1.55 {
		failedEstimate := b.failAmt * 70 / 100
		if b.estimate == 0 || failedEstimate < b.estimate {
			b.estimate = failedEstimate
		}
		if b.conf < 8 {
			b.conf++
		}
	}
}

func (r *candidateRouter) recordAttributedLiquidityFailure(
	traversals []candidateTraversal, index int) {

	for i, traversal := range traversals {
		distance := i - index
		if distance < 0 {
			distance = -distance
		}

		switch distance {
		case 0:
			r.edgePenalty[traversal.key] += 0.90
			r.observeLiquidityFailure(traversal, 0.78)

		case 1:
			r.edgePenalty[traversal.key] += 0.14
			r.observeLiquidityFailure(traversal, 0.11)
		}
	}
}

func (r *candidateRouter) lowerRetryCap(
	amount lnwire.MilliSatoshi, numerator int64) {

	if amount <= 1 {
		return
	}

	cap := amount * lnwire.MilliSatoshi(numerator) / 100
	if cap < 1 {
		cap = 1
	}
	if r.retryCap == 0 || cap < r.retryCap {
		r.retryCap = cap
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64,
	rt *route.Route, result routing.SimHtlcResult) error {

	if result.Failure == nil {
		r.retryCap = 0
		r.recordSuccess(rt)
		return nil
	}

	r.failures++
	signature := candidateRouteSignature(rt)
	r.routeFails[signature] += 1

	traversals := r.routeTraversals(rt)
	for _, traversal := range traversals {
		r.edgePenalty[traversal.key] += 0.035
	}

	code := result.Failure.Code()
	if code == lnwire.CodeTemporaryChannelFailure {
		attemptTraversals, index, ok := r.failureIndex(
			rt, result.FailureSource,
		)
		if ok {
			r.recordAttributedLiquidityFailure(
				attemptTraversals, index,
			)
			r.lowerRetryCap(candidateDeliveredAmount(rt), 64)
			return nil
		}
	}

	r.unknownFails++
	for _, traversal := range traversals {
		r.edgePenalty[traversal.key] += 0.20
	}

	if code == lnwire.CodeFeeInsufficient ||
		code == lnwire.CodeIncorrectCltvExpiry {

		attemptTraversals, index, ok := r.failureIndex(
			rt, result.FailureSource,
		)
		if ok {
			attemptTraversals[index].edgePenaltyFallback(r)
			if index > 0 {
				r.edgePenalty[
					attemptTraversals[index-1].key
				] += 0.25
			}
			if index+1 < len(attemptTraversals) {
				r.edgePenalty[
					attemptTraversals[index+1].key
				] += 0.25
			}
		}
	}

	r.lowerRetryCap(candidateDeliveredAmount(rt), 76)
	return nil
}

func (t candidateTraversal) edgePenaltyFallback(r *candidateRouter) {
	r.edgePenalty[t.key] += 2.25
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40
	riskWeight     = 2_500_000.0
)

type edgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
	cap    lnwire.MilliSatoshi
}

type liquidityBelief struct {
	lowerOK lnwire.MilliSatoshi
	upper   lnwire.MilliSatoshi

	estimate  lnwire.MilliSatoshi
	confidence float64

	suspectAmt   lnwire.MilliSatoshi
	failVotes    uint8
	lastFailPath uint64
}

var sharedBeliefs = struct {
	sync.Mutex
	m map[edgeKey]liquidityBelief
}{
	m: make(map[edgeKey]liquidityBelief),
}

type candidateEdge struct {
	key      edgeKey
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usableHTLC(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return amt <= e.capacity
}

type edgeUse struct {
	edge   *candidateEdge
	amount lnwire.MilliSatoshi
}

type searchResult struct {
	rt      *route.Route
	path    []*candidateEdge
	uses    []edgeUse
	logProb float64
	fee     lnwire.MilliSatoshi
}

type plannedRoute struct {
	result *searchResult
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeByKey     map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[edgeKey]liquidityBelief

	// reserved includes successful shards and routes returned but not yet
	// reported. This prevents atomic MPP siblings from double-spending a
	// corridor.
	reserved map[edgeKey]lnwire.MilliSatoshi
	issued   map[*route.Route][]edgeUse

	// penalty is payment-local. Unlike shared beliefs, it can react
	// aggressively without permanently poisoning later payments.
	penalty map[edgeKey]float64

	// tried records the smallest failed delivery amount for an exact path.
	// The same path remains eligible at a lower amount.
	tried map[uint64]lnwire.MilliSatoshi

	plan         []plannedRoute
	retryCeiling lnwire.MilliSatoshi
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edgeByKey:     make(map[edgeKey]*candidateEdge),
		localBalances: make(map[uint64]lnwire.MilliSatoshi),
		beliefs:       make(map[edgeKey]liquidityBelief),
		reserved:      make(map[edgeKey]lnwire.MilliSatoshi),
		issued:        make(map[*route.Route][]edgeUse),
		penalty:       make(map[edgeKey]float64),
		tried:         make(map[uint64]lnwire.MilliSatoshi),
	}

	for id, balance := range localBalances {
		r.localBalances[id] = balance
	}

	ctx := context.Background()
	seen := make(map[route.Vertex]bool)
	queue := []route.Vertex{source}
	seen[source] = true

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				capacity := lnwire.NewMSatFromSatoshis(ch.Capacity)
				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					cap:    capacity,
				}
				edge := &candidateEdge{
					key:           key,
					chanID:        ch.ChannelID,
					from:          ch.OtherNode,
					to:            node,
					capacity:      capacity,
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[edge.to] = append(
					r.incomingEdges[edge.to], edge,
				)
				r.edgeByKey[key] = edge

				sharedBeliefs.Lock()
				b := sharedBeliefs.m[key]
				sharedBeliefs.Unlock()
				r.beliefs[key] = b

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func clampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005
	case p > 0.995:
		return 0.995
	default:
		return p
	}
}

// bimodalPrior models a channel as roughly equally likely to be in a
// depleted mode or a well-funded mode. Tiny HTLCs can pass either mode,
// while amounts near capacity fall off a logistic cliff.
func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.025)

	z := (x - 0.90) / 0.045
	var highMode float64
	switch {
	case z > 40:
		highMode = 0
	case z < -40:
		highMode = 1
	default:
		highMode = 1 / (1 + math.Exp(z))
	}

	return clampProbability(0.5*lowMode + 0.5*highMode)
}

func (r *candidateRouter) totalReserved(key edgeKey,
	extra map[edgeKey]lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	total := r.reserved[key]
	if extra != nil {
		total += extra[key]
	}
	return total
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi,
	extra map[edgeKey]lnwire.MilliSatoshi) float64 {

	reserved := r.totalReserved(edge.key, extra)
	needed := reserved + amt

	if edge.from == r.source {
		if needed <= r.localBalances[edge.chanID] {
			return 0.995
		}
		return 0.005
	}

	prior := bimodalPrior(needed, edge.capacity)
	b := r.beliefs[edge.key]

	if b.lowerOK > edge.capacity {
		b.lowerOK = edge.capacity
	}
	if b.upper > edge.capacity {
		b.upper = edge.capacity
	}
	if b.estimate > edge.capacity {
		b.estimate = edge.capacity
	}

	// Truthful successes dominate uncertain failures.
	if b.lowerOK > 0 && needed <= b.lowerOK {
		return 0.995
	}
	if b.upper > 0 && needed >= b.upper {
		return 0.008
	}

	p := prior
	if b.confidence > 0 && b.estimate > 0 {
		scale := math.Max(float64(edge.capacity)*0.10, 1)
		z := (float64(needed) - float64(b.estimate)) / scale

		var estimated float64
		switch {
		case z > 40:
			estimated = 0
		case z < -40:
			estimated = 1
		default:
			estimated = 1 / (1 + math.Exp(z))
		}

		weight := math.Min(0.70, b.confidence*0.70)
		p = (1-weight)*p + weight*estimated
	}

	// A single uncorroborated blame is only soft evidence.
	if b.failVotes == 1 && b.suspectAmt > 0 &&
		needed >= b.suspectAmt*3/4 {

		p *= 0.62
	}

	return clampProbability(p)
}

func (r *candidateRouter) edgeAvailable(edge *candidateEdge,
	amt lnwire.MilliSatoshi,
	extra map[edgeKey]lnwire.MilliSatoshi) bool {

	if !edge.usableHTLC(amt) {
		return false
	}

	reserved := r.totalReserved(edge.key, extra)
	if reserved+amt > edge.capacity {
		return false
	}

	if edge.from == r.source &&
		reserved+amt > r.localBalances[edge.chanID] {

		return false
	}

	return true
}

type dijkstraItem struct {
	node   route.Vertex
	score  float64
	amount lnwire.MilliSatoshi
	index  int
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int { return len(q) }
func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}
func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index = i
	q[j].index = j
}
func (q *dijkstraQueue) Push(x any) {
	item := x.(*dijkstraItem)
	item.index = len(*q)
	*q = append(*q, item)
}
func (q *dijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	extra map[edgeKey]lnwire.MilliSatoshi,
	reuse map[edgeKey]int, bias map[edgeKey]float64) (*searchResult, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is payment target")
	}

	bestScore := make(map[route.Vertex]float64)
	required := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)
	logProbability := make(map[route.Vertex]float64)

	bestScore[r.spec.Target] = 0
	required[r.spec.Target] = amt
	logProbability[r.spec.Target] = 0

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node:   r.spec.Target,
		score:  0,
		amount: amt,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		node := item.node

		current, ok := bestScore[node]
		if !ok || item.score > current+0.0001 {
			continue
		}
		if node == r.source {
			break
		}

		arriving := required[node]
		for _, edge := range r.incomingEdges[node] {
			if !r.edgeAvailable(edge, arriving, extra) {
				continue
			}

			p := r.edgeProbability(edge, arriving, extra)
			edgeFee := lnwire.MilliSatoshi(0)
			sending := arriving
			if edge.from != r.source {
				edgeFee = edge.fee(arriving)
				sending += edgeFee
			}

			edgeCost := float64(edgeFee) -
				riskWeight*math.Log(p) + 2_000

			edgeCost += r.penalty[edge.key]
			if bias != nil {
				edgeCost += bias[edge.key]
			}
			if reuse != nil && reuse[edge.key] > 0 {
				edgeCost += float64(reuse[edge.key]) * 4_000_000
			}

			score := item.score + edgeCost
			old, exists := bestScore[edge.from]
			if exists && score >= old {
				continue
			}

			bestScore[edge.from] = score
			required[edge.from] = sending
			next[edge.from] = edge
			logProbability[edge.from] =
				logProbability[node] + math.Log(p)

			heap.Push(pq, &dijkstraItem{
				node:   edge.from,
				score:  score,
				amount: sending,
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	rt, path, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, err
	}

	uses := routeUses(rt, path)
	return &searchResult{
		rt:      rt,
		path:    path,
		uses:    uses,
		logProb: logProbability[r.source],
		fee:     rt.TotalAmount - amt,
	}, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route,
	[]*candidateEdge, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.to
	}

	if len(path) == 0 {
		return nil, nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		nextEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			nextEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(nextEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forward := amt
		expiry := uint32(finalCltvDelta)
		if i < last {
			forward = amtOver[i+1]
			expiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, path, nil
}

func routeUses(rt *route.Route, path []*candidateEdge) []edgeUse {
	uses := make([]edgeUse, len(path))
	for i, edge := range path {
		amount := rt.TotalAmount
		if i > 0 {
			amount = rt.Hops[i-1].AmtToForward
		}
		uses[i] = edgeUse{edge: edge, amount: amount}
	}
	return uses
}

func deliveredAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func routeHash(rt *route.Route) uint64 {
	h := uint64(1469598103934665603)
	for _, hop := range rt.Hops {
		h ^= hop.ChannelID
		h *= 1099511628211
		for _, b := range hop.PubKeyBytes {
			h ^= uint64(b)
			h *= 1099511628211
		}
	}
	return h
}

func (r *candidateRouter) findFreshRoute(amt lnwire.MilliSatoshi,
	extra map[edgeKey]lnwire.MilliSatoshi,
	reuse map[edgeKey]int) (*searchResult, error) {

	bias := make(map[edgeKey]float64)
	var lastErr error

	for n := 0; n < 10; n++ {
		result, err := r.findRoute(amt, extra, reuse, bias)
		if err != nil {
			return nil, err
		}

		hash := routeHash(result.rt)
		failedAt, failed := r.tried[hash]
		if !failed || amt < failedAt {
			return result, nil
		}

		lastErr = errors.New("all candidate routes already failed")
		if len(result.path) == 0 {
			break
		}

		// Exclude a different edge on successive duplicate paths. This
		// uses only payment-local information and does not turn an
		// unreadable onion error into a permanent channel accusation.
		index := int((hash + uint64(n)) % uint64(len(result.path)))
		bias[result.path[index].key] += 7_000_000
	}

	if lastErr == nil {
		lastErr = errors.New("no fresh route found")
	}
	return nil, lastErr
}

func (r *candidateRouter) reliableDeliveryLimit(result *searchResult,
	extra map[edgeKey]lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	delivery := deliveredAmount(result.rt)
	limit := delivery * 8
	if limit < delivery {
		limit = delivery
	}

	for _, use := range result.uses {
		edge := use.edge
		reserved := r.totalReserved(edge.key, extra)

		var safeTotal lnwire.MilliSatoshi
		if edge.from == r.source {
			safeTotal = r.localBalances[edge.chanID]
		} else {
			b := r.beliefs[edge.key]
			safeTotal = edge.capacity * 78 / 100

			if b.estimate > 0 && b.confidence > 0 {
				w := math.Min(0.85, b.confidence)
				safeTotal = lnwire.MilliSatoshi(
					(1-w)*float64(safeTotal) +
						w*float64(b.estimate),
				)
			}
			if b.lowerOK > safeTotal {
				safeTotal = b.lowerOK
			}
			if b.upper > 0 && safeTotal >= b.upper {
				safeTotal = b.upper * 9 / 10
			}
		}

		if safeTotal > edge.capacity {
			safeTotal = edge.capacity
		}
		if safeTotal <= reserved {
			return 0
		}

		available := safeTotal - reserved
		edgeLimit := delivery * available / use.amount

		if edge.maxHTLC != 0 && use.amount > 0 {
			policyLimit := delivery * edge.maxHTLC / use.amount
			if policyLimit < edgeLimit {
				edgeLimit = policyLimit
			}
		}
		if edgeLimit < limit {
			limit = edgeLimit
		}
	}

	return limit
}

func addReservations(dst map[edgeKey]lnwire.MilliSatoshi,
	uses []edgeUse) {

	for _, use := range uses {
		dst[use.edge.key] += use.amount
	}
}

func planMetric(results []*searchResult) float64 {
	metric := -0.04 * float64(len(results))
	for _, result := range results {
		metric += result.logProb
		metric -= float64(result.fee) / 5_000_000
	}
	return metric
}

func (r *candidateRouter) buildPlanForParts(amt lnwire.MilliSatoshi,
	parts int) ([]*searchResult, bool) {

	remaining := amt
	virtual := make(map[edgeKey]lnwire.MilliSatoshi)
	reuse := make(map[edgeKey]int)
	results := make([]*searchResult, 0, parts)

	for i := 0; i < parts; i++ {
		slots := parts - i
		if remaining <= 0 {
			return nil, false
		}

		share := (remaining + lnwire.MilliSatoshi(slots) - 1) /
			lnwire.MilliSatoshi(slots)

		result, err := r.findFreshRoute(share, virtual, reuse)
		if err != nil {
			return nil, false
		}

		safe := r.reliableDeliveryLimit(result, virtual)
		if safe < share {
			if slots == 1 || safe <= 0 {
				return nil, false
			}

			share = safe
			result, err = r.findFreshRoute(share, virtual, reuse)
			if err != nil {
				return nil, false
			}
		}

		if share <= 0 || share >= remaining && slots > 1 {
			return nil, false
		}

		results = append(results, result)
		addReservations(virtual, result.uses)
		for _, use := range result.uses {
			reuse[use.edge.key]++
		}
		remaining -= share
	}

	if remaining != 0 {
		return nil, false
	}
	return results, true
}

// preparePlan compares a direct attempt with jointly constructed route sets.
// The set planner accounts for all earlier shards as virtual reservations,
// so atomic siblings cannot unknowingly depend on the same liquidity twice.
func (r *candidateRouter) preparePlan(amt lnwire.MilliSatoshi,
	partsLeft uint32) error {

	r.plan = nil
	if partsLeft == 0 {
		return errors.New("maximum in-flight parts reached")
	}

	var best []*searchResult
	bestMetric := math.Inf(-1)

	direct, directErr := r.findFreshRoute(amt, nil, nil)
	if directErr == nil {
		best = []*searchResult{direct}
		bestMetric = planMetric(best)
	}

	maxParts := int(partsLeft)
	if maxParts > 16 {
		maxParts = 16
	}

	for parts := 2; parts <= maxParts; parts++ {
		results, ok := r.buildPlanForParts(amt, parts)
		if !ok {
			continue
		}

		metric := planMetric(results)
		if metric > bestMetric+0.08 {
			best = results
			bestMetric = metric
		}
	}

	if len(best) == 0 {
		if directErr != nil {
			return directErr
		}
		return errors.New("no route set found")
	}

	r.plan = make([]plannedRoute, len(best))
	for i, result := range best {
		r.plan[i] = plannedRoute{result: result}
	}
	return nil
}

func (r *candidateRouter) issue(result *searchResult) *route.Route {
	addReservations(r.reserved, result.uses)
	r.issued[result.rt] = result.uses
	return result.rt
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum in-flight parts reached")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.plan) > 0 {
		result := r.plan[0].result
		if deliveredAmount(result.rt) <= amt {
			r.plan = r.plan[1:]
			return r.issue(result), nil
		}
		r.plan = nil
	}

	if err := r.preparePlan(amt, partsLeft); err == nil &&
		len(r.plan) > 0 {

		result := r.plan[0].result
		r.plan = r.plan[1:]
		return r.issue(result), nil
	}

	// If joint planning cannot complete the amount, retain a conservative
	// lower-amount escape hatch. It never proposes a shard so small that
	// the currently available atomic slots could not finish the payment.
	if partsLeft <= 1 {
		return nil, errors.New("no route found")
	}

	minShard := (amt + lnwire.MilliSatoshi(partsLeft) - 1) /
		lnwire.MilliSatoshi(partsLeft)
	tryAmt := amt
	if r.retryCeiling > 0 && r.retryCeiling < tryAmt {
		tryAmt = r.retryCeiling
	}
	if tryAmt < minShard {
		tryAmt = minShard
	}

	for tryAmt >= minShard {
		result, err := r.findFreshRoute(tryAmt, nil, nil)
		if err == nil {
			return r.issue(result), nil
		}
		if tryAmt == minShard {
			break
		}

		next := tryAmt * 3 / 5
		if next < minShard {
			next = minShard
		}
		if next == tryAmt {
			break
		}
		tryAmt = next
	}

	return nil, errors.New("no route found")
}

func (r *candidateRouter) saveBelief(key edgeKey,
	b liquidityBelief) {

	r.beliefs[key] = b
	sharedBeliefs.Lock()
	sharedBeliefs.m[key] = b
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) learnSuccess(use edgeUse,
	totalObserved lnwire.MilliSatoshi) {

	key := use.edge.key
	b := r.beliefs[key]

	if totalObserved > b.lowerOK {
		b.lowerOK = totalObserved
	}
	if totalObserved > b.estimate {
		b.estimate = totalObserved
	}
	b.confidence = math.Min(1, b.confidence+0.35)

	// A success is truthful and therefore disproves any ceiling at or
	// below the amount that just passed.
	if b.upper > 0 && totalObserved >= b.upper {
		b.upper = 0
	}
	if b.suspectAmt > 0 && totalObserved >= b.suspectAmt {
		b.suspectAmt = 0
		b.failVotes = 0
		b.lastFailPath = 0
	}

	r.saveBelief(key, b)
}

func (r *candidateRouter) learnFailure(edge *candidateEdge,
	totalObserved lnwire.MilliSatoshi, pathHash uint64) {

	key := edge.key
	b := r.beliefs[key]

	if b.suspectAmt == 0 ||
		totalObserved < b.suspectAmt/2 ||
		totalObserved > b.suspectAmt*2 {

		b.suspectAmt = totalObserved
		b.failVotes = 1
		b.lastFailPath = pathHash
	} else {
		if totalObserved < b.suspectAmt {
			b.suspectAmt = totalObserved
		}
		// Repeated blame on the identical route does not corroborate the
		// reported hop. A second, distinct route does.
		if pathHash != b.lastFailPath && b.failVotes < 255 {
			b.failVotes++
			b.lastFailPath = pathHash
		}
	}

	failedEstimate := totalObserved * 3 / 4
	if b.estimate == 0 {
		b.estimate = failedEstimate
	} else {
		b.estimate = (b.estimate*3 + failedEstimate) / 4
	}
	b.confidence = math.Min(1, b.confidence+0.15)

	if b.failVotes >= 2 {
		if b.upper == 0 || b.suspectAmt < b.upper {
			b.upper = b.suspectAmt
		}
		if b.lowerOK >= b.upper {
			b.lowerOK = 0
		}
	}

	r.saveBelief(key, b)
}

func releaseReservations(reserved map[edgeKey]lnwire.MilliSatoshi,
	uses []edgeUse) {

	for _, use := range uses {
		current := reserved[use.edge.key]
		if current <= use.amount {
			delete(reserved, use.edge.key)
		} else {
			reserved[use.edge.key] = current - use.amount
		}
	}
}

func findFailureNode(rt *route.Route, source route.Vertex) int {
	if source == rt.SourcePubKey {
		return 0
	}
	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}
	return -1
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	uses, ok := r.issued[rt]
	if !ok {
		// The simulator normally returns the same route pointer. Rebuild
		// the edge uses defensively if it returns an equivalent route.
		path := make([]*candidateEdge, 0, len(rt.Hops))
		from := rt.SourcePubKey
		for _, hop := range rt.Hops {
			var found *candidateEdge
			for _, edge := range r.incomingEdges[hop.PubKeyBytes] {
				if edge.from == from && edge.chanID == hop.ChannelID {
					found = edge
					break
				}
			}
			if found == nil {
				break
			}
			path = append(path, found)
			from = hop.PubKeyBytes
		}
		if len(path) == len(rt.Hops) {
			uses = routeUses(rt, path)
		}
	}
	delete(r.issued, rt)

	if result.Failure == nil {
		for _, use := range uses {
			// reserved includes this shard and any prior successful
			// siblings, which is the total liquidity proven to have
			// existed before those reservations.
			r.learnSuccess(use, r.reserved[use.edge.key])
		}
		return nil
	}

	hash := routeHash(rt)
	delivered := deliveredAmount(rt)
	if old, exists := r.tried[hash]; !exists || delivered < old {
		r.tried[hash] = delivered
	}

	// Capture total demand before releasing this failed attempt.
	totalDemand := make(map[edgeKey]lnwire.MilliSatoshi, len(uses))
	for _, use := range uses {
		totalDemand[use.edge.key] = r.reserved[use.edge.key]
	}
	releaseReservations(r.reserved, uses)
	r.plan = nil

	nextCeiling := delivered * 3 / 5
	if nextCeiling > 0 &&
		(r.retryCeiling == 0 || nextCeiling < r.retryCeiling) {

		r.retryCeiling = nextCeiling
	}

	failNode := findFailureNode(rt, result.FailureSource)
	if failNode < 0 {
		// Unreadable attribution is not written to the persistent
		// channel store. The exact failed route is still avoided at this
		// amount through r.tried.
		return nil
	}

	code := result.Failure.Code()
	isLiquidity := code == lnwire.CodeTemporaryChannelFailure

	// A node failure refers to its outgoing channel, whose hop index is
	// the node index. The target has no outgoing channel.
	if failNode >= len(uses) {
		return nil
	}

	primary := failNode
	if isLiquidity {
		use := uses[primary]
		r.penalty[use.edge.key] += 5_000_000
		r.learnFailure(
			use.edge, totalDemand[use.edge.key], hash,
		)

		// Shifted attribution is plausible. Adjacent edges receive only
		// payment-local soft penalties; they never receive persistent
		// hard bounds without being reported directly and corroborated.
		if primary > 0 {
			r.penalty[uses[primary-1].edge.key] += 900_000
		}
		if primary+1 < len(uses) {
			r.penalty[uses[primary+1].edge.key] += 900_000
		}
		return nil
	}

	// Policy failures cannot safely establish a liquidity ceiling,
	// especially when the reported source may have shifted.
	r.penalty[uses[primary].edge.key] += 8_000_000
	if primary > 0 {
		r.penalty[uses[primary-1].edge.key] += 1_000_000
	}
	if primary+1 < len(uses) {
		r.penalty[uses[primary+1].edge.key] += 1_000_000
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	candidateMinimumShard = lnwire.MilliSatoshi(1_000_000)
	candidateAttemptLimit  = uint32(48)
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi

	suspectAmt   lnwire.MilliSatoshi
	suspectVotes uint8

	stamp uint64
}

var candidateMemory = struct {
	sync.Mutex
	epoch   uint64
	beliefs map[candidateEdgeKey]candidateBelief
}{
	beliefs: make(map[candidateEdgeKey]candidateBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec
	epoch  uint64

	incomingEdges map[route.Vertex][]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[candidateEdgeKey]candidateBelief

	// Successful shards consume or hold liquidity for the rest of the
	// payment. Accounting for that aggregate use is essential for atomic
	// MPP, where sibling shards compete with existing holds.
	reserved map[candidateEdgeKey]lnwire.MilliSatoshi

	// These penalties are deliberately payment-local. They diversify
	// retries without turning uncertain failure attribution into persistent
	// channel knowledge.
	edgePenalty map[candidateEdgeKey]float64

	retryLimit lnwire.MilliSatoshi
	attempts   uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	candidateMemory.Lock()
	candidateMemory.epoch++
	epoch := candidateMemory.epoch

	snapshot := make(map[candidateEdgeKey]candidateBelief,
		len(candidateMemory.beliefs))
	for key, belief := range candidateMemory.beliefs {
		snapshot[key] = belief
	}
	candidateMemory.Unlock()

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		epoch:         epoch,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		localBalances: localBalances,
		beliefs:       snapshot,
		reserved:      make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		edgePenalty:   make(map[candidateEdgeKey]float64),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
					},
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: policy.FeeBaseMSat,
					feeRatePPM: policy.
						FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func candidateClampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005
	case p > 0.995:
		return 0.995
	default:
		return p
	}
}

// The prior reflects a channel whose funds are usually concentrated almost
// entirely on one side. The low mode explains tiny payments that pass even
// on a depleted direction, while the high mode has a steep capacity cliff.
func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.025)
	highMode := 1 / (1 + math.Exp(18*(x-0.82)))

	return candidateClampProbability(0.5*lowMode + 0.5*highMode)
}

func (r *candidateRouter) evidenceConfidence(b candidateBelief) float64 {
	if b.stamp == 0 || r.epoch <= b.stamp+3 {
		return 1
	}

	age := float64(r.epoch - b.stamp - 3)
	return math.Max(0.12, math.Exp(-age/12))
}

func (r *candidateRouter) probability(edge *candidateEdge,
	totalAmt lnwire.MilliSatoshi) float64 {

	if edge.from == r.source {
		available := r.localBalances[edge.chanID]
		if totalAmt <= available {
			return 0.999
		}
		return 0.001
	}

	prior := candidatePrior(totalAmt, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok || belief.stamp == 0 {
		return prior
	}

	learned := prior

	switch {
	case belief.lowerOK > 0 && totalAmt <= belief.lowerOK:
		learned = 0.995

	case belief.upperFail > 0 && totalAmt >= belief.upperFail:
		learned = 0.008

	case belief.lowerOK > 0 && belief.upperFail > belief.lowerOK:
		span := float64(belief.upperFail - belief.lowerOK)
		pos := float64(totalAmt-belief.lowerOK) / span
		pos = math.Max(0, math.Min(1, pos))
		learned = 0.995*(1-pos) + 0.008*pos

	case belief.lowerOK > 0 && totalAmt > belief.lowerOK:
		ratio := float64(belief.lowerOK) / float64(totalAmt)
		learned = prior + (0.995-prior)*ratio*ratio

	case belief.upperFail > 0 && totalAmt < belief.upperFail:
		ratio := float64(totalAmt) / float64(belief.upperFail)
		learned = prior * (1 - 0.75*ratio*ratio)
	}

	// A single plausible-but-unconfirmed blame remains a soft hint.
	if belief.upperFail == 0 && belief.suspectAmt > 0 &&
		totalAmt >= belief.suspectAmt {

		learned *= 0.58
	}

	confidence := r.evidenceConfidence(belief)
	p := confidence*learned + (1-confidence)*prior

	return candidateClampProbability(p)
}

func (r *candidateRouter) hardFailed(edge *candidateEdge,
	totalAmt lnwire.MilliSatoshi) bool {

	belief, ok := r.beliefs[edge.key]
	if !ok || belief.upperFail == 0 {
		return false
	}

	return r.evidenceConfidence(belief) >= 0.72 &&
		totalAmt >= belief.upperFail
}

type candidateItem struct {
	node  route.Vertex
	score float64
}

type candidateQueue []*candidateItem

func (q candidateQueue) Len() int {
	return len(q)
}

func (q candidateQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *candidateQueue) Push(value any) {
	*q = append(*q, value.(*candidateItem))
}

func (q *candidateQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]
	return last
}

type candidatePath struct {
	route       *route.Route
	edges       []*candidateEdge
	probability float64
	pressure    float64
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*candidatePath, error) {

	if amt <= 0 {
		return nil, errors.New("invalid payment amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is target")
	}

	scores := make(map[route.Vertex]float64)
	amounts := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)

	scores[r.spec.Target] = 0
	amounts[r.spec.Target] = amt

	pq := &candidateQueue{}
	heap.Push(pq, &candidateItem{
		node:  r.spec.Target,
		score: 0,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateItem)
		bestScore, ok := scores[item.node]
		if !ok || item.score > bestScore+1e-12 {
			continue
		}
		if item.node == r.source {
			break
		}

		arriving := amounts[item.node]

		for _, edge := range r.incomingEdges[item.node] {
			if !edge.usable(arriving) {
				continue
			}

			totalLiquidity := arriving + r.reserved[edge.key]
			if totalLiquidity < arriving ||
				totalLiquidity > edge.capacity {

				continue
			}

			if edge.from == r.source {
				if totalLiquidity >
					r.localBalances[edge.chanID] {

					continue
				}
			} else if r.hardFailed(edge, totalLiquidity) {
				continue
			}

			sending := arriving
			fee := lnwire.MilliSatoshi(0)
			if edge.from != r.source {
				fee = edge.fee(arriving)
				sending += fee
				if sending < arriving {
					continue
				}
			}

			probability := r.probability(edge, totalLiquidity)

			// Reliability dominates. The small hop charge discourages the
			// extremely long routes that compound many bimodal risks.
			edgeCost := -math.Log(probability) + 0.06
			if arriving > 0 {
				edgeCost += 3 * float64(fee) /
					float64(arriving)
			}
			edgeCost += r.edgePenalty[edge.key]

			newScore := item.score + edgeCost
			oldScore, visited := scores[edge.from]
			if visited && newScore >= oldScore {
				continue
			}

			scores[edge.from] = newScore
			amounts[edge.from] = sending
			next[edge.from] = edge
			heap.Push(pq, &candidateItem{
				node:  edge.from,
				score: newScore,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	rt, path, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, err
	}

	probability := 1.0
	pressure := 0.0

	for i, edge := range path {
		amtOver := candidateRouteAmount(rt, i)
		totalLiquidity := amtOver + r.reserved[edge.key]

		probability *= r.probability(edge, totalLiquidity)

		denominator := edge.capacity
		if edge.from == r.source {
			denominator = r.localBalances[edge.chanID]
		} else if belief, ok := r.beliefs[edge.key]; ok &&
			belief.upperFail > 0 &&
			r.evidenceConfidence(belief) >= 0.72 &&
			belief.upperFail < denominator {

			denominator = belief.upperFail
		}

		if denominator > 0 {
			ratio := float64(totalLiquidity) /
				float64(denominator)
			if ratio > pressure {
				pressure = ratio
			}
		}
	}

	return &candidatePath{
		route:       rt,
		edges:       path,
		probability: probability,
		pressure:    pressure,
	}, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route,
	[]*candidateEdge, error) {

	const finalCltvDelta = uint32(40)

	var path []*candidateEdge
	seen := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if seen[node] {
			return nil, nil, errors.New("cycle in route")
		}
		seen[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.to
	}

	if len(path) == 0 {
		return nil, nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := finalCltvDelta

		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, path, nil
}

func candidateCeilDiv(a lnwire.MilliSatoshi,
	b uint32) lnwire.MilliSatoshi {

	if b <= 1 {
		return a
	}

	divisor := lnwire.MilliSatoshi(b)
	return (a + divisor - 1) / divisor
}

func candidateAddAmount(amounts *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, amt,
	remaining lnwire.MilliSatoshi) {

	if amt < candidateMinimumShard {
		amt = candidateMinimumShard
	}
	if amt > remaining {
		amt = remaining
	}
	if amt <= 0 || seen[amt] {
		return
	}

	seen[amt] = true
	*amounts = append(*amounts, amt)
}

// RequestRoute compares several feasible shard sizes rather than discovering
// a split through a long halving ladder. The score rewards reliable progress,
// allowing unequal corridors to receive unequal shares while keeping shards
// near the size required to finish within MaxParts.
func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid remaining amount")
	}
	if r.attempts >= candidateAttemptLimit {
		return nil, errors.New("route portfolio exhausted")
	}

	partsLeft := uint32(1)
	if r.spec.MaxParts > inFlightHtlcs {
		partsLeft = r.spec.MaxParts - inFlightHtlcs
	}

	if partsLeft <= 1 {
		path, err := r.findRoute(amt)
		if err != nil {
			return nil, err
		}
		return path.route, nil
	}

	full, fullErr := r.findRoute(amt)
	if r.attempts == 0 && fullErr == nil {
		if full.probability >= 0.68 ||
			full.pressure < 0.28 ||
			(amt < 50_000_000 &&
				full.probability >= 0.25) {

			return full.route, nil
		}
	}

	average := candidateCeilDiv(amt, partsLeft)
	seen := make(map[lnwire.MilliSatoshi]bool)
	var amounts []lnwire.MilliSatoshi

	// A broad route gets more than the average share. A narrow but reliable
	// route may get less, with later parts taking a correspondingly larger
	// share. This discrete portfolio captures most of the benefit of joint
	// route/amount planning without probing every possible split.
	candidateAddAmount(&amounts, seen, average, amt)
	candidateAddAmount(
		&amounts, seen,
		candidateCeilDiv(2*amt, partsLeft+1), amt,
	)
	candidateAddAmount(
		&amounts, seen, average*3/2, amt,
	)
	candidateAddAmount(&amounts, seen, amt/2, amt)

	if r.retryLimit > 0 {
		candidateAddAmount(
			&amounts, seen, r.retryLimit, amt,
		)
	}

	// A below-average shard is useful when one narrow corridor complements
	// a larger one. It is not the default, which prevents successful dust
	// shards from consuming all available part slots.
	if r.attempts > 1 {
		candidateAddAmount(
			&amounts, seen, average*3/4, amt,
		)
	}
	if r.attempts > 5 {
		candidateAddAmount(
			&amounts, seen, average/2, amt,
		)
	}

	// An alternate full route remains useful after an uncertain or shifted
	// failure, but it competes with planned shards instead of being retried
	// unconditionally.
	candidateAddAmount(&amounts, seen, amt, amt)

	var (
		best      *candidatePath
		bestScore = math.Inf(-1)
		lastErr   error
	)

	for _, shardAmt := range amounts {
		path, err := r.findRoute(shardAmt)
		if err != nil {
			lastErr = err
			continue
		}

		progress := float64(shardAmt) / float64(average)
		if progress < 0.01 {
			progress = 0.01
		}

		score := math.Log(path.probability)
		score += 0.34 * math.Log(progress)
		score -= 0.18 * path.pressure

		delivered := path.route.Hops[
			len(path.route.Hops)-1].AmtToForward
		fee := path.route.TotalAmount - delivered
		if delivered > 0 && fee > 0 {
			feePPM := 1_000_000 * float64(fee) /
				float64(delivered)
			score -= feePPM / 20_000
		}

		if r.retryLimit > 0 && shardAmt > r.retryLimit {
			ratio := float64(shardAmt) /
				float64(r.retryLimit)
			score -= 0.22 * math.Log(ratio)
		}

		if r.attempts > 0 && shardAmt == amt {
			score -= 0.20
		}

		if score > bestScore {
			bestScore = score
			best = path
		}
	}

	if best != nil {
		return best.route, nil
	}
	if lastErr != nil {
		return nil, lastErr
	}
	if fullErr != nil {
		return nil, fullErr
	}

	return nil, errors.New("no route found")
}

func candidateRouteAmount(rt *route.Route,
	edgeIndex int) lnwire.MilliSatoshi {

	if edgeIndex == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[edgeIndex-1].AmtToForward
}

func candidateRouteEdgeKey(rt *route.Route,
	edgeIndex int) candidateEdgeKey {

	from := rt.SourcePubKey
	if edgeIndex > 0 {
		from = rt.Hops[edgeIndex-1].PubKeyBytes
	}

	return candidateEdgeKey{
		chanID: rt.Hops[edgeIndex].ChannelID,
		from:   from,
	}
}

func candidateFailureEdge(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func candidateIsLiquidityFailure(failure any) bool {
	switch failure.(type) {
	case *lnwire.FailTemporaryChannelFailure:
		return true
	default:
		return false
	}
}

func candidateIsPolicyFailure(failure any) bool {
	switch failure.(type) {
	case *lnwire.FailFeeInsufficient,
		*lnwire.FailIncorrectCltvExpiry:

		return true
	default:
		return false
	}
}

func (r *candidateRouter) saveBelief(
	key candidateEdgeKey, belief candidateBelief) {

	belief.stamp = r.epoch
	r.beliefs[key] = belief

	candidateMemory.Lock()
	candidateMemory.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) recordSuccess(key candidateEdgeKey,
	totalAmt lnwire.MilliSatoshi) {

	belief := r.beliefs[key]

	if totalAmt > belief.lowerOK {
		belief.lowerOK = totalAmt
	}

	// Success attribution is always truthful.
	if belief.upperFail > 0 && totalAmt >= belief.upperFail {
		belief.upperFail = 0
	}
	if belief.suspectAmt > 0 && totalAmt >= belief.suspectAmt {
		belief.suspectAmt = 0
		belief.suspectVotes = 0
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) recordFailure(key candidateEdgeKey,
	totalAmt lnwire.MilliSatoshi) {

	belief := r.beliefs[key]

	// Do not combine widely separated observations into corroboration in a
	// moving network.
	if belief.stamp > 0 && r.epoch > belief.stamp+6 {
		belief.suspectAmt = 0
		belief.suspectVotes = 0
	}

	corroborates := false
	if belief.suspectAmt > 0 {
		low := belief.suspectAmt * 60 / 100
		high := belief.suspectAmt * 150 / 100
		corroborates = totalAmt >= low && totalAmt <= high
	}

	if corroborates {
		if belief.suspectVotes < 255 {
			belief.suspectVotes++
		}
		if totalAmt < belief.suspectAmt {
			belief.suspectAmt = totalAmt
		}
	} else {
		belief.suspectAmt = totalAmt
		belief.suspectVotes = 1
	}

	requiredVotes := uint8(2)
	if belief.lowerOK > 0 && totalAmt <= belief.lowerOK {
		requiredVotes = 3
	}

	if belief.suspectVotes >= requiredVotes {
		if totalAmt <= belief.lowerOK {
			belief.lowerOK = 0
		}

		if belief.upperFail == 0 ||
			belief.suspectAmt < belief.upperFail {

			belief.upperFail = belief.suspectAmt
		}
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) addPenalty(key candidateEdgeKey,
	increment, maximum float64) {

	r.edgePenalty[key] = math.Min(
		maximum, r.edgePenalty[key]+increment,
	)
}

// ReportAttempt preserves truthful success bounds, quarantines liquidity
// blame until corroborated, and uses only reversible per-payment penalties
// for unreadable or potentially shifted failures.
func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID
	r.attempts++

	if rt == nil || len(rt.Hops) == 0 {
		return nil
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key := candidateRouteEdgeKey(rt, i)
			amtOver := candidateRouteAmount(rt, i)
			totalAmt := amtOver + r.reserved[key]

			r.recordSuccess(key, totalAmt)
			r.reserved[key] += amtOver

			// A successful corridor is known-good, but atomic siblings
			// should still seek independent capacity where available.
			r.addPenalty(key, 0.48, 4)
		}

		r.retryLimit = 0
		return nil
	}

	// The route-level fact that something failed is reliable even when its
	// source is not. This moderate penalty quickly avoids exact retry loops
	// but does not persist beyond the payment.
	for i := range rt.Hops {
		key := candidateRouteEdgeKey(rt, i)
		r.addPenalty(key, 0.22, 8)
	}

	failIndex := candidateFailureEdge(
		rt, result.FailureSource,
	)
	attributed := failIndex >= 0 && failIndex < len(rt.Hops)

	delivered := rt.Hops[len(rt.Hops)-1].AmtToForward

	if candidateIsLiquidityFailure(result.Failure) && attributed {
		key := candidateRouteEdgeKey(rt, failIndex)
		amtOver := candidateRouteAmount(rt, failIndex)
		totalAmt := amtOver + r.reserved[key]

		r.recordFailure(key, totalAmt)
		r.addPenalty(key, 1.15, 10)

		// Shifted blame is normally adjacent to the real failure. Small
		// neighbor penalties hedge against it without writing false bounds.
		if failIndex > 0 {
			neighbor := candidateRouteEdgeKey(
				rt, failIndex-1,
			)
			r.addPenalty(neighbor, 0.34, 6)
		}
		if failIndex+1 < len(rt.Hops) {
			neighbor := candidateRouteEdgeKey(
				rt, failIndex+1,
			)
			r.addPenalty(neighbor, 0.34, 6)
		}

		lowerRetry := delivered * 72 / 100
		if lowerRetry < candidateMinimumShard {
			lowerRetry = candidateMinimumShard
		}
		r.retryLimit = lowerRetry

		return nil
	}

	if candidateIsPolicyFailure(result.Failure) && attributed {
		key := candidateRouteEdgeKey(rt, failIndex)
		r.addPenalty(key, 2.0, 10)

		if failIndex > 0 {
			neighbor := candidateRouteEdgeKey(
				rt, failIndex-1,
			)
			r.addPenalty(neighbor, 0.25, 5)
		}
		if failIndex+1 < len(rt.Hops) {
			neighbor := candidateRouteEdgeKey(
				rt, failIndex+1,
			)
			r.addPenalty(neighbor, 0.25, 5)
		}

		r.retryLimit = delivered
		return nil
	}

	// An unreadable failure supplies no channel-level evidence. Keep the
	// amount available to the route-set planner and rely on route diversity.
	r.retryLimit = delivered
	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40
	riskWeight     = 3_000_000.0
	maxLabels      = 10
)

type edgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
	cap    lnwire.MilliSatoshi
}

type liquidityBelief struct {
	lowerOK lnwire.MilliSatoshi
	upper   lnwire.MilliSatoshi

	estimate  lnwire.MilliSatoshi
	confidence float64

	suspectAmt   lnwire.MilliSatoshi
	failVotes    uint8
	lastFailPath uint64
}

var sharedBeliefs = struct {
	sync.Mutex
	m map[edgeKey]liquidityBelief
}{
	m: make(map[edgeKey]liquidityBelief),
}

type candidateEdge struct {
	key      edgeKey
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usableHTLC(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type edgeUse struct {
	edge   *candidateEdge
	amount lnwire.MilliSatoshi
}

type searchResult struct {
	rt      *route.Route
	path    []*candidateEdge
	uses    []edgeUse
	logProb float64
	fee     lnwire.MilliSatoshi
}

type plannedRoute struct {
	result *searchResult
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[edgeKey]liquidityBelief

	// reserved includes every issued shard that has not failed. held only
	// includes shards whose success has been confirmed.
	reserved map[edgeKey]lnwire.MilliSatoshi
	held     map[edgeKey]lnwire.MilliSatoshi
	issued   map[*route.Route][]edgeUse

	// Payment-local penalties react quickly but never poison later
	// payments.
	penalty map[edgeKey]float64

	// For an exact path, this is the smallest delivery amount known to
	// have failed. Lower amounts remain eligible.
	tried map[uint64]lnwire.MilliSatoshi

	plan []plannedRoute
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		localBalances: make(map[uint64]lnwire.MilliSatoshi),
		beliefs:       make(map[edgeKey]liquidityBelief),
		reserved:      make(map[edgeKey]lnwire.MilliSatoshi),
		held:          make(map[edgeKey]lnwire.MilliSatoshi),
		issued:        make(map[*route.Route][]edgeUse),
		penalty:       make(map[edgeKey]float64),
		tried:         make(map[uint64]lnwire.MilliSatoshi),
	}

	for id, balance := range localBalances {
		r.localBalances[id] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				capacity := lnwire.NewMSatFromSatoshis(ch.Capacity)
				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					cap:    capacity,
				}
				edge := &candidateEdge{
					key:           key,
					chanID:        ch.ChannelID,
					from:          ch.OtherNode,
					to:            node,
					capacity:      capacity,
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				sharedBeliefs.Lock()
				r.beliefs[key] = sharedBeliefs.m[key]
				sharedBeliefs.Unlock()

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func clampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005
	case p > 0.995:
		return 0.995
	default:
		return p
	}
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.025)
	z := (x - 0.90) / 0.045

	var highMode float64
	switch {
	case z > 40:
		highMode = 0
	case z < -40:
		highMode = 1
	default:
		highMode = 1 / (1 + math.Exp(z))
	}

	return clampProbability(0.5*lowMode + 0.5*highMode)
}

func (r *candidateRouter) totalReserved(key edgeKey,
	extra map[edgeKey]lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	total := r.reserved[key]
	if extra != nil {
		total += extra[key]
	}
	return total
}

func (r *candidateRouter) edgeAvailable(edge *candidateEdge,
	amt lnwire.MilliSatoshi,
	extra map[edgeKey]lnwire.MilliSatoshi) bool {

	if !edge.usableHTLC(amt) {
		return false
	}

	needed := r.totalReserved(edge.key, extra) + amt
	if needed > edge.capacity {
		return false
	}
	if edge.from == r.source &&
		needed > r.localBalances[edge.chanID] {

		return false
	}

	return true
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi,
	extra map[edgeKey]lnwire.MilliSatoshi) float64 {

	needed := r.totalReserved(edge.key, extra) + amt
	if edge.from == r.source {
		if needed <= r.localBalances[edge.chanID] {
			return 0.995
		}
		return 0.005
	}

	prior := bimodalPrior(needed, edge.capacity)
	b := r.beliefs[edge.key]

	if b.lowerOK > edge.capacity {
		b.lowerOK = edge.capacity
	}
	if b.upper > edge.capacity {
		b.upper = edge.capacity
	}
	if b.estimate > edge.capacity {
		b.estimate = edge.capacity
	}

	// Settlements are always truthful, unlike failure attribution.
	if b.lowerOK > 0 && needed <= b.lowerOK {
		return 0.995
	}
	if b.upper > 0 && needed >= b.upper {
		return 0.006
	}

	p := prior
	if b.estimate > 0 && b.confidence > 0 {
		scale := math.Max(float64(edge.capacity)*0.09, 1)
		z := (float64(needed) - float64(b.estimate)) / scale

		var estimateP float64
		switch {
		case z > 40:
			estimateP = 0
		case z < -40:
			estimateP = 1
		default:
			estimateP = 1 / (1 + math.Exp(z))
		}

		weight := math.Min(0.72, b.confidence*0.72)
		p = (1-weight)*p + weight*estimateP
	}

	// One report is a suspicion, two reports are useful soft evidence,
	// and only three independent route contexts establish a hard bound.
	if b.suspectAmt > 0 && needed >= b.suspectAmt*3/4 {
		switch b.failVotes {
		case 1:
			p *= 0.72
		case 2:
			p *= 0.42
		}
	}

	return clampProbability(p)
}

type pathLabel struct {
	node    route.Vertex
	score   float64
	amount  lnwire.MilliSatoshi
	logProb float64

	edge *candidateEdge
	next *pathLabel

	active bool
	index  int
}

type labelQueue []*pathLabel

func (q labelQueue) Len() int {
	return len(q)
}

func (q labelQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q labelQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index = i
	q[j].index = j
}

func (q *labelQueue) Push(x any) {
	item := x.(*pathLabel)
	item.index = len(*q)
	*q = append(*q, item)
}

func (q *labelQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func addLabel(labels map[route.Vertex][]*pathLabel,
	label *pathLabel) bool {

	existing := labels[label.node]
	for _, old := range existing {
		if !old.active {
			continue
		}
		if old.score <= label.score+0.0001 &&
			old.amount <= label.amount {

			return false
		}
	}

	for _, old := range existing {
		if !old.active {
			continue
		}
		if label.score <= old.score+0.0001 &&
			label.amount <= old.amount {

			old.active = false
		}
	}

	label.active = true
	labels[label.node] = append(existing, label)

	active := make([]*pathLabel, 0, len(labels[label.node]))
	for _, item := range labels[label.node] {
		if item.active {
			active = append(active, item)
		}
	}
	if len(active) <= maxLabels {
		return true
	}

	bestScore := active[0]
	minAmount := active[0]
	for _, item := range active[1:] {
		if item.score < bestScore.score {
			bestScore = item
		}
		if item.amount < minAmount.amount {
			minAmount = item
		}
	}

	var victim *pathLabel
	for _, item := range active {
		if item == bestScore || item == minAmount {
			continue
		}
		if victim == nil || item.score > victim.score {
			victim = item
		}
	}
	if victim == nil {
		if bestScore != minAmount {
			victim = label
		} else {
			victim = active[len(active)-1]
		}
	}

	victim.active = false
	return victim != label
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	extra map[edgeKey]lnwire.MilliSatoshi,
	reuse map[edgeKey]int,
	bias map[edgeKey]float64) (*searchResult, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is payment target")
	}

	labels := make(map[route.Vertex][]*pathLabel)
	start := &pathLabel{
		node:    r.spec.Target,
		amount:  amt,
		active:  true,
		logProb: 0,
	}
	labels[start.node] = []*pathLabel{start}

	pq := &labelQueue{}
	heap.Push(pq, start)

	var sourceLabel *pathLabel
	for pq.Len() > 0 {
		current := heap.Pop(pq).(*pathLabel)
		if !current.active {
			continue
		}
		if current.node == r.source {
			sourceLabel = current
			break
		}

		for _, edge := range r.incomingEdges[current.node] {
			if !r.edgeAvailable(edge, current.amount, extra) {
				continue
			}

			p := r.edgeProbability(edge, current.amount, extra)
			edgeFee := lnwire.MilliSatoshi(0)
			sending := current.amount
			if edge.from != r.source {
				edgeFee = edge.fee(current.amount)
				if edgeFee < 0 ||
					sending > lnwire.MilliSatoshi(math.MaxInt64)-edgeFee {

					continue
				}
				sending += edgeFee
			}

			edgeCost := float64(edgeFee) -
				riskWeight*math.Log(p) + 8_000
			edgeCost += r.penalty[edge.key]
			if bias != nil {
				edgeCost += bias[edge.key]
			}
			if reuse != nil && reuse[edge.key] > 0 {
				edgeCost += float64(reuse[edge.key]) * 3_200_000
			}

			next := &pathLabel{
				node:    edge.from,
				score:   current.score + edgeCost,
				amount:  sending,
				logProb: current.logProb + math.Log(p),
				edge:    edge,
				next:    current,
			}
			if addLabel(labels, next) {
				heap.Push(pq, next)
			}
		}
	}

	if sourceLabel == nil {
		return nil, errors.New("no route found")
	}

	path := make([]*candidateEdge, 0)
	for label := sourceLabel; label.edge != nil; label = label.next {
		path = append(path, label.edge)
	}
	rt, err := r.buildRoute(amt, path)
	if err != nil {
		return nil, err
	}

	return &searchResult{
		rt:      rt,
		path:    path,
		uses:    routeUses(rt, path),
		logProb: sourceLabel.logProb,
		fee:     rt.TotalAmount - amt,
	}, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, error) {

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))
	last := len(path) - 1

	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		nextEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			nextEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(nextEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forward := amt
		expiry := uint32(finalCltvDelta)
		if i < last {
			forward = amtOver[i+1]
			expiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func routeUses(rt *route.Route, path []*candidateEdge) []edgeUse {
	uses := make([]edgeUse, len(path))
	for i, edge := range path {
		amount := rt.TotalAmount
		if i > 0 {
			amount = rt.Hops[i-1].AmtToForward
		}
		uses[i] = edgeUse{edge: edge, amount: amount}
	}
	return uses
}

func deliveredAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func routeHash(rt *route.Route) uint64 {
	h := uint64(1469598103934665603)
	for _, hop := range rt.Hops {
		h ^= hop.ChannelID
		h *= 1099511628211
		for _, b := range hop.PubKeyBytes {
			h ^= uint64(b)
			h *= 1099511628211
		}
	}
	return h
}

func (r *candidateRouter) findFreshRoute(amt lnwire.MilliSatoshi,
	extra map[edgeKey]lnwire.MilliSatoshi,
	reuse map[edgeKey]int) (*searchResult, error) {

	bias := make(map[edgeKey]float64)
	var lastErr error

	for n := 0; n < 14; n++ {
		result, err := r.findRoute(amt, extra, reuse, bias)
		if err != nil {
			return nil, err
		}

		hash := routeHash(result.rt)
		failedAt, failed := r.tried[hash]
		if !failed || amt < failedAt {
			return result, nil
		}

		lastErr = errors.New("candidate paths already failed")
		if len(result.path) == 0 {
			break
		}

		index := int((hash + uint64(n)*7) %
			uint64(len(result.path)))
		bias[result.path[index].key] += 9_000_000
	}

	if lastErr == nil {
		lastErr = errors.New("no fresh route found")
	}
	return nil, lastErr
}

func addReservations(dst map[edgeKey]lnwire.MilliSatoshi,
	uses []edgeUse) {

	for _, use := range uses {
		dst[use.edge.key] += use.amount
	}
}

func copyReservations(src map[edgeKey]lnwire.MilliSatoshi) map[edgeKey]lnwire.MilliSatoshi {
	dst := make(map[edgeKey]lnwire.MilliSatoshi, len(src))
	for key, value := range src {
		dst[key] = value
	}
	return dst
}

func copyReuse(src map[edgeKey]int) map[edgeKey]int {
	dst := make(map[edgeKey]int, len(src))
	for key, value := range src {
		dst[key] = value
	}
	return dst
}

func planMetric(results []*searchResult) float64 {
	metric := -0.06 * float64(len(results))
	for _, result := range results {
		metric += result.logProb
		metric -= float64(result.fee) / 10_000_000
	}
	return metric
}

func uniqueAmounts(remaining lnwire.MilliSatoshi,
	slots int) []lnwire.MilliSatoshi {

	average := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)

	ratios := [][2]int64{
		{1, 1},
		{2, 3},
		{4, 3},
		{1, 2},
		{3, 2},
		{2, 5},
		{5, 3},
		{1, 4},
		{2, 1},
	}

	seen := make(map[lnwire.MilliSatoshi]bool)
	amounts := make([]lnwire.MilliSatoshi, 0, len(ratios))
	for _, ratio := range ratios {
		amount := average * lnwire.MilliSatoshi(ratio[0]) /
			lnwire.MilliSatoshi(ratio[1])
		if amount <= 0 {
			amount = 1
		}
		if amount >= remaining {
			continue
		}
		if remaining-amount <
			lnwire.MilliSatoshi(slots-1) {

			continue
		}
		if !seen[amount] {
			seen[amount] = true
			amounts = append(amounts, amount)
		}
	}

	return amounts
}

func (r *candidateRouter) searchPlan(
	remaining lnwire.MilliSatoshi, slots int,
	virtual map[edgeKey]lnwire.MilliSatoshi,
	reuse map[edgeKey]int, budget *int) ([]*searchResult, bool) {

	if remaining <= 0 || slots <= 0 || *budget <= 0 {
		return nil, false
	}

	if slots == 1 {
		*budget--
		result, err := r.findFreshRoute(remaining, virtual, reuse)
		if err != nil {
			return nil, false
		}
		return []*searchResult{result}, true
	}

	var best []*searchResult
	bestMetric := math.Inf(-1)

	for _, amount := range uniqueAmounts(remaining, slots) {
		if *budget <= 0 {
			break
		}
		*budget--

		result, err := r.findFreshRoute(amount, virtual, reuse)
		if err != nil {
			continue
		}

		nextVirtual := copyReservations(virtual)
		addReservations(nextVirtual, result.uses)

		nextReuse := copyReuse(reuse)
		for _, use := range result.uses {
			nextReuse[use.edge.key]++
		}

		tail, ok := r.searchPlan(
			remaining-amount, slots-1,
			nextVirtual, nextReuse, budget,
		)
		if !ok {
			continue
		}

		candidate := make([]*searchResult, 1, len(tail)+1)
		candidate[0] = result
		candidate = append(candidate, tail...)

		metric := planMetric(candidate)
		if metric > bestMetric {
			bestMetric = metric
			best = candidate
		}
	}

	return best, len(best) != 0
}

func (r *candidateRouter) buildPlanForParts(
	amt lnwire.MilliSatoshi, parts int) ([]*searchResult, bool) {

	budget := 36 + parts*10
	return r.searchPlan(
		amt, parts,
		make(map[edgeKey]lnwire.MilliSatoshi),
		make(map[edgeKey]int), &budget,
	)
}

func appendUniquePart(parts []int, value, limit int) []int {
	if value < 2 || value > limit {
		return parts
	}
	for _, existing := range parts {
		if existing == value {
			return parts
		}
	}
	return append(parts, value)
}

func (r *candidateRouter) preparePlan(amt lnwire.MilliSatoshi,
	partsLeft uint32) error {

	r.plan = nil
	if partsLeft == 0 {
		return errors.New("maximum in-flight parts reached")
	}

	var best []*searchResult
	bestMetric := math.Inf(-1)
	direct, directErr := r.findFreshRoute(amt, nil, nil)
	if directErr == nil {
		best = []*searchResult{direct}
		bestMetric = planMetric(best)
	}

	limit := partsLeft
	if limit > 32 {
		limit = 32
	}
	maxParts := int(limit)

	partCounts := make([]int, 0, 16)
	for parts := 2; parts <= maxParts && parts <= 10; parts++ {
		partCounts = append(partCounts, parts)
	}
	for _, parts := range []int{12, 16, 20, 24, 32, maxParts} {
		partCounts = appendUniquePart(partCounts, parts, maxParts)
	}

	for _, parts := range partCounts {
		results, ok := r.buildPlanForParts(amt, parts)
		if !ok {
			continue
		}

		metric := planMetric(results)
		if metric > bestMetric+0.04 {
			bestMetric = metric
			best = results
		}
	}

	if len(best) == 0 {
		if directErr != nil {
			return directErr
		}
		return errors.New("no route set found")
	}

	r.plan = make([]plannedRoute, len(best))
	for i, result := range best {
		r.plan[i] = plannedRoute{result: result}
	}
	return nil
}

func (r *candidateRouter) issue(result *searchResult) *route.Route {
	addReservations(r.reserved, result.uses)
	r.issued[result.rt] = result.uses
	return result.rt
}

func fallbackAmounts(amt, minimum lnwire.MilliSatoshi,
	allowBelow bool) []lnwire.MilliSatoshi {

	if minimum <= 0 {
		minimum = 1
	}

	raw := []lnwire.MilliSatoshi{
		amt,
		amt * 4 / 5,
		amt * 2 / 3,
		amt * 3 / 5,
		amt / 2,
		minimum,
	}
	if allowBelow {
		raw = append(raw, minimum*2/3, minimum/2)
	}

	seen := make(map[lnwire.MilliSatoshi]bool)
	result := make([]lnwire.MilliSatoshi, 0, len(raw))
	for _, amount := range raw {
		if amount <= 0 || amount > amt {
			continue
		}
		if !allowBelow && amount < minimum {
			continue
		}
		if !seen[amount] {
			seen[amount] = true
			result = append(result, amount)
		}
	}
	return result
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum in-flight parts reached")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.plan) > 0 {
		result := r.plan[0].result
		if deliveredAmount(result.rt) <= amt {
			r.plan = r.plan[1:]
			return r.issue(result), nil
		}
		r.plan = nil
	}

	if err := r.preparePlan(amt, partsLeft); err == nil &&
		len(r.plan) > 0 {

		result := r.plan[0].result
		r.plan = r.plan[1:]
		return r.issue(result), nil
	}

	minimum := amt
	if partsLeft > 1 {
		minimum = (amt + lnwire.MilliSatoshi(partsLeft) - 1) /
			lnwire.MilliSatoshi(partsLeft)
	}

	for _, tryAmt := range fallbackAmounts(
		amt, minimum, partsLeft > 2,
	) {
		result, err := r.findFreshRoute(tryAmt, nil, nil)
		if err == nil {
			return r.issue(result), nil
		}
	}

	return nil, errors.New("no route found")
}

func (r *candidateRouter) saveBelief(key edgeKey,
	b liquidityBelief) {

	r.beliefs[key] = b
	sharedBeliefs.Lock()
	sharedBeliefs.m[key] = b
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) learnSuccess(use edgeUse,
	totalObserved lnwire.MilliSatoshi) {

	key := use.edge.key
	b := r.beliefs[key]

	if totalObserved > b.lowerOK {
		b.lowerOK = totalObserved
	}
	if b.estimate == 0 || totalObserved > b.estimate {
		b.estimate = totalObserved
	} else {
		b.estimate = (b.estimate*3 + totalObserved) / 4
	}
	b.confidence = math.Min(1, b.confidence+0.40)

	if b.upper > 0 && totalObserved >= b.upper {
		b.upper = 0
	}
	if b.suspectAmt > 0 && totalObserved >= b.suspectAmt {
		b.suspectAmt = 0
		b.failVotes = 0
		b.lastFailPath = 0
	}

	r.saveBelief(key, b)
}

func (r *candidateRouter) learnFailure(edge *candidateEdge,
	totalObserved lnwire.MilliSatoshi, pathHash uint64) {

	if totalObserved <= 0 {
		return
	}

	key := edge.key
	b := r.beliefs[key]
	distinct := false

	if b.suspectAmt == 0 ||
		totalObserved < b.suspectAmt/2 ||
		totalObserved > b.suspectAmt*2 {

		b.suspectAmt = totalObserved
		b.failVotes = 1
		b.lastFailPath = pathHash
		distinct = true
	} else {
		if totalObserved < b.suspectAmt {
			b.suspectAmt = totalObserved
		}
		if pathHash != b.lastFailPath {
			distinct = true
			if b.failVotes < 255 {
				b.failVotes++
			}
			b.lastFailPath = pathHash
		}
	}

	if distinct {
		failedEstimate := totalObserved * 3 / 4
		if b.estimate == 0 {
			b.estimate = failedEstimate
		} else {
			b.estimate = (b.estimate*4 + failedEstimate) / 5
		}
		b.confidence = math.Min(1, b.confidence+0.10)
	}

	if b.failVotes >= 3 {
		if b.upper == 0 || b.suspectAmt < b.upper {
			b.upper = b.suspectAmt
		}
		if b.lowerOK >= b.upper {
			b.lowerOK = 0
		}
	}

	r.saveBelief(key, b)
}

func releaseReservations(reserved map[edgeKey]lnwire.MilliSatoshi,
	uses []edgeUse) {

	for _, use := range uses {
		current := reserved[use.edge.key]
		if current <= use.amount {
			delete(reserved, use.edge.key)
		} else {
			reserved[use.edge.key] = current - use.amount
		}
	}
}

func findFailureNode(rt *route.Route, source route.Vertex) int {
	if source == rt.SourcePubKey {
		return 0
	}
	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}
	return -1
}

func (r *candidateRouter) reconstructUses(
	rt *route.Route) []edgeUse {

	path := make([]*candidateEdge, 0, len(rt.Hops))
	from := rt.SourcePubKey

	for _, hop := range rt.Hops {
		var found *candidateEdge
		for _, edge := range r.incomingEdges[hop.PubKeyBytes] {
			if edge.from == from && edge.chanID == hop.ChannelID {
				found = edge
				break
			}
		}
		if found == nil {
			return nil
		}
		path = append(path, found)
		from = hop.PubKeyBytes
	}

	return routeUses(rt, path)
}

func (r *candidateRouter) ReportAttempt(attemptID uint64,
	rt *route.Route, result routing.SimHtlcResult) error {

	_ = attemptID
	if rt == nil {
		return errors.New("nil reported route")
	}

	uses, ok := r.issued[rt]
	if !ok {
		uses = r.reconstructUses(rt)
	}
	delete(r.issued, rt)

	if result.Failure == nil {
		for _, use := range uses {
			observed := r.held[use.edge.key] + use.amount
			r.learnSuccess(use, observed)
			r.held[use.edge.key] = observed

			if penalty := r.penalty[use.edge.key]; penalty > 0 {
				r.penalty[use.edge.key] = penalty * 0.15
			}
		}
		return nil
	}

	hash := routeHash(rt)
	delivered := deliveredAmount(rt)
	if old, exists := r.tried[hash]; !exists || delivered < old {
		r.tried[hash] = delivered
	}

	totalDemand := make(map[edgeKey]lnwire.MilliSatoshi, len(uses))
	for _, use := range uses {
		totalDemand[use.edge.key] = r.reserved[use.edge.key]
	}
	releaseReservations(r.reserved, uses)
	r.plan = nil

	failNode := findFailureNode(rt, result.FailureSource)
	if failNode < 0 || failNode >= len(uses) {
		// An unreadable onion failure only proves that this exact route
		// failed at this amount.
		return nil
	}

	primary := failNode
	code := result.Failure.Code()
	if code == lnwire.CodeTemporaryChannelFailure {
		use := uses[primary]
		r.penalty[use.edge.key] += 3_500_000
		r.learnFailure(
			use.edge, totalDemand[use.edge.key], hash,
		)

		// Adjacent edges are plausible under shifted attribution, but
		// receive only weak, payment-local evidence.
		if primary > 0 {
			r.penalty[uses[primary-1].edge.key] += 450_000
		}
		if primary+1 < len(uses) {
			r.penalty[uses[primary+1].edge.key] += 450_000
		}
		return nil
	}

	// A real policy failure will repeat, so avoid it strongly within this
	// payment. It never establishes a persistent liquidity bound.
	r.penalty[uses[primary].edge.key] += 10_000_000
	if primary > 0 {
		r.penalty[uses[primary-1].edge.key] += 600_000
	}
	if primary+1 < len(uses) {
		r.penalty[uses[primary+1].edge.key] += 600_000
	}

	return nil
}

var _ routing.SimRouter = (*candidateRouter)(nil)

func (r *candidateRouter) String() string {
	return fmt.Sprintf("candidate-router(%v->%v)", r.source, r.spec.Target)
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	chanID  uint64
	from, to route.Vertex

	capacity      lnwire.MilliSatoshi
	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

// Success observations are exact. Failure observations remain soft because
// their reported source may be shifted to an adjacent hop.
type candidateBelief struct {
	capacity lnwire.MilliSatoshi

	lowerOK lnwire.MilliSatoshi
	okStamp uint64

	failAmt    lnwire.MilliSatoshi
	failWeight float64
	failStamp  uint64
}

var candidateMemory = struct {
	sync.Mutex
	epoch   uint64
	beliefs map[candidateEdgeKey]candidateBelief
}{
	beliefs: make(map[candidateEdgeKey]candidateBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec
	epoch  uint64

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[candidateEdgeKey]candidateBelief

	// Includes successful shards already settled or held by atomic MPP.
	reserved map[candidateEdgeKey]lnwire.MilliSatoshi

	// Per-payment penalties provide route diversity without poisoning the
	// persistent liquidity model.
	edgePenalty map[candidateEdgeKey]float64

	retryCeiling lnwire.MilliSatoshi

	failedAttempts      uint32
	consecutiveFailures uint32
	successfulParts     uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	candidateMemory.Lock()
	candidateMemory.epoch++
	epoch := candidateMemory.epoch

	snapshot := make(map[candidateEdgeKey]candidateBelief,
		len(candidateMemory.beliefs))
	for key, belief := range candidateMemory.beliefs {
		snapshot[key] = belief
	}
	candidateMemory.Unlock()

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		epoch:         epoch,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[candidateEdgeKey]*candidateEdge),
		localBalances: localBalances,
		beliefs:       snapshot,
		reserved:      make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		edgePenalty:   make(map[candidateEdgeKey]float64),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key:    key,
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: policy.FeeBaseMSat,
					feeRatePPM: policy.
						FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[key] = edge

				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func candidateClampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005
	case p > 0.995:
		return 0.995
	default:
		return p
	}
}

// The prior represents a channel whose funds are normally concentrated on
// one side. Amounts near capacity encounter an additional logistic cliff.
func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.025)
	highMode := 1 / (1 + math.Exp(18*(x-0.82)))

	return candidateClampProbability(
		0.5*lowMode + 0.5*highMode,
	)
}

func (r *candidateRouter) evidenceConfidence(stamp uint64) float64 {
	if stamp == 0 {
		return 0
	}
	if r.epoch <= stamp+3 {
		return 1
	}

	age := float64(r.epoch - stamp - 3)
	return math.Exp(-age / 11)
}

func (r *candidateRouter) probability(edge *candidateEdge,
	totalAmt lnwire.MilliSatoshi) float64 {

	if edge.from == r.source {
		available := r.localBalances[edge.chanID]
		if totalAmt <= available {
			return 0.999
		}

		return 0.001
	}

	prior := candidatePrior(totalAmt, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok || belief.capacity != edge.capacity {
		return prior
	}

	p := prior

	if belief.lowerOK > 0 {
		confidence := r.evidenceConfidence(belief.okStamp)
		learned := prior

		if totalAmt <= belief.lowerOK {
			learned = 0.995
		} else {
			ratio := float64(belief.lowerOK) /
				float64(totalAmt)
			learned = prior +
				(0.995-prior)*ratio*ratio
		}

		p = confidence*learned + (1-confidence)*p
	}

	if belief.failAmt > 0 && belief.failWeight > 0 {
		confidence := r.evidenceConfidence(
			belief.failStamp,
		)
		ratio := float64(totalAmt) /
			float64(belief.failAmt)
		ratio = math.Max(0, math.Min(1, ratio))

		// A single readable attribution is useful but not a hard
		// ceiling. Repeated compatible blame progressively strengthens
		// the observation.
		severity := belief.failWeight *
			ratio * ratio * ratio
		multiplier := math.Exp(-1.12 * severity)
		multiplier = (1-confidence) +
			confidence*multiplier
		p *= multiplier
	}

	return candidateClampProbability(p)
}

type candidateItem struct {
	node  route.Vertex
	score float64
}

type candidateQueue []*candidateItem

func (q candidateQueue) Len() int {
	return len(q)
}

func (q candidateQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *candidateQueue) Push(value any) {
	*q = append(*q, value.(*candidateItem))
}

func (q *candidateQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]
	return last
}

type candidatePath struct {
	route       *route.Route
	edges       []*candidateEdge
	probability float64
	pressure    float64
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*candidatePath, error) {

	if amt <= 0 {
		return nil, errors.New("invalid payment amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is target")
	}

	scores := make(map[route.Vertex]float64)
	amounts := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)

	scores[r.spec.Target] = 0
	amounts[r.spec.Target] = amt

	pq := &candidateQueue{}
	heap.Push(pq, &candidateItem{
		node:  r.spec.Target,
		score: 0,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateItem)
		bestScore, ok := scores[item.node]
		if !ok || item.score > bestScore+1e-12 {
			continue
		}
		if item.node == r.source {
			break
		}

		arriving := amounts[item.node]

		for _, edge := range r.incomingEdges[item.node] {
			if !edge.usable(arriving) {
				continue
			}

			totalLiquidity := arriving +
				r.reserved[edge.key]
			if totalLiquidity < arriving ||
				totalLiquidity > edge.capacity {

				continue
			}

			if edge.from == r.source &&
				totalLiquidity >
					r.localBalances[edge.chanID] {

				continue
			}

			sending := arriving
			fee := lnwire.MilliSatoshi(0)
			if edge.from != r.source {
				fee = edge.fee(arriving)
				sending += fee
				if sending < arriving {
					continue
				}
			}

			probability := r.probability(
				edge, totalLiquidity,
			)
			edgeCost := -math.Log(probability) + 0.07
			if arriving > 0 {
				edgeCost += 4 * float64(fee) /
					float64(arriving)
			}
			edgeCost += r.edgePenalty[edge.key]

			newScore := item.score + edgeCost
			oldScore, visited := scores[edge.from]
			if visited && newScore >= oldScore {
				continue
			}

			scores[edge.from] = newScore
			amounts[edge.from] = sending
			next[edge.from] = edge
			heap.Push(pq, &candidateItem{
				node:  edge.from,
				score: newScore,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	rt, path, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, err
	}

	probability := 1.0
	pressure := 0.0

	for i, edge := range path {
		amtOver := candidateRouteAmount(rt, i)
		totalLiquidity := amtOver +
			r.reserved[edge.key]

		probability *= r.probability(
			edge, totalLiquidity,
		)

		denominator := edge.capacity
		if edge.from == r.source {
			denominator = r.localBalances[edge.chanID]
		}

		if denominator > 0 {
			ratio := float64(totalLiquidity) /
				float64(denominator)
			if ratio > pressure {
				pressure = ratio
			}
		}
	}

	return &candidatePath{
		route:       rt,
		edges:       path,
		probability: probability,
		pressure:    pressure,
	}, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route,
	[]*candidateEdge, error) {

	const finalCltvDelta = uint32(40)

	var path []*candidateEdge
	seen := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if seen[node] {
			return nil, nil, errors.New("cycle in route")
		}
		seen[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, nil, fmt.Errorf(
				"broken path at %v", node,
			)
		}

		path = append(path, edge)
		node = edge.to
	}

	if len(path) == 0 {
		return nil, nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := finalCltvDelta

		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, path, nil
}

func candidateCeilDiv(a lnwire.MilliSatoshi,
	b uint32) lnwire.MilliSatoshi {

	if b <= 1 {
		return a
	}

	divisor := lnwire.MilliSatoshi(b)
	return (a + divisor - 1) / divisor
}

func candidateRouteAmount(rt *route.Route,
	edgeIndex int) lnwire.MilliSatoshi {

	if edgeIndex == 0 {
		return rt.TotalAmount
	}

	return rt.Hops[edgeIndex-1].AmtToForward
}

func candidateRouteEdgeKey(rt *route.Route,
	edgeIndex int) candidateEdgeKey {

	from := rt.SourcePubKey
	if edgeIndex > 0 {
		from = rt.Hops[edgeIndex-1].PubKeyBytes
	}

	return candidateEdgeKey{
		chanID: rt.Hops[edgeIndex].ChannelID,
		from:   from,
		to:     rt.Hops[edgeIndex].PubKeyBytes,
	}
}

func (r *candidateRouter) reservePath(path *candidatePath,
	add bool) {

	for i, edge := range path.edges {
		amt := candidateRouteAmount(path.route, i)
		if add {
			r.reserved[edge.key] += amt
			continue
		}

		current := r.reserved[edge.key]
		if current <= amt {
			delete(r.reserved, edge.key)
		} else {
			r.reserved[edge.key] = current - amt
		}
	}
}

type candidatePlan struct {
	paths     []*candidatePath
	delivered []lnwire.MilliSatoshi
	score     float64
}

func candidatePathCost(path *candidatePath,
	delivered lnwire.MilliSatoshi) float64 {

	probability := math.Max(path.probability, 1e-12)
	score := -math.Log(probability) + 0.04

	fee := path.route.TotalAmount - delivered
	if fee > 0 && delivered > 0 {
		score += 3 * float64(fee) /
			float64(delivered)
	}

	return score
}

func candidateShardAmounts(total lnwire.MilliSatoshi,
	parts uint32) []lnwire.MilliSatoshi {

	if parts <= 1 {
		return []lnwire.MilliSatoshi{total}
	}

	base := candidateCeilDiv(total, parts)
	factors := [...]int64{100, 120, 80, 145, 65, 170}
	maximum := total - lnwire.MilliSatoshi(parts-1)

	seen := make(map[lnwire.MilliSatoshi]bool)
	result := make([]lnwire.MilliSatoshi, 0, len(factors))

	for _, factor := range factors {
		amt := base * lnwire.MilliSatoshi(factor) / 100
		if amt < 1 {
			amt = 1
		}
		if amt > maximum {
			amt = maximum
		}
		if amt <= 0 || amt >= total || seen[amt] {
			continue
		}

		seen[amt] = true
		result = append(result, amt)
	}

	return result
}

// searchPlan jointly chooses shard amounts and routes. Virtual reservations
// make later shards account for liquidity already allocated to earlier
// members of the prospective atomic route set.
func (r *candidateRouter) searchPlan(remaining lnwire.MilliSatoshi,
	parts uint32, root bool, budget *int) (*candidatePlan, bool) {

	if remaining <= 0 || parts == 0 || *budget <= 0 {
		return nil, false
	}

	if parts == 1 {
		*budget--
		path, err := r.findRoute(remaining)
		if err != nil {
			return nil, false
		}

		score := candidatePathCost(path, remaining)
		if root && r.retryCeiling > 0 &&
			remaining > r.retryCeiling {

			ratio := float64(remaining) /
				float64(r.retryCeiling)
			score += 1.8 + 0.6*(ratio-1)
		}

		return &candidatePlan{
			paths:     []*candidatePath{path},
			delivered: []lnwire.MilliSatoshi{remaining},
			score:     score,
		}, true
	}

	var best *candidatePlan

	for _, shard := range candidateShardAmounts(
		remaining, parts,
	) {
		if *budget <= 0 {
			break
		}

		*budget--
		path, err := r.findRoute(shard)
		if err != nil {
			continue
		}

		firstCost := candidatePathCost(path, shard)
		if root && r.retryCeiling > 0 &&
			shard > r.retryCeiling {

			ratio := float64(shard) /
				float64(r.retryCeiling)
			firstCost += 1.8 + 0.6*(ratio-1)
		}

		r.reservePath(path, true)
		tail, ok := r.searchPlan(
			remaining-shard, parts-1, false, budget,
		)
		r.reservePath(path, false)

		if !ok {
			continue
		}

		plan := &candidatePlan{
			paths: append(
				[]*candidatePath{path},
				tail.paths...,
			),
			delivered: append(
				[]lnwire.MilliSatoshi{shard},
				tail.delivered...,
			),
			score: firstCost + tail.score,
		}

		if best == nil || plan.score < best.score {
			best = plan
		}
	}

	return best, best != nil
}

// RequestRoute first constructs a feasible route set in memory. This avoids
// consuming attempts on a halving probe ladder and permits unequal atomic
// MPP splits when parallel corridors have unequal carrying capacity.
func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid remaining amount")
	}

	if r.consecutiveFailures >= 64 ||
		r.failedAttempts >= 96 {

		return nil, errors.New("routing attempts exhausted")
	}

	partsLeft := uint32(1)
	if r.spec.MaxParts > 0 {
		if inFlightHtlcs >= r.spec.MaxParts {
			return nil, errors.New("maximum parts reached")
		}
		partsLeft = r.spec.MaxParts - inFlightHtlcs
	}

	if partsLeft <= 1 {
		path, err := r.findRoute(amt)
		if err != nil {
			return nil, err
		}

		return path.route, nil
	}

	full, fullErr := r.findRoute(amt)

	// Below the bimodal cliff, splitting multiplies the number of uncertain
	// channels without materially improving per-channel probability.
	if fullErr == nil && r.retryCeiling == 0 &&
		(amt < 20_000_000 ||
			full.pressure < 0.55 ||
			full.probability >= 0.68) {

		return full.route, nil
	}

	var best *candidatePlan
	if fullErr == nil {
		score := candidatePathCost(full, amt)
		if r.retryCeiling > 0 && amt > r.retryCeiling {
			ratio := float64(amt) /
				float64(r.retryCeiling)
			score += 1.8 + 0.6*(ratio-1)
		}

		best = &candidatePlan{
			paths:     []*candidatePath{full},
			delivered: []lnwire.MilliSatoshi{amt},
			score:     score,
		}
	}

	maxPlannedParts := partsLeft
	if maxPlannedParts > 10 {
		maxPlannedParts = 10
	}

	for parts := uint32(2); parts <= maxPlannedParts; parts++ {
		budget := 110
		plan, ok := r.searchPlan(
			amt, parts, true, &budget,
		)
		if !ok {
			continue
		}
		if best == nil || plan.score < best.score {
			best = plan
		}
	}

	if best != nil && len(best.paths) > 0 {
		return best.paths[0].route, nil
	}

	// A complete set may evade the bounded planner. Retain a conservative
	// lower-amount fallback instead of abandoning a routable payment.
	desired := candidateCeilDiv(amt, partsLeft)
	if r.retryCeiling > 0 &&
		r.retryCeiling < desired {

		desired = r.retryCeiling
	}
	if desired <= 0 {
		desired = 1
	}

	var lastErr error
	for desired > 0 {
		path, err := r.findRoute(desired)
		if err == nil {
			return path.route, nil
		}
		lastErr = err

		if desired == 1 {
			break
		}

		smaller := desired * 72 / 100
		if smaller < 1 {
			smaller = 1
		}
		if smaller >= desired {
			break
		}
		desired = smaller
	}

	if lastErr == nil {
		lastErr = errors.New("no route found")
	}

	return nil, lastErr
}

func candidateFailureEdge(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func candidateIsLiquidityFailure(failure any) bool {
	switch failure.(type) {
	case *lnwire.FailTemporaryChannelFailure:
		return true
	default:
		return false
	}
}

func candidateIsPolicyFailure(failure any) bool {
	switch failure.(type) {
	case *lnwire.FailFeeInsufficient,
		*lnwire.FailIncorrectCltvExpiry:

		return true
	default:
		return false
	}
}

func (r *candidateRouter) saveBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	candidateMemory.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) recordSuccess(key candidateEdgeKey,
	totalAmt lnwire.MilliSatoshi) {

	edge, ok := r.edges[key]
	if !ok || edge.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.capacity != 0 &&
		belief.capacity != edge.capacity {

		belief = candidateBelief{}
	}
	belief.capacity = edge.capacity

	oldConfidence := r.evidenceConfidence(belief.okStamp)
	if belief.lowerOK == 0 || oldConfidence < 0.45 {
		belief.lowerOK = totalAmt
	} else if totalAmt > belief.lowerOK {
		belief.lowerOK = totalAmt
	}
	belief.okStamp = r.epoch

	// A truthful success directly contradicts failures at or below the
	// demonstrated amount.
	if belief.failAmt > 0 && totalAmt >= belief.failAmt {
		belief.failWeight *= 0.12
		if belief.failWeight < 0.08 {
			belief.failAmt = 0
			belief.failWeight = 0
			belief.failStamp = 0
		}
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) recordFailure(key candidateEdgeKey,
	totalAmt lnwire.MilliSatoshi, weight float64) {

	edge, ok := r.edges[key]
	if !ok || edge.from == r.source || weight <= 0 {
		return
	}

	belief := r.beliefs[key]
	if belief.capacity != 0 &&
		belief.capacity != edge.capacity {

		belief = candidateBelief{}
	}
	belief.capacity = edge.capacity

	if belief.failWeight > 0 {
		confidence := r.evidenceConfidence(
			belief.failStamp,
		)
		belief.failWeight *= confidence
		if belief.failWeight < 0.08 {
			belief.failWeight = 0
			belief.failAmt = 0
		}
	}

	combined := belief.failWeight + weight
	if belief.failAmt == 0 || belief.failWeight == 0 {
		belief.failAmt = totalAmt
	} else {
		average := (float64(belief.failAmt)*
			belief.failWeight +
			float64(totalAmt)*weight) / combined
		belief.failAmt = lnwire.MilliSatoshi(average)
	}

	belief.failWeight = math.Min(5, combined)
	belief.failStamp = r.epoch

	r.saveBelief(key, belief)
}

func (r *candidateRouter) recordFailureIndex(
	rt *route.Route, index int, weight float64) {

	if index < 0 || index >= len(rt.Hops) {
		return
	}

	key := candidateRouteEdgeKey(rt, index)
	amtOver := candidateRouteAmount(rt, index)
	totalAmt := amtOver + r.reserved[key]

	r.recordFailure(key, totalAmt, weight)
}

func (r *candidateRouter) addPenalty(key candidateEdgeKey,
	increment, maximum float64) {

	r.edgePenalty[key] = math.Min(
		maximum, r.edgePenalty[key]+increment,
	)
}

// ReportAttempt treats settled attempts as exact observations. Readable
// liquidity blame is spread across the reported edge and its neighbors,
// matching the known one-hop attribution noise. Unreadable failures affect
// only temporary route diversity and never persistent liquidity beliefs.
func (r *candidateRouter) ReportAttempt(attemptID uint64,
	rt *route.Route, result routing.SimHtlcResult) error {

	_ = attemptID

	if rt == nil || len(rt.Hops) == 0 {
		return nil
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key := candidateRouteEdgeKey(rt, i)
			amtOver := candidateRouteAmount(rt, i)
			totalAmt := amtOver + r.reserved[key]

			r.recordSuccess(key, totalAmt)
			r.reserved[key] += amtOver
			r.edgePenalty[key] *= 0.22
		}

		r.successfulParts++
		r.consecutiveFailures = 0
		r.retryCeiling = 0
		return nil
	}

	r.failedAttempts++
	r.consecutiveFailures++

	for i := range rt.Hops {
		key := candidateRouteEdgeKey(rt, i)
		r.addPenalty(key, 0.035, 1.1)
	}

	failIndex := candidateFailureEdge(
		rt, result.FailureSource,
	)
	attributed := failIndex >= 0 &&
		failIndex < len(rt.Hops)

	if candidateIsLiquidityFailure(result.Failure) &&
		attributed {

		// Most readable reports are correct, but adjacent edges retain
		// some probability because shifted attribution is common.
		r.recordFailureIndex(rt, failIndex, 0.72)
		r.recordFailureIndex(rt, failIndex-1, 0.14)
		r.recordFailureIndex(rt, failIndex+1, 0.14)

		center := candidateRouteEdgeKey(rt, failIndex)
		r.addPenalty(center, 0.72, 3.5)

		if failIndex > 0 {
			key := candidateRouteEdgeKey(
				rt, failIndex-1,
			)
			r.addPenalty(key, 0.16, 2)
		}
		if failIndex+1 < len(rt.Hops) {
			key := candidateRouteEdgeKey(
				rt, failIndex+1,
			)
			r.addPenalty(key, 0.16, 2)
		}

		delivered := rt.Hops[len(rt.Hops)-1].
			AmtToForward
		lowerRetry := delivered * 70 / 100
		if lowerRetry < 1 {
			lowerRetry = 1
		}

		if r.retryCeiling == 0 ||
			lowerRetry < r.retryCeiling {

			r.retryCeiling = lowerRetry
		}

		return nil
	}

	if candidateIsPolicyFailure(result.Failure) &&
		attributed {

		key := candidateRouteEdgeKey(rt, failIndex)
		r.addPenalty(key, 1.35, 4)

		if failIndex > 0 {
			neighbor := candidateRouteEdgeKey(
				rt, failIndex-1,
			)
			r.addPenalty(neighbor, 0.18, 1.5)
		}
		if failIndex+1 < len(rt.Hops) {
			neighbor := candidateRouteEdgeKey(
				rt, failIndex+1,
			)
			r.addPenalty(neighbor, 0.18, 1.5)
		}
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"reflect"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

func (e *candidateEdge) upperAllows(amt lnwire.MilliSatoshi) bool {
	if amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	conf      uint8

	suspectAmt   lnwire.MilliSatoshi
	suspectVotes uint8
}

var candidateBeliefStore = struct {
	sync.Mutex
	beliefs map[candidateEdgeKey]*candidateBelief
}{
	beliefs: make(map[candidateEdgeKey]*candidateBelief),
}

type candidateLocalFailure struct {
	upper lnwire.MilliSatoshi
	count uint8
}

type candidateTraversal struct {
	key  candidateEdgeKey
	edge *candidateEdge
	amt  lnwire.MilliSatoshi
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec
	atomic bool

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	reserved    map[candidateEdgeKey]lnwire.MilliSatoshi
	usedTotals  map[candidateEdgeKey]lnwire.MilliSatoshi
	localFails  map[candidateEdgeKey]candidateLocalFailure
	edgePenalty map[candidateEdgeKey]float64
	failedRoute map[uint64]uint8

	plan []*route.Route

	failures     uint32
	unknownFails uint32
	retryCap     lnwire.MilliSatoshi
	delivered    lnwire.MilliSatoshi
	settled      bool
}

func candidateAtomicMPP(spec *routing.SimPaymentSpec) bool {
	if spec == nil {
		return false
	}

	v := reflect.ValueOf(spec)
	if v.Kind() == reflect.Pointer {
		if v.IsNil() {
			return false
		}
		v = v.Elem()
	}
	if v.Kind() != reflect.Struct {
		return false
	}

	for _, name := range []string{"AtomicMPP", "AtomicMpp", "Atomic"} {
		field := v.FieldByName(name)
		if field.IsValid() && field.Kind() == reflect.Bool {
			return field.Bool()
		}
	}

	return false
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		atomic:        candidateAtomicMPP(spec),
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[candidateEdgeKey]*candidateEdge),
		localBalances: localBalances,
		reserved:      make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		usedTotals:    make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		localFails:    make(map[candidateEdgeKey]candidateLocalFailure),
		edgePenalty:   make(map[candidateEdgeKey]float64),
		failedRoute:   make(map[uint64]uint8),
	}

	ctx := context.Background()
	seen := make(map[route.Vertex]bool)
	queue := []route.Vertex{source}
	seen[source] = true

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[key] = edge

				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.002
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.48 * math.Exp(-x/0.024)
	highMode := 0.50 / (1 + math.Exp((x-0.90)/0.026))
	p := 0.005 + lowMode + highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func candidateLogisticProbability(amt, estimate,
	capacity lnwire.MilliSatoshi) float64 {

	if capacity <= 0 {
		return 0.005
	}

	scale := 0.065 * float64(capacity)
	if scale < 1 {
		scale = 1
	}

	z := (float64(amt) - float64(estimate)) / scale
	if z >= 30 {
		return 0.005
	}
	if z <= -30 {
		return 0.995
	}

	return 1 / (1 + math.Exp(z))
}

func (r *candidateRouter) edgeProbability(e *candidateEdge,
	amt lnwire.MilliSatoshi,
	extra map[candidateEdgeKey]lnwire.MilliSatoshi) float64 {

	required := amt + r.reserved[e.key]
	if extra != nil {
		required += extra[e.key]
	}
	if required > e.capacity {
		return 0.001
	}

	if e.key.from == r.source {
		if r.localBalances[e.key.chanID] < required {
			return 0.001
		}
		return 0.999
	}

	p := candidatePrior(required, e.capacity)

	candidateBeliefStore.Lock()
	stored, ok := candidateBeliefStore.beliefs[e.key]
	var belief candidateBelief
	if ok {
		belief = *stored
	}
	candidateBeliefStore.Unlock()

	if ok {
		if belief.estimate > 0 && belief.conf > 0 {
			q := candidateLogisticProbability(
				required, belief.estimate, e.capacity,
			)
			weight := 0.13 * float64(belief.conf)
			if weight > 0.72 {
				weight = 0.72
			}
			p = (1-weight)*p + weight*q
		}

		if belief.lowerOK > 0 && required <= belief.lowerOK {
			p = math.Max(p, 0.995)
		}

		if belief.upperFail > 0 {
			switch {
			case required >= belief.upperFail:
				p = math.Min(p, 0.007)

			case belief.lowerOK > 0 &&
				belief.upperFail > belief.lowerOK:

				span := float64(
					belief.upperFail - belief.lowerOK,
				)
				pos := float64(
					required - belief.lowerOK,
				) / span
				if pos > 0 {
					bounded := 0.995*(1-pos) + 0.007*pos
					p = 0.30*p + 0.70*bounded
				}
			}
		}
	}

	if local, ok := r.localFails[e.key]; ok &&
		required >= local.upper {

		if local.count >= 2 {
			p = math.Min(p, 0.003)
		} else {
			p *= 0.10
		}
	}

	if p < 0.002 {
		return 0.002
	}
	if p > 0.995 {
		return 0.995
	}

	return p
}

func (r *candidateRouter) edgeCost(e *candidateEdge,
	amt lnwire.MilliSatoshi,
	extra map[candidateEdgeKey]lnwire.MilliSatoshi,
	diversity map[candidateEdgeKey]float64) float64 {

	p := r.edgeProbability(e, amt, extra)
	cost := -math.Log(p) + 0.018 + r.edgePenalty[e.key]

	if diversity != nil {
		cost += diversity[e.key]
	}

	reserved := r.reserved[e.key]
	if extra != nil {
		reserved += extra[e.key]
	}
	if reserved > 0 && e.capacity > 0 {
		cost += 0.05 +
			0.45*float64(reserved)/float64(e.capacity)
	}

	return cost
}

type candidateDijkstraItem struct {
	node  route.Vertex
	score float64
	amt   lnwire.MilliSatoshi
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *candidateDijkstraQueue) Push(x any) {
	*q = append(*q, x.(*candidateDijkstraItem))
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi,
	extra map[candidateEdgeKey]lnwire.MilliSatoshi,
	diversity map[candidateEdgeKey]float64) (*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}

	score := make(map[route.Vertex]float64)
	arriving := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)

	score[r.spec.Target] = 0
	arriving[r.spec.Target] = amt

	pq := &candidateDijkstraQueue{}
	heap.Push(pq, &candidateDijkstraItem{
		node: r.spec.Target,
		amt:  amt,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)
		bestScore, ok := score[item.node]
		if !ok || item.score > bestScore+1e-12 {
			continue
		}
		if item.amt != arriving[item.node] {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOver := item.amt
			if !edge.policyAllows(amtOver) {
				continue
			}

			required := amtOver + r.reserved[edge.key]
			if extra != nil {
				required += extra[edge.key]
			}
			if required > edge.capacity {
				continue
			}
			if edge.key.from == r.source &&
				r.localBalances[edge.key.chanID] < required {

				continue
			}

			if local, ok := r.localFails[edge.key]; ok &&
				local.count >= 2 &&
				required >= local.upper {

				continue
			}

			sending := amtOver
			feeCost := 0.0
			if edge.key.from != r.source {
				fee := edge.fee(amtOver)
				sending += fee

				denom := float64(amt)
				if denom < 1 {
					denom = 1
				}
				feeCost = 22 * float64(fee) / denom
			}

			newScore := item.score +
				r.edgeCost(
					edge, amtOver, extra, diversity,
				) + feeCost

			oldScore, exists := score[edge.key.from]
			if exists && newScore >= oldScore {
				continue
			}

			score[edge.key.from] = newScore
			arriving[edge.key.from] = sending
			next[edge.key.from] = edge
			heap.Push(pq, &candidateDijkstraItem{
				node:  edge.key.from,
				score: newScore,
				amt:   sending,
			})
		}
	}

	if _, ok := score[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}

	pathProbability := 1.0
	for _, traversal := range r.routeTraversals(rt) {
		pathProbability *= r.edgeProbability(
			traversal.edge, traversal.amt, extra,
		)
	}

	return rt, pathProbability, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
	}

	return r.buildRouteFromPath(amt, path)
}

func (r *candidateRouter) buildRouteFromPath(
	amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		if !edge.policyAllows(amtOver[i]) {
			return nil, errors.New("path violates channel policy")
		}

		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateCeilDiv(amt lnwire.MilliSatoshi,
	parts uint32) lnwire.MilliSatoshi {

	if parts <= 1 {
		return amt
	}

	divisor := lnwire.MilliSatoshi(parts)
	return (amt + divisor - 1) / divisor
}

func candidateDeliveredAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func (r *candidateRouter) routeTraversals(
	rt *route.Route) []candidateTraversal {

	if rt == nil {
		return nil
	}

	traversals := make([]candidateTraversal, 0, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		key := candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		edge := r.edges[key]
		if edge == nil {
			from = hop.PubKeyBytes
			continue
		}

		amt := rt.TotalAmount
		if i > 0 {
			amt = rt.Hops[i-1].AmtToForward
		}

		traversals = append(traversals, candidateTraversal{
			key:  key,
			edge: edge,
			amt:  amt,
		})
		from = hop.PubKeyBytes
	}

	return traversals
}

func (r *candidateRouter) pathFromRoute(
	rt *route.Route) ([]*candidateEdge, bool) {

	traversals := r.routeTraversals(rt)
	if len(traversals) != len(rt.Hops) {
		return nil, false
	}

	path := make([]*candidateEdge, len(traversals))
	for i := range traversals {
		path[i] = traversals[i].edge
	}
	return path, true
}

func candidateRouteHash(rt *route.Route, withAmount bool) uint64 {
	h := uint64(1469598103934665603)
	for _, hop := range rt.Hops {
		h ^= hop.ChannelID
		h *= 1099511628211
	}
	if withAmount {
		h ^= uint64(candidateDeliveredAmount(rt))
		h *= 1099511628211
	}
	return h
}

func (r *candidateRouter) credibleLimit(
	e *candidateEdge) lnwire.MilliSatoshi {

	if e.key.from == r.source {
		limit := r.localBalances[e.key.chanID]
		if limit > e.capacity {
			limit = e.capacity
		}
		return limit
	}

	limit := e.capacity * 88 / 100
	if e.maxHTLC > 0 && e.maxHTLC < limit {
		limit = e.maxHTLC
	}

	candidateBeliefStore.Lock()
	stored := candidateBeliefStore.beliefs[e.key]
	var belief candidateBelief
	if stored != nil {
		belief = *stored
	}
	candidateBeliefStore.Unlock()

	if stored != nil {
		if belief.lowerOK > limit {
			limit = belief.lowerOK
		}

		if belief.estimate > 0 && belief.conf >= 2 {
			estimateLimit := belief.estimate * 94 / 100
			if estimateLimit > belief.lowerOK &&
				estimateLimit < limit {

				limit = estimateLimit
			}
		}

		if belief.upperFail > 0 {
			failedLimit := belief.upperFail * 68 / 100
			if failedLimit < limit {
				limit = failedLimit
			}
		}
	}

	if local, ok := r.localFails[e.key]; ok && local.upper > 0 {
		factor := lnwire.MilliSatoshi(72)
		if local.count >= 2 {
			factor = 58
		}
		localLimit := local.upper * factor / 100
		if localLimit < limit {
			limit = localLimit
		}
	}

	if limit > e.capacity {
		limit = e.capacity
	}
	return limit
}

func (r *candidateRouter) pathUpperFeasible(
	amt lnwire.MilliSatoshi, path []*candidateEdge,
	extra map[candidateEdgeKey]lnwire.MilliSatoshi) bool {

	if amt <= 0 || len(path) == 0 {
		return false
	}

	rt, err := r.buildRouteIgnoringMinimums(amt, path)
	if err != nil {
		return false
	}

	for _, traversal := range r.routeTraversals(rt) {
		if !traversal.edge.upperAllows(traversal.amt) {
			return false
		}

		required := traversal.amt + r.reserved[traversal.key]
		if extra != nil {
			required += extra[traversal.key]
		}
		if required > r.credibleLimit(traversal.edge) {
			return false
		}
	}

	return true
}

func (r *candidateRouter) buildRouteIgnoringMinimums(
	amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, error) {

	if amt <= 0 || len(path) == 0 {
		return nil, errors.New("invalid path")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))
	last := len(path) - 1

	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		if !edge.upperAllows(amtOver[i]) {
			return nil, errors.New("amount exceeds path limit")
		}

		forward := amt
		expiry := uint32(finalCltvDelta)
		if i < last {
			forward = amtOver[i+1]
			expiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func (r *candidateRouter) fixedPathMax(
	upper lnwire.MilliSatoshi, path []*candidateEdge,
	extra map[candidateEdgeKey]lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if upper <= 0 {
		return 0
	}

	low := lnwire.MilliSatoshi(0)
	high := upper

	for low < high {
		mid := low + (high-low+1)/2
		if r.pathUpperFeasible(mid, path, extra) {
			low = mid
		} else {
			high = mid - 1
		}
	}

	return low
}

func (r *candidateRouter) addExtraReservation(
	extra map[candidateEdgeKey]lnwire.MilliSatoshi,
	rt *route.Route) {

	for _, traversal := range r.routeTraversals(rt) {
		extra[traversal.key] += traversal.amt
	}
}

func (r *candidateRouter) targetPartCount(
	amt lnwire.MilliSatoshi, available uint32) uint32 {

	if available <= 1 {
		return 1
	}

	var target uint32
	switch {
	case amt <= 25_000_000:
		target = 1
	case amt <= 100_000_000:
		target = 4
	case amt <= 500_000_000:
		target = 8
	case amt <= 1_500_000_000:
		target = 12
	default:
		target = 16
	}

	if target > available {
		target = available
	}
	if target == 0 {
		target = 1
	}
	return target
}

type candidatePathCapacity struct {
	path []*candidateEdge
	max  lnwire.MilliSatoshi
}

func (r *candidateRouter) buildJointPlan(
	amt lnwire.MilliSatoshi,
	slots uint32) []*route.Route {

	count := r.targetPartCount(amt, slots)
	if count <= 1 {
		rt, _, err := r.findRoute(amt, nil, nil)
		if err != nil {
			return nil
		}
		return []*route.Route{rt}
	}

	probe := candidateCeilDiv(amt, count)
	probe = probe * 2 / 3
	if probe < 1 {
		probe = 1
	}

	discoveryReserve := make(
		map[candidateEdgeKey]lnwire.MilliSatoshi,
	)
	diversity := make(map[candidateEdgeKey]float64)
	seenPaths := make(map[uint64]bool)
	paths := make([]candidatePathCapacity, 0, count)

	for uint32(len(paths)) < count {
		var rt *route.Route
		searchAmt := probe
		for tries := 0; tries < 5; tries++ {
			found, _, err := r.findRoute(
				searchAmt, discoveryReserve, diversity,
			)
			if err == nil {
				rt = found
				break
			}

			searchAmt = searchAmt * 2 / 3
			if searchAmt < 1 {
				searchAmt = 1
			}
		}
		if rt == nil {
			break
		}

		pathHash := candidateRouteHash(rt, false)
		if seenPaths[pathHash] {
			for _, traversal := range r.routeTraversals(rt) {
				diversity[traversal.key] += 2.5
			}
			continue
		}
		seenPaths[pathHash] = true

		path, ok := r.pathFromRoute(rt)
		if !ok {
			break
		}

		pathMax := r.fixedPathMax(amt, path, nil)
		if pathMax <= 0 {
			for _, traversal := range r.routeTraversals(rt) {
				diversity[traversal.key] += 2.5
			}
			continue
		}

		paths = append(paths, candidatePathCapacity{
			path: path,
			max:  pathMax,
		})

		nominal := searchAmt
		if nominal > pathMax {
			nominal = pathMax
		}
		nominalRoute, err := r.buildRouteFromPath(nominal, path)
		if err == nil {
			r.addExtraReservation(discoveryReserve, nominalRoute)
		}
		for _, edge := range path {
			diversity[edge.key] += 1.35
		}
	}

	if len(paths) == 0 {
		return nil
	}

	sort.Slice(paths, func(i, j int) bool {
		return paths[i].max < paths[j].max
	})

	extra := make(map[candidateEdgeKey]lnwire.MilliSatoshi)
	plan := make([]*route.Route, 0, len(paths))
	remaining := amt

	for i := 0; i < len(paths) && remaining > 0; i++ {
		maxNow := r.fixedPathMax(
			remaining, paths[i].path, extra,
		)
		if maxNow <= 0 {
			continue
		}

		pathsLeft := uint32(len(paths) - i)
		desired := candidateCeilDiv(remaining, pathsLeft)

		futureCapacity := lnwire.MilliSatoshi(0)
		for j := i + 1; j < len(paths); j++ {
			futureCapacity += r.fixedPathMax(
				remaining, paths[j].path, extra,
			)
			if futureCapacity >= remaining {
				break
			}
		}

		required := lnwire.MilliSatoshi(0)
		if futureCapacity < remaining {
			required = remaining - futureCapacity
		}

		take := desired
		if take < required {
			take = required
		}
		if take > maxNow {
			take = maxNow
		}
		if take > remaining {
			take = remaining
		}
		if take <= 0 {
			continue
		}

		rt, err := r.buildRouteFromPath(take, paths[i].path)
		if err != nil {
			if maxNow != take {
				rt, err = r.buildRouteFromPath(
					maxNow, paths[i].path,
				)
			}
			if err != nil {
				continue
			}
			take = candidateDeliveredAmount(rt)
		}

		if r.failedRoute[candidateRouteHash(rt, true)] >= 2 {
			continue
		}

		plan = append(plan, rt)
		r.addExtraReservation(extra, rt)
		remaining -= take
	}

	if remaining != 0 || len(plan) == 0 ||
		uint32(len(plan)) > slots {

		return nil
	}

	return plan
}

func (r *candidateRouter) buildGreedyPlan(
	amt lnwire.MilliSatoshi,
	slots uint32) []*route.Route {

	count := r.targetPartCount(amt, slots)
	extra := make(map[candidateEdgeKey]lnwire.MilliSatoshi)
	plan := make([]*route.Route, 0, count)
	remaining := amt

	for i := uint32(0); i < count && remaining > 0; i++ {
		left := count - i
		shard := candidateCeilDiv(remaining, left)

		rt, _, err := r.findRoute(shard, extra, nil)
		if err != nil {
			return nil
		}
		if r.failedRoute[candidateRouteHash(rt, true)] >= 2 {
			return nil
		}

		plan = append(plan, rt)
		r.addExtraReservation(extra, rt)
		remaining -= candidateDeliveredAmount(rt)
	}

	if remaining != 0 {
		return nil
	}
	return plan
}

func candidatePlanAmount(plan []*route.Route) lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	for _, rt := range plan {
		total += candidateDeliveredAmount(rt)
	}
	return total
}

func (r *candidateRouter) freshRoute(
	amt lnwire.MilliSatoshi) (*route.Route, error) {

	var last *route.Route
	for tries := 0; tries < 7; tries++ {
		rt, _, err := r.findRoute(amt, nil, nil)
		if err != nil {
			return nil, err
		}
		last = rt

		if r.failedRoute[candidateRouteHash(rt, true)] < 2 {
			return rt, nil
		}

		for _, traversal := range r.routeTraversals(rt) {
			r.edgePenalty[traversal.key] += 0.55
		}
	}

	if last != nil {
		return last, nil
	}
	return nil, errors.New("no fresh route found")
}

func (r *candidateRouter) failureBudget() uint32 {
	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}

	budget := 16 + 4*maxParts
	if budget < 40 {
		budget = 40
	}
	if budget > 96 {
		budget = 96
	}
	return budget
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum parts already in flight")
	}
	if r.failures >= r.failureBudget() {
		return nil, errors.New("routing failure budget exhausted")
	}

	if len(r.plan) != 0 {
		if candidatePlanAmount(r.plan) == amt {
			rt := r.plan[0]
			r.plan = r.plan[1:]
			return rt, nil
		}
		r.plan = nil
	}

	slots := maxParts - inFlightHtlcs

	r.plan = r.buildJointPlan(amt, slots)
	if len(r.plan) == 0 {
		r.plan = r.buildGreedyPlan(amt, slots)
	}
	if len(r.plan) != 0 {
		rt := r.plan[0]
		r.plan = r.plan[1:]
		return rt, nil
	}

	if slots == 1 {
		return r.freshRoute(amt)
	}

	desired := candidateCeilDiv(amt, slots)
	if r.retryCap > 0 && r.retryCap < desired {
		desired = r.retryCap
	}
	if desired < 1 {
		desired = 1
	}
	if desired > amt {
		desired = amt
	}

	for tries := 0; tries < 7; tries++ {
		rt, err := r.freshRoute(desired)
		if err == nil {
			return rt, nil
		}

		if desired >= amt {
			break
		}

		next := desired * 3 / 2
		if next <= desired || next > amt {
			next = amt
		}
		desired = next
	}

	return r.freshRoute(amt)
}

func (r *candidateRouter) recordProof(rt *route.Route) {
	traversals := r.routeTraversals(rt)

	candidateBeliefStore.Lock()
	defer candidateBeliefStore.Unlock()

	for _, traversal := range traversals {
		required := traversal.amt + r.reserved[traversal.key]

		b := candidateBeliefStore.beliefs[traversal.key]
		if b == nil {
			b = &candidateBelief{}
			candidateBeliefStore.beliefs[traversal.key] = b
		}

		if required > b.lowerOK {
			b.lowerOK = required
		}

		highEstimate := traversal.edge.capacity * 88 / 100
		if required > highEstimate {
			highEstimate = required
		}
		if highEstimate > b.estimate {
			b.estimate = highEstimate
		}
		if b.conf < 8 {
			b.conf++
		}

		if b.upperFail > 0 && required >= b.upperFail {
			b.upperFail = 0
		}
		if b.suspectAmt > 0 && required >= b.suspectAmt {
			b.suspectAmt = 0
			b.suspectVotes = 0
		}
	}
}

func (r *candidateRouter) applySettlement(
	used map[candidateEdgeKey]lnwire.MilliSatoshi) {

	candidateBeliefStore.Lock()
	defer candidateBeliefStore.Unlock()

	for key, amount := range used {
		if amount <= 0 {
			continue
		}

		if b := candidateBeliefStore.beliefs[key]; b != nil {
			if b.lowerOK > amount {
				b.lowerOK -= amount
			} else {
				b.lowerOK = 0
			}
			if b.estimate > amount {
				b.estimate -= amount
			} else {
				b.estimate = 0
			}
			if b.upperFail > amount {
				b.upperFail -= amount
			} else {
				b.upperFail = 0
			}
			if b.suspectAmt > amount {
				b.suspectAmt -= amount
			} else {
				b.suspectAmt = 0
				b.suspectVotes = 0
			}
		}

		reverse := candidateEdgeKey{
			chanID: key.chanID,
			from:   key.to,
			to:     key.from,
		}
		reverseBelief := candidateBeliefStore.beliefs[reverse]
		if reverseBelief == nil {
			reverseBelief = &candidateBelief{}
			candidateBeliefStore.beliefs[reverse] = reverseBelief
		}

		reverseCapacity := lnwire.MilliSatoshi(0)
		if edge := r.edges[reverse]; edge != nil {
			reverseCapacity = edge.capacity
		} else if edge := r.edges[key]; edge != nil {
			reverseCapacity = edge.capacity
		}

		reverseBelief.lowerOK += amount
		reverseBelief.estimate += amount
		if reverseBelief.conf < 8 {
			reverseBelief.conf++
		}

		if reverseCapacity > 0 {
			if reverseBelief.lowerOK > reverseCapacity {
				reverseBelief.lowerOK = reverseCapacity
			}
			if reverseBelief.estimate > reverseCapacity {
				reverseBelief.estimate = reverseCapacity
			}
		}

		if reverseBelief.upperFail > 0 {
			reverseBelief.upperFail += amount
			if reverseCapacity > 0 &&
				reverseBelief.upperFail > reverseCapacity {

				reverseBelief.upperFail = reverseCapacity
			}
		}
	}
}

func (r *candidateRouter) recordSuccess(rt *route.Route) {
	traversals := r.routeTraversals(rt)
	r.recordProof(rt)

	for _, traversal := range traversals {
		required := traversal.amt + r.reserved[traversal.key]
		if local, ok := r.localFails[traversal.key]; ok &&
			required >= local.upper {

			delete(r.localFails, traversal.key)
		}
	}

	if r.atomic {
		for _, traversal := range traversals {
			r.reserved[traversal.key] += traversal.amt
			r.usedTotals[traversal.key] += traversal.amt
		}
	} else {
		settled := make(
			map[candidateEdgeKey]lnwire.MilliSatoshi,
			len(traversals),
		)
		for _, traversal := range traversals {
			settled[traversal.key] += traversal.amt

			if traversal.key.from == r.source {
				r.reserved[traversal.key] += traversal.amt
			}
		}
		r.applySettlement(settled)
	}

	r.delivered += candidateDeliveredAmount(rt)
	if r.delivered < r.spec.Amount || r.settled {
		return
	}

	if r.atomic {
		r.applySettlement(r.usedTotals)
	}
	r.settled = true
}

func (r *candidateRouter) failureIndex(rt *route.Route,
	source route.Vertex) (int, bool) {

	traversals := r.routeTraversals(rt)
	if len(traversals) != len(rt.Hops) {
		return -1, false
	}

	if source == rt.SourcePubKey {
		return 0, true
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes != source {
			continue
		}

		index := i + 1
		if index >= len(traversals) {
			return -1, false
		}
		return index, true
	}

	return -1, false
}

func (r *candidateRouter) recordAttributedLiquidityFailure(
	traversal candidateTraversal) {

	required := traversal.amt + r.reserved[traversal.key]

	local := r.localFails[traversal.key]
	if local.upper == 0 || required < local.upper {
		local.upper = required
	}
	if local.count < 255 {
		local.count++
	}
	r.localFails[traversal.key] = local
	r.edgePenalty[traversal.key] += 1.55

	if traversal.key.from == r.source {
		return
	}

	candidateBeliefStore.Lock()
	defer candidateBeliefStore.Unlock()

	b := candidateBeliefStore.beliefs[traversal.key]
	if b == nil {
		b = &candidateBelief{}
		candidateBeliefStore.beliefs[traversal.key] = b
	}

	if b.suspectVotes == 0 {
		b.suspectAmt = required
		b.suspectVotes = 1
		return
	}

	if b.suspectAmt == 0 || required < b.suspectAmt {
		b.suspectAmt = required
	}
	if b.suspectVotes < 255 {
		b.suspectVotes++
	}

	if b.suspectVotes < 3 {
		return
	}

	if b.upperFail == 0 || b.suspectAmt < b.upperFail {
		b.upperFail = b.suspectAmt
	}

	failedEstimate := b.suspectAmt * 68 / 100
	if b.estimate == 0 || failedEstimate < b.estimate {
		b.estimate = failedEstimate
	}
	if b.conf < 8 {
		b.conf++
	}
}

func (r *candidateRouter) penalizeFailureNeighborhood(
	rt *route.Route, index int, policyFailure bool) {

	traversals := r.routeTraversals(rt)
	if index < 0 || index >= len(traversals) {
		return
	}

	center := 1.0
	neighbor := 0.35
	if policyFailure {
		center = 1.8
		neighbor = 0.65
	}

	r.edgePenalty[traversals[index].key] += center
	if index > 0 {
		r.edgePenalty[traversals[index-1].key] += neighbor
	}
	if index+1 < len(traversals) {
		r.edgePenalty[traversals[index+1].key] += neighbor
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64,
	rt *route.Route, result routing.SimHtlcResult) error {

	if result.Failure == nil {
		r.retryCap = 0
		r.recordSuccess(rt)
		return nil
	}

	r.plan = nil
	r.failures++

	hash := candidateRouteHash(rt, true)
	if r.failedRoute[hash] < 255 {
		r.failedRoute[hash]++
	}

	traversals := r.routeTraversals(rt)
	for _, traversal := range traversals {
		r.edgePenalty[traversal.key] += 0.06
	}

	code := result.Failure.Code()
	index, attributed := r.failureIndex(
		rt, result.FailureSource,
	)

	if code == lnwire.CodeTemporaryChannelFailure && attributed {
		r.penalizeFailureNeighborhood(rt, index, false)
		r.recordAttributedLiquidityFailure(traversals[index])

		delivered := candidateDeliveredAmount(rt)
		if delivered > 1 {
			factor := lnwire.MilliSatoshi(68)
			if r.localFails[traversals[index].key].count >= 2 {
				factor = 56
			}
			r.retryCap = delivered * factor / 100
		}
		return nil
	}

	if (code == lnwire.CodeFeeInsufficient ||
		code == lnwire.CodeIncorrectCltvExpiry) && attributed {

		r.penalizeFailureNeighborhood(rt, index, true)
		return nil
	}

	r.unknownFails++
	for _, traversal := range traversals {
		r.edgePenalty[traversal.key] += 0.27
	}

	if r.unknownFails%2 == 0 {
		delivered := candidateDeliveredAmount(rt)
		if delivered > 1 {
			r.retryCap = delivered * 72 / 100
		}
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40
	riskWeight     = 2_500_000.0
)

type edgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
	cap    lnwire.MilliSatoshi
}

type liquidityBelief struct {
	lowerOK lnwire.MilliSatoshi
	upper   lnwire.MilliSatoshi

	estimate   lnwire.MilliSatoshi
	confidence float64

	suspectAmt   lnwire.MilliSatoshi
	failVotes    uint8
	lastFailPath uint64
}

var sharedBeliefs = struct {
	sync.Mutex
	m map[edgeKey]liquidityBelief
}{
	m: make(map[edgeKey]liquidityBelief),
}

type candidateEdge struct {
	key      edgeKey
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usableHTLC(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type edgeUse struct {
	edge   *candidateEdge
	amount lnwire.MilliSatoshi
}

type searchResult struct {
	rt      *route.Route
	path    []*candidateEdge
	uses    []edgeUse
	logProb float64
	fee     lnwire.MilliSatoshi
}

type plannedRoute struct {
	result *searchResult
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[edgeKey]liquidityBelief

	reserved map[edgeKey]lnwire.MilliSatoshi
	issued   map[*route.Route][]edgeUse

	liquidityPenalty map[edgeKey]float64
	penaltyAmount    map[edgeKey]lnwire.MilliSatoshi
	fixedPenalty     map[edgeKey]float64

	tried map[uint64]lnwire.MilliSatoshi

	plan           []plannedRoute
	retryCeiling   lnwire.MilliSatoshi
	failedAttempts uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:           source,
		spec:             spec,
		incomingEdges:    make(map[route.Vertex][]*candidateEdge),
		localBalances:    make(map[uint64]lnwire.MilliSatoshi),
		beliefs:          make(map[edgeKey]liquidityBelief),
		reserved:         make(map[edgeKey]lnwire.MilliSatoshi),
		issued:           make(map[*route.Route][]edgeUse),
		liquidityPenalty: make(map[edgeKey]float64),
		penaltyAmount:    make(map[edgeKey]lnwire.MilliSatoshi),
		fixedPenalty:     make(map[edgeKey]float64),
		tried:            make(map[uint64]lnwire.MilliSatoshi),
	}

	for id, balance := range localBalances {
		r.localBalances[id] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				capacity := lnwire.NewMSatFromSatoshis(ch.Capacity)
				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					cap:    capacity,
				}
				edge := &candidateEdge{
					key:           key,
					chanID:        ch.ChannelID,
					from:          ch.OtherNode,
					to:            node,
					capacity:      capacity,
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				sharedBeliefs.Lock()
				r.beliefs[key] = sharedBeliefs.m[key]
				sharedBeliefs.Unlock()

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func clampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005
	case p > 0.995:
		return 0.995
	default:
		return p
	}
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.025)
	z := (x - 0.90) / 0.045

	var highMode float64
	switch {
	case z > 40:
		highMode = 0
	case z < -40:
		highMode = 1
	default:
		highMode = 1 / (1 + math.Exp(z))
	}

	return clampProbability(0.5*lowMode + 0.5*highMode)
}

func (r *candidateRouter) totalReserved(key edgeKey,
	extra map[edgeKey]lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	total := r.reserved[key]
	if extra != nil {
		total += extra[key]
	}
	return total
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi,
	extra map[edgeKey]lnwire.MilliSatoshi) float64 {

	needed := r.totalReserved(edge.key, extra) + amt

	if edge.from == r.source {
		if needed <= r.localBalances[edge.chanID] {
			return 0.995
		}
		return 0.005
	}

	prior := bimodalPrior(needed, edge.capacity)
	b := r.beliefs[edge.key]

	if b.lowerOK > edge.capacity {
		b.lowerOK = edge.capacity
	}
	if b.upper > edge.capacity {
		b.upper = edge.capacity
	}
	if b.estimate > edge.capacity {
		b.estimate = edge.capacity
	}

	if b.lowerOK > 0 && needed <= b.lowerOK {
		return 0.995
	}
	if b.upper > 0 && needed >= b.upper {
		return 0.008
	}

	p := prior
	if b.confidence > 0 && b.estimate > 0 {
		scale := math.Max(float64(edge.capacity)*0.10, 1)
		z := (float64(needed) - float64(b.estimate)) / scale

		var estimated float64
		switch {
		case z > 40:
			estimated = 0
		case z < -40:
			estimated = 1
		default:
			estimated = 1 / (1 + math.Exp(z))
		}

		weight := math.Min(0.70, b.confidence*0.70)
		p = (1-weight)*p + weight*estimated
	}

	if b.failVotes == 1 && b.suspectAmt > 0 &&
		needed >= b.suspectAmt*3/4 {

		p *= 0.62
	}

	return clampProbability(p)
}

func (r *candidateRouter) edgeAvailable(edge *candidateEdge,
	amt lnwire.MilliSatoshi,
	extra map[edgeKey]lnwire.MilliSatoshi) bool {

	if !edge.usableHTLC(amt) {
		return false
	}

	needed := r.totalReserved(edge.key, extra) + amt
	if needed > edge.capacity {
		return false
	}

	if edge.from == r.source &&
		needed > r.localBalances[edge.chanID] {

		return false
	}

	return true
}

func (r *candidateRouter) localPenalty(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	p := r.fixedPenalty[edge.key]
	liquidity := r.liquidityPenalty[edge.key]
	failedAt := r.penaltyAmount[edge.key]

	if liquidity == 0 {
		return p
	}
	if failedAt > 0 && amt < failedAt {
		ratio := float64(amt) / float64(failedAt)
		liquidity *= ratio * ratio
	}

	return p + liquidity
}

type dijkstraItem struct {
	node  route.Vertex
	score float64
	index int
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index = i
	q[j].index = j
}

func (q *dijkstraQueue) Push(x any) {
	item := x.(*dijkstraItem)
	item.index = len(*q)
	*q = append(*q, item)
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	extra map[edgeKey]lnwire.MilliSatoshi,
	reuse map[edgeKey]int,
	bias map[edgeKey]float64) (*searchResult, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is payment target")
	}

	bestScore := make(map[route.Vertex]float64)
	required := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)
	logProbability := make(map[route.Vertex]float64)

	bestScore[r.spec.Target] = 0
	required[r.spec.Target] = amt
	logProbability[r.spec.Target] = 0

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node:  r.spec.Target,
		score: 0,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		node := item.node

		current, ok := bestScore[node]
		if !ok || item.score > current+0.0001 {
			continue
		}
		if node == r.source {
			break
		}

		arriving := required[node]
		for _, edge := range r.incomingEdges[node] {
			if !r.edgeAvailable(edge, arriving, extra) {
				continue
			}

			p := r.edgeProbability(edge, arriving, extra)
			sending := arriving
			edgeFee := lnwire.MilliSatoshi(0)
			if edge.from != r.source {
				edgeFee = edge.fee(arriving)
				sending += edgeFee
			}

			edgeCost := float64(edgeFee) -
				riskWeight*math.Log(p) + 25_000
			edgeCost += r.localPenalty(edge, arriving)

			if bias != nil {
				edgeCost += bias[edge.key]
			}
			if reuse != nil && reuse[edge.key] > 0 {
				edgeCost += float64(reuse[edge.key]) * 4_500_000
			}

			score := item.score + edgeCost
			old, exists := bestScore[edge.from]
			if exists && score >= old {
				continue
			}

			bestScore[edge.from] = score
			required[edge.from] = sending
			next[edge.from] = edge
			logProbability[edge.from] =
				logProbability[node] + math.Log(p)

			heap.Push(pq, &dijkstraItem{
				node:  edge.from,
				score: score,
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	rt, path, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, err
	}

	return &searchResult{
		rt:      rt,
		path:    path,
		uses:    routeUses(rt, path),
		logProb: logProbability[r.source],
		fee:     rt.TotalAmount - amt,
	}, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route,
	[]*candidateEdge, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.to
	}

	if len(path) == 0 {
		return nil, nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		nextEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			nextEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(nextEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forward := amt
		expiry := uint32(finalCltvDelta)
		if i < last {
			forward = amtOver[i+1]
			expiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, path, nil
}

func routeUses(rt *route.Route, path []*candidateEdge) []edgeUse {
	uses := make([]edgeUse, len(path))
	for i, edge := range path {
		amount := rt.TotalAmount
		if i > 0 {
			amount = rt.Hops[i-1].AmtToForward
		}
		uses[i] = edgeUse{
			edge:   edge,
			amount: amount,
		}
	}
	return uses
}

func deliveredAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func routeHash(rt *route.Route) uint64 {
	h := uint64(1469598103934665603)
	for _, hop := range rt.Hops {
		h ^= hop.ChannelID
		h *= 1099511628211
		for _, b := range hop.PubKeyBytes {
			h ^= uint64(b)
			h *= 1099511628211
		}
	}
	return h
}

func (r *candidateRouter) findFreshRoute(amt lnwire.MilliSatoshi,
	extra map[edgeKey]lnwire.MilliSatoshi,
	reuse map[edgeKey]int) (*searchResult, error) {

	bias := make(map[edgeKey]float64)
	var lastErr error

	for n := 0; n < 14; n++ {
		result, err := r.findRoute(amt, extra, reuse, bias)
		if err != nil {
			return nil, err
		}

		hash := routeHash(result.rt)
		failedAt, failed := r.tried[hash]
		if !failed || amt < failedAt {
			return result, nil
		}

		lastErr = errors.New("all candidate routes already failed")
		if len(result.path) == 0 {
			break
		}

		index := int((hash + uint64(n)) % uint64(len(result.path)))
		bias[result.path[index].key] += 12_000_000
	}

	if lastErr == nil {
		lastErr = errors.New("no fresh route found")
	}
	return nil, lastErr
}

func (r *candidateRouter) reliableDeliveryLimit(result *searchResult,
	extra map[edgeKey]lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	delivery := deliveredAmount(result.rt)
	limit := delivery * 8
	if limit < delivery {
		limit = delivery
	}

	for _, use := range result.uses {
		edge := use.edge
		reserved := r.totalReserved(edge.key, extra)

		var safeTotal lnwire.MilliSatoshi
		if edge.from == r.source {
			safeTotal = r.localBalances[edge.chanID]
		} else {
			b := r.beliefs[edge.key]
			safeTotal = edge.capacity * 78 / 100

			if b.estimate > 0 && b.confidence > 0 {
				w := math.Min(0.85, b.confidence)
				safeTotal = lnwire.MilliSatoshi(
					(1-w)*float64(safeTotal) +
						w*float64(b.estimate),
				)
			}
			if b.lowerOK > safeTotal {
				safeTotal = b.lowerOK
			}
			if b.upper > 0 && safeTotal >= b.upper {
				safeTotal = b.upper * 9 / 10
			}
		}

		if safeTotal > edge.capacity {
			safeTotal = edge.capacity
		}
		if safeTotal <= reserved || use.amount <= 0 {
			return 0
		}

		available := safeTotal - reserved
		edgeLimit := delivery * available / use.amount

		if edge.maxHTLC != 0 {
			policyLimit := delivery * edge.maxHTLC / use.amount
			if policyLimit < edgeLimit {
				edgeLimit = policyLimit
			}
		}
		if edgeLimit < limit {
			limit = edgeLimit
		}
	}

	return limit
}

func addReservations(dst map[edgeKey]lnwire.MilliSatoshi,
	uses []edgeUse) {

	for _, use := range uses {
		dst[use.edge.key] += use.amount
	}
}

func (r *candidateRouter) planMetric(results []*searchResult) float64 {
	totals := make(map[edgeKey]lnwire.MilliSatoshi)
	edges := make(map[edgeKey]*candidateEdge)
	var totalFee lnwire.MilliSatoshi

	for _, result := range results {
		totalFee += result.fee
		for _, use := range result.uses {
			totals[use.edge.key] += use.amount
			edges[use.edge.key] = use.edge
		}
	}

	metric := -0.06 * float64(len(results)-1)
	for key, amount := range totals {
		p := r.edgeProbability(edges[key], amount, nil)
		metric += math.Log(p)
	}
	metric -= float64(totalFee) / 5_000_000

	return metric
}

func (r *candidateRouter) buildPlanForParts(amt,
	maxShard lnwire.MilliSatoshi, parts int,
	frontload bool) ([]*searchResult, bool) {

	remaining := amt
	virtual := make(map[edgeKey]lnwire.MilliSatoshi)
	reuse := make(map[edgeKey]int)
	results := make([]*searchResult, 0, parts)

	for i := 0; i < parts; i++ {
		slots := parts - i
		if remaining <= 0 {
			return nil, false
		}

		share := (remaining + lnwire.MilliSatoshi(slots) - 1) /
			lnwire.MilliSatoshi(slots)
		if share > maxShard {
			return nil, false
		}

		result, err := r.findFreshRoute(share, virtual, reuse)
		if err != nil {
			return nil, false
		}

		if frontload && slots > 1 {
			safe := r.reliableDeliveryLimit(result, virtual)
			tailFloor := (share + 1) / 2
			maxNow := remaining -
				lnwire.MilliSatoshi(slots-1)*tailFloor
			if maxNow > maxShard {
				maxNow = maxShard
			}

			desired := safe
			if desired > maxNow {
				desired = maxNow
			}
			if desired > share {
				larger, largerErr := r.findFreshRoute(
					desired, virtual, reuse,
				)
				if largerErr == nil {
					share = desired
					result = larger
				}
			}
		}

		if share <= 0 || share > remaining {
			return nil, false
		}
		if slots > 1 &&
			remaining-share >
				lnwire.MilliSatoshi(slots-1)*maxShard {

			return nil, false
		}

		results = append(results, result)
		addReservations(virtual, result.uses)
		for _, use := range result.uses {
			reuse[use.edge.key]++
		}
		remaining -= share
	}

	if remaining != 0 {
		return nil, false
	}

	return results, true
}

func (r *candidateRouter) preparePlan(amt lnwire.MilliSatoshi,
	partsLeft uint32) error {

	r.plan = nil
	if partsLeft == 0 {
		return errors.New("maximum in-flight parts reached")
	}

	maxShard := amt
	if r.retryCeiling > 0 && r.retryCeiling < maxShard {
		maxShard = r.retryCeiling
	}

	minShard := (amt + lnwire.MilliSatoshi(partsLeft) - 1) /
		lnwire.MilliSatoshi(partsLeft)
	if maxShard < minShard {
		maxShard = minShard
	}

	minParts := int(
		(amt + maxShard - 1) / maxShard,
	)
	if minParts < 1 {
		minParts = 1
	}

	var best []*searchResult
	bestMetric := math.Inf(-1)
	var directErr error

	if minParts == 1 {
		direct, err := r.findFreshRoute(amt, nil, nil)
		directErr = err
		if err == nil {
			best = []*searchResult{direct}
			bestMetric = r.planMetric(best)
		}
	}

	maxParts := int(partsLeft)
	for parts := minParts; parts <= maxParts; parts++ {
		if parts == 1 {
			continue
		}

		for _, frontload := range []bool{false, true} {
			results, ok := r.buildPlanForParts(
				amt, maxShard, parts, frontload,
			)
			if !ok {
				continue
			}

			metric := r.planMetric(results)
			if metric > bestMetric+0.04 {
				best = results
				bestMetric = metric
			}
		}
	}

	if len(best) == 0 {
		if directErr != nil {
			return directErr
		}
		return errors.New("no route set found")
	}

	r.plan = make([]plannedRoute, len(best))
	for i, result := range best {
		r.plan[i] = plannedRoute{result: result}
	}

	return nil
}

func (r *candidateRouter) issue(result *searchResult) *route.Route {
	addReservations(r.reserved, result.uses)
	r.issued[result.rt] = result.uses
	return result.rt
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum in-flight parts reached")
	}

	partsLeft := maxParts - inFlightHtlcs

	if len(r.plan) > 0 {
		result := r.plan[0].result
		if deliveredAmount(result.rt) <= amt {
			r.plan = r.plan[1:]
			return r.issue(result), nil
		}
		r.plan = nil
	}

	if err := r.preparePlan(amt, partsLeft); err == nil &&
		len(r.plan) > 0 {

		result := r.plan[0].result
		r.plan = r.plan[1:]
		return r.issue(result), nil
	}

	if partsLeft <= 1 {
		return nil, errors.New("no route found")
	}

	minShard := (amt + lnwire.MilliSatoshi(partsLeft) - 1) /
		lnwire.MilliSatoshi(partsLeft)
	tryAmt := amt

	if r.retryCeiling > 0 && r.retryCeiling < tryAmt {
		tryAmt = r.retryCeiling
	}
	if tryAmt < minShard {
		tryAmt = minShard
	}

	for tryAmt >= minShard {
		result, err := r.findFreshRoute(tryAmt, nil, nil)
		if err == nil {
			return r.issue(result), nil
		}
		if tryAmt == minShard {
			break
		}

		next := tryAmt * 3 / 5
		if next < minShard {
			next = minShard
		}
		if next == tryAmt {
			break
		}
		tryAmt = next
	}

	return nil, errors.New("no route found")
}

func (r *candidateRouter) saveBelief(key edgeKey,
	b liquidityBelief) {

	r.beliefs[key] = b

	sharedBeliefs.Lock()
	sharedBeliefs.m[key] = b
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) learnSuccess(use edgeUse,
	totalObserved lnwire.MilliSatoshi) {

	key := use.edge.key
	b := r.beliefs[key]

	if totalObserved > b.lowerOK {
		b.lowerOK = totalObserved
	}
	if totalObserved > b.estimate {
		b.estimate = totalObserved
	}
	b.confidence = math.Min(1, b.confidence+0.35)

	if b.upper > 0 && totalObserved >= b.upper {
		b.upper = 0
	}
	if b.suspectAmt > 0 && totalObserved >= b.suspectAmt {
		b.suspectAmt = 0
		b.failVotes = 0
		b.lastFailPath = 0
	}

	r.saveBelief(key, b)
}

func (r *candidateRouter) learnFailure(edge *candidateEdge,
	totalObserved lnwire.MilliSatoshi, pathHash uint64) {

	key := edge.key
	b := r.beliefs[key]

	if b.suspectAmt == 0 ||
		totalObserved < b.suspectAmt/2 ||
		totalObserved > b.suspectAmt*2 {

		b.suspectAmt = totalObserved
		b.failVotes = 1
		b.lastFailPath = pathHash
	} else {
		if totalObserved < b.suspectAmt {
			b.suspectAmt = totalObserved
		}
		if pathHash != b.lastFailPath && b.failVotes < 255 {
			b.failVotes++
			b.lastFailPath = pathHash
		}
	}

	failedEstimate := totalObserved * 3 / 4
	if b.estimate == 0 {
		b.estimate = failedEstimate
	} else {
		b.estimate = (b.estimate*3 + failedEstimate) / 4
	}
	b.confidence = math.Min(1, b.confidence+0.15)

	if b.failVotes >= 2 {
		if b.upper == 0 || b.suspectAmt < b.upper {
			b.upper = b.suspectAmt
		}
		if b.lowerOK >= b.upper {
			b.lowerOK = 0
		}
	}

	r.saveBelief(key, b)
}

func (r *candidateRouter) addLiquidityPenalty(key edgeKey,
	amount lnwire.MilliSatoshi, penalty float64) {

	r.liquidityPenalty[key] += penalty
	if amount > 0 &&
		(r.penaltyAmount[key] == 0 ||
			amount < r.penaltyAmount[key]) {

		r.penaltyAmount[key] = amount
	}
}

func releaseReservations(reserved map[edgeKey]lnwire.MilliSatoshi,
	uses []edgeUse) {

	for _, use := range uses {
		current := reserved[use.edge.key]
		if current <= use.amount {
			delete(reserved, use.edge.key)
		} else {
			reserved[use.edge.key] = current - use.amount
		}
	}
}

func findFailureNode(rt *route.Route, source route.Vertex) int {
	if source == rt.SourcePubKey {
		return 0
	}
	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}
	return -1
}

func (r *candidateRouter) rebuildUses(rt *route.Route) []edgeUse {
	path := make([]*candidateEdge, 0, len(rt.Hops))
	from := rt.SourcePubKey

	for _, hop := range rt.Hops {
		var found *candidateEdge
		for _, edge := range r.incomingEdges[hop.PubKeyBytes] {
			if edge.from == from && edge.chanID == hop.ChannelID {
				found = edge
				break
			}
		}
		if found == nil {
			return nil
		}

		path = append(path, found)
		from = hop.PubKeyBytes
	}

	return routeUses(rt, path)
}

func (r *candidateRouter) ReportAttempt(attemptID uint64,
	rt *route.Route, result routing.SimHtlcResult) error {

	_ = attemptID

	uses, ok := r.issued[rt]
	if !ok {
		uses = r.rebuildUses(rt)
	}
	delete(r.issued, rt)

	if result.Failure == nil {
		for _, use := range uses {
			r.learnSuccess(
				use, r.reserved[use.edge.key],
			)
		}
		return nil
	}

	r.failedAttempts++

	hash := routeHash(rt)
	delivered := deliveredAmount(rt)
	if old, exists := r.tried[hash]; !exists || delivered < old {
		r.tried[hash] = delivered
	}

	totalDemand := make(map[edgeKey]lnwire.MilliSatoshi, len(uses))
	for _, use := range uses {
		totalDemand[use.edge.key] = r.reserved[use.edge.key]
	}

	releaseReservations(r.reserved, uses)
	r.plan = nil

	nextCeiling := delivered * 3 / 5
	if nextCeiling > 0 &&
		(r.retryCeiling == 0 || nextCeiling < r.retryCeiling) {

		r.retryCeiling = nextCeiling
	}

	failNode := findFailureNode(rt, result.FailureSource)
	if failNode < 0 {
		return nil
	}

	if failNode >= len(uses) {
		return nil
	}

	primary := failNode
	code := result.Failure.Code()

	if code == lnwire.CodeTemporaryChannelFailure {
		use := uses[primary]
		demand := totalDemand[use.edge.key]

		r.addLiquidityPenalty(
			use.edge.key, demand, 5_000_000,
		)
		r.learnFailure(use.edge, demand, hash)

		if primary > 0 {
			adjacent := uses[primary-1]
			r.addLiquidityPenalty(
				adjacent.edge.key,
				totalDemand[adjacent.edge.key],
				750_000,
			)
		}
		if primary+1 < len(uses) {
			adjacent := uses[primary+1]
			r.addLiquidityPenalty(
				adjacent.edge.key,
				totalDemand[adjacent.edge.key],
				750_000,
			)
		}

		return nil
	}

	r.fixedPenalty[uses[primary].edge.key] += 8_000_000
	if primary > 0 {
		r.fixedPenalty[uses[primary-1].edge.key] += 900_000
	}
	if primary+1 < len(uses) {
		r.fixedPenalty[uses[primary+1].edge.key] += 900_000
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	conf      uint8

	suspectAmt   lnwire.MilliSatoshi
	suspectVotes uint8
}

var candidateBeliefStore = struct {
	sync.Mutex
	beliefs map[candidateEdgeKey]*candidateBelief
}{
	beliefs: make(map[candidateEdgeKey]*candidateBelief),
}

type candidateLocalFailure struct {
	upper lnwire.MilliSatoshi
	count uint8
}

type candidateTraversal struct {
	key  candidateEdgeKey
	edge *candidateEdge
	amt  lnwire.MilliSatoshi
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	reserved    map[candidateEdgeKey]lnwire.MilliSatoshi
	usedTotals  map[candidateEdgeKey]lnwire.MilliSatoshi
	localFails  map[candidateEdgeKey]candidateLocalFailure
	edgePenalty map[candidateEdgeKey]float64

	baseParts   uint32
	failures    uint32
	unknownFails uint32
	retryCap    lnwire.MilliSatoshi
	delivered   lnwire.MilliSatoshi
	settled     bool
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[candidateEdgeKey]*candidateEdge),
		localBalances: localBalances,
		reserved:      make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		usedTotals:    make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		localFails:    make(map[candidateEdgeKey]candidateLocalFailure),
		edgePenalty:   make(map[candidateEdgeKey]float64),
	}

	r.baseParts = r.initialPartCount(spec.Amount)
	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if r.baseParts > maxParts {
		r.baseParts = maxParts
	}
	if r.baseParts == 0 {
		r.baseParts = 1
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[key] = edge

				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func (r *candidateRouter) initialPartCount(
	amt lnwire.MilliSatoshi) uint32 {

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}

	switch {
	case amt <= 25_000_000:
		return 1

	case amt <= 250_000_000:
		if maxParts < 3 {
			return maxParts
		}
		return 3

	case amt <= 1_000_000_000:
		if maxParts < 6 {
			return maxParts
		}
		return 6

	default:
		// Large atomic payments benefit from committing the smallest
		// feasible shards immediately instead of spending attempts on a
		// halving ladder.
		return maxParts
	}
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.003
	}

	x := float64(amt) / float64(capacity)

	lowMode := 0.48 * math.Exp(-x/0.025)
	highMode := 0.50 / (1 + math.Exp((x-0.90)/0.025))
	p := 0.005 + lowMode + highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func candidateLogisticProbability(amt, estimate,
	capacity lnwire.MilliSatoshi) float64 {

	if capacity <= 0 {
		return 0.005
	}

	scale := 0.07 * float64(capacity)
	if scale < 1 {
		scale = 1
	}

	z := (float64(amt) - float64(estimate)) / scale
	if z > 30 {
		return 0.005
	}
	if z < -30 {
		return 0.995
	}

	return 1 / (1 + math.Exp(z))
}

func (r *candidateRouter) edgeProbability(e *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	required := amt + r.reserved[e.key]
	if required > e.capacity {
		return 0.001
	}

	// The sender's balance is exact. A temporary failure attributed to
	// this edge is necessarily stale or shifted information.
	if e.key.from == r.source {
		if r.localBalances[e.key.chanID] < required {
			return 0.001
		}
		return 0.999
	}

	p := candidatePrior(required, e.capacity)

	candidateBeliefStore.Lock()
	stored, ok := candidateBeliefStore.beliefs[e.key]
	var belief candidateBelief
	if ok {
		belief = *stored
	}
	candidateBeliefStore.Unlock()

	if ok {
		if belief.estimate > 0 && belief.conf > 0 {
			q := candidateLogisticProbability(
				required, belief.estimate, e.capacity,
			)
			weight := 0.13 * float64(belief.conf)
			if weight > 0.72 {
				weight = 0.72
			}
			p = (1-weight)*p + weight*q
		}

		if belief.lowerOK > 0 && required <= belief.lowerOK {
			p = math.Max(p, 0.995)
		}

		if belief.upperFail > 0 {
			switch {
			case required >= belief.upperFail:
				// Corroborated failures are strong evidence, but never
				// make a channel permanently impossible.
				p = math.Min(p, 0.012)

			case belief.lowerOK > 0 &&
				belief.upperFail > belief.lowerOK:

				span := float64(
					belief.upperFail - belief.lowerOK,
				)
				pos := float64(
					required - belief.lowerOK,
				) / span
				if pos > 0 {
					bounded := 0.995*(1-pos) + 0.012*pos
					p = 0.32*p + 0.68*bounded
				}
			}
		}
	}

	if local, found := r.localFails[e.key]; found &&
		required >= local.upper {

		if local.count >= 2 {
			p = math.Min(p, 0.005)
		} else {
			p *= 0.15
		}
	}

	if p < 0.003 {
		return 0.003
	}
	if p > 0.995 {
		return 0.995
	}

	return p
}

func (r *candidateRouter) edgeCost(e *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	p := r.edgeProbability(e, amt)
	required := amt + r.reserved[e.key]

	penalty := r.edgePenalty[e.key]
	if local, ok := r.localFails[e.key]; ok &&
		required < local.upper {

		// A lower-amount retry remains attractive after a high-amount
		// liquidity miss.
		penalty *= 0.18
	}

	cost := -math.Log(p) + 0.025 + penalty

	if reserved := r.reserved[e.key]; reserved > 0 &&
		e.capacity > 0 {

		// Prefer a route-set spread across independent corridors, while
		// still permitting reuse of a route proven to be liquid.
		fraction := float64(reserved) / float64(e.capacity)
		cost += 0.16 + 0.85*fraction
	}

	return cost
}

type candidateDijkstraItem struct {
	node  route.Vertex
	score float64
	amt   lnwire.MilliSatoshi
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *candidateDijkstraQueue) Push(x any) {
	*q = append(*q, x.(*candidateDijkstraItem))
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}

	score := make(map[route.Vertex]float64)
	arriving := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)

	score[r.spec.Target] = 0
	arriving[r.spec.Target] = amt

	pq := &candidateDijkstraQueue{}
	heap.Push(pq, &candidateDijkstraItem{
		node: r.spec.Target,
		amt:  amt,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)

		bestScore, ok := score[item.node]
		if !ok || item.score > bestScore+1e-12 {
			continue
		}
		if item.amt != arriving[item.node] {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOver := item.amt
			if !edge.policyAllows(amtOver) {
				continue
			}

			required := amtOver + r.reserved[edge.key]
			if required > edge.capacity {
				continue
			}
			if edge.key.from == r.source &&
				r.localBalances[edge.key.chanID] < required {

				continue
			}

			sending := amtOver
			feeCost := 0.0

			if edge.key.from != r.source {
				fee := edge.fee(amtOver)
				sending += fee

				denom := float64(amt)
				if denom < 1 {
					denom = 1
				}

				// Reliability dominates, with fees breaking ties among
				// paths of comparable likelihood.
				feeCost = 24 * float64(fee) / denom
			}

			newScore := item.score +
				r.edgeCost(edge, amtOver) + feeCost

			oldScore, exists := score[edge.key.from]
			if exists && newScore >= oldScore {
				continue
			}

			score[edge.key.from] = newScore
			arriving[edge.key.from] = sending
			next[edge.key.from] = edge

			heap.Push(pq, &candidateDijkstraItem{
				node:  edge.key.from,
				score: newScore,
				amt:   sending,
			})
		}
	}

	if _, ok := score[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}

	pathProbability := 1.0
	for _, traversal := range r.routeTraversals(rt) {
		pathProbability *= r.edgeProbability(
			traversal.edge, traversal.amt,
		)
		if pathProbability < 1e-15 {
			pathProbability = 1e-15
		}
	}

	return rt, pathProbability, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)

		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateCeilDiv(amt lnwire.MilliSatoshi,
	parts uint32) lnwire.MilliSatoshi {

	if parts <= 1 {
		return amt
	}

	divisor := lnwire.MilliSatoshi(parts)
	return (amt + divisor - 1) / divisor
}

func (r *candidateRouter) targetPartCount() uint32 {
	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}

	target := r.baseParts
	if r.failures > 0 {
		target += 1 + r.failures/2
	}
	if r.unknownFails > 1 {
		target++
	}

	if target > maxParts {
		target = maxParts
	}
	if target == 0 {
		target = 1
	}

	return target
}

func (r *candidateRouter) decayPenalties() {
	for key, penalty := range r.edgePenalty {
		penalty *= 0.84
		if penalty < 0.01 {
			delete(r.edgePenalty, key)
			continue
		}
		r.edgePenalty[key] = penalty
	}
}

func candidateAppendAmount(amounts []lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value, limit,
	minimum lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if value < minimum {
		value = minimum
	}
	if value > limit {
		value = limit
	}
	if value <= 0 || seen[value] {
		return amounts
	}

	seen[value] = true
	return append(amounts, value)
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum parts already in flight")
	}

	r.decayPenalties()

	partsLeft := maxParts - inFlightHtlcs
	minimumShard := candidateCeilDiv(amt, partsLeft)

	targetParts := r.targetPartCount()
	var desiredSlots uint32
	if targetParts > inFlightHtlcs {
		desiredSlots = targetParts - inFlightHtlcs
	} else {
		desiredSlots = 1
	}
	if desiredSlots > partsLeft {
		desiredSlots = partsLeft
	}
	if desiredSlots == 0 {
		desiredSlots = 1
	}

	nominalShard := candidateCeilDiv(amt, desiredSlots)

	// Preserve efficient single-path behavior for small payments and for
	// routes whose liquidity has already been strongly established.
	if r.baseParts == 1 {
		if rt, _, err := r.findRoute(amt); err == nil {
			return rt, nil
		}
	}

	if r.failures == 0 && amt != minimumShard {
		if rt, probability, err := r.findRoute(amt); err == nil &&
			probability >= 0.82 {

			return rt, nil
		}
	}

	// Jointly choose a shard amount and route. The minimum candidate
	// guarantees that the remaining payment still fits in the available
	// part slots. Larger candidates allow strong, high-capacity corridors
	// to take deliberately unequal shares.
	seen := make(map[lnwire.MilliSatoshi]bool)
	amounts := make([]lnwire.MilliSatoshi, 0, 8)

	amounts = candidateAppendAmount(
		amounts, seen, minimumShard, amt, minimumShard,
	)
	if r.retryCap > 0 {
		amounts = candidateAppendAmount(
			amounts, seen, r.retryCap, amt, minimumShard,
		)
	}
	amounts = candidateAppendAmount(
		amounts, seen, minimumShard+minimumShard/4,
		amt, minimumShard,
	)
	amounts = candidateAppendAmount(
		amounts, seen, minimumShard+minimumShard/2,
		amt, minimumShard,
	)
	amounts = candidateAppendAmount(
		amounts, seen, minimumShard*2,
		amt, minimumShard,
	)
	amounts = candidateAppendAmount(
		amounts, seen, nominalShard, amt, minimumShard,
	)
	amounts = candidateAppendAmount(
		amounts, seen, amt, amt, minimumShard,
	)

	var bestRoute *route.Route
	bestUtility := math.Inf(-1)
	bestAmount := lnwire.MilliSatoshi(0)
	var lastErr error

	for _, shard := range amounts {
		rt, probability, err := r.findRoute(shard)
		if err != nil {
			lastErr = err
			continue
		}

		if probability < 1e-15 {
			probability = 1e-15
		}

		progress := float64(shard) / float64(minimumShard)
		utility := math.Log(probability) + 0.42*math.Log(progress)

		// Prefer fewer attempts only when reliability is effectively tied.
		if utility > bestUtility+1e-12 ||
			(math.Abs(utility-bestUtility) <= 1e-12 &&
				shard > bestAmount) {

			bestRoute = rt
			bestUtility = utility
			bestAmount = shard
		}
	}

	if bestRoute != nil {
		return bestRoute, nil
	}
	if lastErr != nil {
		return nil, lastErr
	}

	return nil, errors.New("no route found")
}

func (r *candidateRouter) routeTraversals(
	rt *route.Route) []candidateTraversal {

	traversals := make([]candidateTraversal, 0, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		key := candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		edge := r.edges[key]
		if edge == nil {
			from = hop.PubKeyBytes
			continue
		}

		amt := rt.TotalAmount
		if i > 0 {
			amt = rt.Hops[i-1].AmtToForward
		}

		traversals = append(traversals, candidateTraversal{
			key:  key,
			edge: edge,
			amt:  amt,
		})
		from = hop.PubKeyBytes
	}

	return traversals
}

func candidateDeliveredAmount(rt *route.Route) lnwire.MilliSatoshi {
	if len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func (r *candidateRouter) recordSuccess(rt *route.Route) {
	traversals := r.routeTraversals(rt)

	candidateBeliefStore.Lock()
	for _, traversal := range traversals {
		required := traversal.amt + r.reserved[traversal.key]

		b := candidateBeliefStore.beliefs[traversal.key]
		if b == nil {
			b = &candidateBelief{}
			candidateBeliefStore.beliefs[traversal.key] = b
		}

		if required > b.lowerOK {
			b.lowerOK = required
		}

		highEstimate := traversal.edge.capacity * 88 / 100
		if required > highEstimate {
			highEstimate = required
		}
		if highEstimate > b.estimate {
			b.estimate = highEstimate
		}
		if b.conf < 8 {
			b.conf++
		}

		// Successes are truthful and override conflicting failure blame.
		if b.upperFail > 0 && required >= b.upperFail {
			b.upperFail = 0
		}
		if b.suspectAmt > 0 && required >= b.suspectAmt {
			b.suspectAmt = 0
			b.suspectVotes = 0
		}
	}
	candidateBeliefStore.Unlock()

	for _, traversal := range traversals {
		required := traversal.amt + r.reserved[traversal.key]

		if local, ok := r.localFails[traversal.key]; ok &&
			required >= local.upper {

			delete(r.localFails, traversal.key)
		}

		if penalty := r.edgePenalty[traversal.key]; penalty > 0 {
			penalty *= 0.15
			if penalty < 0.01 {
				delete(r.edgePenalty, traversal.key)
			} else {
				r.edgePenalty[traversal.key] = penalty
			}
		}

		r.reserved[traversal.key] += traversal.amt
		r.usedTotals[traversal.key] += traversal.amt
	}

	r.delivered += candidateDeliveredAmount(rt)
	if r.delivered >= r.spec.Amount && !r.settled {
		r.recordSettlement()
		r.settled = true
	}
}

func (r *candidateRouter) recordSettlement() {
	candidateBeliefStore.Lock()
	defer candidateBeliefStore.Unlock()

	for key, used := range r.usedTotals {
		if used <= 0 {
			continue
		}

		if b := candidateBeliefStore.beliefs[key]; b != nil {
			if b.lowerOK > used {
				b.lowerOK -= used
			} else {
				b.lowerOK = 0
			}
			if b.estimate > used {
				b.estimate -= used
			} else {
				b.estimate = 0
			}
			if b.upperFail > used {
				b.upperFail -= used
			} else {
				b.upperFail = 0
			}
			if b.suspectAmt > used {
				b.suspectAmt -= used
			} else {
				b.suspectAmt = 0
				b.suspectVotes = 0
			}
		}

		reverse := candidateEdgeKey{
			chanID: key.chanID,
			from:   key.to,
			to:     key.from,
		}
		reverseBelief := candidateBeliefStore.beliefs[reverse]
		if reverseBelief == nil {
			reverseBelief = &candidateBelief{}
			candidateBeliefStore.beliefs[reverse] = reverseBelief
		}

		reverseCapacity := lnwire.MilliSatoshi(0)
		if edge := r.edges[reverse]; edge != nil {
			reverseCapacity = edge.capacity
		} else if edge := r.edges[key]; edge != nil {
			reverseCapacity = edge.capacity
		}

		reverseBelief.lowerOK += used
		reverseBelief.estimate += used

		if reverseCapacity > 0 {
			if reverseBelief.lowerOK > reverseCapacity {
				reverseBelief.lowerOK = reverseCapacity
			}
			if reverseBelief.estimate > reverseCapacity {
				reverseBelief.estimate = reverseCapacity
			}
		}

		if reverseBelief.upperFail > 0 {
			reverseBelief.upperFail += used
			if reverseCapacity > 0 &&
				reverseBelief.upperFail > reverseCapacity {

				reverseBelief.upperFail = reverseCapacity
			}
		}
	}
}

func (r *candidateRouter) failureEdge(rt *route.Route,
	source route.Vertex) (candidateTraversal, bool) {

	traversals := r.routeTraversals(rt)
	if len(traversals) != len(rt.Hops) {
		return candidateTraversal{}, false
	}

	index := -1
	if source == rt.SourcePubKey {
		index = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == source {
				index = i + 1
				break
			}
		}
	}

	if index < 0 || index >= len(traversals) {
		return candidateTraversal{}, false
	}

	return traversals[index], true
}

func (r *candidateRouter) recordAttributedLiquidityFailure(
	traversal candidateTraversal) {

	required := traversal.amt + r.reserved[traversal.key]

	// Local balances are exact, so remote attribution cannot teach us
	// anything about an edge originating at the sender.
	if traversal.key.from == r.source {
		return
	}

	local := r.localFails[traversal.key]
	if local.upper == 0 || required < local.upper {
		local.upper = required
	}
	if local.count < 255 {
		local.count++
	}
	r.localFails[traversal.key] = local
	r.edgePenalty[traversal.key] += 1.0

	candidateBeliefStore.Lock()
	defer candidateBeliefStore.Unlock()

	b := candidateBeliefStore.beliefs[traversal.key]
	if b == nil {
		b = &candidateBelief{}
		candidateBeliefStore.beliefs[traversal.key] = b
	}

	if b.suspectVotes == 0 {
		b.suspectAmt = required
		b.suspectVotes = 1
		return
	}

	if b.suspectAmt == 0 || required < b.suspectAmt {
		b.suspectAmt = required
	}
	if b.suspectVotes < 255 {
		b.suspectVotes++
	}

	// A single readable report is quarantined. Corroboration promotes it
	// to a soft bound, limiting damage from shifted attribution.
	if b.suspectVotes >= 2 {
		if b.upperFail == 0 || b.suspectAmt < b.upperFail {
			b.upperFail = b.suspectAmt
		}

		failedEstimate := b.suspectAmt * 70 / 100
		if b.estimate == 0 || failedEstimate < b.estimate {
			b.estimate = failedEstimate
		}
		if b.conf < 8 {
			b.conf++
		}
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64,
	rt *route.Route, result routing.SimHtlcResult) error {

	if result.Failure == nil {
		r.retryCap = 0
		r.recordSuccess(rt)
		return nil
	}

	r.failures++
	traversals := r.routeTraversals(rt)

	// A small, fading route-wide penalty prevents immediate repetition
	// without driving the router permanently toward long detours.
	for _, traversal := range traversals {
		r.edgePenalty[traversal.key] += 0.025
	}

	code := result.Failure.Code()
	if code == lnwire.CodeTemporaryChannelFailure {
		if traversal, ok := r.failureEdge(
			rt, result.FailureSource,
		); ok {
			r.recordAttributedLiquidityFailure(traversal)

			delivered := candidateDeliveredAmount(rt)
			if delivered > 1 {
				r.retryCap = delivered * 64 / 100
			}
			return nil
		}
	}

	// An off-route source explicitly carries no channel information.
	r.unknownFails++
	for _, traversal := range traversals {
		r.edgePenalty[traversal.key] += 0.16
	}

	delivered := candidateDeliveredAmount(rt)
	if delivered > 1 {
		factor := lnwire.MilliSatoshi(76)
		if r.unknownFails > 1 {
			factor = 68
		}
		r.retryCap = delivered * factor / 100
	}

	if code == lnwire.CodeFeeInsufficient ||
		code == lnwire.CodeIncorrectCltvExpiry {

		if traversal, ok := r.failureEdge(
			rt, result.FailureSource,
		); ok {
			r.edgePenalty[traversal.key] += 1.5
		}
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40
	riskWeight     = 2_200_000.0
	maxLabels      = 8
	maxPathLength  = 32
)

type edgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
	cap    lnwire.MilliSatoshi
}

type liquidityBelief struct {
	lowerOK lnwire.MilliSatoshi
	upper   lnwire.MilliSatoshi

	estimate  lnwire.MilliSatoshi
	confidence float64

	suspectAmt lnwire.MilliSatoshi
	evidence   float64
	lastPath   uint64
}

var sharedBeliefs = struct {
	sync.Mutex
	m map[edgeKey]liquidityBelief
}{
	m: make(map[edgeKey]liquidityBelief),
}

type candidateEdge struct {
	key      edgeKey
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usableHTLC(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type edgeUse struct {
	edge   *candidateEdge
	amount lnwire.MilliSatoshi
}

type searchResult struct {
	rt      *route.Route
	path    []*candidateEdge
	uses    []edgeUse
	logProb float64
	fee     lnwire.MilliSatoshi
}

type plannedRoute struct {
	result *searchResult
}

type localMiss struct {
	amount lnwire.MilliSatoshi
	weight float64
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[edgeKey]liquidityBelief

	// reserved contains held successful shards and attempts that have been
	// returned but not reported. held contains truthful successful shards
	// only, so pending siblings never inflate a success observation.
	reserved map[edgeKey]lnwire.MilliSatoshi
	held     map[edgeKey]lnwire.MilliSatoshi
	issued   map[*route.Route][]edgeUse

	misses        map[edgeKey]localMiss
	policyPenalty map[edgeKey]float64
	tried         map[uint64]lnwire.MilliSatoshi

	plan         []plannedRoute
	retryCeiling lnwire.MilliSatoshi
	failures     int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	if spec == nil {
		return nil, errors.New("nil payment specification")
	}

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		localBalances:  make(map[uint64]lnwire.MilliSatoshi),
		beliefs:        make(map[edgeKey]liquidityBelief),
		reserved:       make(map[edgeKey]lnwire.MilliSatoshi),
		held:           make(map[edgeKey]lnwire.MilliSatoshi),
		issued:         make(map[*route.Route][]edgeUse),
		misses:         make(map[edgeKey]localMiss),
		policyPenalty:  make(map[edgeKey]float64),
		tried:          make(map[uint64]lnwire.MilliSatoshi),
	}

	for id, balance := range localBalances {
		r.localBalances[id] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				capacity := lnwire.NewMSatFromSatoshis(ch.Capacity)
				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					cap:    capacity,
				}
				edge := &candidateEdge{
					key:           key,
					chanID:        ch.ChannelID,
					from:          ch.OtherNode,
					to:            node,
					capacity:      capacity,
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				sharedBeliefs.Lock()
				r.beliefs[key] = sharedBeliefs.m[key]
				sharedBeliefs.Unlock()

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func clampProbability(p float64) float64 {
	if p < 0.005 {
		return 0.005
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.025)

	z := (x - 0.90) / 0.045
	var highMode float64
	switch {
	case z > 40:
		highMode = 0
	case z < -40:
		highMode = 1
	default:
		highMode = 1 / (1 + math.Exp(z))
	}

	return clampProbability(0.5*lowMode + 0.5*highMode)
}

func (r *candidateRouter) totalReserved(key edgeKey,
	extra map[edgeKey]lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	total := r.reserved[key]
	if extra != nil {
		total += extra[key]
	}
	return total
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi,
	extra map[edgeKey]lnwire.MilliSatoshi) float64 {

	needed := r.totalReserved(edge.key, extra) + amt
	if edge.from == r.source {
		if needed <= r.localBalances[edge.chanID] {
			return 0.995
		}
		return 0.005
	}

	prior := bimodalPrior(needed, edge.capacity)
	b := r.beliefs[edge.key]

	if b.lowerOK > edge.capacity {
		b.lowerOK = edge.capacity
	}
	if b.upper > edge.capacity {
		b.upper = edge.capacity
	}
	if b.estimate > edge.capacity {
		b.estimate = edge.capacity
	}

	if b.lowerOK > 0 && needed <= b.lowerOK {
		return 0.995
	}
	if b.upper > b.lowerOK && needed >= b.upper {
		return 0.008
	}

	p := prior
	if b.estimate > 0 && b.confidence > 0 {
		scale := math.Max(float64(edge.capacity)*0.10, 1)
		z := (float64(needed) - float64(b.estimate)) / scale

		var estimated float64
		switch {
		case z > 40:
			estimated = 0
		case z < -40:
			estimated = 1
		default:
			estimated = 1 / (1 + math.Exp(z))
		}

		weight := math.Min(0.72, b.confidence*0.72)
		p = (1-weight)*p + weight*estimated
	}

	if b.evidence > 0 && b.suspectAmt > 0 &&
		needed*4 >= b.suspectAmt*3 {

		p *= math.Exp(-0.38 * math.Min(b.evidence, 2.5))
	}

	return clampProbability(p)
}

func (r *candidateRouter) edgeAvailable(edge *candidateEdge,
	amt lnwire.MilliSatoshi,
	extra map[edgeKey]lnwire.MilliSatoshi) bool {

	if !edge.usableHTLC(amt) {
		return false
	}

	needed := r.totalReserved(edge.key, extra) + amt
	if needed > edge.capacity {
		return false
	}
	if edge.from == r.source &&
		needed > r.localBalances[edge.chanID] {

		return false
	}

	return true
}

func (r *candidateRouter) missPenalty(edge *candidateEdge,
	needed lnwire.MilliSatoshi) float64 {

	miss := r.misses[edge.key]
	if miss.amount <= 0 || miss.weight <= 0 {
		return 0
	}

	ratio := float64(needed) / float64(miss.amount)
	if ratio > 1 {
		ratio = 1
	}
	if ratio < 0 {
		ratio = 0
	}

	// Blame matters strongly near the failed amount, but fades quickly
	// enough that the same channel remains useful for a smaller shard.
	return 14_000_000 * miss.weight * ratio * ratio * ratio
}

type searchState struct {
	node     route.Vertex
	score    float64
	amount   lnwire.MilliSatoshi
	logProb  float64
	edge     *candidateEdge
	next     *searchState
	depth    int
	dead     bool
	heapIndex int
}

type stateQueue []*searchState

func (q stateQueue) Len() int { return len(q) }
func (q stateQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}
func (q stateQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].heapIndex = i
	q[j].heapIndex = j
}
func (q *stateQueue) Push(x any) {
	item := x.(*searchState)
	item.heapIndex = len(*q)
	*q = append(*q, item)
}
func (q *stateQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func stateContains(s *searchState, node route.Vertex) bool {
	for current := s; current != nil; current = current.next {
		if current.node == node {
			return true
		}
	}
	return false
}

func acceptLabel(labels map[route.Vertex][]*searchState,
	candidate *searchState) bool {

	old := labels[candidate.node]
	for _, label := range old {
		if !label.dead &&
			label.score <= candidate.score &&
			label.amount <= candidate.amount {

			return false
		}
	}

	kept := old[:0]
	for _, label := range old {
		if label.dead {
			continue
		}
		if candidate.score <= label.score &&
			candidate.amount <= label.amount {

			label.dead = true
			continue
		}
		kept = append(kept, label)
	}
	kept = append(kept, candidate)

	if len(kept) > maxLabels {
		minAmountIndex := 0
		for i := 1; i < len(kept); i++ {
			if kept[i].amount < kept[minAmountIndex].amount {
				minAmountIndex = i
			}
		}

		remove := -1
		for i := range kept {
			if i == minAmountIndex {
				continue
			}
			if remove < 0 || kept[i].score > kept[remove].score {
				remove = i
			}
		}
		if remove >= 0 {
			kept[remove].dead = true
			removedCandidate := kept[remove] == candidate
			kept = append(kept[:remove], kept[remove+1:]...)
			labels[candidate.node] = kept
			return !removedCandidate
		}
	}

	labels[candidate.node] = kept
	return true
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	extra map[edgeKey]lnwire.MilliSatoshi,
	reuse map[edgeKey]int,
	bias map[edgeKey]float64) (*searchResult, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is payment target")
	}

	root := &searchState{
		node:    r.spec.Target,
		amount:  amt,
		depth:   0,
		logProb: 0,
	}
	labels := map[route.Vertex][]*searchState{
		r.spec.Target: {root},
	}
	pq := &stateQueue{}
	heap.Push(pq, root)

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*searchState)
		if item.dead {
			continue
		}
		if item.node == r.source {
			path := make([]*candidateEdge, 0, item.depth)
			for current := item; current != nil && current.edge != nil;
				current = current.next {

				path = append(path, current.edge)
			}

			rt, err := r.buildRoute(amt, path)
			if err != nil {
				return nil, err
			}
			return &searchResult{
				rt:      rt,
				path:    path,
				uses:    routeUses(rt, path),
				logProb: item.logProb,
				fee:     rt.TotalAmount - amt,
			}, nil
		}
		if item.depth >= maxPathLength {
			continue
		}

		arriving := item.amount
		for _, edge := range r.incomingEdges[item.node] {
			if stateContains(item, edge.from) ||
				!r.edgeAvailable(edge, arriving, extra) {

				continue
			}

			p := r.edgeProbability(edge, arriving, extra)
			sending := arriving
			edgeFee := lnwire.MilliSatoshi(0)
			if edge.from != r.source {
				edgeFee = edge.fee(arriving)
				sending += edgeFee
			}

			needed := r.totalReserved(edge.key, extra) + arriving
			edgeCost := float64(edgeFee) -
				riskWeight*math.Log(p) + 25_000
			edgeCost += r.missPenalty(edge, needed)
			edgeCost += r.policyPenalty[edge.key]

			if bias != nil {
				edgeCost += bias[edge.key]
			}
			if reuse != nil && reuse[edge.key] > 0 {
				edgeCost += 5_000_000 *
					float64(reuse[edge.key])
			}

			next := &searchState{
				node:     edge.from,
				score:    item.score + edgeCost,
				amount:   sending,
				logProb:  item.logProb + math.Log(p),
				edge:     edge,
				next:     item,
				depth:    item.depth + 1,
			}
			if acceptLabel(labels, next) {
				heap.Push(pq, next)
			}
		}
	}

	return nil, errors.New("no route found")
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, error) {

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}
	if path[0].from != r.source ||
		path[len(path)-1].to != r.spec.Target {

		return nil, errors.New("invalid path endpoints")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))
	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		nextEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			nextEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(nextEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forward := amt
		expiry := uint32(finalCltvDelta)
		if i < last {
			forward = amtOver[i+1]
			expiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func routeUses(rt *route.Route, path []*candidateEdge) []edgeUse {
	uses := make([]edgeUse, len(path))
	for i, edge := range path {
		amount := rt.TotalAmount
		if i > 0 {
			amount = rt.Hops[i-1].AmtToForward
		}
		uses[i] = edgeUse{edge: edge, amount: amount}
	}
	return uses
}

func deliveredAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func routeHash(rt *route.Route) uint64 {
	h := uint64(1469598103934665603)
	for _, hop := range rt.Hops {
		h ^= hop.ChannelID
		h *= 1099511628211
		for _, b := range hop.PubKeyBytes {
			h ^= uint64(b)
			h *= 1099511628211
		}
	}
	return h
}

func (r *candidateRouter) findFreshRoute(amt lnwire.MilliSatoshi,
	extra map[edgeKey]lnwire.MilliSatoshi,
	reuse map[edgeKey]int) (*searchResult, error) {

	bias := make(map[edgeKey]float64)
	var lastErr error

	for n := 0; n < 14; n++ {
		result, err := r.findRoute(amt, extra, reuse, bias)
		if err != nil {
			return nil, err
		}

		hash := routeHash(result.rt)
		failedAt, failed := r.tried[hash]
		if !failed || amt*100 <= failedAt*72 {
			return result, nil
		}

		lastErr = errors.New("candidate route already failed")
		if len(result.path) == 0 {
			break
		}

		index := int((hash + uint64(n*7)) %
			uint64(len(result.path)))
		bias[result.path[index].key] += 18_000_000
	}

	if lastErr == nil {
		lastErr = errors.New("no fresh route found")
	}
	return nil, lastErr
}

func (r *candidateRouter) reliableDeliveryLimit(result *searchResult,
	extra map[edgeKey]lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	delivery := deliveredAmount(result.rt)
	limit := delivery * 8
	if limit < delivery {
		limit = delivery
	}

	for _, use := range result.uses {
		edge := use.edge
		reserved := r.totalReserved(edge.key, extra)

		var safeTotal lnwire.MilliSatoshi
		if edge.from == r.source {
			safeTotal = r.localBalances[edge.chanID]
		} else {
			b := r.beliefs[edge.key]
			safeTotal = edge.capacity * 68 / 100

			if b.estimate > 0 && b.confidence > 0 {
				w := math.Min(0.82, b.confidence)
				safeTotal = lnwire.MilliSatoshi(
					(1-w)*float64(safeTotal) +
						w*float64(b.estimate),
				)
			}
			if b.lowerOK > safeTotal {
				safeTotal = b.lowerOK
			}
			if b.upper > b.lowerOK && safeTotal >= b.upper {
				safeTotal = b.upper * 17 / 20
			}
		}

		if safeTotal > edge.capacity {
			safeTotal = edge.capacity
		}
		if safeTotal <= reserved {
			return 0
		}

		available := safeTotal - reserved
		edgeLimit := delivery * available / use.amount

		if edge.maxHTLC != 0 {
			policyLimit := delivery * edge.maxHTLC / use.amount
			if policyLimit < edgeLimit {
				edgeLimit = policyLimit
			}
		}
		if edgeLimit < limit {
			limit = edgeLimit
		}
	}

	return limit
}

func addReservations(dst map[edgeKey]lnwire.MilliSatoshi,
	uses []edgeUse) {

	for _, use := range uses {
		dst[use.edge.key] += use.amount
	}
}

func releaseReservations(dst map[edgeKey]lnwire.MilliSatoshi,
	uses []edgeUse) {

	for _, use := range uses {
		current := dst[use.edge.key]
		if current <= use.amount {
			delete(dst, use.edge.key)
		} else {
			dst[use.edge.key] = current - use.amount
		}
	}
}

func (r *candidateRouter) planMetric(results []*searchResult) float64 {
	totals := make(map[edgeKey]lnwire.MilliSatoshi)
	edges := make(map[edgeKey]*candidateEdge)
	fees := lnwire.MilliSatoshi(0)

	for _, result := range results {
		fees += result.fee
		for _, use := range result.uses {
			totals[use.edge.key] += use.amount
			edges[use.edge.key] = use.edge
		}
	}

	metric := -0.035 * float64(len(results))
	for key, amount := range totals {
		edge := edges[key]
		p := r.edgeProbability(edge, amount, nil)
		metric += math.Log(p)

		needed := r.reserved[key] + amount
		metric -= r.missPenalty(edge, needed) / riskWeight
		metric -= r.policyPenalty[key] / riskWeight
	}
	metric -= float64(fees) / 20_000_000

	return metric
}

func (r *candidateRouter) buildPlanForParts(amt lnwire.MilliSatoshi,
	parts int, maxShard lnwire.MilliSatoshi) ([]*searchResult, bool) {

	remaining := amt
	virtual := make(map[edgeKey]lnwire.MilliSatoshi)
	reuse := make(map[edgeKey]int)
	results := make([]*searchResult, 0, parts)

	for i := 0; i < parts && remaining > 0; i++ {
		slots := parts - i
		goal := (remaining + lnwire.MilliSatoshi(slots) - 1) /
			lnwire.MilliSatoshi(slots)

		probe := goal
		if maxShard > 0 && probe > maxShard {
			probe = maxShard
		}
		if slots == 1 {
			probe = remaining
			if maxShard > 0 && probe > maxShard {
				return nil, false
			}
		}

		var result *searchResult
		var err error
		for tries := 0; tries < 5 && probe > 0; tries++ {
			result, err = r.findFreshRoute(probe, virtual, reuse)
			if err == nil {
				break
			}
			probe = probe * 2 / 3
		}
		if err != nil || result == nil {
			return nil, false
		}

		safe := r.reliableDeliveryLimit(result, virtual)
		if safe <= 0 {
			return nil, false
		}

		share := goal
		if safe < share {
			share = safe * 9 / 10
		} else if slots > 1 {
			preferred := safe * 17 / 20
			unequalCap := goal * 8 / 5
			if preferred > share {
				share = preferred
			}
			if share > unequalCap {
				share = unequalCap
			}
		} else {
			share = remaining
		}

		if maxShard > 0 && share > maxShard {
			share = maxShard
		}
		if share > remaining {
			share = remaining
		}
		if share <= 0 {
			return nil, false
		}

		result, err = r.findFreshRoute(share, virtual, reuse)
		if err != nil {
			return nil, false
		}

		safe = r.reliableDeliveryLimit(result, virtual)
		if safe < share {
			if slots == 1 || safe <= 0 {
				return nil, false
			}
			share = safe * 9 / 10
			if share <= 0 {
				return nil, false
			}
			result, err = r.findFreshRoute(share, virtual, reuse)
			if err != nil {
				return nil, false
			}
		}

		results = append(results, result)
		addReservations(virtual, result.uses)
		for _, use := range result.uses {
			reuse[use.edge.key]++
		}
		remaining -= share
	}

	if remaining != 0 {
		return nil, false
	}
	return results, true
}

func appendPartOption(options []int, value, maximum int) []int {
	if value < 2 || value > maximum {
		return options
	}
	for _, existing := range options {
		if existing == value {
			return options
		}
	}
	return append(options, value)
}

func (r *candidateRouter) preparePlan(amt lnwire.MilliSatoshi,
	partsLeft uint32) error {

	r.plan = nil
	if partsLeft == 0 {
		return errors.New("maximum in-flight parts reached")
	}

	var best []*searchResult
	bestMetric := math.Inf(-1)

	allowDirect := partsLeft == 1 || r.failures < 3 ||
		r.retryCeiling == 0 || amt <= r.retryCeiling

	direct, directErr := r.findFreshRoute(amt, nil, nil)
	if allowDirect && directErr == nil {
		best = []*searchResult{direct}
		bestMetric = r.planMetric(best)
	}

	maxParts := int(partsLeft)
	if maxParts > 16 {
		maxParts = 16
	}

	maxShard := lnwire.MilliSatoshi(0)
	if r.failures >= 3 {
		maxShard = r.retryCeiling
	}

	options := make([]int, 0, 7)
	options = appendPartOption(options, 2, maxParts)
	options = appendPartOption(options, 3, maxParts)
	options = appendPartOption(options, 4, maxParts)
	options = appendPartOption(options, 6, maxParts)
	options = appendPartOption(options, 8, maxParts)
	options = appendPartOption(options, 12, maxParts)
	options = appendPartOption(options, maxParts, maxParts)

	for _, parts := range options {
		results, ok := r.buildPlanForParts(amt, parts, maxShard)
		if !ok {
			continue
		}

		metric := r.planMetric(results)
		if metric > bestMetric+0.02 {
			best = results
			bestMetric = metric
		}
	}

	if len(best) == 0 {
		if directErr != nil {
			return directErr
		}
		return errors.New("no route set found")
	}

	r.plan = make([]plannedRoute, len(best))
	for i, result := range best {
		r.plan[i] = plannedRoute{result: result}
	}
	return nil
}

func (r *candidateRouter) issue(result *searchResult) *route.Route {
	addReservations(r.reserved, result.uses)
	r.issued[result.rt] = result.uses
	return result.rt
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum in-flight parts reached")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.plan) > 0 {
		result := r.plan[0].result
		if deliveredAmount(result.rt) <= amt {
			r.plan = r.plan[1:]
			return r.issue(result), nil
		}
		r.plan = nil
	}

	if err := r.preparePlan(amt, partsLeft); err == nil &&
		len(r.plan) > 0 {

		result := r.plan[0].result
		r.plan = r.plan[1:]
		return r.issue(result), nil
	}

	if partsLeft <= 1 {
		return nil, errors.New("no route found")
	}

	tryAmt := amt
	if r.failures >= 3 && r.retryCeiling > 0 &&
		r.retryCeiling < tryAmt {

		tryAmt = r.retryCeiling
	}

	minTry := amt / lnwire.MilliSatoshi(partsLeft*6)
	if minTry <= 0 {
		minTry = 1
	}

	for tries := 0; tries < 10 && tryAmt >= minTry; tries++ {
		result, err := r.findFreshRoute(tryAmt, nil, nil)
		if err == nil {
			safe := r.reliableDeliveryLimit(result, nil)
			if safe > 0 && safe < tryAmt {
				tryAmt = safe * 9 / 10
				if tryAmt < minTry {
					tryAmt = minTry
				}
				continue
			}
			return r.issue(result), nil
		}

		next := tryAmt * 2 / 3
		if next < minTry {
			next = minTry
		}
		if next == tryAmt {
			break
		}
		tryAmt = next
	}

	return nil, errors.New("no route found")
}

func (r *candidateRouter) saveBelief(key edgeKey,
	b liquidityBelief) {

	r.beliefs[key] = b
	sharedBeliefs.Lock()
	sharedBeliefs.m[key] = b
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) learnSuccess(use edgeUse,
	totalObserved lnwire.MilliSatoshi) {

	key := use.edge.key
	b := r.beliefs[key]

	if totalObserved > b.lowerOK {
		b.lowerOK = totalObserved
	}
	if totalObserved > b.estimate {
		b.estimate = totalObserved
	}
	b.confidence = math.Min(1, b.confidence+0.35)

	if b.upper > 0 && totalObserved >= b.upper {
		b.upper = 0
	}
	if b.suspectAmt > 0 && totalObserved >= b.suspectAmt {
		b.suspectAmt = 0
		b.evidence = 0
		b.lastPath = 0
	}

	r.saveBelief(key, b)

	if miss := r.misses[key]; miss.amount > 0 &&
		totalObserved >= miss.amount {

		delete(r.misses, key)
	}
}

func (r *candidateRouter) learnFailure(edge *candidateEdge,
	totalObserved lnwire.MilliSatoshi, pathHash uint64,
	weight float64) {

	if edge.from == r.source || totalObserved <= 0 || weight <= 0 {
		return
	}

	key := edge.key
	b := r.beliefs[key]

	if b.suspectAmt == 0 ||
		totalObserved*2 < b.suspectAmt ||
		totalObserved > b.suspectAmt*2 {

		b.suspectAmt = totalObserved
		b.evidence = weight
		b.lastPath = pathHash
	} else {
		if totalObserved < b.suspectAmt {
			b.suspectAmt = totalObserved
		}
		if b.lastPath == pathHash {
			b.evidence += weight * 0.35
		} else {
			b.evidence += weight
			b.lastPath = pathHash
		}
	}

	failedEstimate := totalObserved * 2 / 3
	if b.estimate == 0 {
		b.estimate = failedEstimate
	} else {
		w := math.Min(0.35, weight*0.28)
		b.estimate = lnwire.MilliSatoshi(
			(1-w)*float64(b.estimate) +
				w*float64(failedEstimate),
		)
	}
	b.confidence = math.Min(1, b.confidence+0.12*weight)

	// Two independently attributed primary observations are enough to
	// establish a ceiling. Adjacent-hop evidence needs many more samples.
	if b.evidence >= 1.35 &&
		(b.lowerOK == 0 || b.suspectAmt > b.lowerOK) {

		if b.upper == 0 || b.suspectAmt < b.upper {
			b.upper = b.suspectAmt
		}
	}

	r.saveBelief(key, b)
}

func (r *candidateRouter) addLocalMiss(edge *candidateEdge,
	amount lnwire.MilliSatoshi, weight float64) {

	if amount <= 0 || weight <= 0 {
		return
	}

	old := r.misses[edge.key]
	if old.amount == 0 ||
		amount*2 < old.amount ||
		amount > old.amount*2 {

		r.misses[edge.key] = localMiss{
			amount: amount,
			weight: weight,
		}
		return
	}

	if amount < old.amount {
		old.amount = amount
	}
	old.weight = math.Min(4, old.weight+weight)
	r.misses[edge.key] = old
}

func findFailureNode(rt *route.Route, source route.Vertex) int {
	if source == rt.SourcePubKey {
		return 0
	}
	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}
	return -1
}

func (r *candidateRouter) applyLiquidityBlame(uses []edgeUse,
	totalDemand map[edgeKey]lnwire.MilliSatoshi,
	primary int, pathHash uint64) {

	if len(uses) == 0 {
		return
	}

	apply := func(index int, weight float64) {
		if index < 0 || index >= len(uses) {
			return
		}
		use := uses[index]
		amount := totalDemand[use.edge.key]
		r.addLocalMiss(use.edge, amount, weight)
		r.learnFailure(use.edge, amount, pathHash, weight)
	}

	// The target has no outgoing edge. Blame placed there is most
	// plausibly a one-hop shift from the final forwarding node.
	if primary >= len(uses) {
		apply(len(uses)-1, 0.80)
		return
	}

	// Local outbound liquidity is known exactly. A reported liquidity
	// failure there is therefore much more likely to be shifted blame.
	if primary == 0 && uses[0].edge.from == r.source {
		apply(0, 0.08)
		apply(1, 0.78)
		return
	}

	apply(primary, 0.76)
	apply(primary-1, 0.12)
	apply(primary+1, 0.12)
}

func (r *candidateRouter) lookupIssued(rt *route.Route) []edgeUse {
	if uses, ok := r.issued[rt]; ok {
		delete(r.issued, rt)
		return uses
	}

	hash := routeHash(rt)
	for issuedRoute, uses := range r.issued {
		if routeHash(issuedRoute) == hash &&
			deliveredAmount(issuedRoute) == deliveredAmount(rt) {

			delete(r.issued, issuedRoute)
			return uses
		}
	}

	path := make([]*candidateEdge, 0, len(rt.Hops))
	from := rt.SourcePubKey
	for _, hop := range rt.Hops {
		var found *candidateEdge
		for _, edge := range r.incomingEdges[hop.PubKeyBytes] {
			if edge.from == from && edge.chanID == hop.ChannelID {
				found = edge
				break
			}
		}
		if found == nil {
			return nil
		}
		path = append(path, found)
		from = hop.PubKeyBytes
	}

	return routeUses(rt, path)
}

func (r *candidateRouter) ReportAttempt(attemptID uint64,
	rt *route.Route, result routing.SimHtlcResult) error {

	_ = attemptID
	if rt == nil {
		return errors.New("nil reported route")
	}

	uses := r.lookupIssued(rt)

	if result.Failure == nil {
		for _, use := range uses {
			r.held[use.edge.key] += use.amount
			r.learnSuccess(use, r.held[use.edge.key])
		}
		return nil
	}

	r.failures++
	hash := routeHash(rt)
	delivered := deliveredAmount(rt)
	if old, exists := r.tried[hash]; !exists || delivered < old {
		r.tried[hash] = delivered
	}

	totalDemand := make(map[edgeKey]lnwire.MilliSatoshi, len(uses))
	for _, use := range uses {
		// Only successful held siblings and this attempt are known to
		// contribute to the failed demand. Other pending attempts are
		// excluded because they have not yet proven anything.
		totalDemand[use.edge.key] =
			r.held[use.edge.key] + use.amount
	}

	releaseReservations(r.reserved, uses)
	r.plan = nil

	nextCeiling := delivered * 31 / 50
	if nextCeiling > 0 &&
		(r.retryCeiling == 0 || nextCeiling < r.retryCeiling) {

		r.retryCeiling = nextCeiling
	}

	failNode := findFailureNode(rt, result.FailureSource)
	if failNode < 0 {
		// Unreadable onion failures provide route-level evidence only.
		return nil
	}

	code := result.Failure.Code()
	if code == lnwire.CodeTemporaryChannelFailure {
		r.applyLiquidityBlame(
			uses, totalDemand, failNode, hash,
		)
		return nil
	}

	isPolicy := code == lnwire.CodeFeeInsufficient ||
		code == lnwire.CodeIncorrectCltvExpiry
	if !isPolicy || len(uses) == 0 {
		return nil
	}

	if failNode >= len(uses) {
		r.policyPenalty[uses[len(uses)-1].edge.key] += 8_000_000
		return nil
	}

	r.policyPenalty[uses[failNode].edge.key] += 10_000_000
	if failNode > 0 {
		r.policyPenalty[uses[failNode-1].edge.key] += 1_500_000
	}
	if failNode+1 < len(uses) {
		r.policyPenalty[uses[failNode+1].edge.key] += 1_500_000
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type edgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type beliefKey struct {
	network uint64
	edge    edgeKey
}

type liquidityBelief struct {
	lowerOK lnwire.MilliSatoshi
	upper   lnwire.MilliSatoshi

	estimate lnwire.MilliSatoshi
	conf     float64

	probeFail  lnwire.MilliSatoshi
	failVotes  uint8
}

var persistentBeliefs = struct {
	sync.RWMutex
	values map[beliefKey]liquidityBelief
}{
	values: make(map[beliefKey]liquidityBelief),
}

type candidateEdge struct {
	key edgeKey

	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usableHTLC(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return amt <= e.capacity
}

type plannedShard struct {
	route *route.Route
	amt   lnwire.MilliSatoshi
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges          map[edgeKey]*candidateEdge
	localBalances  map[uint64]lnwire.MilliSatoshi
	networkID      uint64

	// reserved includes successful shards from the current payment. This
	// models both atomic holds and liquidity already consumed by settled
	// non-atomic shards.
	reserved map[edgeKey]lnwire.MilliSatoshi

	// Per-payment evidence affects exploration immediately, while persistent
	// hard bounds require corroboration.
	suspicions map[edgeKey]uint8
	penalty    map[edgeKey]float64
	tried      map[string]uint8

	plan []plannedShard
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[edgeKey]*candidateEdge),
		localBalances:  localBalances,
		reserved:       make(map[edgeKey]lnwire.MilliSatoshi),
		suspicions:     make(map[edgeKey]uint8),
		penalty:        make(map[edgeKey]float64),
		tried:          make(map[string]uint8),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, exists := r.edges[key]; exists {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: pol.FeeBaseMSat,
					feeRatePPM: pol.
						FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.edges[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkID = graphFingerprint(r.edges)
	return r, nil
}

func graphFingerprint(edges map[edgeKey]*candidateEdge) uint64 {
	var result uint64

	for _, edge := range edges {
		h := uint64(1469598103934665603)
		mix := func(v byte) {
			h ^= uint64(v)
			h *= 1099511628211
		}

		for i := 0; i < 8; i++ {
			mix(byte(edge.key.chanID >> (8 * i)))
		}
		for _, b := range edge.key.from {
			mix(b)
		}
		for _, b := range edge.key.to {
			mix(b)
		}

		capacity := uint64(edge.capacity)
		for i := 0; i < 8; i++ {
			mix(byte(capacity >> (8 * i)))
		}

		result ^= h
	}

	if result == 0 {
		return 1
	}
	return result
}

func clampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005
	case p > 0.995:
		return 0.995
	default:
		return p
	}
}

// bimodalPrior models a channel as being either nearly depleted or nearly
// full. Tiny sends can pass in either mode; medium sends mostly depend on
// selecting the rich direction; amounts near capacity encounter a cliff.
func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.035)
	highMode := 1 / (1 + math.Exp((x-0.88)*24))
	return clampProbability(0.50*lowMode + 0.50*highMode)
}

func (r *candidateRouter) getBelief(key edgeKey) liquidityBelief {
	persistentBeliefs.RLock()
	b := persistentBeliefs.values[beliefKey{
		network: r.networkID,
		edge:    key,
	}]
	persistentBeliefs.RUnlock()
	return b
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	required lnwire.MilliSatoshi) float64 {

	p := bimodalPrior(required, edge.capacity)
	b := r.getBelief(edge.key)

	if b.lowerOK > 0 && required <= b.lowerOK {
		return 0.995
	}

	if b.upper > 0 {
		if required >= b.upper {
			return 0.012
		}

		lo := b.lowerOK
		if lo >= b.upper {
			lo = 0
		}

		if required > lo {
			span := float64(b.upper - lo)
			pos := float64(required-lo) / span
			boundP := 0.995*(1-pos) + 0.012*pos
			weight := math.Min(0.85, 0.35+0.10*b.conf)
			p = (1-weight)*p + weight*boundP
		}
	}

	if b.estimate > 0 {
		width := math.Max(float64(edge.capacity)*0.075, 1_000_000)
		estimateP := 1 / (1 + math.Exp(
			(float64(required)-float64(b.estimate))/width,
		))
		weight := math.Min(0.65, b.conf/(b.conf+3))
		p = (1-weight)*p + weight*estimateP
	}

	return clampProbability(p)
}

func (r *candidateRouter) recordSuccess(key edgeKey,
	required lnwire.MilliSatoshi) {

	persistentBeliefs.Lock()
	bk := beliefKey{network: r.networkID, edge: key}
	b := persistentBeliefs.values[bk]

	if required > b.lowerOK {
		b.lowerOK = required
	}

	estimate := required + required/4
	if estimate > b.estimate {
		b.estimate = estimate
	}

	// Success is truthful. It immediately invalidates any contradictory
	// failure ceiling, including one produced by stale or shifted blame.
	if b.upper > 0 && required >= b.upper {
		b.upper = 0
		b.probeFail = 0
		b.failVotes = 0
	}

	if b.conf < 8 {
		b.conf += 1
	}
	persistentBeliefs.values[bk] = b
	persistentBeliefs.Unlock()
}

func closeFailureAmounts(a, b lnwire.MilliSatoshi) bool {
	if a <= 0 || b <= 0 {
		return false
	}

	delta := a - b
	if delta < 0 {
		delta = -delta
	}

	tolerance := b / 3
	if tolerance < 1_000_000 {
		tolerance = 1_000_000
	}
	return delta <= tolerance
}

// recordLiquidityFailure quarantines a first report. A hard ceiling is only
// installed after a second compatible attribution to the same directed edge.
func (r *candidateRouter) recordLiquidityFailure(key edgeKey,
	required lnwire.MilliSatoshi) {

	persistentBeliefs.Lock()
	bk := beliefKey{network: r.networkID, edge: key}
	b := persistentBeliefs.values[bk]

	// A truthful success outweighs a contradictory, potentially shifted
	// failure attribution.
	if b.lowerOK > 0 && required <= b.lowerOK {
		b.probeFail = 0
		b.failVotes = 0
		persistentBeliefs.values[bk] = b
		persistentBeliefs.Unlock()
		return
	}

	if closeFailureAmounts(required, b.probeFail) {
		if b.failVotes < 255 {
			b.failVotes++
		}
		if required < b.probeFail {
			b.probeFail = required
		}
	} else {
		b.probeFail = required
		b.failVotes = 1
	}

	if b.failVotes >= 2 {
		if b.upper == 0 || b.probeFail < b.upper {
			b.upper = b.probeFail
		}

		estimate := b.probeFail * 2 / 3
		if b.estimate == 0 || estimate < b.estimate {
			b.estimate = estimate
		}
		if b.conf < 8 {
			b.conf += 1
		}
	}

	persistentBeliefs.values[bk] = b
	persistentBeliefs.Unlock()
}

type searchItem struct {
	node   route.Vertex
	score  float64
	amount lnwire.MilliSatoshi
	index  int
}

type searchQueue []*searchItem

func (q searchQueue) Len() int {
	return len(q)
}

func (q searchQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q searchQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index = i
	q[j].index = j
}

func (q *searchQueue) Push(x any) {
	item := x.(*searchItem)
	item.index = len(*q)
	*q = append(*q, item)
}

func (q *searchQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

type routeSearchResult struct {
	route *route.Route
	score float64
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	reserved map[edgeKey]lnwire.MilliSatoshi,
	reuse map[edgeKey]uint8) (*routeSearchResult, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is target")
	}

	dist := make(map[route.Vertex]float64)
	amountAt := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)

	dist[r.spec.Target] = 0
	amountAt[r.spec.Target] = amt

	pq := &searchQueue{}
	heap.Push(pq, &searchItem{
		node:   r.spec.Target,
		score:  0,
		amount: amt,
	})

	feeScale := math.Max(float64(amt)*0.0025, 25_000)

	for pq.Len() != 0 {
		item := heap.Pop(pq).(*searchItem)
		bestScore, ok := dist[item.node]
		if !ok || item.score > bestScore+1e-12 {
			continue
		}
		if item.node == r.source {
			break
		}

		arriving := amountAt[item.node]
		for _, edge := range r.incomingEdges[item.node] {
			if !edge.usableHTLC(arriving) {
				continue
			}

			already := reserved[edge.key]
			if already > edge.capacity ||
				arriving > edge.capacity-already {

				continue
			}

			required := already + arriving
			probability := r.edgeProbability(edge, required)

			if edge.key.from == r.source {
				local := r.localBalances[edge.key.chanID]
				if already > local || arriving > local-already {
					continue
				}
				probability = 0.995
			}

			sending := arriving
			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(arriving)
				if fee < 0 {
					continue
				}
				sending += fee
				if sending < arriving {
					continue
				}
			}

			increment := -math.Log(probability)
			increment += float64(fee) / feeScale
			increment += 0.012
			increment += r.penalty[edge.key]

			if count := reuse[edge.key]; count > 0 &&
				edge.key.from != r.source {

				increment += 0.70 * float64(count)
			}

			candidate := item.score + increment
			old, exists := dist[edge.key.from]
			if exists && candidate >= old {
				continue
			}

			dist[edge.key.from] = candidate
			amountAt[edge.key.from] = sending
			next[edge.key.from] = edge
			heap.Push(pq, &searchItem{
				node:   edge.key.from,
				score:  candidate,
				amount: sending,
			})
		}
	}

	score, ok := dist[r.source]
	if !ok {
		return nil, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, err
	}

	return &routeSearchResult{
		route: rt,
		score: score,
	}, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("cycle in route")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		nextEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			nextEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(nextEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forward := amt
		expiry := uint32(finalCltvDelta)

		if i < last {
			forward = amtOver[i+1]
			expiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func routeDeliveredAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func routeEdge(rt *route.Route, index int) (edgeKey,
	lnwire.MilliSatoshi, bool) {

	if rt == nil || index < 0 || index >= len(rt.Hops) {
		return edgeKey{}, 0, false
	}

	from := rt.SourcePubKey
	amt := rt.TotalAmount
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
		amt = rt.Hops[index-1].AmtToForward
	}

	return edgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
		to:     rt.Hops[index].PubKeyBytes,
	}, amt, true
}

func routeSignature(rt *route.Route) string {
	if rt == nil {
		return ""
	}

	s := fmt.Sprintf("%d", routeDeliveredAmount(rt))
	for i := range rt.Hops {
		key, _, ok := routeEdge(rt, i)
		if !ok {
			continue
		}
		s += fmt.Sprintf("/%d:%x:%x", key.chanID, key.from, key.to)
	}
	return s
}

func copyReservations(src map[edgeKey]lnwire.MilliSatoshi,
) map[edgeKey]lnwire.MilliSatoshi {

	dst := make(map[edgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func shardAmounts(total lnwire.MilliSatoshi, parts int,
	unequal bool) []lnwire.MilliSatoshi {

	if parts <= 1 {
		return []lnwire.MilliSatoshi{total}
	}

	result := make([]lnwire.MilliSatoshi, parts)
	remaining := total

	if !unequal {
		for i := 0; i < parts; i++ {
			left := parts - i
			result[i] = remaining / lnwire.MilliSatoshi(left)
			remaining -= result[i]
		}
		return result
	}

	// A modest front-loaded split lets the best corridor carry more while
	// retaining enough parts for weaker parallel corridors.
	denominator := int64(parts*2 + 1)
	for i := 0; i < parts; i++ {
		if i == parts-1 {
			result[i] = remaining
			break
		}

		weight := int64(2)
		if i == 0 {
			weight = 3
		}

		result[i] = lnwire.MilliSatoshi(
			int64(total) * weight / denominator,
		)
		remaining -= result[i]
	}

	return result
}

func (r *candidateRouter) constructPlan(total lnwire.MilliSatoshi,
	parts int, unequal bool) ([]plannedShard, float64, error) {

	amounts := shardAmounts(total, parts, unequal)
	tempReserved := copyReservations(r.reserved)
	reuse := make(map[edgeKey]uint8)
	plan := make([]plannedShard, 0, len(amounts))
	totalScore := 0.10 * float64(parts-1)

	for _, shardAmt := range amounts {
		if shardAmt <= 0 {
			return nil, 0, errors.New("invalid shard amount")
		}

		found, err := r.findRoute(shardAmt, tempReserved, reuse)
		if err != nil {
			return nil, 0, err
		}

		plan = append(plan, plannedShard{
			route: found.route,
			amt:   shardAmt,
		})
		totalScore += found.score

		for i := range found.route.Hops {
			key, amtOver, ok := routeEdge(found.route, i)
			if !ok {
				continue
			}
			tempReserved[key] += amtOver
			if reuse[key] < 255 {
				reuse[key]++
			}
		}
	}

	return plan, totalScore, nil
}

func (r *candidateRouter) bestPlan(total lnwire.MilliSatoshi,
	partsLeft uint32) ([]plannedShard, error) {

	maxParts := int(partsLeft)
	if maxParts < 1 {
		return nil, errors.New("no payment parts available")
	}
	if maxParts > 16 {
		maxParts = 16
	}

	var best []plannedShard
	bestScore := math.Inf(1)

	for parts := 1; parts <= maxParts; parts++ {
		for variant := 0; variant < 2; variant++ {
			if parts == 1 && variant == 1 {
				continue
			}

			plan, score, err := r.constructPlan(
				total, parts, variant == 1,
			)
			if err != nil {
				continue
			}
			if score < bestScore {
				best = plan
				bestScore = score
			}
		}
	}

	if len(best) == 0 {
		return nil, errors.New("no route found")
	}
	return best, nil
}

func planTotal(plan []plannedShard) lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	for _, shard := range plan {
		total += shard.amt
	}
	return total
}

func (r *candidateRouter) diversifyRepeatedPlan(
	plan []plannedShard) bool {

	if len(plan) == 0 {
		return false
	}

	first := plan[0].route
	signature := routeSignature(first)
	repeats := r.tried[signature]
	if repeats < 2 {
		return false
	}

	if len(first.Hops) == 0 {
		return false
	}

	choice := int(repeats) % len(first.Hops)
	key, _, ok := routeEdge(first, choice)
	if !ok {
		return false
	}

	r.penalty[key] += 2.5
	return true
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}

	if len(r.plan) > 0 && planTotal(r.plan) == amt {
		next := r.plan[0]
		r.plan = r.plan[1:]
		return next.route, nil
	}
	r.plan = nil

	var partsLeft uint32
	if inFlightHtlcs < r.spec.MaxParts {
		partsLeft = r.spec.MaxParts - inFlightHtlcs
	}
	if partsLeft == 0 {
		return nil, errors.New("maximum payment parts reached")
	}

	for diversification := 0; diversification < 6; diversification++ {
		plan, err := r.bestPlan(amt, partsLeft)
		if err != nil {
			return nil, err
		}

		if r.diversifyRepeatedPlan(plan) {
			continue
		}

		next := plan[0]
		r.plan = plan[1:]
		return next.route, nil
	}

	return nil, errors.New("no fresh route found")
}

func failureOutgoingIndex(rt *route.Route,
	source route.Vertex) int {

	if rt == nil {
		return -1
	}
	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}
	return -1
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if rt == nil {
		return nil
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key, amtOver, ok := routeEdge(rt, i)
			if !ok {
				continue
			}

			required := r.reserved[key] + amtOver
			r.recordSuccess(key, required)
			r.reserved[key] = required

			if r.penalty[key] > 0.25 {
				r.penalty[key] *= 0.5
			} else {
				delete(r.penalty, key)
			}
		}
		return nil
	}

	r.plan = nil
	signature := routeSignature(rt)
	if r.tried[signature] < 255 {
		r.tried[signature]++
	}

	// An off-route source explicitly carries no usable attribution.
	failIndex := failureOutgoingIndex(rt, result.FailureSource)
	if failIndex < 0 || failIndex >= len(rt.Hops) {
		return nil
	}

	key, amtOver, ok := routeEdge(rt, failIndex)
	if !ok {
		return nil
	}

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		if r.suspicions[key] < 255 {
			r.suspicions[key]++
		}

		// A single plausible report only nudges route selection. Repeated
		// compatible reports earn a stronger per-payment penalty and a
		// corroborated persistent liquidity ceiling.
		if r.suspicions[key] == 1 {
			r.penalty[key] += 0.45
		} else {
			r.penalty[key] += 1.10
		}
		r.recordLiquidityFailure(
			key, r.reserved[key]+amtOver,
		)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		// The route was built from current gossip, so a policy failure is
		// likely stale gossip or shifted blame. Avoid it for this payment
		// without poisoning persistent liquidity knowledge.
		r.penalty[key] += 2.0
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(
	amt lnwire.MilliSatoshi) bool {

	if amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	conf      uint8

	suspectAmt    lnwire.MilliSatoshi
	suspectWeight float64
}

var candidateBeliefStore = struct {
	sync.Mutex
	beliefs map[candidateEdgeKey]*candidateBelief
}{
	beliefs: make(map[candidateEdgeKey]*candidateBelief),
}

type candidateLocalFailure struct {
	upper  lnwire.MilliSatoshi
	weight float64
}

type candidateTraversal struct {
	key  candidateEdgeKey
	edge *candidateEdge
	amt  lnwire.MilliSatoshi
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	reserved    map[candidateEdgeKey]lnwire.MilliSatoshi
	usedTotals  map[candidateEdgeKey]lnwire.MilliSatoshi
	localFails  map[candidateEdgeKey]candidateLocalFailure
	edgePenalty map[candidateEdgeKey]float64
	routeFails  map[uint64]uint16

	plannedParts         uint32
	failures             uint32
	failuresSinceProgress uint32
	unknownFails         uint32
	successfulParts      uint32
	retryCap             lnwire.MilliSatoshi
	delivered            lnwire.MilliSatoshi
	settled              bool
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[candidateEdgeKey]*candidateEdge),
		localBalances: localBalances,
		reserved:      make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		usedTotals:    make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		localFails:    make(map[candidateEdgeKey]candidateLocalFailure),
		edgePenalty:   make(map[candidateEdgeKey]float64),
		routeFails:    make(map[uint64]uint16),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[key] = edge

				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.plannedParts = r.initialPartCount(spec.Amount)
	if spec.MaxParts != 0 && r.plannedParts > spec.MaxParts {
		r.plannedParts = spec.MaxParts
	}
	if r.plannedParts == 0 {
		r.plannedParts = 1
	}

	return r, nil
}

func (r *candidateRouter) initialPartCount(
	amt lnwire.MilliSatoshi) uint32 {

	switch {
	case amt <= 15_000_000:
		return 1

	case amt <= 40_000_000:
		return 2

	case amt <= 90_000_000:
		return 4

	case amt <= 220_000_000:
		return 8

	case amt <= 500_000_000:
		return 12

	default:
		return 16
	}
}

func candidatePrior(amt,
	capacity lnwire.MilliSatoshi) float64 {

	if capacity <= 0 || amt > capacity {
		return 0.003
	}

	x := float64(amt) / float64(capacity)

	lowMode := 0.48 * math.Exp(-x/0.025)
	highMode := 0.50 / (1 + math.Exp((x-0.90)/0.025))
	p := 0.005 + lowMode + highMode

	switch {
	case p < 0.005:
		return 0.005

	case p > 0.985:
		return 0.985

	default:
		return p
	}
}

func candidateLogisticProbability(amt, estimate,
	capacity lnwire.MilliSatoshi) float64 {

	if capacity <= 0 {
		return 0.005
	}

	scale := 0.065 * float64(capacity)
	if scale < 1 {
		scale = 1
	}

	z := (float64(amt) - float64(estimate)) / scale
	switch {
	case z > 30:
		return 0.005

	case z < -30:
		return 0.995

	default:
		return 1 / (1 + math.Exp(z))
	}
}

func candidateClampProbability(p float64) float64 {
	switch {
	case p < 0.003:
		return 0.003

	case p > 0.995:
		return 0.995

	default:
		return p
	}
}

func (r *candidateRouter) edgeProbability(e *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	required := amt + r.reserved[e.key]
	if required > e.capacity {
		return 0.001
	}

	if e.key.from == r.source {
		if r.localBalances[e.key.chanID] < required {
			return 0.001
		}

		return 0.999
	}

	p := candidatePrior(required, e.capacity)

	candidateBeliefStore.Lock()
	stored := candidateBeliefStore.beliefs[e.key]
	var belief candidateBelief
	if stored != nil {
		belief = *stored
	}
	candidateBeliefStore.Unlock()

	if stored != nil {
		if belief.estimate > 0 && belief.conf > 0 {
			estimateP := candidateLogisticProbability(
				required, belief.estimate, e.capacity,
			)

			weight := 0.13 * float64(belief.conf)
			if weight > 0.78 {
				weight = 0.78
			}
			p = (1-weight)*p + weight*estimateP
		}

		if belief.lowerOK > 0 && required <= belief.lowerOK {
			p = math.Max(p, 0.995)
		}

		if belief.upperFail > 0 {
			switch {
			case required >= belief.upperFail:
				p = math.Min(p, 0.012)

			case belief.lowerOK > 0 &&
				belief.upperFail > belief.lowerOK &&
				required > belief.lowerOK:

				span := float64(
					belief.upperFail - belief.lowerOK,
				)
				position := float64(
					required - belief.lowerOK,
				) / span
				bounded := 0.995*(1-position) +
					0.012*position
				p = 0.30*p + 0.70*bounded
			}
		}
	}

	if local, ok := r.localFails[e.key]; ok &&
		local.upper > 0 && required >= local.upper {

		p *= math.Exp(-1.75 * local.weight)
	}

	return candidateClampProbability(p)
}

func (r *candidateRouter) edgeCost(e *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	p := r.edgeProbability(e, amt)
	cost := -math.Log(p) + 0.016 + r.edgePenalty[e.key]

	if reserved := r.reserved[e.key]; reserved > 0 &&
		e.capacity > 0 {

		ratio := float64(reserved) / float64(e.capacity)
		cost += 0.12 + 1.10*ratio*ratio
	}

	return cost
}

type candidatePathLabel struct {
	node       route.Vertex
	score      float64
	amt        lnwire.MilliSatoshi
	nextEdge   *candidateEdge
	nextLabel  *candidatePathLabel
	active     bool
}

type candidateDijkstraQueue []*candidatePathLabel

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *candidateDijkstraQueue) Push(x any) {
	*q = append(*q, x.(*candidatePathLabel))
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]

	return item
}

func candidateLabelDominates(a *candidatePathLabel,
	score float64, amt lnwire.MilliSatoshi) bool {

	return a.active && a.score <= score+1e-12 && a.amt <= amt
}

func (r *candidateRouter) addPathLabel(
	labels map[route.Vertex][]*candidatePathLabel,
	label *candidatePathLabel) bool {

	nodeLabels := labels[label.node]
	active := 0

	for _, old := range nodeLabels {
		if candidateLabelDominates(old, label.score, label.amt) {
			return false
		}
		if old.active {
			active++
		}
	}

	for _, old := range nodeLabels {
		if old.active &&
			label.score <= old.score+1e-12 &&
			label.amt <= old.amt {

			old.active = false
			active--
		}
	}

	if active >= 8 {
		var worst *candidatePathLabel
		worstRank := math.Inf(-1)
		denominator := float64(r.spec.Amount)
		if denominator < 1 {
			denominator = 1
		}

		for _, old := range nodeLabels {
			if !old.active {
				continue
			}

			rank := old.score +
				0.20*float64(old.amt)/denominator
			if rank > worstRank {
				worst = old
				worstRank = rank
			}
		}

		newRank := label.score +
			0.20*float64(label.amt)/denominator
		if newRank >= worstRank {
			return false
		}
		worst.active = false
	}

	labels[label.node] = append(nodeLabels, label)
	return true
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}

	target := &candidatePathLabel{
		node:   r.spec.Target,
		score:  0,
		amt:    amt,
		active: true,
	}

	labels := map[route.Vertex][]*candidatePathLabel{
		r.spec.Target: {target},
	}
	pq := &candidateDijkstraQueue{}
	heap.Push(pq, target)

	var sourceLabel *candidatePathLabel

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidatePathLabel)
		if !item.active {
			continue
		}
		if item.node == r.source {
			sourceLabel = item
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOverEdge := item.amt
			if !edge.policyAllows(amtOverEdge) {
				continue
			}

			required := amtOverEdge + r.reserved[edge.key]
			if required > edge.capacity {
				continue
			}
			if edge.key.from == r.source &&
				r.localBalances[edge.key.chanID] < required {

				continue
			}

			sending := amtOverEdge
			feeCost := 0.0
			if edge.key.from != r.source {
				fee := edge.fee(amtOverEdge)
				sending += fee

				denominator := float64(amt)
				if denominator < 1 {
					denominator = 1
				}
				feeCost = 34 * float64(fee) / denominator
			}

			label := &candidatePathLabel{
				node:      edge.key.from,
				score:     item.score +
					r.edgeCost(edge, amtOverEdge) +
					feeCost,
				amt:       sending,
				nextEdge:  edge,
				nextLabel: item,
				active:    true,
			}
			if !r.addPathLabel(labels, label) {
				continue
			}

			heap.Push(pq, label)
		}
	}

	if sourceLabel == nil {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, sourceLabel)
	if err != nil {
		return nil, 0, err
	}

	probability := 1.0
	for _, traversal := range r.routeTraversals(rt) {
		probability *= r.edgeProbability(
			traversal.edge, traversal.amt,
		)
	}

	return rt, probability, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	sourceLabel *candidatePathLabel) (*route.Route, error) {

	var path []*candidateEdge
	for label := sourceLabel; label.node != r.spec.Target; {
		if label.nextEdge == nil || label.nextLabel == nil {
			return nil, fmt.Errorf(
				"broken path at %v", label.node,
			)
		}

		path = append(path, label.nextEdge)
		label = label.nextLabel
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))

	last := len(path) - 1
	amounts[last] = amt
	expiries[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amounts[i] = amounts[i+1] +
			forwardingEdge.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amountToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)

		if i < last {
			amountToForward = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amountToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateCeilDiv(amt lnwire.MilliSatoshi,
	parts uint32) lnwire.MilliSatoshi {

	if parts <= 1 {
		return amt
	}

	divisor := lnwire.MilliSatoshi(parts)
	return (amt + divisor - 1) / divisor
}

func (r *candidateRouter) targetPartCount() uint32 {
	target := r.plannedParts
	target += r.failures / 4

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if target > maxParts {
		target = maxParts
	}
	if target == 0 {
		target = 1
	}

	return target
}

func candidateAppendAmount(amounts []lnwire.MilliSatoshi,
	amt, maximum lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if amt <= 0 || amt > maximum {
		return amounts
	}

	for _, existing := range amounts {
		if existing == amt {
			return amounts
		}
	}

	return append(amounts, amt)
}

func candidateRouteFingerprint(rt *route.Route) uint64 {
	h := uint64(1469598103934665603)
	for _, hop := range rt.Hops {
		h ^= hop.ChannelID
		h *= 1099511628211
	}
	h ^= uint64(candidateDeliveredAmount(rt))
	h *= 1099511628211

	return h
}

type candidateRouteChoice struct {
	route   *route.Route
	utility float64
}

func (r *candidateRouter) chooseRoute(
	amt lnwire.MilliSatoshi, inFlightHtlcs,
	maxParts uint32) (*route.Route, error) {

	partsLeft := maxParts - inFlightHtlcs
	targetParts := r.targetPartCount()

	desiredSlots := uint32(1)
	if targetParts > inFlightHtlcs {
		desiredSlots = targetParts - inFlightHtlcs
	}
	if desiredSlots > partsLeft {
		desiredSlots = partsLeft
	}
	if desiredSlots == 0 {
		desiredSlots = 1
	}

	planBase := candidateCeilDiv(amt, desiredSlots)

	floorDivisor := partsLeft * 3
	if floorDivisor < partsLeft {
		floorDivisor = partsLeft
	}
	floor := candidateCeilDiv(amt, floorDivisor)

	absoluteDivisor := maxParts * 6
	if absoluteDivisor < maxParts {
		absoluteDivisor = maxParts
	}
	absoluteFloor := candidateCeilDiv(
		r.spec.Amount, absoluteDivisor,
	)
	if absoluteFloor > floor {
		floor = absoluteFloor
	}
	if floor > amt {
		floor = amt
	}
	if floor <= 0 {
		floor = 1
	}

	base := planBase
	retrying := r.retryCap > 0
	if retrying && r.retryCap < base {
		base = r.retryCap
	}
	if base < floor {
		base = floor
	}
	if base > amt {
		base = amt
	}

	var candidates []lnwire.MilliSatoshi
	candidates = candidateAppendAmount(candidates, base, amt)
	candidates = candidateAppendAmount(
		candidates, base*3/4, amt,
	)
	candidates = candidateAppendAmount(
		candidates, base/2, amt,
	)
	candidates = candidateAppendAmount(candidates, floor, amt)

	if retrying {
		candidates = candidateAppendAmount(
			candidates, r.retryCap, amt,
		)
		candidates = candidateAppendAmount(
			candidates, planBase, amt,
		)
	} else {
		candidates = candidateAppendAmount(
			candidates, base*5/4, amt,
		)
		candidates = candidateAppendAmount(
			candidates, base*3/2, amt,
		)
		candidates = candidateAppendAmount(
			candidates, base*2, amt,
		)
		candidates = candidateAppendAmount(
			candidates, amt, amt,
		)
	}

	var best *candidateRouteChoice
	var lastErr error

	for _, candidate := range candidates {
		rt, probability, err := r.findRoute(candidate)
		if err != nil {
			lastErr = err
			continue
		}

		if probability < 1e-300 {
			probability = 1e-300
		}

		progressRatio := float64(candidate) / float64(planBase)
		if progressRatio < 1e-9 {
			progressRatio = 1e-9
		}

		utility := math.Log(probability) +
			0.76*math.Log(progressRatio)

		if candidate < planBase {
			utility -= 0.16 * math.Log(
				float64(planBase) / float64(candidate),
			)
		}

		if retrying && candidate > r.retryCap {
			utility -= 0.34
		}

		delivered := candidateDeliveredAmount(rt)
		if delivered > 0 && rt.TotalAmount > delivered {
			feeRatio := float64(
				rt.TotalAmount-delivered,
			) / float64(delivered)
			utility -= 7.0 * feeRatio
		}

		fingerprint := candidateRouteFingerprint(rt)
		utility -= 0.48 * float64(r.routeFails[fingerprint])

		if best == nil || utility > best.utility {
			best = &candidateRouteChoice{
				route:   rt,
				utility: utility,
			}
		}
	}

	if best != nil {
		return best.route, nil
	}
	if lastErr == nil {
		lastErr = errors.New("no route found")
	}

	return nil, lastErr
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum parts already in flight")
	}

	if r.failuresSinceProgress >= 64 {
		return nil, errors.New("route search exhausted")
	}
	if r.failures >= 96 {
		return nil, errors.New("attempt budget exhausted")
	}

	return r.chooseRoute(amt, inFlightHtlcs, maxParts)
}

func (r *candidateRouter) routeTraversals(
	rt *route.Route) []candidateTraversal {

	traversals := make(
		[]candidateTraversal, 0, len(rt.Hops),
	)
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		key := candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		edge := r.edges[key]
		if edge == nil {
			from = hop.PubKeyBytes
			continue
		}

		amount := rt.TotalAmount
		if i > 0 {
			amount = rt.Hops[i-1].AmtToForward
		}

		traversals = append(traversals, candidateTraversal{
			key:  key,
			edge: edge,
			amt:  amount,
		})
		from = hop.PubKeyBytes
	}

	return traversals
}

func candidateDeliveredAmount(
	rt *route.Route) lnwire.MilliSatoshi {

	if len(rt.Hops) == 0 {
		return 0
	}

	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func (r *candidateRouter) recordSuccess(rt *route.Route) {
	traversals := r.routeTraversals(rt)

	candidateBeliefStore.Lock()
	for _, traversal := range traversals {
		required := traversal.amt + r.reserved[traversal.key]

		belief := candidateBeliefStore.beliefs[traversal.key]
		if belief == nil {
			belief = &candidateBelief{}
			candidateBeliefStore.beliefs[traversal.key] = belief
		}

		if required > belief.lowerOK {
			belief.lowerOK = required
		}

		highEstimate := traversal.edge.capacity * 88 / 100
		if required > highEstimate {
			highEstimate = required
		}
		if highEstimate > belief.estimate {
			belief.estimate = highEstimate
		}
		if belief.conf < 8 {
			belief.conf++
		}

		if belief.upperFail > 0 &&
			required >= belief.upperFail {

			belief.upperFail = 0
		}
		if belief.suspectAmt > 0 &&
			required >= belief.suspectAmt {

			belief.suspectAmt = 0
			belief.suspectWeight = 0
		}
	}
	candidateBeliefStore.Unlock()

	for _, traversal := range traversals {
		required := traversal.amt + r.reserved[traversal.key]

		if local, ok := r.localFails[traversal.key]; ok &&
			required >= local.upper {

			delete(r.localFails, traversal.key)
		}

		r.reserved[traversal.key] += traversal.amt
		r.usedTotals[traversal.key] += traversal.amt
		r.edgePenalty[traversal.key] *= 0.25
	}

	r.successfulParts++
	r.failuresSinceProgress = 0
	r.retryCap = 0
	r.delivered += candidateDeliveredAmount(rt)

	if r.delivered >= r.spec.Amount && !r.settled {
		r.recordSettlement()
		r.settled = true
	}
}

func candidateSubtractFloor(value,
	delta lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if value > delta {
		return value - delta
	}

	return 0
}

func candidateShiftUpperDown(value,
	delta lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if value == 0 {
		return 0
	}
	if value > delta {
		return value - delta
	}

	return 1
}

func (r *candidateRouter) recordSettlement() {
	candidateBeliefStore.Lock()
	defer candidateBeliefStore.Unlock()

	for key, used := range r.usedTotals {
		if used <= 0 {
			continue
		}

		if belief := candidateBeliefStore.beliefs[key]; belief != nil {
			belief.lowerOK = candidateSubtractFloor(
				belief.lowerOK, used,
			)
			belief.estimate = candidateSubtractFloor(
				belief.estimate, used,
			)
			belief.upperFail = candidateShiftUpperDown(
				belief.upperFail, used,
			)
			belief.suspectAmt = candidateSubtractFloor(
				belief.suspectAmt, used,
			)
			if belief.suspectAmt == 0 {
				belief.suspectWeight = 0
			}
		}

		reverse := candidateEdgeKey{
			chanID: key.chanID,
			from:   key.to,
			to:     key.from,
		}
		reverseBelief := candidateBeliefStore.beliefs[reverse]
		if reverseBelief == nil {
			reverseBelief = &candidateBelief{}
			candidateBeliefStore.beliefs[reverse] = reverseBelief
		}

		reverseCapacity := lnwire.MilliSatoshi(0)
		if edge := r.edges[reverse]; edge != nil {
			reverseCapacity = edge.capacity
		} else if edge := r.edges[key]; edge != nil {
			reverseCapacity = edge.capacity
		}

		reverseBelief.lowerOK += used
		reverseBelief.estimate += used

		if reverseCapacity > 0 {
			if reverseBelief.lowerOK > reverseCapacity {
				reverseBelief.lowerOK = reverseCapacity
			}
			if reverseBelief.estimate > reverseCapacity {
				reverseBelief.estimate = reverseCapacity
			}
		}

		if reverseBelief.upperFail > 0 {
			reverseBelief.upperFail += used
			if reverseCapacity > 0 &&
				reverseBelief.upperFail > reverseCapacity {

				reverseBelief.upperFail = reverseCapacity
			}
		}
	}
}

func (r *candidateRouter) failureTraversalIndex(
	rt *route.Route, source route.Vertex) (int, bool) {

	if source == rt.SourcePubKey {
		return 0, len(rt.Hops) > 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes != source {
			continue
		}

		index := i + 1
		if index >= len(rt.Hops) {
			return 0, false
		}

		return index, true
	}

	return 0, false
}

func (r *candidateRouter) addLocalFailure(
	traversal candidateTraversal, weight float64) {

	required := traversal.amt + r.reserved[traversal.key]

	local := r.localFails[traversal.key]
	if local.upper == 0 || required < local.upper {
		local.upper = required
	}
	local.weight += weight
	if local.weight > 4 {
		local.weight = 4
	}
	r.localFails[traversal.key] = local
}

func (r *candidateRouter) recordPersistentFailure(
	traversal candidateTraversal, weight float64) {

	if traversal.key.from == r.source {
		return
	}

	required := traversal.amt + r.reserved[traversal.key]

	candidateBeliefStore.Lock()
	defer candidateBeliefStore.Unlock()

	belief := candidateBeliefStore.beliefs[traversal.key]
	if belief == nil {
		belief = &candidateBelief{}
		candidateBeliefStore.beliefs[traversal.key] = belief
	}

	if belief.suspectAmt == 0 || required < belief.suspectAmt {
		belief.suspectAmt = required
	}
	belief.suspectWeight += weight

	if belief.suspectWeight < 2.05 {
		return
	}

	if belief.upperFail == 0 ||
		belief.suspectAmt < belief.upperFail {

		belief.upperFail = belief.suspectAmt
	}

	failedEstimate := belief.suspectAmt * 68 / 100
	if belief.estimate == 0 ||
		failedEstimate < belief.estimate {

		belief.estimate = failedEstimate
	}
	if belief.conf < 8 {
		belief.conf++
	}
}

func (r *candidateRouter) recordAttributedLiquidityFailure(
	traversals []candidateTraversal, claimed int) {

	for offset := -1; offset <= 1; offset++ {
		index := claimed + offset
		if index < 0 || index >= len(traversals) {
			continue
		}

		weight := 0.17
		penalty := 0.14
		if offset == 0 {
			weight = 0.72
			penalty = 0.62
		}

		traversal := traversals[index]
		r.addLocalFailure(traversal, weight)
		r.edgePenalty[traversal.key] += penalty

		if offset == 0 {
			r.recordPersistentFailure(traversal, weight)
		}
	}
}

func (r *candidateRouter) recordPolicyFailure(
	traversals []candidateTraversal, claimed int) {

	for offset := -1; offset <= 1; offset++ {
		index := claimed + offset
		if index < 0 || index >= len(traversals) {
			continue
		}

		penalty := 0.38
		if offset == 0 {
			penalty = 2.40
		}
		r.edgePenalty[traversals[index].key] += penalty
	}
}

func (r *candidateRouter) lowerRetryCap(
	delivered lnwire.MilliSatoshi, factor int64) {

	if delivered <= 1 {
		return
	}

	next := delivered * lnwire.MilliSatoshi(factor) / 100
	if next < 1 {
		next = 1
	}
	if r.retryCap == 0 || next < r.retryCap {
		r.retryCap = next
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64,
	rt *route.Route, result routing.SimHtlcResult) error {

	if result.Failure == nil {
		r.recordSuccess(rt)
		return nil
	}

	r.failures++
	r.failuresSinceProgress++
	r.routeFails[candidateRouteFingerprint(rt)]++

	traversals := r.routeTraversals(rt)
	if len(traversals) != len(rt.Hops) {
		r.unknownFails++
		r.lowerRetryCap(candidateDeliveredAmount(rt), 70)
		return nil
	}

	for _, traversal := range traversals {
		r.edgePenalty[traversal.key] += 0.012
	}

	code := result.Failure.Code()
	claimed, attributed := r.failureTraversalIndex(
		rt, result.FailureSource,
	)

	switch code {
	case lnwire.CodeTemporaryChannelFailure:
		if attributed {
			r.recordAttributedLiquidityFailure(
				traversals, claimed,
			)
			r.lowerRetryCap(
				candidateDeliveredAmount(rt), 58,
			)
			return nil
		}

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		if attributed {
			r.recordPolicyFailure(traversals, claimed)
			return nil
		}
	}

	r.unknownFails++
	r.lowerRetryCap(candidateDeliveredAmount(rt), 70)

	routePenalty := 0.20
	if len(traversals) > 12 {
		routePenalty = 0.14
	}
	for _, traversal := range traversals {
		r.edgePenalty[traversal.key] += routePenalty
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type edgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type beliefKey struct {
	network uint64
	edge    edgeKey
}

type liquidityBelief struct {
	lowerOK lnwire.MilliSatoshi
	upper   lnwire.MilliSatoshi

	estimate lnwire.MilliSatoshi
	conf     float64

	probeFail lnwire.MilliSatoshi
	failVotes uint8
}

var persistentBeliefs = struct {
	sync.RWMutex
	values map[beliefKey]liquidityBelief
}{
	values: make(map[beliefKey]liquidityBelief),
}

type candidateEdge struct {
	key edgeKey

	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usableHTLC(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type plannedShard struct {
	route *route.Route
	amt   lnwire.MilliSatoshi
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges          map[edgeKey]*candidateEdge
	localBalances  map[uint64]lnwire.MilliSatoshi
	networkID      uint64

	// This is cumulative liquidity already consumed or held by successful
	// shards. Planning adds hypothetical sibling reservations on top.
	reserved map[edgeKey]lnwire.MilliSatoshi

	// Failure attribution is noisy. A plausible report gets only a soft,
	// payment-local penalty; persistent hard bounds require corroboration.
	suspicions map[edgeKey]uint8
	penalty    map[edgeKey]float64

	triedExact map[string]uint8
	pathFails  map[string]uint8
	failCount  uint32

	plan []plannedShard
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[edgeKey]*candidateEdge),
		localBalances:  localBalances,
		reserved:       make(map[edgeKey]lnwire.MilliSatoshi),
		suspicions:     make(map[edgeKey]uint8),
		penalty:        make(map[edgeKey]float64),
		triedExact:     make(map[string]uint8),
		pathFails:      make(map[string]uint8),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edges[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edges[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkID = graphFingerprint(r.edges)
	return r, nil
}

func graphFingerprint(edges map[edgeKey]*candidateEdge) uint64 {
	var result uint64

	for _, edge := range edges {
		h := uint64(1469598103934665603)
		mix := func(v byte) {
			h ^= uint64(v)
			h *= 1099511628211
		}

		for i := 0; i < 8; i++ {
			mix(byte(edge.key.chanID >> (8 * i)))
		}
		for _, b := range edge.key.from {
			mix(b)
		}
		for _, b := range edge.key.to {
			mix(b)
		}
		capacity := uint64(edge.capacity)
		for i := 0; i < 8; i++ {
			mix(byte(capacity >> (8 * i)))
		}

		result ^= h
	}

	if result == 0 {
		return 1
	}
	return result
}

func clampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005
	case p > 0.995:
		return 0.995
	default:
		return p
	}
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)

	// Either direction is usually almost empty or almost full. Very small
	// shards can also pass through the depleted mode.
	lowMode := math.Exp(-x / 0.045)
	highMode := 1 / (1 + math.Exp((x-0.90)*25))
	return clampProbability(0.48*lowMode + 0.52*highMode)
}

func (r *candidateRouter) getBelief(key edgeKey) liquidityBelief {
	persistentBeliefs.RLock()
	b := persistentBeliefs.values[beliefKey{
		network: r.networkID,
		edge:    key,
	}]
	persistentBeliefs.RUnlock()
	return b
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	required lnwire.MilliSatoshi) float64 {

	p := bimodalPrior(required, edge.capacity)
	b := r.getBelief(edge.key)

	if b.lowerOK > 0 && required <= b.lowerOK {
		return 0.995
	}

	if b.upper > 0 {
		if required >= b.upper {
			return 0.010
		}

		lo := b.lowerOK
		if lo >= b.upper {
			lo = 0
		}
		if required > lo {
			position := float64(required-lo) /
				float64(b.upper-lo)
			boundP := 0.995*(1-position) + 0.010*position
			weight := math.Min(0.84, 0.34+0.10*b.conf)
			p = (1-weight)*p + weight*boundP
		}
	}

	if b.estimate > 0 {
		width := math.Max(
			float64(edge.capacity)*0.07, 1_000_000,
		)
		estimateP := 1 / (1 + math.Exp(
			(float64(required)-float64(b.estimate))/width,
		))
		weight := math.Min(0.62, b.conf/(b.conf+3.5))
		p = (1-weight)*p + weight*estimateP
	}

	return clampProbability(p)
}

func (r *candidateRouter) recordSuccess(key edgeKey,
	required lnwire.MilliSatoshi) {

	persistentBeliefs.Lock()
	defer persistentBeliefs.Unlock()

	bk := beliefKey{network: r.networkID, edge: key}
	b := persistentBeliefs.values[bk]

	if required > b.lowerOK {
		b.lowerOK = required
	}

	estimate := required + required/3
	if estimate > b.estimate {
		b.estimate = estimate
	}

	// Successful attempts are always trustworthy.
	if b.upper > 0 && required >= b.upper {
		b.upper = 0
		b.probeFail = 0
		b.failVotes = 0
	}

	if b.conf < 10 {
		b.conf++
	}
	persistentBeliefs.values[bk] = b
}

func closeFailureAmounts(a, b lnwire.MilliSatoshi) bool {
	if a <= 0 || b <= 0 {
		return false
	}

	delta := a - b
	if delta < 0 {
		delta = -delta
	}

	tolerance := b / 3
	if tolerance < 1_000_000 {
		tolerance = 1_000_000
	}
	return delta <= tolerance
}

func (r *candidateRouter) recordLiquidityFailure(key edgeKey,
	required lnwire.MilliSatoshi) {

	persistentBeliefs.Lock()
	defer persistentBeliefs.Unlock()

	bk := beliefKey{network: r.networkID, edge: key}
	b := persistentBeliefs.values[bk]

	if b.lowerOK > 0 && required <= b.lowerOK {
		b.probeFail = 0
		b.failVotes = 0
		persistentBeliefs.values[bk] = b
		return
	}

	if closeFailureAmounts(required, b.probeFail) {
		if b.failVotes < 255 {
			b.failVotes++
		}
		if required < b.probeFail {
			b.probeFail = required
		}
	} else {
		b.probeFail = required
		b.failVotes = 1
	}

	// A shifted attribution should not create a hard bound by itself.
	if b.failVotes >= 2 {
		if b.upper == 0 || b.probeFail < b.upper {
			b.upper = b.probeFail
		}

		estimate := b.probeFail * 2 / 3
		if b.estimate == 0 || estimate < b.estimate {
			b.estimate = estimate
		}
		if b.conf < 10 {
			b.conf++
		}
	}

	persistentBeliefs.values[bk] = b
}

type searchItem struct {
	node  route.Vertex
	score float64
	index int
}

type searchQueue []*searchItem

func (q searchQueue) Len() int {
	return len(q)
}

func (q searchQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q searchQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index = i
	q[j].index = j
}

func (q *searchQueue) Push(x any) {
	item := x.(*searchItem)
	item.index = len(*q)
	*q = append(*q, item)
}

func (q *searchQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func edgeLaneBias(key edgeKey, lane int) float64 {
	if lane == 0 {
		return 0
	}

	h := key.chanID ^ uint64(lane)*0x9e3779b97f4a7c15
	for i := 0; i < 4; i++ {
		h ^= uint64(key.from[i]) << (8 * i)
		h ^= uint64(key.to[i]) << (8 * (3 - i))
		h *= 1099511628211
	}

	return 0.035 * float64((h>>17)%17)
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	reserved map[edgeKey]lnwire.MilliSatoshi,
	reuse map[edgeKey]uint8, reusePenalty float64,
	lane int) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is target")
	}

	dist := make(map[route.Vertex]float64)
	amountAt := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)

	dist[r.spec.Target] = 0
	amountAt[r.spec.Target] = amt

	pq := &searchQueue{}
	heap.Push(pq, &searchItem{
		node:  r.spec.Target,
		score: 0,
	})

	feeScale := math.Max(float64(amt)*0.003, 40_000)

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*searchItem)
		best, ok := dist[item.node]
		if !ok || item.score > best+1e-12 {
			continue
		}
		if item.node == r.source {
			break
		}

		arriving := amountAt[item.node]
		for _, edge := range r.incomingEdges[item.node] {
			if !edge.usableHTLC(arriving) {
				continue
			}

			already := reserved[edge.key]
			if already > edge.capacity ||
				arriving > edge.capacity-already {

				continue
			}

			required := already + arriving
			probability := r.edgeProbability(edge, required)

			if edge.key.from == r.source {
				local := r.localBalances[edge.key.chanID]
				if already > local || arriving > local-already {
					continue
				}
				probability = 0.995
			}

			sending := arriving
			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(arriving)
				if fee < 0 {
					continue
				}
				sending += fee
				if sending < arriving {
					continue
				}
			}

			increment := -math.Log(probability)
			increment += float64(fee) / feeScale
			increment += 0.015
			increment += r.penalty[edge.key]
			increment += edgeLaneBias(edge.key, lane)

			if count := reuse[edge.key]; count > 0 &&
				edge.key.from != r.source {

				increment += reusePenalty * float64(count)
			}

			candidate := item.score + increment
			old, exists := dist[edge.key.from]
			if exists && candidate >= old {
				continue
			}

			dist[edge.key.from] = candidate
			amountAt[edge.key.from] = sending
			next[edge.key.from] = edge
			heap.Push(pq, &searchItem{
				node:  edge.key.from,
				score: candidate,
			})
		}
	}

	if _, ok := dist[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	return r.buildRoute(amt, next)
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("cycle in route")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		nextEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			nextEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(nextEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forward := amt
		expiry := uint32(finalCltvDelta)

		if i < last {
			forward = amtOver[i+1]
			expiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func routeDeliveredAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func routeEdge(rt *route.Route, index int) (edgeKey,
	lnwire.MilliSatoshi, bool) {

	if rt == nil || index < 0 || index >= len(rt.Hops) {
		return edgeKey{}, 0, false
	}

	from := rt.SourcePubKey
	amt := rt.TotalAmount
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
		amt = rt.Hops[index-1].AmtToForward
	}

	return edgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
		to:     rt.Hops[index].PubKeyBytes,
	}, amt, true
}

func routeSignature(rt *route.Route) string {
	if rt == nil {
		return ""
	}

	s := fmt.Sprintf("%d", routeDeliveredAmount(rt))
	for i := range rt.Hops {
		key, _, ok := routeEdge(rt, i)
		if ok {
			s += fmt.Sprintf("/%d:%x:%x",
				key.chanID, key.from, key.to,
			)
		}
	}
	return s
}

func routePathSignature(rt *route.Route) string {
	if rt == nil {
		return ""
	}

	s := ""
	for i := range rt.Hops {
		key, _, ok := routeEdge(rt, i)
		if ok {
			s += fmt.Sprintf("/%d:%x:%x",
				key.chanID, key.from, key.to,
			)
		}
	}
	return s
}

func copyReservations(
	src map[edgeKey]lnwire.MilliSatoshi,
) map[edgeKey]lnwire.MilliSatoshi {

	dst := make(map[edgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func shardAmounts(total lnwire.MilliSatoshi, parts, scheme int,
	reverse bool) []lnwire.MilliSatoshi {

	if parts <= 1 {
		return []lnwire.MilliSatoshi{total}
	}

	weights := make([]int64, parts)
	var weightTotal int64

	for i := 0; i < parts; i++ {
		switch scheme {
		case 1:
			weights[i] = 2
			if i == 0 {
				weights[i] = 3
			}

		case 2:
			// A two-to-one gradient covers unequal corridors without
			// creating tiny probe shards.
			weights[i] = int64(parts*2 - i)

		default:
			weights[i] = 1
		}
	}

	if reverse {
		for i, j := 0, parts-1; i < j; i, j = i+1, j-1 {
			weights[i], weights[j] = weights[j], weights[i]
		}
	}

	for _, weight := range weights {
		weightTotal += weight
	}

	result := make([]lnwire.MilliSatoshi, parts)
	remaining := total
	remainingWeight := weightTotal

	for i := 0; i < parts; i++ {
		if i == parts-1 {
			result[i] = remaining
			break
		}

		result[i] = lnwire.MilliSatoshi(
			int64(remaining) * weights[i] / remainingWeight,
		)
		if result[i] <= 0 {
			result[i] = 1
		}

		remaining -= result[i]
		remainingWeight -= weights[i]
	}

	return result
}

func (r *candidateRouter) scoreRoute(rt *route.Route,
	reserved map[edgeKey]lnwire.MilliSatoshi,
	reuse map[edgeKey]uint8, reusePenalty float64) float64 {

	delivered := routeDeliveredAmount(rt)
	feeScale := math.Max(float64(delivered)*0.003, 40_000)
	score := 0.0

	for i := range rt.Hops {
		key, amtOver, ok := routeEdge(rt, i)
		if !ok {
			continue
		}

		edge := r.edges[key]
		if edge == nil {
			return math.Inf(1)
		}

		required := reserved[key] + amtOver
		p := r.edgeProbability(edge, required)
		if key.from == r.source {
			p = 0.995
		}

		score += -math.Log(p) + 0.015 + r.penalty[key]

		if key.from != r.source {
			score += float64(edge.fee(amtOver)) / feeScale
			score += reusePenalty * float64(reuse[key])
		}
	}

	score += 0.70 * float64(r.triedExact[routeSignature(rt)])
	score += 0.16 * float64(r.pathFails[routePathSignature(rt)])
	return score
}

func (r *candidateRouter) constructPlan(total lnwire.MilliSatoshi,
	parts, scheme int, reverse bool, lane int,
	reusePenalty float64) ([]plannedShard, float64, error) {

	amounts := shardAmounts(total, parts, scheme, reverse)
	tempReserved := copyReservations(r.reserved)
	reuse := make(map[edgeKey]uint8)
	plan := make([]plannedShard, 0, len(amounts))
	scores := make([]float64, 0, len(amounts))

	for _, shardAmt := range amounts {
		if shardAmt <= 0 {
			return nil, 0, errors.New("invalid shard amount")
		}

		rt, err := r.findRoute(
			shardAmt, tempReserved, reuse,
			reusePenalty, lane,
		)
		if err != nil {
			return nil, 0, err
		}

		score := r.scoreRoute(
			rt, tempReserved, reuse, reusePenalty,
		)
		plan = append(plan, plannedShard{
			route: rt,
			amt:   shardAmt,
		})
		scores = append(scores, score)

		for i := range rt.Hops {
			key, amtOver, ok := routeEdge(rt, i)
			if !ok {
				continue
			}

			tempReserved[key] += amtOver
			if reuse[key] < 255 {
				reuse[key]++
			}
		}
	}

	var sum, maximum float64
	for _, score := range scores {
		sum += score
		if score > maximum {
			maximum = score
		}
	}

	average := sum / float64(len(scores))

	// Summing all path risks alone strongly biases toward one oversized
	// shard. This mixed objective still charges for every added path, while
	// allowing a deliberately split route set to win when its shards are
	// materially safer or a single route cannot carry the payment.
	totalScore := average + 0.12*maximum + 0.10*sum
	totalScore += 0.07 * float64(parts-1)

	return plan, totalScore, nil
}

func candidatePartCounts(minParts, maxParts int) []int {
	selected := make(map[int]bool)
	for _, parts := range []int{1, 2, 3, 4, 6, 8, 12, 16} {
		if parts >= minParts && parts <= maxParts {
			selected[parts] = true
		}
	}
	selected[minParts] = true
	selected[maxParts] = true

	result := make([]int, 0, len(selected))
	for parts := minParts; parts <= maxParts; parts++ {
		if selected[parts] {
			result = append(result, parts)
		}
	}
	return result
}

func (r *candidateRouter) minimumParts(maxParts int) int {
	minParts := 1
	switch {
	case r.failCount >= 6:
		minParts = 8
	case r.failCount >= 3:
		minParts = 4
	case r.failCount >= 1:
		minParts = 2
	}

	if minParts > maxParts {
		minParts = maxParts
	}
	return minParts
}

func (r *candidateRouter) bestPlan(total lnwire.MilliSatoshi,
	partsLeft uint32) ([]plannedShard, error) {

	maxParts := int(partsLeft)
	if maxParts < 1 {
		return nil, errors.New("no payment parts available")
	}
	if maxParts > 16 {
		maxParts = 16
	}

	minParts := r.minimumParts(maxParts)
	counts := candidatePartCounts(minParts, maxParts)

	type variant struct {
		scheme       int
		reverse      bool
		lane         int
		reusePenalty float64
	}

	variants := []variant{
		{scheme: 0, lane: 0, reusePenalty: 1.4},
		{scheme: 0, lane: 1, reusePenalty: 4.0},
		{scheme: 1, lane: 0, reusePenalty: 2.2},
		{scheme: 1, reverse: true, lane: 2, reusePenalty: 2.2},
		{scheme: 2, lane: 3, reusePenalty: 3.2},
	}

	var best []plannedShard
	bestScore := math.Inf(1)

	for _, parts := range counts {
		for _, variant := range variants {
			if parts == 1 &&
				(variant.scheme != 0 || variant.lane > 2) {

				continue
			}

			plan, score, err := r.constructPlan(
				total, parts, variant.scheme,
				variant.reverse, variant.lane,
				variant.reusePenalty,
			)
			if err != nil {
				continue
			}

			if score < bestScore {
				best = plan
				bestScore = score
			}
		}
	}

	if len(best) == 0 {
		return nil, errors.New("no route found")
	}
	return best, nil
}

func planTotal(plan []plannedShard) lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	for _, shard := range plan {
		total += shard.amt
	}
	return total
}

func (r *candidateRouter) emergencyShard(amt lnwire.MilliSatoshi,
	partsLeft uint32) (*route.Route, error) {

	if partsLeft == 0 {
		return nil, errors.New("no payment parts available")
	}

	divisor := lnwire.MilliSatoshi(partsLeft)
	shard := (amt + divisor - 1) / divisor
	if shard <= 0 {
		shard = amt
	}

	var best *route.Route
	bestScore := math.Inf(1)
	reuse := make(map[edgeKey]uint8)

	for lane := 0; lane < 4; lane++ {
		rt, err := r.findRoute(
			shard, r.reserved, reuse, 0, lane,
		)
		if err != nil {
			continue
		}

		score := r.scoreRoute(rt, r.reserved, reuse, 0)
		if score < bestScore {
			best = rt
			bestScore = score
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}
	return best, nil
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}

	if len(r.plan) > 0 && planTotal(r.plan) == amt {
		next := r.plan[0]
		r.plan = r.plan[1:]
		return next.route, nil
	}
	r.plan = nil

	if inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum payment parts reached")
	}
	partsLeft := r.spec.MaxParts - inFlightHtlcs

	plan, err := r.bestPlan(amt, partsLeft)
	if err == nil && len(plan) > 0 {
		next := plan[0]
		r.plan = plan[1:]
		return next.route, nil
	}

	// Greedy route-set construction can paint itself into a corner even
	// though its first average-sized shard is useful. Replanning after that
	// shard settles may expose a feasible residual allocation.
	return r.emergencyShard(amt, partsLeft)
}

func failureOutgoingIndex(rt *route.Route,
	source route.Vertex) int {

	if rt == nil {
		return -1
	}
	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}
	return -1
}

func (r *candidateRouter) ReportAttempt(attemptID uint64,
	rt *route.Route, result routing.SimHtlcResult) error {

	_ = attemptID

	if rt == nil {
		return nil
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key, amtOver, ok := routeEdge(rt, i)
			if !ok {
				continue
			}

			required := r.reserved[key] + amtOver
			r.recordSuccess(key, required)
			r.reserved[key] = required

			if r.penalty[key] > 0.20 {
				r.penalty[key] *= 0.45
			} else {
				delete(r.penalty, key)
			}
		}
		return nil
	}

	r.plan = nil
	r.failCount++

	exact := routeSignature(rt)
	path := routePathSignature(rt)
	if r.triedExact[exact] < 255 {
		r.triedExact[exact]++
	}
	if r.pathFails[path] < 255 {
		r.pathFails[path]++
	}

	// An off-route source explicitly carries no channel information. The
	// failed amount still affects future shard sizing, but no edge is blamed.
	failIndex := failureOutgoingIndex(rt, result.FailureSource)
	if failIndex < 0 || failIndex >= len(rt.Hops) {
		return nil
	}

	key, amtOver, ok := routeEdge(rt, failIndex)
	if !ok {
		return nil
	}

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		if r.suspicions[key] < 255 {
			r.suspicions[key]++
		}

		if r.suspicions[key] == 1 {
			r.penalty[key] += 0.28
		} else {
			r.penalty[key] += 0.90
		}

		r.recordLiquidityFailure(
			key, r.reserved[key]+amtOver,
		)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		// Gossip-derived routes should satisfy the advertised policy. Treat
		// this as stale policy or shifted blame and keep it payment-local.
		r.penalty[key] += 1.8
	}

	return nil
}
